@dataclass(frozen=True)
class CampaignPaths:
    config: Path
    config_dir: Path
    workspace: Path
    state_db: Path
    manifest: Path
    internal: Path
    data: Path
    runs: Path
    models: Path
    results: Path

    @classmethod
    def from_config(cls, config_path: str | Path, cfg: Mapping[str, Any]) -> "CampaignPaths":
        config = Path(config_path).expanduser().resolve()
        config_dir = config.parent
        workspace_value = cfg.get("campaign", {}).get("workspace", "mlff-campaign")
        workspace = _resolve_path(workspace_value, config_dir)
        manifest_value = cfg.get("data", {}).get("manifest", DEFAULT_MANIFEST_NAME)
        manifest = _resolve_path(manifest_value, workspace)
        internal = workspace / ".mdstats"
        return cls(
            config=config,
            config_dir=config_dir,
            workspace=workspace,
            state_db=internal / "campaign.sqlite3",
            manifest=manifest,
            internal=internal,
            data=workspace / "data",
            runs=workspace / "runs",
            models=workspace / "models",
            results=workspace / "results",
        )

    def ensure(self) -> None:
        for path in (self.workspace, self.internal, self.data, self.runs, self.models, self.results):
            path.mkdir(parents=True, exist_ok=True)


@dataclass(frozen=True)
class _Data8RuntimeEntry:
    """One immutable DATA8 identity plus its promoted live filesystem root.

    Production DATA8 trees are assembled under a temporary staging directory
    and atomically promoted into a content-addressed generation.  The immutable
    bundle intentionally retains the assembly-time locator, so campaign runtime
    code must resolve the live root from the production-materialization record.
    """

    variant_id: str
    bundle: Any
    root: Path
    materialization: Any | None = None


@dataclass(frozen=True)
class _TrainingMethodSpec:
    mode: str
    seeds: tuple[int, ...]
    cross_validation_folds: int
    fold_partition_seed: int
    seed_mode: str = "optimizer_only"

    def __post_init__(self) -> None:
        allowed = {"naive_fine_tuning", "multihead_replay"}
        if self.mode not in allowed:
            raise CampaignCliError(
                f"Unsupported training mode {self.mode!r}; choose one of {sorted(allowed)}."
            )
        seeds = tuple(int(value) for value in self.seeds)
        if not seeds or len(set(seeds)) != len(seeds) or any(value < 0 for value in seeds):
            raise CampaignCliError(
                f"[training.{self.mode}].seeds must contain unique nonnegative integers."
            )
        folds = int(self.cross_validation_folds)
        if folds == 1 or folds < 0:
            raise CampaignCliError(
                f"[training.{self.mode}].cross_validation_folds must be 0 (final-only) "
                "or at least 2."
            )
        partition_seed = int(self.fold_partition_seed)
        if partition_seed < 0:
            raise CampaignCliError(
                f"[training.{self.mode}].fold_partition_seed must be nonnegative."
            )
        seed_mode = str(self.seed_mode).strip().lower()
        if seed_mode not in {"optimizer_only", "optimizer_and_cv_partition"}:
            raise CampaignCliError(
                f"[training.{self.mode}].seed_mode must be optimizer_only or optimizer_and_cv_partition."
            )
        object.__setattr__(self, "seeds", seeds)
        object.__setattr__(self, "cross_validation_folds", folds)
        object.__setattr__(self, "fold_partition_seed", partition_seed)
        object.__setattr__(self, "seed_mode", seed_mode)


@dataclass(frozen=True, eq=False)
class _VariantSpec:
    mode: str
    selection_size: int
    seed: int
    cross_validation_folds: int
    fold_partition_seed: int

    @property
    def variant_id(self) -> str:
        return f"{self.mode}-n{self.selection_size}-seed{self.seed}"

    def __eq__(self, other: object) -> bool:
        if isinstance(other, _VariantSpec):
            return (
                self.mode, self.selection_size, self.seed,
                self.cross_validation_folds, self.fold_partition_seed,
            ) == (
                other.mode, other.selection_size, other.seed,
                other.cross_validation_folds, other.fold_partition_seed,
            )
        if isinstance(other, tuple):
            if len(other) == 3:
                return (self.mode, self.selection_size, self.seed) == other
            if len(other) == 5:
                return (
                    self.mode, self.selection_size, self.seed,
                    self.cross_validation_folds, self.fold_partition_seed,
                ) == other
        return NotImplemented

    def __hash__(self) -> int:
        return hash((
            self.mode, self.selection_size, self.seed,
            self.cross_validation_folds, self.fold_partition_seed,
        ))


@dataclass(frozen=True)
class _VariantAvailability:
    protocol_variant_digest: str
    protocol_family_digest: str
    training_mode: Any
    selection_size: int
    seed: int
    expected_runs: tuple[Any, ...]
    completed_runs: tuple[Any, ...]
    completed_folds: tuple[Any, ...]
    final_run: Any | None
    evidence_level: Any

    @property
    def expected_fold_count(self) -> int:
        return sum(1 for run in self.expected_runs if run.fold_index is not None)

    @property
    def completed_fold_indices(self) -> tuple[int, ...]:
        return tuple(sorted(int(run.fold_index) for run in self.completed_folds))

    @property
    def final_completed(self) -> bool:
        return self.final_run is not None

    @property
    def missing_runs(self) -> tuple[Any, ...]:
        completed = {run.content_digest for run in self.completed_runs}
        return tuple(run for run in self.expected_runs if run.content_digest not in completed)

    @property
    def rank(self) -> int:
        value = getattr(self.evidence_level, "value", str(self.evidence_level))
        return {
            "complete_variant": 3,
            "partial_cross_validation": 2,
            "single_model": 1,
        }[value]


def _coerce_variant_spec(value: Any) -> _VariantSpec:
    if isinstance(value, _VariantSpec):
        return value
    if isinstance(value, tuple) and len(value) in {3, 5}:
        mode, size, seed = value[:3]
        folds = 3 if len(value) == 3 else value[3]
        fold_seed = 104729 if len(value) == 3 else value[4]
        return _VariantSpec(
            mode=str(mode), selection_size=int(size), seed=int(seed),
            cross_validation_folds=int(folds), fold_partition_seed=int(fold_seed),
        )
    raise CampaignCliError(f"Invalid training variant specification: {value!r}.")


class CampaignStore:
    """Single-file durable state for orchestration records and stage summaries."""

    def __init__(self, path: str | Path):
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._db_local = threading.local()
        configure_sha256_receipt_store(self.path.parent / "hash-receipts.sqlite3")
        with self._connect() as db:
            db.executescript(
                """
                PRAGMA journal_mode=DELETE;
                PRAGMA synchronous=NORMAL;
                PRAGMA busy_timeout=30000;
                CREATE TABLE IF NOT EXISTS meta (
                    key TEXT PRIMARY KEY,
                    value TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS records (
                    key TEXT PRIMARY KEY,
                    class_name TEXT NOT NULL,
                    digest TEXT,
                    payload TEXT NOT NULL,
                    updated_utc TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS stages (
                    name TEXT PRIMARY KEY,
                    state TEXT NOT NULL,
                    message TEXT NOT NULL,
                    updated_utc TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp_utc TEXT NOT NULL,
                    level TEXT NOT NULL,
                    stage TEXT NOT NULL,
                    message TEXT NOT NULL
                );
                """
            )
            db.execute("INSERT OR REPLACE INTO meta(key,value) VALUES (?,?)", ("schema", CAMPAIGN_STATE_SCHEMA))

    def _connect(self) -> sqlite3.Connection:
        """Return one persistent SQLite connection per calling thread.

        Campaign orchestration performs many tiny record/meta lookups. Reopening
        SQLite for every operation was measurable control-plane overhead, while
        sharing a connection across worker threads would violate sqlite3's
        thread-affinity contract. A thread-local connection gives us pooling
        without weakening that ownership rule.
        """

        db = getattr(self._db_local, "connection", None)
        if db is None:
            db = sqlite3.connect(self.path, timeout=30.0)
            db.execute("PRAGMA busy_timeout=30000")
            self._db_local.connection = db
        return db

    def close(self) -> None:
        db = getattr(self._db_local, "connection", None)
        if db is not None:
            try:
                db.close()
            finally:
                self._db_local.connection = None

    @property
    def external_record_directory(self) -> Path:
        return self.path.parent / "records"

    def _write_external_payload(self, key: str, payload: Mapping[str, Any]) -> tuple[str, str]:
        """Stream a large JSON record to content-addressed storage.

        The encoder writes incrementally, avoiding a second giant in-memory JSON
        string.  SQLite stores only a small, checksummed pointer.
        """

        directory = self.external_record_directory
        directory.mkdir(parents=True, exist_ok=True)
        encoder = json.JSONEncoder(sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        hasher = hashlib.sha256()
        byte_count = 0
        fd, temporary_name = tempfile.mkstemp(prefix="record-", suffix=".json.tmp", dir=directory)
        temporary = Path(temporary_name)
        try:
            with os.fdopen(fd, "wb") as handle:
                for text_chunk in encoder.iterencode(payload):
                    chunk = text_chunk.encode("utf-8")
                    handle.write(chunk)
                    hasher.update(chunk)
                    byte_count += len(chunk)
                handle.flush()
                os.fsync(handle.fileno())
            sha256 = hasher.hexdigest()
            destination = directory / f"{sha256}.json"
            if destination.exists():
                temporary.unlink()
            else:
                os.replace(temporary, destination)
            pointer = {
                "schema": EXTERNAL_RECORD_POINTER_SCHEMA,
                "relative_path": str(destination.relative_to(self.path.parent)),
                "sha256": sha256,
                "size_bytes": byte_count,
                "record_key": key,
            }
            return json.dumps(pointer, sort_keys=True, separators=(",", ":")), sha256
        except Exception:
            temporary.unlink(missing_ok=True)
            raise

    def _read_external_payload(self, pointer: Mapping[str, Any], *, key: str) -> dict[str, Any]:
        if pointer.get("schema") != EXTERNAL_RECORD_POINTER_SCHEMA:
            raise CampaignCliError(f"Stored campaign record pointer is invalid: {key}.")
        relative = Path(str(pointer.get("relative_path", "")))
        if relative.is_absolute() or ".." in relative.parts:
            raise CampaignCliError(f"Stored campaign record pointer escapes the campaign workspace: {key}.")
        path = (self.path.parent / relative).resolve()
        root = self.path.parent.resolve()
        if root not in path.parents:
            raise CampaignCliError(f"Stored campaign record pointer escapes the campaign workspace: {key}.")
        if not path.is_file():
            raise CampaignCliError(f"External campaign record is missing for {key}: {path}")
        expected = str(pointer.get("sha256", ""))
        actual = _sha256(path)
        if not expected or actual != expected:
            raise CampaignCliError(f"External campaign record checksum mismatch for {key}: {path}")
        with path.open("r", encoding="utf-8") as handle:
            payload = json.load(handle)
        if not isinstance(payload, dict):
            raise CampaignCliError(f"External campaign record is invalid: {key}.")
        return payload

    def set_meta(self, key: str, value: Any) -> None:
        encoded = json.dumps(value, sort_keys=True)
        with self._connect() as db:
            db.execute("INSERT OR REPLACE INTO meta(key,value) VALUES (?,?)", (key, encoded))

    def get_meta(self, key: str, default: Any = None) -> Any:
        with self._connect() as db:
            row = db.execute("SELECT value FROM meta WHERE key=?", (key,)).fetchone()
        return default if row is None else json.loads(row[0])

    def _encode_record_for_storage(self, key: str, record: Any) -> tuple[str, str | None, str]:
        """Return ``(class_name, digest, payload_json)`` for one record."""

        # DATA4 contains hundreds of thousands of nested scientific records.
        # Persist it as checksummed JSONL shards before calling ``to_dict`` so
        # campaign state never creates a second multi-gigabyte object graph.
        from .data4_bundle import Data4FeatureBundle
        from .data4_sharded_store import write_data4_sharded_record
        from .data6_bundle import Data6FeatureBundle
        from .data6_sharded_store import write_data6_sharded_record
        from .target_coverage import TargetCoverageReference
        from .target_coverage_store import write_target_coverage_native_record
        from .target_coverage_exact_neighborhood import TargetCoverageExactNeighborhoodStore
        from .target_coverage_exact_neighborhood_store import write_target_coverage_exact_neighborhood_native_record
        from .target_coverage_sparse_index import TargetCoverageSparseIndex
        from .target_coverage_sparse_index_store import write_target_coverage_sparse_index_native_record
        from .target_multi_view_selection_state import TargetMultiViewSelectionStateCache
        from .target_multi_view_selection_state_store import write_target_multi_view_selection_state_native_record

        if isinstance(record, Data4FeatureBundle):
            pointer = write_data4_sharded_record(
                record, self.external_record_directory, record_key=key
            )
            encoded = json.dumps(pointer, sort_keys=True, separators=(",", ":"))
            return type(record).__name__, record.content_digest, encoded
        if isinstance(record, Data6FeatureBundle):
            pointer = write_data6_sharded_record(
                record, self.external_record_directory, record_key=key
            )
            encoded = json.dumps(pointer, sort_keys=True, separators=(",", ":"))
            return type(record).__name__, record.content_digest, encoded
        if isinstance(record, TargetCoverageReference):
            pointer = write_target_coverage_native_record(
                record, self.external_record_directory, record_key=key
            )
            encoded = json.dumps(pointer, sort_keys=True, separators=(",", ":"))
            return type(record).__name__, record.content_digest, encoded
        if isinstance(record, TargetCoverageExactNeighborhoodStore):
            pointer = write_target_coverage_exact_neighborhood_native_record(
                record, self.external_record_directory, record_key=key
            )
            encoded = json.dumps(pointer, sort_keys=True, separators=(",", ":"))
            return type(record).__name__, record.content_digest, encoded
        if isinstance(record, TargetCoverageSparseIndex):
            pointer = write_target_coverage_sparse_index_native_record(
                record, self.external_record_directory, record_key=key
            )
            encoded = json.dumps(pointer, sort_keys=True, separators=(",", ":"))
            return type(record).__name__, record.content_digest, encoded
        if isinstance(record, TargetMultiViewSelectionStateCache):
            pointer = write_target_multi_view_selection_state_native_record(
                record, self.external_record_directory, record_key=key
            )
            encoded = json.dumps(pointer, sort_keys=True, separators=(",", ":"))
            return type(record).__name__, record.content_digest, encoded

        payload = record.to_dict() if hasattr(record, "to_dict") else record
        if not isinstance(payload, Mapping):
            raise CampaignCliError(f"Record {key!r} is not JSON-mappable.")
        record_digest = payload.get("content_digest")
        if record_digest is None and hasattr(record, "content_digest"):
            record_digest = record.content_digest
        class_name = type(record).__name__ if hasattr(record, "to_dict") else "mapping"

        force_external = key in {"frame_catalog", "data4", "data6"}
        if force_external:
            encoded, _ = self._write_external_payload(key, payload)
        else:
            encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"))
            if len(encoded.encode("utf-8")) >= EXTERNAL_RECORD_THRESHOLD_BYTES:
                encoded, _ = self._write_external_payload(key, payload)
        return class_name, record_digest, encoded

    def put_record(self, key: str, record: Any) -> None:
        class_name, record_digest, encoded = self._encode_record_for_storage(key, record)
        with self._connect() as db:
            db.execute(
                "INSERT OR REPLACE INTO records(key,class_name,digest,payload,updated_utc) VALUES (?,?,?,?,?)",
                (key, class_name, record_digest, encoded, _utc_now()),
            )

    def put_records(self, records: Mapping[str, Any]) -> None:
        """Persist several compact orchestration records in one transaction.

        Large sharded/external payloads are fully materialized before the SQLite
        transaction begins, so filesystem work never holds the database write
        lock. This method is for naturally atomic parent-side record groups.
        """

        if not records:
            return
        encoded_rows: list[tuple[str, str, str | None, str, str]] = []
        timestamp = _utc_now()
        for key, record in records.items():
            class_name, record_digest, encoded = self._encode_record_for_storage(
                str(key), record
            )
            encoded_rows.append(
                (str(key), class_name, record_digest, encoded, timestamp)
            )
        with self._connect() as db:
            db.executemany(
                "INSERT OR REPLACE INTO records(key,class_name,digest,payload,updated_utc) VALUES (?,?,?,?,?)",
                encoded_rows,
            )

    def replace_records_atomically(
        self, records: Mapping[str, Any], *, delete_keys: Sequence[str] = ()
    ) -> None:
        """Atomically delete stale aliases and publish one replacement record set.

        All record serialization/externalization happens before the SQLite write
        transaction. The database transaction then performs deletions and alias
        replacement together, which is required by MVMIGRATE1 so v4/v2/v2 and
        v5/v3/v3 cannot become partially mixed after interruption.
        """

        encoded_rows: list[tuple[str, str, str | None, str, str]] = []
        timestamp = _utc_now()
        for key, record in records.items():
            class_name, record_digest, encoded = self._encode_record_for_storage(
                str(key), record
            )
            encoded_rows.append((str(key), class_name, record_digest, encoded, timestamp))
        delete = tuple(dict.fromkeys(str(key) for key in delete_keys if str(key)))
        with self._connect() as db:
            if delete:
                db.executemany("DELETE FROM records WHERE key=?", ((key,) for key in delete))
            if encoded_rows:
                db.executemany(
                    "INSERT OR REPLACE INTO records(key,class_name,digest,payload,updated_utc) VALUES (?,?,?,?,?)",
                    encoded_rows,
                )

    def _decode_record_payload(self, key: str, encoded: str) -> dict[str, Any]:
        payload = json.loads(encoded)
        if not isinstance(payload, dict):
            raise CampaignCliError(f"Stored campaign record is invalid: {key}.")
        if payload.get("schema") == EXTERNAL_RECORD_POINTER_SCHEMA:
            return self._read_external_payload(payload, key=key)
        return payload

    def get_payload_optional(self, key: str) -> dict[str, Any] | None:
        """Fetch one optional payload with one SQL query and one JSON decode."""

        with self._connect() as db:
            row = db.execute("SELECT payload FROM records WHERE key=?", (key,)).fetchone()
        if row is None:
            return None
        payload = self._decode_record_payload(key, row[0])
        from .data4_sharded_store import DATA4_SHARDED_POINTER_SCHEMA
        from .data6_sharded_store import DATA6_SHARDED_POINTER_SCHEMA
        from .target_coverage_store import TARGET_COVERAGE_NATIVE_POINTER_SCHEMA
        from .target_coverage_exact_neighborhood_store import TARGET_COVERAGE_EXACT_NEIGHBORHOOD_NATIVE_POINTER_SCHEMA
        from .target_coverage_sparse_index_store import TARGET_COVERAGE_SPARSE_INDEX_NATIVE_POINTER_SCHEMA
        from .target_multi_view_selection_state_store import TARGET_MULTI_VIEW_SELECTION_STATE_NATIVE_POINTER_SCHEMA
        if payload.get("schema") in {
            DATA4_SHARDED_POINTER_SCHEMA,
            DATA6_SHARDED_POINTER_SCHEMA,
            TARGET_COVERAGE_NATIVE_POINTER_SCHEMA,
            TARGET_COVERAGE_EXACT_NEIGHBORHOOD_NATIVE_POINTER_SCHEMA,
            TARGET_COVERAGE_SPARSE_INDEX_NATIVE_POINTER_SCHEMA,
            TARGET_MULTI_VIEW_SELECTION_STATE_NATIVE_POINTER_SCHEMA,
        }:
            raise CampaignCliError(
                f"Record {key!r} uses memory-bounded scientific shards; request it with get_record()."
            )
        return payload

    def get_payload(self, key: str) -> dict[str, Any]:
        payload = self.get_payload_optional(key)
        if payload is None:
            raise CampaignCliError(f"Required campaign record is missing: {key}. Run `status` for the next step.")
        return payload

    def _record_from_encoded_payload(self, key: str, encoded: str, cls: type[Any]) -> Any:
        payload = self._decode_record_payload(key, encoded)
        from .data4_bundle import Data4FeatureBundle
        from .data4_sharded_store import (
            DATA4_SHARDED_POINTER_SCHEMA, Data4ShardedStoreError,
            read_data4_sharded_record,
        )
        if cls is Data4FeatureBundle and isinstance(payload, Mapping) and payload.get("schema") == DATA4_SHARDED_POINTER_SCHEMA:
            try:
                return read_data4_sharded_record(
                    payload, self.path.parent,
                    progress_callback=lambda message: print(f"[DATA4 restore] {message}", flush=True),
                )
            except Data4ShardedStoreError as exc:
                raise CampaignCliError(str(exc)) from exc
        from .data6_bundle import Data6FeatureBundle
        from .data6_sharded_store import (
            DATA6_SHARDED_POINTER_SCHEMA, Data6ShardedStoreError,
            read_data6_sharded_record,
        )
        if cls is Data6FeatureBundle and isinstance(payload, Mapping) and payload.get("schema") == DATA6_SHARDED_POINTER_SCHEMA:
            try:
                return read_data6_sharded_record(
                    payload, self.path.parent,
                    progress_callback=lambda message: print(f"[DATA6 restore] {message}", flush=True),
                )
            except Data6ShardedStoreError as exc:
                raise CampaignCliError(str(exc)) from exc
        from .target_coverage import TargetCoverageReference
        from .target_coverage_store import (
            TARGET_COVERAGE_NATIVE_POINTER_SCHEMA,
            TargetCoverageNativeStoreError,
            read_target_coverage_native_record,
        )
        if cls is TargetCoverageReference and isinstance(payload, Mapping) and payload.get("schema") == TARGET_COVERAGE_NATIVE_POINTER_SCHEMA:
            try:
                return read_target_coverage_native_record(payload, self.path.parent)
            except TargetCoverageNativeStoreError as exc:
                raise CampaignCliError(str(exc)) from exc
        from .target_coverage_exact_neighborhood import TargetCoverageExactNeighborhoodStore
        from .target_coverage_exact_neighborhood_store import (
            TARGET_COVERAGE_EXACT_NEIGHBORHOOD_NATIVE_POINTER_SCHEMA,
            TargetCoverageExactNeighborhoodNativeStoreError,
            read_target_coverage_exact_neighborhood_native_record,
        )
        if cls is TargetCoverageExactNeighborhoodStore and isinstance(payload, Mapping) and payload.get("schema") == TARGET_COVERAGE_EXACT_NEIGHBORHOOD_NATIVE_POINTER_SCHEMA:
            try:
                return read_target_coverage_exact_neighborhood_native_record(payload, self.path.parent)
            except TargetCoverageExactNeighborhoodNativeStoreError as exc:
                raise CampaignCliError(str(exc)) from exc
        from .target_coverage_sparse_index import TargetCoverageSparseIndex
        from .target_coverage_sparse_index_store import (
            TARGET_COVERAGE_SPARSE_INDEX_NATIVE_POINTER_SCHEMA,
            TargetCoverageSparseIndexNativeStoreError,
            read_target_coverage_sparse_index_native_record,
        )
        if cls is TargetCoverageSparseIndex and isinstance(payload, Mapping) and payload.get("schema") == TARGET_COVERAGE_SPARSE_INDEX_NATIVE_POINTER_SCHEMA:
            try:
                return read_target_coverage_sparse_index_native_record(
                    payload,
                    self.path.parent,
                    progress_callback=lambda message: print(
                        f"[TARGET-DATA2C-MVIDX1 restore] {message}", flush=True
                    ),
                )
            except TargetCoverageSparseIndexNativeStoreError as exc:
                raise CampaignCliError(str(exc)) from exc
        from .target_multi_view_selection_state import TargetMultiViewSelectionStateCache
        from .target_multi_view_selection_state_store import (
            TARGET_MULTI_VIEW_SELECTION_STATE_NATIVE_POINTER_SCHEMA,
            TargetMultiViewSelectionStateNativeStoreError,
            read_target_multi_view_selection_state_native_record,
        )
        if cls is TargetMultiViewSelectionStateCache and isinstance(payload, Mapping) and payload.get("schema") == TARGET_MULTI_VIEW_SELECTION_STATE_NATIVE_POINTER_SCHEMA:
            try:
                return read_target_multi_view_selection_state_native_record(payload, self.path.parent)
            except TargetMultiViewSelectionStateNativeStoreError as exc:
                raise CampaignCliError(str(exc)) from exc
        if payload.get("schema") in {
            DATA4_SHARDED_POINTER_SCHEMA,
            DATA6_SHARDED_POINTER_SCHEMA,
            TARGET_COVERAGE_NATIVE_POINTER_SCHEMA,
            TARGET_COVERAGE_EXACT_NEIGHBORHOOD_NATIVE_POINTER_SCHEMA,
            TARGET_COVERAGE_SPARSE_INDEX_NATIVE_POINTER_SCHEMA,
            TARGET_MULTI_VIEW_SELECTION_STATE_NATIVE_POINTER_SCHEMA,
        }:
            raise CampaignCliError(
                f"Record {key!r} uses memory-bounded scientific shards but was requested as {cls.__name__}."
            )
        return cls.from_dict(payload)

    def get_record_optional(self, key: str, cls: type[Any]) -> Any | None:
        """Fetch one optional scientific record without a has/get double query."""

        with self._connect() as db:
            row = db.execute("SELECT payload FROM records WHERE key=?", (key,)).fetchone()
        if row is None:
            return None
        return self._record_from_encoded_payload(key, row[0], cls)

    def get_record(self, key: str, cls: type[Any]) -> Any:
        record = self.get_record_optional(key, cls)
        if record is None:
            raise CampaignCliError(f"Required campaign record is missing: {key}. Run `status` for the next step.")
        return record

    def has_record(self, key: str) -> bool:
        with self._connect() as db:
            return db.execute("SELECT 1 FROM records WHERE key=?", (key,)).fetchone() is not None

    def record_digest(self, key: str) -> str | None:
        """Return the persisted scientific digest without deserializing a record."""

        with self._connect() as db:
            row = db.execute("SELECT digest FROM records WHERE key=?", (key,)).fetchone()
        if row is None:
            raise CampaignCliError(
                f"Required campaign record is missing: {key}. Run `status` for the next step."
            )
        return None if row[0] in (None, "") else str(row[0])

    def record_keys(self, prefix: str = "") -> tuple[str, ...]:
        with self._connect() as db:
            rows = db.execute("SELECT key FROM records WHERE key LIKE ? ORDER BY key", (prefix + "%",)).fetchall()
        return tuple(row[0] for row in rows)

    def delete_records(self, prefix: str) -> None:
        """Delete compact orchestration pointers while leaving native artifacts intact."""

        with self._connect() as db:
            db.execute("DELETE FROM records WHERE key LIKE ?", (prefix + "%",))

    def delete_record(self, key: str) -> None:
        with self._connect() as db:
            db.execute("DELETE FROM records WHERE key=?", (key,))

    def storage_references(self) -> tuple[Path, ...]:
        """Return external files/directories reachable from current records."""

        from .data4_sharded_store import DATA4_SHARDED_POINTER_SCHEMA
        from .data6_sharded_store import DATA6_SHARDED_POINTER_SCHEMA
        from .target_coverage_store import TARGET_COVERAGE_NATIVE_POINTER_SCHEMA
        from .target_coverage_exact_neighborhood_store import TARGET_COVERAGE_EXACT_NEIGHBORHOOD_NATIVE_POINTER_SCHEMA
        from .target_coverage_sparse_index_store import TARGET_COVERAGE_SPARSE_INDEX_NATIVE_POINTER_SCHEMA
        from .target_multi_view_selection_state_store import TARGET_MULTI_VIEW_SELECTION_STATE_NATIVE_POINTER_SCHEMA

        references: set[Path] = set()
        with self._connect() as db:
            rows = db.execute("SELECT payload FROM records").fetchall()
        root = self.path.parent.resolve()
        for (encoded,) in rows:
            try:
                payload = json.loads(encoded)
            except Exception:
                continue
            if not isinstance(payload, Mapping):
                continue
            schema = payload.get("schema")
            if schema not in {
                EXTERNAL_RECORD_POINTER_SCHEMA,
                DATA4_SHARDED_POINTER_SCHEMA,
                DATA6_SHARDED_POINTER_SCHEMA,
                TARGET_COVERAGE_NATIVE_POINTER_SCHEMA,
                TARGET_COVERAGE_EXACT_NEIGHBORHOOD_NATIVE_POINTER_SCHEMA,
                TARGET_COVERAGE_SPARSE_INDEX_NATIVE_POINTER_SCHEMA,
                TARGET_MULTI_VIEW_SELECTION_STATE_NATIVE_POINTER_SCHEMA,
            }:
                continue
            relative = Path(str(payload.get("relative_path", "")))
            if relative.is_absolute() or ".." in relative.parts or relative in {Path(""), Path(".")}:
                continue
            candidate = (root / relative).resolve()
            if root == candidate or root not in candidate.parents:
                continue
            references.add(candidate)
            if schema in {
                DATA4_SHARDED_POINTER_SCHEMA,
                DATA6_SHARDED_POINTER_SCHEMA,
                TARGET_COVERAGE_NATIVE_POINTER_SCHEMA,
                TARGET_COVERAGE_EXACT_NEIGHBORHOOD_NATIVE_POINTER_SCHEMA,
                TARGET_COVERAGE_SPARSE_INDEX_NATIVE_POINTER_SCHEMA,
                TARGET_MULTI_VIEW_SELECTION_STATE_NATIVE_POINTER_SCHEMA,
            }:
                references.add(candidate.parent)
        return tuple(sorted(references))

    def compact(self, *, maximum_events: int = 10_000) -> None:
        """Bound orchestration history and compact the SQLite file."""

        maximum_events = max(100, int(maximum_events))
        with self._connect() as db:
            db.execute(
                "DELETE FROM events WHERE id NOT IN "
                "(SELECT id FROM events ORDER BY id DESC LIMIT ?)",
                (maximum_events,),
            )
            db.execute("PRAGMA optimize")
        # VACUUM cannot run inside a transaction. It is safe here because the
        # campaign parent is the sole database writer.
        with self._connect() as db:
            db.execute("VACUUM")
        prune_sha256_receipts()

    def set_stage(self, name: str, state: StageState, message: str) -> None:
        timestamp = _utc_now()
        with self._connect() as db:
            db.execute(
                "INSERT OR REPLACE INTO stages(name,state,message,updated_utc) VALUES (?,?,?,?)",
                (name, state.value, message, timestamp),
            )
            db.execute(
                "INSERT INTO events(timestamp_utc,level,stage,message) VALUES (?,?,?,?)",
                (timestamp, "info" if state is not StageState.FAILED else "error", name, message),
            )

    def stage(self, name: str) -> tuple[StageState, str]:
        with self._connect() as db:
            row = db.execute("SELECT state,message FROM stages WHERE name=?", (name,)).fetchone()
        if row is None:
            return StageState.NOT_STARTED, "not started"
        return StageState(row[0]), row[1]

    def event(self, level: str, stage: str, message: str) -> None:
        with self._connect() as db:
            db.execute(
                "INSERT INTO events(timestamp_utc,level,stage,message) VALUES (?,?,?,?)",
                (_utc_now(), level, stage, message),
            )


def _utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


@contextmanager
def _interrupt_guard(callback: Callable[[], None]):
    """Convert terminal/termination signals into a durable cooperative stop.

    The campaign remains alive until supervised MACE process groups have exited
    and their resumable execution records are committed.  Handling SIGTERM and
    SIGHUP in addition to Ctrl-C prevents service-manager or terminal-close
    termination from bypassing the same child cleanup path.
    """

    if os.name != "posix" or threading.current_thread() is not threading.main_thread():
        yield
        return
    supported = [
        candidate
        for candidate in (
            getattr(signal, "SIGINT", None),
            getattr(signal, "SIGTERM", None),
            getattr(signal, "SIGHUP", None),
        )
        if candidate is not None
    ]
    if not supported:
        yield
        return
    previous = {int(candidate): signal.getsignal(candidate) for candidate in supported}
    requested = False

    def _handler(signum: int, frame: Any) -> None:
        del signum, frame
        nonlocal requested
        if not requested:
            requested = True
            callback()

    for candidate in supported:
        signal.signal(candidate, _handler)
    try:
        yield
    finally:
        for candidate, handler in previous.items():
            signal.signal(candidate, handler)


def _process_rss_mib() -> float:
    """Best-effort current resident-set size for progress diagnostics."""

    try:
        import resource

        value = float(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss)
        # Linux reports KiB; macOS reports bytes.
        return value / (1024.0 if sys.platform != "darwin" else 1024.0 * 1024.0)
    except Exception:
        return float("nan")


def _resolve_path(value: str | Path, base: Path) -> Path:
    path = Path(value).expanduser()
    return (path if path.is_absolute() else base / path).resolve()


def _load_config(path: str | Path) -> tuple[dict[str, Any], CampaignPaths]:
    config_path = Path(path).expanduser().resolve()
    if not config_path.is_file():
        raise CampaignCliError(f"Configuration not found: {config_path}. Run `init` first.")
    with config_path.open("rb") as handle:
        cfg = tomllib.load(handle)
    if cfg.get("schema") not in (None, CAMPAIGN_CLI_SCHEMA):
        raise CampaignCliError(f"Unsupported campaign configuration schema: {cfg.get('schema')!r}.")
    paths = CampaignPaths.from_config(config_path, cfg)
    paths.ensure()
    # TRAIN2A migration authority is configuration-level and must fail on every
    # command, not only when DATA8 is rebuilt. Historical configs without an
    # explicit policy_generation remain under their original semantics.
    _validate_train2_migration_config(cfg)
    _normalize_foundation_config_in_memory(cfg)
    _validate_canonical_foundation_head_aliases(cfg)
    return cfg, paths


def _normalize_foundation_config_in_memory(cfg: dict[str, Any]) -> None:
    """Normalize legacy foundation settings without rewriting campaign TOML.

    MH1-CONFIG1 makes ``[foundation]`` the canonical configuration namespace.
    Historical 0.20.177a0-and-earlier MPA-0 campaign files contain only
    ``[model].foundation_name``; those are unambiguous enough to normalize to
    the singleton MPA-0/default contract in memory.  Unknown head-blind legacy
    foundations remain untouched so a later strict foundation-resolution gate
    can fail them closed rather than guessing multi-head semantics.
    """

    section = cfg.get("foundation")
    if isinstance(section, Mapping):
        family = str(section.get("family", "")).strip()
        head = str(section.get("head", "")).strip()
        if not family:
            raise CampaignCliError("[foundation].family must be non-empty when [foundation] is present.")
        if not head:
            raise CampaignCliError("[foundation].head must be non-empty when [foundation] is present.")
        try:
            from .foundation import MaceFoundationFamily

            canonical_family = MaceFoundationFamily.parse(family).value
        except Exception as exc:
            raise CampaignCliError(f"Invalid [foundation].family: {exc}") from exc
        if isinstance(section, dict):
            section["family"] = canonical_family
        return

    model = cfg.get("model", {})
    legacy_name = str(model.get("foundation_name", "")).strip() if isinstance(model, Mapping) else ""
    normalized = legacy_name.lower().replace("-", "_").replace(" ", "_")
    if "mpa_0" in normalized or "mpa0" in normalized:
        cfg["foundation"] = {
            "family": "mace_mpa_0",
            "head": "default",
            "label": legacy_name or "MACE-MPA-0",
            "legacy_normalized": True,
        }


def _foundation_config(cfg: Mapping[str, Any]) -> Mapping[str, Any]:
    section = cfg.get("foundation")
    if not isinstance(section, Mapping):
        raise CampaignCliError(
            "Campaign has no canonical [foundation] section and its legacy foundation could not be "
            "normalized safely. Add [foundation].family and [foundation].head explicitly."
        )
    return section


def _canonical_foundation_head(cfg: Mapping[str, Any]) -> str:
    head = str(_foundation_config(cfg).get("head", "")).strip()
    if not head:
        raise CampaignCliError("Canonical [foundation].head is empty.")
    return head


def _validate_canonical_foundation_head_aliases(cfg: Mapping[str, Any]) -> None:
    """Reject conflicting source-head selectors in generalized campaigns.

    Historical head-blind MPA-0 TOML retains its original evaluation/PES aliases
    until MH1-EVAL1 migration.  A campaign that already declares canonical
    ``[foundation]`` semantics, however, may not independently point those old
    selectors at a different source head.  New templates omit the aliases.
    """

    foundation = cfg.get("foundation")
    if not isinstance(foundation, Mapping) or bool(foundation.get("legacy_normalized", False)):
        return
    canonical_head = str(foundation.get("head", "")).strip()
    for section_name, key in (
        ("evaluation", "replay_baseline_head"),
        ("verification", "pes_foundation_head"),
    ):
        section = cfg.get(section_name, {})
        if not isinstance(section, Mapping):
            continue
        value = section.get(key)
        alias = "" if value is None else str(value).strip()
        if alias and alias != canonical_head:
            raise CampaignCliError(
                f"[{section_name}].{key}={alias!r} conflicts with canonical "
                f"[foundation].head={canonical_head!r}. Remove the legacy selector or make it identical."
            )


def _cfg(cfg: Mapping[str, Any], section: str, key: str, default: Any = None) -> Any:
    return cfg.get(section, {}).get(key, default)


def _foundation_configuration_contract(cfg: Mapping[str, Any]) -> dict[str, Any]:
    """Return the pre-preparation configuration identity for source foundation policy.

    This is intentionally a configuration contract, not a scientific checkpoint
    identity.  MH1-INF1 will bind the inspected model bytes/architecture.  CONFIG1
    needs only to guarantee that family, selected source head, and requested
    acceleration cannot change unnoticed between doctor runs.
    """

    foundation = _foundation_config(cfg)
    acceleration = cfg.get("acceleration", {})
    if not isinstance(acceleration, Mapping):
        raise CampaignCliError("[acceleration] must be a TOML table.")
    source_backend = str(acceleration.get("backend", "e3nn")).strip().lower()
    training_backend = str(acceleration.get("training_backend", source_backend)).strip().lower()
    if source_backend not in {"cueq", "e3nn"}:
        raise CampaignCliError("[acceleration].backend must be 'cueq' or 'e3nn'.")
    if training_backend not in {"cueq", "e3nn"}:
        raise CampaignCliError("[acceleration].training_backend must be 'cueq' or 'e3nn'.")
    payload = {
        "schema": FOUNDATION_CONFIG_CONTRACT_SCHEMA,
        "family": str(foundation.get("family", "")).strip(),
        "head": str(foundation.get("head", "")).strip(),
        "source_backend": source_backend,
        "training_backend": training_backend,
        "phase_separated": "training_backend" in acceleration,
        "only_cueq": bool(acceleration.get("only_cueq", False)),
        "require_available": bool(acceleration.get("require_available", True)),
    }
    payload["content_digest"] = digest(payload)
    return payload


def _acceleration_policy(cfg: Mapping[str, Any]) -> Any:
    """Return the explicit, protocol-frozen MACE acceleration choice."""

    import mdstats

    backend = str(_cfg(cfg, "acceleration", "backend", "e3nn")).strip().lower()
    if backend == "auto":
        raise CampaignCliError(
            "[acceleration].backend='auto' is not permitted in an active campaign. "
            "Run `init` to resolve the environment once, or choose 'cueq'/'e3nn' explicitly."
        )
    try:
        return mdstats.MaceAccelerationPolicy(
            backend=mdstats.MaceAccelerationBackend(backend),
            only_cueq=bool(_cfg(cfg, "acceleration", "only_cueq", False)),
            require_available=bool(_cfg(cfg, "acceleration", "require_available", True)),
        )
    except Exception as exc:
        raise CampaignCliError(f"Invalid [acceleration] policy: {exc}") from exc



def _training_acceleration_policy(cfg: Mapping[str, Any]) -> Any:
    """Return the protocol-frozen TRAIN2 acceleration choice.

    Revision-60 campaigns carry an explicit ``training_backend`` so source
    inference/DATA6/evaluation can remain e3nn while TRAIN2 uses pure CuEq.
    Historical campaigns without that key preserve their original unified
    backend semantics exactly.
    """

    import mdstats

    table = cfg.get("acceleration", {})
    if not isinstance(table, Mapping):
        raise CampaignCliError("[acceleration] must be a TOML table.")
    source_backend = str(table.get("backend", "e3nn")).strip().lower()
    backend = str(table.get("training_backend", source_backend)).strip().lower()
    if backend == "auto":
        raise CampaignCliError(
            "[acceleration].training_backend='auto' is not permitted in an active campaign. "
            "Choose 'cueq' or 'e3nn' explicitly."
        )
    try:
        return mdstats.MaceAccelerationPolicy(
            backend=mdstats.MaceAccelerationBackend(backend),
            only_cueq=bool(table.get("only_cueq", False)),
            require_available=bool(table.get("require_available", True)),
        )
    except Exception as exc:
        raise CampaignCliError(f"Invalid TRAIN2 [acceleration] policy: {exc}") from exc


def _phase_separated_acceleration(cfg: Mapping[str, Any]) -> bool:
    table = cfg.get("acceleration", {})
    return bool(isinstance(table, Mapping) and "training_backend" in table)


def _training_acceleration_parity_policy() -> Any:
    """Return the stable-channel TRAIN2/source CuEq/e3nn parity policy.

    Revision 86 restores the conventional FP32 ``rtol=1e-5, atol=1e-6``
    authority for energy/stress/descriptors.  Force parity is no longer
    authorized by this one-shot allclose policy; FP32 TRAIN2 force equivalence
    is governed by :func:`_training_acceleration_noise_normalized_policy`.
    """

    import mdstats

    return mdstats.MaceAccelerationParityPolicy(
        float32_rtol=1.0e-5,
        float32_atol=1.0e-6,
        float64_rtol=1.0e-10,
        float64_atol=1.0e-12,
    )


def _training_acceleration_noise_normalized_policy() -> Any:
    """Return the permanent TRAIN2 FP32 warm-up/all-pairs force parity policy."""

    import mdstats

    return mdstats.TrainingAccelerationNoiseNormalizedParityPolicy(
        repeat_count=10,
        warmup_count=1,
        stable_channel_abs_ceiling=1.0e-6,
        force_distribution_quantile=99.0,
        force_distribution_ratio_ceiling=1.25,
        force_max_self_factor=1.5,
        force_max_absolute_ceiling=1.0e-4,
        force_threshold=1.0e-5,
    )


_BINARY_PRECISION_DTYPES = {"single": "float32", "double": "float64"}
_RETIRED_PRECISION_PROFILES = {"refine", "mixed"}


def _legacy_precision_schedule_policy(cfg: Mapping[str, Any]) -> Any | None:
    """Deserialize the pre-ADAPT-PREC1 staged schedule without authorizing it.

    Historical schedule records remain readable for status/storage/reporting.  New
    production execution must use :func:`_binary_model_precision_contract`, which
    rejects staged/refine semantics and never returns this policy to DATA8/runtime.
    """

    import mdstats

    training = cfg.get("training", {})
    precision = training.get("precision")
    if precision is None:
        return None
    if not isinstance(precision, Mapping):
        raise CampaignCliError("[training.precision] must be a TOML table.")
    stage_payloads = precision.get("stage")
    if not isinstance(stage_payloads, list) or not stage_payloads:
        raise CampaignCliError(
            "[training.precision] requires one or more [[training.precision.stage]] tables."
        )
    try:
        stages = tuple(
            mdstats.PrecisionStage(
                dtype=str(item["dtype"]),
                fraction=float(item["fraction"]),
                learning_rate_scale=float(item.get("learning_rate_scale", 1.0)),
            )
            for item in stage_payloads
        )
        profile = str(_cfg(cfg, "campaign", "precision_profile", "custom")).strip() or "custom"
        policy = mdstats.PrecisionSchedulePolicy(
            requested_profile=profile,
            stages=stages,
            minimum_final_stage_epochs=int(precision.get("minimum_final_stage_epochs", 0)),
            minimum_final_stage_gradient_updates=int(
                precision.get("minimum_final_stage_gradient_updates", 0)
            ),
            preserve_optimizer_state=bool(precision.get("preserve_optimizer_state", True)),
            preserve_scheduler_state=bool(precision.get("preserve_scheduler_state", True)),
            preserve_ema_state=bool(precision.get("preserve_ema_state", True)),
            model_dtype=str(_cfg(cfg, "model", "dtype", training.get("dtype", "float32"))),
            critical_operation_dtype=str(
                precision.get("critical_operation_dtype", "float64")
            ),
            evaluation_dtype=str(_cfg(cfg, "evaluation", "dtype", training.get("dtype", "float32"))),
            verification_dtype=str(_cfg(cfg, "verification", "dtype", training.get("dtype", "float32"))),
            export_dtype=str(cfg.get("export", {}).get("dtype", training.get("dtype", "float32"))),
        )
    except Exception as exc:
        raise CampaignCliError(f"Invalid historical staged precision configuration: {exc}") from exc
    training_dtype = str(training.get("dtype", stages[0].dtype))
    if training_dtype != stages[0].dtype:
        raise CampaignCliError(
            "[training].dtype must equal the first historical [[training.precision.stage]].dtype."
        )
    mode = str(precision.get("mode", policy.mode))
    if mode != policy.mode:
        raise CampaignCliError(
            f"[training.precision].mode={mode!r} disagrees with the historical stage count; "
            f"expected {policy.mode!r}."
        )
    return policy


def _binary_model_precision_contract(
    cfg: Mapping[str, Any],
    *,
    allow_historical_refine: bool = False,
) -> dict[str, Any]:
    """Resolve the ADAPT-PREC1 learned-model dtype and validate all inference surfaces.

    The precision mode controls only learned-model arithmetic.  mdstats-owned critical
    reductions/statistics/MD bookkeeping remain FP64 and are not a user-selectable mode.
    """

    campaign = cfg.get("campaign", {})
    training = cfg.get("training", {})
    model = cfg.get("model", {})
    requested = campaign.get("precision_profile")
    requested_text = "" if requested is None else str(requested).strip().lower()

    historical = _legacy_precision_schedule_policy(cfg)
    if requested_text in _RETIRED_PRECISION_PROFILES or (
        historical is not None and len(historical.stages) > 1
    ):
        if allow_historical_refine:
            if historical is None:
                raise CampaignCliError(
                    "Historical staged precision evidence is incomplete: the configuration names "
                    f"{requested_text!r} but contains no explicit schedule."
                )
            return {
                "requested_profile": historical.requested_profile,
                "model_dtype": historical.model_dtype,
                "historical_schedule": historical,
                "historical_read_only": True,
            }
        raise CampaignCliError(
            "The staged `refine`/`mixed` precision mode is retired for production campaigns. "
            "Choose `single` (FP32 learned model) or `double` (FP64 learned model). "
            "Historical staged evidence remains readable through status/storage/reporting, "
            "but cannot be resumed or silently reinterpreted under the binary precision contract."
        )

    # Pre-PREC/one-stage configurations are scientifically equivalent when every
    # learned-model inference surface already agrees on one dtype.  Infer the binary
    # label only when the profile is absent/legacy; explicit unknown profile names fail.
    if requested_text in _BINARY_PRECISION_DTYPES:
        profile = requested_text
        expected_dtype = _BINARY_PRECISION_DTYPES[profile]
        source = "explicit"
    elif requested_text in {"", "legacy", "legacy_custom", "custom"}:
        inferred_dtype = str(training.get("dtype", model.get("dtype", "float32")))
        if inferred_dtype not in {"float32", "float64"}:
            raise CampaignCliError(f"Unsupported learned-model dtype {inferred_dtype!r}.")
        profile = "single" if inferred_dtype == "float32" else "double"
        expected_dtype = inferred_dtype
        source = "legacy_inferred"
    else:
        raise CampaignCliError(
            f"Unsupported precision profile {requested_text!r}. New campaigns support only "
            "`single` and `double`."
        )

    observed = {
        "[model].dtype": str(model.get("dtype", expected_dtype)),
        "[training].dtype": str(training.get("dtype", expected_dtype)),
        "[evaluation].dtype": str(cfg.get("evaluation", {}).get("dtype", expected_dtype)),
        "[verification].dtype": str(cfg.get("verification", {}).get("dtype", expected_dtype)),
        "[export].dtype": str(cfg.get("export", {}).get("dtype", expected_dtype)),
    }
    mismatches = [f"{name}={value!r}" for name, value in observed.items() if value != expected_dtype]
    if mismatches:
        raise CampaignCliError(
            f"Precision profile `{profile}` requires learned-model dtype {expected_dtype} for "
            "training and every model-inference/export surface; mismatches: " + ", ".join(mismatches)
        )

    # Old single/double TOMLs may still contain a one-stage [training.precision]
    # table. Validate it, but deliberately do not return it to DATA8/runtime; this
    # makes staged transition machinery unreachable from the binary production path.
    if historical is not None:
        if len(historical.stages) != 1:
            raise CampaignCliError("Binary precision cannot carry a staged training schedule.")
        stage = historical.stages[0]
        if stage.dtype != expected_dtype or abs(stage.fraction - 1.0) > 1.0e-12:
            raise CampaignCliError(
                "Historical one-stage precision metadata disagrees with the binary model dtype."
            )
        if abs(stage.learning_rate_scale - 1.0) > 1.0e-12:
            raise CampaignCliError(
                "Binary precision does not support a precision-stage learning-rate scale."
            )

    return {
        "requested_profile": profile,
        "model_dtype": expected_dtype,
        "source": source,
        "historical_schedule": historical,
        "historical_read_only": False,
    }


def _precision_schedule_policy(cfg: Mapping[str, Any]) -> None:
    """Validate ADAPT-PREC1 binary precision and return no executable schedule."""

    _binary_model_precision_contract(cfg)
    return None


def _critical_precision_policy(cfg: Mapping[str, Any]) -> Any:
    """Return invariant FP64 mdstats-owned scientific/critical arithmetic policy."""

    import mdstats

    _binary_model_precision_contract(cfg)
    return mdstats.MaceCriticalPrecisionPolicy()


def _precision_profile_payload(cfg: Mapping[str, Any]) -> dict[str, Any]:
    """Return one durable human-readable binary/historical precision summary."""

    import mdstats

    try:
        contract = _binary_model_precision_contract(cfg)
    except CampaignCliError:
        historical = _binary_model_precision_contract(cfg, allow_historical_refine=True)
        schedule = historical["historical_schedule"]
        preview = schedule.resolve(
            max_num_epochs=int(_cfg(cfg, "training", "max_num_epochs", 30)),
            require_update_floor=False,
        )
        return {
            "schema": "mdstats.mlff-precision-profile.v2",
            "requested_profile": schedule.requested_profile,
            "mode": "historical_staged_read_only",
            "model_dtype": schedule.model_dtype,
            "training_dtype": schedule.stages[0].dtype,
            "critical_operation_dtype": schedule.critical_operation_dtype,
            "evaluation_dtype": schedule.evaluation_dtype,
            "verification_dtype": schedule.verification_dtype,
            "export_dtype": schedule.export_dtype,
            "analysis_dtype": "float64",
            "historical_read_only": True,
            "policy_digest": schedule.policy_digest,
            "stages": [
                {
                    "index": int(index),
                    "dtype": stage.dtype,
                    "epoch_start": int(stage.start_epoch),
                    "epoch_stop": int(stage.stop_epoch),
                    "epoch_count": int(stage.epoch_count),
                    "learning_rate_scale": float(stage.learning_rate_scale),
                }
                for index, stage in enumerate(preview.stages)
            ],
        }

    dtype = str(contract["model_dtype"])
    payload_base = {
        "schema": "mdstats.mlff-binary-model-precision.v1",
        "requested_profile": str(contract["requested_profile"]),
        "model_dtype": dtype,
        "analysis_dtype": "float64",
        "source": str(contract["source"]),
    }
    return {
        "schema": "mdstats.mlff-precision-profile.v2",
        "requested_profile": str(contract["requested_profile"]),
        "mode": "binary_model_dtype",
        "model_dtype": dtype,
        "training_dtype": dtype,
        "critical_operation_dtype": "float64",
        "evaluation_dtype": dtype,
        "verification_dtype": dtype,
        "export_dtype": dtype,
        "analysis_dtype": "float64",
        "historical_read_only": False,
        "policy_digest": digest(payload_base),
        "stages": [],
    }


def _print_precision_profile(cfg: Mapping[str, Any], *, prefix: str = "precision") -> dict[str, Any]:
    payload = _precision_profile_payload(cfg)
    if payload.get("historical_read_only"):
        stages = payload["stages"]
        stage_text = " -> ".join(
            f"{item['epoch_count']}x{item['dtype']}@LRx{item['learning_rate_scale']:g}"
            for item in stages
        )
        _warn(
            f"{prefix}: historical read-only profile={payload['requested_profile']}; "
            f"training={stage_text}; model={payload['model_dtype']}; "
            "production resume is disabled under ADAPT-PREC1"
        )
        return payload
    _ok(
        f"{prefix}: profile={payload['requested_profile']}; model/training/inference/export="
        f"{payload['model_dtype']}; mdstats scientific arithmetic={payload['analysis_dtype']}"
    )
    return payload


def _optimizer_policy(
    cfg: Mapping[str, Any],
    *,
    seed: int,
    num_workers: int,
    paths: CampaignPaths | None = None,
) -> Any:
    """Build one protocol-frozen optimizer policy under binary model precision."""

    import mdstats

    contract = _binary_model_precision_contract(cfg)
    model_dtype = str(contract["model_dtype"])
    realization = None if paths is None else _stored_training_acceleration_realization(
        cfg, paths, require_qualified=True
    )
    training_acceleration = _training_acceleration_policy(cfg)
    return mdstats.MaceOptimizerPolicy(
        learning_rate=float(_cfg(cfg, "training", "learning_rate", 1.0e-4)),
        batch_size=int(_cfg(cfg, "training", "batch_size", 2)),
        valid_batch_size=int(_cfg(cfg, "training", "valid_batch_size", 2)),
        num_workers=num_workers,
        max_num_epochs=int(_cfg(cfg, "training", "max_num_epochs", 30)),
        eval_interval=int(_cfg(cfg, "training", "eval_interval", 1)),
        default_dtype=model_dtype,
        device=str(_cfg(cfg, "training", "device", "cuda")),
        seed=seed,
        critical_precision_policy=mdstats.MaceCriticalPrecisionPolicy(),
        acceleration_policy=training_acceleration,
        acceleration_realization_digest=(None if realization is None else realization.content_digest),
        resolved_acceleration_kernel_mode=(None if realization is None else realization.training_kernel_mode),
        precision_schedule_policy=None,
    )


def _training_policy_generation(cfg: Mapping[str, Any]) -> str:
    """Return immutable training-policy family for this campaign config.

    Absence is intentionally historical: campaign files created before TRAIN2A
    retain AdaptiveTrainingStopPolicy semantics. Newly generated configs write
    ``policy_generation = "train2"`` explicitly.
    """

    value = str(_cfg(cfg, "training", "policy_generation", "adaptive_stop_v3")).strip().lower()
    aliases = {
        "adaptive": "adaptive_stop_v3",
        "adaptive_stop": "adaptive_stop_v3",
        "adaptive_stop_v3": "adaptive_stop_v3",
        "legacy": "adaptive_stop_v3",
        "train2": "train2",
    }
    if value not in aliases:
        raise CampaignCliError(
            "[training].policy_generation must be 'train2' or historical 'adaptive_stop_v3'."
        )
    return aliases[value]


def _explicit_config_key(cfg: Mapping[str, Any], section: str, key: str) -> bool:
    table = cfg.get(section, {})
    return isinstance(table, Mapping) and key in table


def _validate_train2_migration_config(cfg: Mapping[str, Any]) -> None:
    """Fail closed when TRAIN2 is mixed with historical adaptive controls."""

    if _training_policy_generation(cfg) != "train2":
        return
    legacy = (
        ("training", "target_stop_fraction"),
        ("training", "replay_stop_multiplier"),
        ("training", "minimum_epochs_before_adaptive_stop"),
        ("training", "replay_degradation_budget_mev_per_a"),
        ("evaluation", "target_score_weight"),
        ("evaluation", "replay_score_weight"),
        ("acceptance", "maximum_replay_degradation_fraction"),
    )
    conflicts = [f"[{section}].{key}" for section, key in legacy if _explicit_config_key(cfg, section, key)]
    if conflicts:
        raise CampaignCliError(
            "TRAIN2 configuration cannot silently reinterpret historical adaptive-stop/"
            "replay-weighted controls. Remove or deliberately migrate: " + ", ".join(conflicts)
        )


def _train2_policy_set(cfg: Mapping[str, Any], *, require_replay: bool) -> tuple[Any, Any, Any, Any]:
    """Build the four orthogonal TRAIN2/EVAL2 policy authorities."""

    import mdstats

    _validate_train2_migration_config(cfg)
    if _training_policy_generation(cfg) != "train2":
        raise CampaignCliError("TRAIN2 policies requested for a historical adaptive campaign.")
    max_epochs = int(_cfg(cfg, "training", "max_num_epochs", 30))
    eval_interval = int(_cfg(cfg, "training", "eval_interval", 1))
    base_lr = float(_cfg(cfg, "training", "learning_rate", 1.0e-4))
    replay_budget_mev = float(
        _cfg(cfg, "acceptance", "allowed_replay_degradation_mev_per_a", 30.0)
    )
    budget = mdstats.TrainingBudgetPolicy(
        planned_epochs=max_epochs,
        checkpoint_interval_epochs=eval_interval,
        allow_performance_driven_termination=False,
    )
    lr = mdstats.LearningRateSchedulePolicy(
        base_learning_rate=base_lr,
        warmup_end_fraction=float(_cfg(cfg, "training", "train2_warmup_end_fraction", 0.05)),
        adaptation_end_fraction=float(_cfg(cfg, "training", "train2_adaptation_end_fraction", 0.80)),
        initial_multiplier=float(_cfg(cfg, "training", "train2_initial_lr_multiplier", 0.10)),
        adaptation_end_multiplier=float(_cfg(cfg, "training", "train2_refinement_start_lr_multiplier", 0.10)),
        final_multiplier=float(_cfg(cfg, "training", "train2_final_lr_multiplier", 0.01)),
        update_driven=True,
        validation_can_mutate_schedule=False,
        native_adaptive_scheduler_enabled=False,
    )
    admissibility = mdstats.CheckpointAdmissibilityPolicy(
        maximum_target_force_rmse_ev_per_angstrom=float(
            _cfg(cfg, "acceptance", "maximum_target_force_rmse_ev_per_angstrom", 0.030)
        ),
        replay_enabled=bool(require_replay),
        replay_degradation_budget_ev_per_angstrom=(
            replay_budget_mev / 1000.0 if require_replay else None
        ),
        replay_label_requirement="true_dft",
        required_physical_gates=(),
    )
    selection = mdstats.CheckpointSelectionPolicy(
        primary_target_metric=str(
            _cfg(cfg, "evaluation", "primary_target_metric", "target_force_rmse_ev_per_angstrom")
        ),
        initial_full_evaluation_candidates=int(_cfg(cfg, "evaluation", "finalist_count", 5)),
        refinement_reserved_candidates=int(
            _cfg(cfg, "evaluation", "refinement_reserved_candidates", 2)
        ),
        practical_equivalence_ev_per_angstrom=(
            float(_target_size_convergence_policy(cfg).practical_equivalence_mev_per_a) / 1000.0
        ),
        bootstrap_replicates=int(_cfg(cfg, "evaluation", "bootstrap_replicates", 2000)),
        bootstrap_confidence=float(_cfg(cfg, "evaluation", "bootstrap_confidence", 0.95)),
        bootstrap_min_independent_blocks=int(
            _cfg(cfg, "evaluation", "bootstrap_min_independent_blocks", 10)
        ),
    )
    return budget, lr, admissibility, selection


def _adaptive_training_stop_policy(
    cfg: Mapping[str, Any],
    *,
    replay_head_name: str = "pt_head",
) -> Any:
    """Build the ADAPT-STOP1 protocol-frozen force-RMSE stopping policy."""

    import mdstats

    maximum_target = float(
        _cfg(cfg, "acceptance", "maximum_target_force_rmse_ev_per_angstrom", 0.030)
    )
    replay_budget_mev = _cfg(cfg, "training", "replay_degradation_budget_mev_per_a", None)
    replay_budget_ev = None if replay_budget_mev is None else float(replay_budget_mev) / 1000.0
    return mdstats.AdaptiveTrainingStopPolicy(
        maximum_target_force_rmse_ev_per_angstrom=maximum_target,
        target_score_weight=float(_cfg(cfg, "evaluation", "target_score_weight", 1.0)),
        replay_score_weight=float(_cfg(cfg, "evaluation", "replay_score_weight", 1.0)),
        replay_degradation_budget_ev_per_angstrom=replay_budget_ev,
        target_stop_fraction=float(_cfg(cfg, "training", "target_stop_fraction", 0.80)),
        replay_stop_multiplier=float(_cfg(cfg, "training", "replay_stop_multiplier", 1.20)),
        minimum_epochs_before_adaptive_stop=int(
            _cfg(cfg, "training", "minimum_epochs_before_adaptive_stop", 3)
        ),
        max_num_epochs=int(_cfg(cfg, "training", "max_num_epochs", 30)),
        replay_enabled=True,
        replay_head_name=str(replay_head_name),
    )


def _precision_template(profile: str) -> dict[str, str]:
    """Resolve one ADAPT-PREC1 init profile into TOML-visible model dtypes."""

    normalized = str(profile).strip().lower()
    if normalized not in _BINARY_PRECISION_DTYPES:
        if normalized in _RETIRED_PRECISION_PROFILES:
            raise CampaignCliError(
                "The staged `refine`/`mixed` precision mode is retired. "
                "Choose `single` or `double`."
            )
        raise CampaignCliError(
            f"Unsupported precision profile {profile!r}; choose `single` or `double`."
        )
    dtype = _BINARY_PRECISION_DTYPES[normalized]
    return {
        "profile": normalized,
        "model_dtype": dtype,
        "training_dtype": dtype,
        "critical_dtype": "float64",
        "evaluation_dtype": dtype,
        "verification_dtype": dtype,
        "export_dtype": dtype,
    }


def _path_cfg(cfg: Mapping[str, Any], paths: CampaignPaths, key: str, *, required: bool = True) -> Path | None:
    value = _cfg(cfg, "paths", key)
    if value in (None, ""):
        if required:
            raise CampaignCliError(f"Missing [paths].{key} in {paths.config}.")
        return None
    return _resolve_path(value, paths.config_dir)


def _true_label_replay_root(
    cfg: Mapping[str, Any], paths: CampaignPaths
) -> Path | None:
    return _path_cfg(cfg, paths, "replay_true_labels", required=False)


def _resolve_true_label_replay_inputs(
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    *,
    require_train: bool,
) -> Any | None:
    import mdstats

    single = mdstats.single_source_replay_config_from_campaign(cfg, base_directory=paths.config_dir)
    if single is not None:
        context = _single_source_replay_context(cfg, paths)
        assert context is not None
        resolution = context["true_resolution"]
        if require_train and resolution.train_artifact is None:
            # Pseudo-label training intentionally has no true-label train transport
            # unless a caller explicitly requests it.  Build it lazily from the
            # exact same source/split authority when required.
            true_views = mdstats.materialize_replay_true_label_views(
                context["source"], context["true_cache"], context["split"],
                paths.internal / "replay-unified" / "views",
                roles=(mdstats.ReplaySplitRole.TRAIN, mdstats.ReplaySplitRole.MONITOR),
            )
            train_view = true_views[mdstats.ReplaySplitRole.TRAIN]
            monitor_view = true_views[mdstats.ReplaySplitRole.MONITOR]
            train_artifact = _inspect_unified_replay_artifact(
                Path(train_view.path), label_mode=mdstats.ReplayLabelMode.TRUE_DFT
            )
            monitor_artifact = _inspect_unified_replay_artifact(
                Path(monitor_view.path), label_mode=mdstats.ReplayLabelMode.TRUE_DFT
            )
            return mdstats.TrueLabelReplayResolution(
                root_directory=str(paths.internal / "replay-unified" / "views"),
                train_path=train_view.path, monitor_path=monitor_view.path,
                train_artifact=train_artifact, monitor_artifact=monitor_artifact,
                source_path=str(context["source"].path), materialized=True,
            )
        return resolution

    root = _true_label_replay_root(cfg, paths)
    if root is None:
        return None
    replay_train = _path_cfg(cfg, paths, "replay_train", required=require_train)
    replay_monitor = _path_cfg(cfg, paths, "replay_monitor")
    assert replay_monitor is not None
    try:
        return mdstats.resolve_true_label_replay_directory(
            root,
            replay_train_path=replay_train,
            replay_monitor_path=replay_monitor,
            output_directory=paths.internal / "true-label-replay",
            require_train=require_train,
        )
    except Exception as exc:
        raise CampaignCliError(f"Could not resolve [paths].replay_true_labels: {exc}") from exc


def _doctor_sample_atoms(cfg: Mapping[str, Any], paths: CampaignPaths) -> Any | None:
    """Load one real campaign geometry for an accelerator model smoke."""

    try:
        import numpy as np
        from ase.io import iread, read
    except Exception:
        return None
    replay = _path_cfg(cfg, paths, "replay_set", required=False)
    if replay is None:
        replay = _path_cfg(cfg, paths, "replay_train", required=False)
    if replay is not None and replay.is_file():
        try:
            # Replay corpora can include isolated atoms or molecular cells.  Use
            # the first fully periodic, finite-volume configuration so the same
            # smoke also verifies the stress path required by this campaign.
            for index, atoms in enumerate(iread(replay, index=":", format="extxyz")):
                if bool(np.all(atoms.pbc)) and float(abs(atoms.get_volume())) > 1.0e-12:
                    return atoms
                if index >= 255:
                    break
        except Exception:
            pass
    root = _path_cfg(cfg, paths, "training_root", required=False)
    if root is not None and root.is_dir():
        pattern = str(_cfg(cfg, "data", "discovery_pattern", "**/*.xml"))
        for candidate in sorted(root.glob(pattern)):
            try:
                return read(candidate, index=0, format="vasp-xml")
            except Exception:
                continue
    return None


def _sha256(path: str | Path) -> str:
    return sha256_file_cached(path)


def _stage_config_key(name: str) -> str:
    return f"stage_config_sha256:{name}"


def _mark_stage(
    store: CampaignStore,
    paths: CampaignPaths,
    name: str,
    state: StageState,
    message: str,
) -> None:
    """Persist a stage transition and bind completion to the current TOML bytes."""

    store.set_stage(name, state, message)
    store.set_meta(
        _stage_config_key(name),
        _sha256(paths.config) if state is StageState.COMPLETE else None,
    )


def _effective_stage(
    store: CampaignStore,
    paths: CampaignPaths,
    name: str,
) -> tuple[StageState, str]:
    state, message = store.stage(name)
    if state is StageState.COMPLETE:
        recorded = store.get_meta(_stage_config_key(name))
        current = _sha256(paths.config)
        if recorded != current:
            return (
                StageState.WAITING,
                "campaign.toml changed after this stage completed; rerun the stage before continuing",
            )
        if name == "preflight":
            if not store.has_record("preflight_smoke"):
                return (
                    StageState.WAITING,
                    "the DATA8-bound one-epoch MACE preflight smoke record is missing; rerun preflight",
                )
            smoke = store.get_payload("preflight_smoke")
            try:
                current_matrix = _data8_matrix_digest(_current_data8_entries(store))
            except Exception as exc:
                return (
                    StageState.WAITING,
                    f"prepared DATA8 identity cannot be restored ({exc}); rerun prepare then preflight",
                )
            if smoke.get("data8_matrix_digest") != current_matrix:
                return (
                    StageState.WAITING,
                    "prepared DATA8 variants changed after preflight; rerun preflight before training",
                )
    return state, message


def _require_stage_complete(
    store: CampaignStore,
    paths: CampaignPaths,
    name: str,
) -> None:
    state, message = _effective_stage(store, paths, name)
    if state is not StageState.COMPLETE:
        raise CampaignCliError(
            f"Stage `{name}` is not complete for the current campaign.toml ({message}). "
            f"Run `{name}` first, or use `status` for the next safe command."
        )


def _ensure_local_wrappers(paths: CampaignPaths) -> dict[str, Path]:
    """Create source-checkout shims with the exact qualified executable names."""
    wrapper_dir = paths.internal / "bin"
    wrapper_dir.mkdir(parents=True, exist_ok=True)
    targets = {
        "mdstats-mace-train": "train_main",
        "mdstats-mace-eval": "eval_main",
        "mdstats-mace-select-head": "select_head_main",
    }
    result: dict[str, Path] = {}
    for name, function in targets.items():
        target = wrapper_dir / name
        source_root = Path(__file__).resolve().parents[2]
        body = (
            f"#!{sys.executable}\n"
            "import sys\n"
            f"sys.path.insert(0, {str(source_root)!r})\n"
            "from mdstats.training_data.critical_precision_cli import " + function + "\n"
            f"raise SystemExit({function}())\n"
        )
        if not target.is_file() or target.read_text(encoding="utf-8") != body:
            target.write_text(body, encoding="utf-8")
            target.chmod(0o755)
        result[name] = target
    return result

def _historical_algorithm_evidence_keys(store: "CampaignStore") -> tuple[str, ...]:
    """Return preserved records produced by retired MLFF ranking/evaluation paths.

    ADAPT-MIGRATE1 treats these as historical evidence.  Merely becoming
    non-default never grants deletion authority.
    """

    prefixes = (
        "evaluation:",
        "multifidelity_policy:",
        "multifidelity_round:",
        "committee_member:",
    )
    exact = {"protocol_comparison", "committee"}
    if hasattr(store, "record_keys"):
        keys = tuple(store.record_keys())
    elif hasattr(store, "records") and isinstance(store.records, Mapping):
        keys = tuple(str(key) for key in store.records)
    else:
        keys = ()
    return tuple(
        sorted(
            key
            for key in keys
            if key in exact or any(key.startswith(prefix) for prefix in prefixes)
        )
    )


def _protocol_freeze_authority(store: "CampaignStore") -> Any | None:
    """Resolve historical, 0.20.127 adaptive-alias, or current freeze authority.

    Generic storage/reclamation code must validate the schema and digest rather
    than treating presence of the ``protocol_freeze`` key as sufficient proof.
    """

    import mdstats

    payload = store.get_payload_optional("protocol_freeze")
    if payload is None:
        return None
    try:
        return mdstats.protocol_freeze_authority_from_payload(payload)
    except Exception as exc:
        raise CampaignCliError(
            "The generic protocol_freeze authority record is malformed or uses an "
            f"unsupported schema: {exc}"
        ) from exc


def _read_storage_migration_summary(
    state_db: Path,
) -> tuple[Any | None, tuple[str, ...]]:
    """Read freeze/historical summary without mutating the campaign state DB."""

    if not state_db.is_file():
        return None, ()
    import mdstats

    uri = f"file:{state_db.resolve()}?mode=ro"
    try:
        db = sqlite3.connect(uri, uri=True, timeout=30.0)
        try:
            row = db.execute(
                "SELECT payload FROM records WHERE key='protocol_freeze'"
            ).fetchone()
            key_rows = db.execute("SELECT key FROM records ORDER BY key").fetchall()
        finally:
            db.close()
    except sqlite3.Error as exc:
        raise CampaignCliError(
            f"Could not read campaign migration/storage authority state: {exc}"
        ) from exc
    authority = None
    if row is not None:
        try:
            payload = json.loads(row[0])
            if not isinstance(payload, Mapping):
                raise TypeError("protocol_freeze payload is not a mapping")
            # Protocol freeze records are intentionally compact and never externalized.
            if payload.get("schema") == EXTERNAL_RECORD_POINTER_SCHEMA:
                raise TypeError("protocol_freeze unexpectedly uses an external pointer")
            authority = mdstats.protocol_freeze_authority_from_payload(payload)
        except Exception as exc:
            raise CampaignCliError(
                f"Stored protocol-freeze authority is unreadable: {exc}"
            ) from exc
    keys = tuple(str(row[0]) for row in key_rows)
    prefixes = (
        "evaluation:", "multifidelity_policy:", "multifidelity_round:", "committee_member:",
    )
    exact = {
        "protocol_comparison", "committee", "adaptive_full_evaluation",
        "adaptive_verification", "adaptive_deployment_model",
        "adaptive_protocol_freeze", "adaptive_migration",
    }
    historical = tuple(
        key for key in keys if key in exact or any(key.startswith(prefix) for prefix in prefixes)
    )
    return authority, historical


def _has_authoritative_protocol_freeze(store: "CampaignStore") -> bool:
    return _protocol_freeze_authority(store) is not None


def _campaign_training_policy_family(campaign: Any) -> str:
    """Classify immutable run protocols without reinterpreting historical evidence."""

    runs = tuple(getattr(campaign, "runs", ()))
    if not runs:
        return "historical"
    adaptive = tuple(
        getattr(getattr(run, "protocol", None), "adaptive_stop_policy", None) is not None
        for run in runs
    )
    train2 = tuple(
        getattr(getattr(run, "protocol", None), "training_budget_policy", None) is not None
        for run in runs
    )
    if any(a and t for a, t in zip(adaptive, train2)):
        raise CampaignCliError("A run cannot carry both adaptive-stop and TRAIN2 authority.")
    families = set()
    for a, t in zip(adaptive, train2):
        families.add("adaptive_stop_v3" if a else "train2" if t else "historical")
    if len(families) != 1:
        raise CampaignCliError(
            "Campaign contains mixed historical/adaptive/TRAIN2 protocol identities; "
            "refusing to infer one training/evaluation semantics."
        )
    return next(iter(families))


def _campaign_uses_adaptive_training(campaign: Any) -> bool:
    """Compatibility helper for the historical ADAPT/MLCV lifecycle."""

    return _campaign_training_policy_family(campaign) == "adaptive_stop_v3"


def _enforce_evaluation_migration_boundary(
    campaign: Any,
    checkpoint_strategy: str,
    mlcv_authority: Any | None = None,
) -> None:
    """Bind evaluator semantics to immutable campaign lifecycle authority.

    MLCV-MIGRATE1 makes conventional nested-CV a distinct authority family.
    Once that authority exists, TOML can no longer redirect the same campaign
    to historical ADAPT-EVAL1 or legacy evaluators. Transitional 0.20.131-138 campaigns carrying both ROLE1 and MON1 authority
    may retain the exact ``adaptive_topk`` spelling they were created
    with, but it is treated only as a recorded alias for the frozen MLCV path.
    """

    strategy = str(checkpoint_strategy).strip().lower()
    if mlcv_authority is not None:
        if mlcv_authority.campaign_plan_digest != campaign.content_digest:
            raise CampaignCliError("MLCV lifecycle authority belongs to another campaign plan.")
        if not mlcv_authority.permits_config_strategy(strategy):
            raise CampaignCliError(
                "This campaign is frozen to conventional MLCV nested-CV authority "
                f"({mlcv_authority.checkpoint_strategy!r}); TOML checkpoint_strategy={strategy!r} "
                "cannot redirect it to fold-winner deployment, ADAPT-EVAL1, or a historical evaluator."
            )
        return

    adaptive = _campaign_uses_adaptive_training(campaign)
    if adaptive and strategy != "adaptive_topk":
        raise CampaignCliError(
            "This pre-MLCV adaptive campaign was prepared with the historical STOP1/RANK1 "
            "authority, so evaluation must use checkpoint_strategy='adaptive_topk'. "
            "It cannot be migrated to conventional nested-CV semantics without a new "
            "MLCV lifecycle identity."
        )
    if not adaptive and strategy in {"adaptive_topk", "mlcv_nested_cv"}:
        raise CampaignCliError(
            "This campaign predates adaptive/MLCV protocol identity and cannot be resumed "
            "under a newer evaluator without a new scientific campaign identity. Keep its "
            "historical evaluator for reporting, or prepare a new campaign."
        )


def _reuse_frozen_adaptive_evaluation(
    paths: "CampaignPaths", store: "CampaignStore"
) -> bool:
    """Refuse to mutate EVAL1 evidence after adaptive deployment is frozen.

    A completed adaptive protocol freeze is the scientific authority boundary.  Once
    present, a later ``evaluate`` invocation may only authenticate/reuse the frozen
    EVAL1 record; configuration edits must not create a second selection history under
    the same campaign identity.
    """

    import mdstats

    freeze = store.get_record_optional(
        "adaptive_protocol_freeze", mdstats.AdaptiveProtocolFreezeRecord
    )
    if freeze is None:
        return False
    evaluation = store.get_record_optional(
        "adaptive_full_evaluation", mdstats.AdaptiveFullEvaluationRecord
    )
    if evaluation is None:
        raise CampaignCliError(
            "Adaptive protocol freeze exists but authoritative ADAPT-EVAL1 evidence is missing."
        )
    if freeze.adaptive_full_evaluation_digest != evaluation.content_digest:
        raise CampaignCliError(
            "Adaptive protocol freeze/full-evaluation digest mismatch; refusing stale evaluation evidence."
        )
    _reconcile_adaptive_migration(paths, store)
    _mark_stage(
        store,
        paths,
        "evaluate",
        StageState.COMPLETE,
        "ADAPT-EVAL1 is immutable because the adaptive deployment protocol is already frozen",
    )
    _ok(
        "reused frozen ADAPT-EVAL1 authority; post-freeze configuration edits do not rerun evaluation"
    )
    return True


def _reconcile_adaptive_migration(
    paths: "CampaignPaths", store: "CampaignStore"
) -> Any | None:
    """Close the ADAPT-MIGRATE1 authority bridge for a verified adaptive campaign.

    This is intentionally idempotent.  It upgrades only the *generic authority
    alias* used by storage/lifecycle consumers; the original adaptive freeze and
    every historical record remain byte-for-byte scientific evidence.
    """

    import mdstats

    freeze = store.get_record_optional(
        "adaptive_protocol_freeze", mdstats.AdaptiveProtocolFreezeRecord
    )
    if freeze is None:
        return None
    evaluation = store.get_record_optional(
        "adaptive_full_evaluation", mdstats.AdaptiveFullEvaluationRecord
    )
    verification = store.get_record_optional(
        "adaptive_verification", mdstats.AdaptiveVerificationRecord
    )
    deployment = store.get_record_optional(
        "adaptive_deployment_model", mdstats.AdaptiveDeploymentModelRecord
    )
    if evaluation is None or verification is None or deployment is None:
        raise CampaignCliError(
            "Adaptive protocol freeze exists without complete EVAL1/VERIFY1/deployment "
            "lineage. Refusing partial migration."
        )
    if not (
        freeze.campaign_plan_digest == evaluation.campaign_plan_digest
        == verification.campaign_plan_digest
        == deployment.campaign_plan_digest
    ):
        raise CampaignCliError("Adaptive migration campaign lineage mismatch.")
    if freeze.adaptive_full_evaluation_digest != evaluation.content_digest:
        raise CampaignCliError("Adaptive migration full-evaluation lineage mismatch.")
    if freeze.adaptive_verification_digest != verification.content_digest:
        raise CampaignCliError("Adaptive migration verification lineage mismatch.")
    if freeze.adaptive_deployment_model_digest != deployment.content_digest:
        raise CampaignCliError("Adaptive migration deployment lineage mismatch.")
    if freeze.exported_model_sha256 != deployment.exported_model_sha256:
        raise CampaignCliError("Adaptive migration published-model SHA-256 mismatch.")

    existing = store.get_record_optional(
        "adaptive_migration", mdstats.AdaptiveMigrationRecord
    )
    alias_payload = store.get_payload_optional("protocol_freeze")
    alias_schema = None if alias_payload is None else str(alias_payload.get("schema"))

    if existing is not None:
        authority = _protocol_freeze_authority(store)
        if authority is None:
            raise CampaignCliError(
                "ADAPT-MIGRATE1 closure exists but protocol-freeze authority disappeared."
            )
        if existing.protocol_freeze_authority_digest != authority.content_digest:
            raise CampaignCliError(
                "ADAPT-MIGRATE1 closure/authority digest mismatch; refusing stale evidence."
            )
        if existing.adaptive_protocol_freeze_digest != freeze.content_digest:
            raise CampaignCliError(
                "ADAPT-MIGRATE1 closure points at a different adaptive freeze."
            )
        return existing

    if alias_payload is not None and alias_schema == mdstats.PROTOCOL_FREEZE_RECORD_SCHEMA:
        raise CampaignCliError(
            "A historical committee protocol freeze and an adaptive protocol freeze both "
            "claim generic authority in the same campaign. Refusing ambiguous migration."
        )
    if alias_payload is not None and alias_schema not in {
        mdstats.ADAPTIVE_PROTOCOL_FREEZE_SCHEMA,
        mdstats.PROTOCOL_FREEZE_AUTHORITY_SCHEMA,
    }:
        raise CampaignCliError(
            f"Unsupported generic protocol-freeze authority schema during migration: {alias_schema!r}."
        )

    authority = mdstats.protocol_freeze_authority_from_adaptive(freeze)
    if alias_schema == mdstats.PROTOCOL_FREEZE_AUTHORITY_SCHEMA:
        current = mdstats.ProtocolFreezeAuthorityRecord.from_dict(alias_payload)
        if current.content_digest != authority.content_digest:
            raise CampaignCliError(
                "Existing protocol-freeze authority disagrees with adaptive freeze evidence."
            )
    else:
        # 0.20.127a0 stored the adaptive scientific freeze itself under this
        # generic key. Replace only that alias; keep adaptive_protocol_freeze.
        store.put_record("protocol_freeze", authority)

    record = mdstats.AdaptiveMigrationRecord(
        campaign_plan_digest=freeze.campaign_plan_digest,
        adaptive_full_evaluation_digest=evaluation.content_digest,
        adaptive_verification_digest=verification.content_digest,
        adaptive_deployment_model_digest=deployment.content_digest,
        adaptive_protocol_freeze_digest=freeze.content_digest,
        protocol_freeze_authority_digest=authority.content_digest,
        model_inference_dtype=freeze.model_inference_dtype,
        scientific_analysis_dtype=freeze.scientific_analysis_dtype,
        historical_evidence_keys=_historical_algorithm_evidence_keys(store),
        migrated_at_utc=freeze.frozen_at_utc,
        migrated_legacy_protocol_freeze_alias_schema=(
            mdstats.ADAPTIVE_PROTOCOL_FREEZE_SCHEMA
            if alias_schema == mdstats.ADAPTIVE_PROTOCOL_FREEZE_SCHEMA
            else None
        ),
    )
    store.put_record("adaptive_migration", record)
    result_path = paths.results / "adaptive-migration.json"
    _atomic_json(result_path, record.to_dict())
    event = getattr(store, "event", None)
    if callable(event):
        event(
            "info",
            "migration",
            "ADAPT-MIGRATE1 closed schema/restart/storage authority migration",
        )
    return record



def _reconcile_mlcv_lifecycle_authority(
    campaign: Any,
    data8_bundles: Sequence[Any],
    store: "CampaignStore",
    *,
    requested_checkpoint_strategy: str,
) -> Any | None:
    """Create/read the immutable conventional-CV evaluator-family identity."""

    import mdstats

    existing = store.get_record_optional(
        "mlcv_lifecycle_authority", mdstats.MlcvLifecycleAuthorityRecord
    )
    source_strategy = str(requested_checkpoint_strategy).strip().lower()
    candidate = mdstats.build_mlcv_lifecycle_authority(
        campaign, data8_bundles, source_checkpoint_strategy=source_strategy
    )
    if existing is None:
        if candidate is not None:
            store.put_record("mlcv_lifecycle_authority", candidate)
            event = getattr(store, "event", None)
            if callable(event):
                event("info", "migration", "MLCV lifecycle authority frozen")
        return candidate
    if candidate is None:
        raise CampaignCliError(
            "MLCV lifecycle authority exists but current DATA8 bundles no longer carry MLCV ROLE1/MON1 evidence."
        )
    # A replay-semantics schema transition is never an in-place reinterpretation.
    # Preserve the old lifecycle record under a content-addressed historical key,
    # then install the new authority only when immutable ROLE1/MON1 identities still
    # match.  A new campaign-plan digest is expected because the STOP/RANK/SELECT
    # policy digests changed in 0.20.140a0.
    identities_match = (
        existing.role_catalog_digests == candidate.role_catalog_digests
        and existing.monitor_catalog_digests == candidate.monitor_catalog_digests
        and existing.checkpoint_strategy == candidate.checkpoint_strategy
        and existing.candidate_limit_per_run == candidate.candidate_limit_per_run
    )
    if getattr(existing, "serialization_schema", "") != mdstats.MLCV_LIFECYCLE_AUTHORITY_SCHEMA:
        if not identities_match:
            raise CampaignCliError(
                "Historical MLCV lifecycle authority cannot be migrated because immutable ROLE1/MON1 identities changed."
            )
        historical_key = f"historical_mlcv_lifecycle_authority:{existing.content_digest}"
        if not store.has_record(historical_key):
            store.put_record(historical_key, existing)
        store.put_record("mlcv_lifecycle_authority", candidate)
        event = getattr(store, "event", None)
        if callable(event):
            event(
                "info", "migration",
                "MLCV lifecycle authority advanced to replay-degradation semantics; historical authority preserved read-only",
            )
        return candidate
    if existing.campaign_plan_digest != campaign.content_digest:
        raise CampaignCliError("Stored MLCV lifecycle authority belongs to another campaign.")
    # Same-generation exact restart: source alias may differ, but immutable
    # role/monitor identities and canonical authority must remain exact.
    if not identities_match:
        raise CampaignCliError("Stored MLCV lifecycle authority disagrees with immutable DATA8 role/monitor evidence.")
    return existing


def _pre_mlcv_evidence_keys(store: "CampaignStore") -> tuple[str, ...]:
    """Return legacy evaluator evidence that MIGRATE1 must preserve read-only."""

    keys = tuple(store.record_keys()) if hasattr(store, "record_keys") else ()
    historical = set(_historical_algorithm_evidence_keys(store))
    historical.update(
        key for key in keys
        if key in {
            "adaptive_full_evaluation", "adaptive_verification", "adaptive_deployment_model",
            "adaptive_protocol_freeze", "adaptive_migration",
        }
        or key.startswith("multifidelity_")
        or key.startswith("committee_member:")
    )
    return tuple(sorted(historical))


def _reconcile_mlcv_migration(
    paths: "CampaignPaths", store: "CampaignStore", campaign: Any
) -> Any | None:
    """Freeze ROLE1->VERIFY1 authority and generic storage ownership for MLCV."""

    import mdstats


    lifecycle = store.get_record_optional(
        "mlcv_lifecycle_authority", mdstats.MlcvLifecycleAuthorityRecord
    )
    production = store.get_record_optional(
        "mlcv_production_model", mdstats.MlcvProductionModelRecord
    )
    if lifecycle is None or production is None:
        return None
    if lifecycle.campaign_plan_digest != campaign.content_digest or production.campaign_plan_digest != campaign.content_digest:
        raise CampaignCliError("MLCV-MIGRATE1 campaign lineage mismatch.")

    qualification = store.get_record(
        "production_qualification", mdstats.ProductionCorpusQualificationRecord
    )
    campaign_cv = store.get_record("mlcv_campaign_cv", mdstats.MlcvCampaignCvAggregateRecord)
    final_selection = store.get_record("mlcv_final_selection", mdstats.MlcvFinalSelectionRecord)
    committee = store.get_record("mlcv_final_committee", mdstats.MlcvFinalCommitteeRecord)
    verification = store.get_record("mlcv_verification", mdstats.MlcvVerificationRecord)
    locked = store.get_record("mlcv_locked_test", mdstats.MlcvLockedTestRecord)

    if production.final_selection_record_digest != final_selection.content_digest:
        raise CampaignCliError("MLCV-MIGRATE1 production/final-selection lineage mismatch.")
    if production.verification_record_digest != verification.content_digest:
        raise CampaignCliError("MLCV-MIGRATE1 production/verification lineage mismatch.")
    if production.locked_test_record_digest != locked.content_digest:
        raise CampaignCliError("MLCV-MIGRATE1 production/locked-E lineage mismatch.")
    if verification.final_committee_record_digest != committee.content_digest:
        raise CampaignCliError("MLCV-MIGRATE1 verification/committee lineage mismatch.")
    if final_selection.campaign_cv_aggregate_digest != campaign_cv.content_digest:
        raise CampaignCliError("MLCV-MIGRATE1 final-selection/CV lineage mismatch.")
    current_schema_checks = (
        (lifecycle.serialization_schema, mdstats.MLCV_LIFECYCLE_AUTHORITY_SCHEMA, "lifecycle"),
        (campaign_cv.serialization_schema, mdstats.MLCV_CAMPAIGN_CV_AGGREGATE_SCHEMA, "AGG1"),
        (final_selection.serialization_schema, mdstats.MLCV_FINAL_SELECTION_RECORD_SCHEMA, "FINAL1 selection"),
        (committee.serialization_schema, mdstats.MLCV_FINAL_COMMITTEE_SCHEMA, "FINAL1 committee"),
    )
    stale = [name for observed, expected, name in current_schema_checks if observed != expected]
    if stale:
        raise CampaignCliError(
            "MLCV-MIGRATE1 refuses historical absolute-replay derived evidence; regenerate replay-dependent "
            "authority before freezing: " + ", ".join(stale)
        )

    ranking_records = []
    selection_records = []
    protected_checkpoints: set[str] = set()
    for run in campaign.runs:
        ranking = store.get_record(f"lightweight_rank:{run.run_id}", mdstats.LightweightRunChampionRecord)
        if ranking.serialization_schema != mdstats.LIGHTWEIGHT_RUN_CHAMPION_SCHEMA:
            raise CampaignCliError("MLCV-MIGRATE1 requires replay-degradation top-five ranking evidence for every run.")
        if ranking.run_plan_digest != run.content_digest:
            raise CampaignCliError(f"MLCV-MIGRATE1 ranking lineage mismatch for {run.run_id}.")
        ranking_records.append(ranking)
        protected_checkpoints.update(v.checkpoint_sha256 for v in ranking.eligible_candidates)
        selection = store.get_record(f"mlcv_run_selection:{run.run_id}", mdstats.MlcvRunSelectionRecord)
        if selection.serialization_schema != mdstats.MLCV_RUN_SELECTION_RECORD_SCHEMA:
            raise CampaignCliError(
                f"MLCV-MIGRATE1 requires replay-degradation SELECT1 evidence for {run.run_id}."
            )
        if selection.run_plan_digest != run.content_digest:
            raise CampaignCliError(f"MLCV-MIGRATE1 SELECT1 lineage mismatch for {run.run_id}.")
        selection_records.append(selection)
        if selection.representative_candidate is not None:
            protected_checkpoints.add(selection.representative_candidate.checkpoint_sha256)

    protected_models = {production.exported_model_sha256}
    protected_models.update(v.exported_model_sha256 for v in committee.members)
    freeze = mdstats.MlcvProtocolFreezeRecord(
        production_qualification_digest=qualification.content_digest,
        campaign_plan_digest=campaign.content_digest,
        lifecycle_authority_digest=lifecycle.content_digest,
        lightweight_ranking_record_digests=tuple(sorted(v.content_digest for v in ranking_records)),
        run_selection_record_digests=tuple(sorted(v.content_digest for v in selection_records)),
        campaign_cv_aggregate_digest=campaign_cv.content_digest,
        final_selection_record_digest=final_selection.content_digest,
        final_committee_record_digest=committee.content_digest,
        verification_record_digest=verification.content_digest,
        locked_test_record_digest=locked.content_digest,
        production_model_record_digest=production.content_digest,
        protected_checkpoint_sha256=tuple(sorted(protected_checkpoints)),
        protected_model_sha256=tuple(sorted(protected_models)),
        model_inference_dtype=production.model_inference_dtype,
        scientific_analysis_dtype=production.scientific_analysis_dtype,
        frozen_at_utc=_utc_now(),
    )
    existing_freeze = store.get_record_optional(
        "mlcv_protocol_freeze", mdstats.MlcvProtocolFreezeRecord
    )
    if existing_freeze is not None:
        # Timestamp is part of the scientific freeze; exact restart reuses it.
        freeze = existing_freeze
        if (
            freeze.campaign_plan_digest != campaign.content_digest
            or freeze.lifecycle_authority_digest != lifecycle.content_digest
            or freeze.production_model_record_digest != production.content_digest
            or freeze.final_selection_record_digest != final_selection.content_digest
            or freeze.verification_record_digest != verification.content_digest
            or freeze.locked_test_record_digest != locked.content_digest
        ):
            raise CampaignCliError("Existing MLCV protocol freeze disagrees with current verified evidence.")
    else:
        store.put_record("mlcv_protocol_freeze", freeze)

    alias_payload = store.get_payload_optional("protocol_freeze")
    authority = mdstats.protocol_freeze_authority_from_mlcv(freeze)
    if alias_payload is not None:
        current = mdstats.protocol_freeze_authority_from_payload(alias_payload)
        if current.authority_kind != "mlcv_deployment" or current.content_digest != authority.content_digest:
            raise CampaignCliError(
                "Another historical/adaptive protocol freeze already claims generic authority; refusing dual-authority MLCV migration."
            )
    else:
        store.put_record("protocol_freeze", authority)

    existing = store.get_record_optional("mlcv_migration", mdstats.MlcvMigrationRecord)
    if existing is not None:
        if (
            existing.lifecycle_authority_digest != lifecycle.content_digest
            or existing.mlcv_protocol_freeze_digest != freeze.content_digest
            or existing.protocol_freeze_authority_digest != authority.content_digest
        ):
            raise CampaignCliError("Existing MLCV-MIGRATE1 closure disagrees with frozen authority.")
        return existing

    migration = mdstats.MlcvMigrationRecord(
        campaign_plan_digest=campaign.content_digest,
        lifecycle_authority_digest=lifecycle.content_digest,
        mlcv_protocol_freeze_digest=freeze.content_digest,
        protocol_freeze_authority_digest=authority.content_digest,
        historical_evidence_keys=_pre_mlcv_evidence_keys(store),
        migrated_at_utc=freeze.frozen_at_utc,
    )
    store.put_record("mlcv_migration", migration)
    _atomic_json(paths.results / "mlcv-migration.json", migration.to_dict())
    event = getattr(store, "event", None)
    if callable(event):
        event("info", "migration", "MLCV-MIGRATE1 closed conventional-CV lifecycle migration")
    return migration

def _atomic_json(path: Path, payload: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + ".tmp")
    temp.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    os.replace(temp, path)


def _update_benchmark(paths: CampaignPaths, stage: str, payload: Mapping[str, Any]) -> None:
    target = paths.results / "campaign-benchmark.json"
    current: dict[str, Any] = {}
    if target.is_file():
        current = json.loads(target.read_text(encoding="utf-8"))
    current.update({"schema": "mdstats.mlff-campaign-benchmark.v1", "updated_utc": _utc_now()})
    stages = current.setdefault("stages", {})
    stages[stage] = dict(payload)
    _atomic_json(target, current)


def _print_header(title: str) -> None:
    print(f"\n{title}\n{'-' * len(title)}", flush=True)


def _ok(message: str) -> None:
    print(f"[PASS] {message}", flush=True)


def _warn(message: str) -> None:
    print(f"[WARN] {message}", flush=True)


def _fail(message: str) -> None:
    print(f"[FAIL] {message}", flush=True)


def _print_metric_summary(prefix: str, label: str, stats: Mapping[str, float]) -> None:
    print(
        f"{prefix} {label}: min={stats['min']:.3e}, median={stats['median']:.3e}, "
        f"p90={stats['p90']:.3e}, p99={stats.get('p99', stats['max']):.3e}, max={stats['max']:.3e}",
        flush=True,
    )


def _print_count_summary(prefix: str, label: str, values: Sequence[int], component_count: int) -> None:
    counts = np.asarray(values, dtype=np.float64)
    print(
        f"{prefix} {label}: min={int(np.min(counts))}, median={float(np.median(counts)):.1f}, "
        f"p90={float(np.percentile(counts, 90.0)):.1f}, p99={float(np.percentile(counts, 99.0)):.1f}, "
        f"max={int(np.max(counts))} of {component_count}",
        flush=True,
    )


def _print_training_repeatability_diagnostic(record: Any, *, prefix: str = "[DIAG]", title: str = "TRAIN2 FP32 repeatability (non-authorizing)") -> None:
    """Print warm-up/all-pairs or historical baseline repeatability statistics."""

    print(
        f"{prefix} {title}: repeats={record.repeat_count}, warmups={getattr(record, 'warmup_count', 0)}, "
        f"mode={getattr(record, 'comparison_mode', 'baseline')}, structures={record.structure_count}, "
        f"atoms={record.atom_count}, force_threshold={record.force_threshold:.1e}", flush=True,
    )
    print(
        f"{prefix} determinism: torch_deterministic_algorithms={record.torch_deterministic_algorithms}, "
        f"debug_mode={record.torch_deterministic_debug_mode}, cudnn_deterministic={record.cudnn_deterministic}, "
        f"CUBLAS_WORKSPACE_CONFIG={record.cublas_workspace_config or '<unset>'}", flush=True,
    )
    print(
        f"{prefix} comparison counts: e3nn-self={record.self_pair_count}, "
        f"CuEq-self={record.self_pair_count}, cross={record.cross_pair_count}", flush=True,
    )

    # Historical v1 records used one paired cross comparison per run and are
    # still printed run-by-run.  DIAG3 all-pairs records contain 100 cross
    # comparisons for N=10, so emit distribution summaries instead of noise.
    if getattr(record, "comparison_mode", "baseline") == "baseline":
        for index in range(record.cross_pair_count):
            print(
                f"{prefix} cross {index + 1:02d}/{record.cross_pair_count:02d}: "
                f"Emax={record.cross_energy_max_abs[index]:.3e}, Fmax={record.cross_force_max_abs[index]:.3e}, "
                f"Frmse={record.cross_force_rmse[index]:.3e}, Fp99={record.cross_force_p99_abs[index]:.3e}, "
                f"Fp99.9={record.cross_force_p999_abs[index]:.3e}, "
                f"F>{record.force_threshold:.1e}={record.cross_force_above_threshold_count[index]}/"
                f"{record.cross_force_component_count}, Smax={record.cross_stress_max_abs[index]:.3e}, "
                f"Dmax={record.cross_descriptor_max_abs[index]:.3e}, "
                f"selection_identical={record.cross_selection_identical[index]}", flush=True,
            )

    summaries = record.summaries
    for label, key in (
        ("e3nn-self Fmax", "e3nn_self_force_max_abs"),
        ("e3nn-self Frmse", "e3nn_self_force_rmse"),
        ("CuEq-self Fmax", "cueq_self_force_max_abs"),
        ("CuEq-self Frmse", "cueq_self_force_rmse"),
    ):
        _print_metric_summary(prefix, label, summaries[key])
    if record.self_detail_available:
        for label, key in (
            ("e3nn-self Fp99", "e3nn_self_force_p99_abs"),
            ("e3nn-self Fp99.9", "e3nn_self_force_p999_abs"),
            ("CuEq-self Fp99", "cueq_self_force_p99_abs"),
            ("CuEq-self Fp99.9", "cueq_self_force_p999_abs"),
        ):
            _print_metric_summary(prefix, label, summaries[key])
        _print_count_summary(prefix, f"e3nn-self F>{record.force_threshold:.1e}",
            record.e3nn_self_force_above_threshold_count, record.cross_force_component_count)
        _print_count_summary(prefix, f"CuEq-self F>{record.force_threshold:.1e}",
            record.cueq_self_force_above_threshold_count, record.cross_force_component_count)
    if getattr(record, "self_channel_detail_available", False):
        for label, key in (
            ("e3nn-self Emax", "e3nn_self_energy_max_abs"),
            ("e3nn-self Smax", "e3nn_self_stress_max_abs"),
            ("e3nn-self Dmax", "e3nn_self_descriptor_max_abs"),
            ("CuEq-self Emax", "cueq_self_energy_max_abs"),
            ("CuEq-self Smax", "cueq_self_stress_max_abs"),
            ("CuEq-self Dmax", "cueq_self_descriptor_max_abs"),
        ):
            _print_metric_summary(prefix, label, summaries[key])
        print(
            f"{prefix} self selection_identical: e3nn={sum(record.e3nn_self_selection_identical)}/"
            f"{record.self_pair_count}, CuEq={sum(record.cueq_self_selection_identical)}/{record.self_pair_count}",
            flush=True,
        )
    for label, key in (
        ("cross Fmax", "cross_force_max_abs"), ("cross Frmse", "cross_force_rmse"),
        ("cross Fp99", "cross_force_p99_abs"), ("cross Fp99.9", "cross_force_p999_abs"),
        ("cross Emax", "cross_energy_max_abs"), ("cross Smax", "cross_stress_max_abs"),
        ("cross Dmax", "cross_descriptor_max_abs"),
    ):
        _print_metric_summary(prefix, label, summaries[key])
    _print_count_summary(prefix, f"cross F>{record.force_threshold:.1e}",
        record.cross_force_above_threshold_count, record.cross_force_component_count)
    print(
        f"{prefix} cross selection_identical={sum(record.cross_selection_identical)}/{record.cross_pair_count}",
        flush=True,
    )


def _print_training_deterministic_control_diagnostic(record: Any) -> None:
    prefix = "[DIAG-DET]"
    print(
        f"{prefix} isolated deterministic control: status={record.status}, repeats={record.repeat_count}, "
        f"CUBLAS_WORKSPACE_CONFIG={record.cublas_workspace_config}",
        flush=True,
    )
    if record.status == "completed" and record.repeatability is not None:
        _print_training_repeatability_diagnostic(
            record.repeatability,
            prefix=prefix,
            title="TRAIN2 FP32 deterministic-control repeatability (non-authorizing)",
        )
    else:
        print(
            f"{prefix} deterministic control unsupported/failed: "
            f"{record.error_type or 'unknown'}: {record.error_message or 'no message'}",
            flush=True,
        )
        if record.worker_stderr_tail:
            tail = " ".join(record.worker_stderr_tail.strip().splitlines()[-4:])
            if tail:
                print(f"{prefix} worker stderr tail: {tail}", flush=True)


def _file_size_mib(path: Path) -> float:
    try:
        return path.stat().st_size / (1024.0 * 1024.0)
    except OSError:
        return 0.0


def _path_size_bytes(path: Path) -> int:
    """Return allocated logical bytes without following directory symlinks."""

    try:
        if path.is_symlink():
            return int(path.lstat().st_size)
        if path.is_file():
            return int(path.stat().st_size)
        total = 0
        for root, directories, files in os.walk(path, followlinks=False):
            # Symlinked directories must be counted as links, not traversed.
            kept: list[str] = []
            root_path = Path(root)
            for name in directories:
                candidate = root_path / name
                if candidate.is_symlink():
                    try:
                        total += int(candidate.lstat().st_size)
                    except OSError:
                        pass
                else:
                    kept.append(name)
            directories[:] = kept
            for name in files:
                candidate = root_path / name
                try:
                    total += int(candidate.lstat().st_size)
                except OSError:
                    pass
        return total
    except OSError:
        return 0


def _format_reclaimed_bytes(value: int) -> str:
    gib = float(value) / (1024.0 ** 3)
    if gib >= 0.1:
        return f"{gib:.2f} GiB"
    return f"{float(value) / (1024.0 ** 2):.1f} MiB"


def _pid_alive(pid: int) -> bool:
    if pid <= 0:
        return False
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    return True


def _active_training_run_ids(
    paths: CampaignPaths,
    *,
    run_roots: Sequence[Path] | None = None,
    ownership_boundary: CampaignOwnershipBoundary | None = None,
) -> set[str]:
    active: set[str] = set()
    if run_roots is None:
        if not paths.runs.is_dir():
            return active
        run_roots = tuple(
            child for child in paths.runs.iterdir() if child.is_dir()
        )
    for run_root in run_roots:
        marker = run_root / "active_process.json"
        if not marker.is_file():
            continue
        try:
            payload = json.loads(marker.read_text(encoding="utf-8"))
            pid = int(payload.get("pid", -1))
        except Exception:
            pid = -1
        if _pid_alive(pid):
            active.add(run_root.name)
        else:
            if ownership_boundary is None:
                marker.unlink(missing_ok=True)
            else:
                authorized, _ = ownership_boundary.destructive_authorization(marker)
                if authorized:
                    marker.unlink(missing_ok=True)
    return active


def _diagnostic_log_tail(path: Path, *, maximum_bytes: int = 64 * 1024) -> str:
    if not path.is_file():
        return ""
    try:
        with path.open("rb") as handle:
            size = path.stat().st_size
            if size > maximum_bytes:
                handle.seek(-maximum_bytes, os.SEEK_END)
            return handle.read().decode("utf-8", errors="replace")
    except OSError:
        return ""


def _write_cleanup_diagnostic(
    destination: Path,
    source: Path,
    *,
    reason: str,
) -> None:
    """Preserve compact forensic evidence before deleting a stale runtime tree."""

    files: list[dict[str, Any]] = []
    tails: dict[str, str] = {}
    if source.exists() and not source.is_symlink():
        for item in sorted(source.rglob("*")):
            if not item.is_file():
                continue
            try:
                relative = item.relative_to(source).as_posix()
                size = int(item.stat().st_size)
            except OSError:
                continue
            files.append({"relative_path": relative, "size_bytes": size})
            if item.suffix == ".log" or item.name.endswith(("stdout", "stderr")):
                tail = _diagnostic_log_tail(item)
                if tail:
                    tails[relative] = tail
    _atomic_json(
        destination,
        {
            "schema": "mdstats.mlff-campaign-cleanup-diagnostic.v1",
            "created_utc": _utc_now(),
            "source": str(source),
            "reason": reason,
            "logical_size_bytes": _path_size_bytes(source),
            "files": files,
            "log_tails": tails,
        },
    )


@dataclass
class _CampaignCleanupReport:
    phase: str
    dry_run: bool
    actions: list[dict[str, Any]] = field(default_factory=list)
    skipped: list[str] = field(default_factory=list)
    ownership_boundary: CampaignOwnershipBoundary | None = field(default=None, repr=False)

    @property
    def reclaimed_bytes(self) -> int:
        return sum(int(item["size_bytes"]) for item in self.actions)

    def add(
        self,
        path: Path,
        *,
        reason: str,
        size_bytes: int,
        cleanup_class: str = "lifecycle_safe",
        prior_identity: Mapping[str, Any] | None = None,
        preserved_capabilities: Sequence[str] = (),
        capability_loss: Sequence[str] = (),
    ) -> None:
        self.actions.append(
            {
                "path": str(path),
                "reason": reason,
                "size_bytes": int(size_bytes),
                "cleanup_class": str(cleanup_class),
                "prior_identity": None if prior_identity is None else dict(prior_identity),
                "capability_loss": list(capability_loss),
                "preserved_capabilities": list(preserved_capabilities),
            }
        )

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema": "mdstats.mlff-campaign-cleanup-report.v1",
            "phase": self.phase,
            "dry_run": self.dry_run,
            "created_utc": _utc_now(),
            "reclaimed_bytes": self.reclaimed_bytes,
            "actions": list(self.actions),
            "skipped": list(self.skipped),
        }


def _cleanup_remove(
    report: _CampaignCleanupReport,
    path: Path,
    *,
    reason: str,
    diagnostic_path: Path | None = None,
    cleanup_class: str = "lifecycle_safe",
    preserved_capabilities: Sequence[str] = (),
    capability_loss: Sequence[str] = (),
) -> None:
    if not path.exists() and not path.is_symlink():
        return
    if report.ownership_boundary is not None:
        authorized, detail = report.ownership_boundary.destructive_authorization(path)
        if not authorized:
            report.skipped.append(
                f"cleanup authority denied for {path}: {detail}"
            )
            return
    size = _path_size_bytes(path)
    try:
        prior_identity = filesystem_identity(path)
    except OSError:
        prior_identity = {"schema": "mdstats.mlff-filesystem-identity.v1", "kind": "unavailable"}
    if diagnostic_path is not None and not report.dry_run:
        if report.ownership_boundary is not None:
            diagnostic_authorized, diagnostic_detail = (
                report.ownership_boundary.destructive_authorization(diagnostic_path)
            )
            if not diagnostic_authorized:
                report.skipped.append(
                    f"cleanup diagnostic write denied for {diagnostic_path}: {diagnostic_detail}"
                )
                return
        _write_cleanup_diagnostic(diagnostic_path, path, reason=reason)
    if not report.dry_run:
        if path.is_symlink() or path.is_file():
            path.unlink(missing_ok=True)
        else:
            shutil.rmtree(path, ignore_errors=False)
    report.add(
        path,
        reason=reason,
        size_bytes=size,
        cleanup_class=cleanup_class,
        prior_identity=prior_identity,
        preserved_capabilities=preserved_capabilities,
        capability_loss=capability_loss,
    )


def _current_materialization_roots(store: CampaignStore) -> set[Path]:
    import mdstats

    roots: set[Path] = set()
    for key in store.record_keys("materialization:"):
        try:
            record = store.get_record(key, mdstats.ProductionMaterializationRecord)
        except Exception:
            continue
        roots.add(Path(record.root_directory).resolve())
    return roots


def _cleanup_orphan_record_storage(
    report: _CampaignCleanupReport,
    store: CampaignStore,
    *,
    stale_before: float,
) -> None:
    root = store.external_record_directory
    if report.ownership_boundary is not None:
        authorized, detail = report.ownership_boundary.traversal_authorization(root)
        if not authorized:
            report.skipped.append(
                f"external-record cleanup skipped because the root failed ownership checks: {detail}: {root}"
            )
            return
    if not root.is_dir():
        return
    references = set(store.storage_references())
    keep_top: set[Path] = set()
    for reference in references:
        try:
            relative = reference.relative_to(root.resolve())
        except ValueError:
            continue
        if relative.parts:
            keep_top.add((root / relative.parts[0]).resolve())
    for child in root.iterdir():
        resolved = child.resolve()
        if resolved in keep_top:
            continue
        try:
            if child.stat().st_mtime > stale_before:
                report.skipped.append(f"young external record candidate retained: {child}")
                continue
        except OSError:
            continue
        _cleanup_remove(report, child, reason="orphaned external campaign record", cleanup_class="garbage", preserved_capabilities=("all_referenced_campaign_records", "campaign_state"))


def _cleanup_materialization_storage(
    report: _CampaignCleanupReport,
    paths: CampaignPaths,
    store: CampaignStore,
    *,
    stale_before: float,
) -> None:
    current_roots = _current_materialization_roots(store)
    data_root_authorized = True
    if report.ownership_boundary is not None:
        data_root_authorized, detail = report.ownership_boundary.traversal_authorization(paths.data)
        if not data_root_authorized:
            report.skipped.append(
                f"DATA7/DATA8 cleanup skipped because the data root failed ownership checks: {detail}: {paths.data}"
            )
    if data_root_authorized and paths.data.is_dir():
        for variant_root in paths.data.iterdir():
            if not variant_root.is_dir():
                continue
            for candidate in variant_root.iterdir():
                if not candidate.is_dir() or candidate.is_symlink():
                    continue
                resolved = candidate.resolve()
                if resolved in current_roots:
                    continue
                marker = candidate / "production_materialization_checkpoint.json"
                if not marker.is_file():
                    continue
                try:
                    if candidate.stat().st_mtime > stale_before:
                        report.skipped.append(f"young obsolete DATA8 root retained: {candidate}")
                        continue
                except OSError:
                    continue
                _cleanup_remove(
                    report,
                    candidate,
                    reason="obsolete unreferenced DATA7/DATA8 materialization root",
                    cleanup_class="stale_staging",
                    preserved_capabilities=("current_data8_materialization", "training_restart", "data8_rematerialization"),
                )
            if not report.dry_run:
                authorized = True
                if report.ownership_boundary is not None:
                    authorized, detail = report.ownership_boundary.destructive_authorization(variant_root)
                    if not authorized:
                        report.skipped.append(
                            f"cleanup authority denied for {variant_root}: {detail}"
                        )
                if authorized:
                    try:
                        variant_root.rmdir()
                    except OSError:
                        pass

    for root in current_roots:
        if report.ownership_boundary is not None:
            authorized, detail = report.ownership_boundary.traversal_authorization(root)
            if not authorized:
                report.skipped.append(
                    f"DATA8 generation cleanup skipped because the recorded root failed ownership checks: {detail}: {root}"
                )
                continue
        # Staging/link/legacy/corrupt trees are never valid restart inputs after
        # an atomic promotion has completed.
        for pattern in (
            ".data8-staging-*",
            ".data8-link-*",
            ".data8-legacy-*",
            ".*.corrupt-*",
        ):
            for candidate in root.glob(pattern):
                try:
                    if candidate.lstat().st_mtime > stale_before:
                        continue
                except OSError:
                    continue
                _cleanup_remove(report, candidate, reason="stale DATA8 promotion artifact", cleanup_class="stale_staging", preserved_capabilities=("current_data8_materialization", "training_restart"))

        generations = root / ".data8-generations"
        pointer = root / "data8"
        live_generation: Path | None = None
        if pointer.is_symlink():
            try:
                live_generation = pointer.resolve(strict=True)
            except OSError:
                live_generation = None
        if generations.is_dir():
            for generation in generations.iterdir():
                if live_generation is not None and generation.resolve() == live_generation:
                    continue
                try:
                    if generation.stat().st_mtime > stale_before:
                        continue
                except OSError:
                    continue
                _cleanup_remove(
                    report,
                    generation,
                    reason="unreferenced prior DATA8 generation",
                    cleanup_class="stale_staging",
                    preserved_capabilities=("current_data8_materialization", "training_restart", "data8_rematerialization"),
                )


def _cleanup_preflight_heavy_artifacts(
    report: _CampaignCleanupReport,
    paths: CampaignPaths,
    store: CampaignStore,
) -> None:
    try:
        preflight_payload = store.get_payload_optional("preflight_smoke")
    except Exception:
        return
    if preflight_payload is None or not bool(preflight_payload.get("passed")):
        return
    root = paths.internal / "preflight-smoke"
    if report.ownership_boundary is not None:
        traversal_authorized, traversal_detail = (
            report.ownership_boundary.traversal_authorization(root)
        )
        if not traversal_authorized:
            report.skipped.append(
                "preflight cleanup skipped because the root failed traversal ownership "
                f"checks: {traversal_detail}: {root}"
            )
            return
    if not root.is_dir():
        return
    diagnostic = root / "retained-diagnostic.json"
    if not report.dry_run and not diagnostic.is_file():
        if report.ownership_boundary is not None:
            diagnostic_authorized, diagnostic_detail = (
                report.ownership_boundary.destructive_authorization(diagnostic)
            )
            if not diagnostic_authorized:
                report.skipped.append(
                    f"preflight diagnostic write denied by ownership boundary: {diagnostic_detail}: {diagnostic}"
                )
                return
        payload = preflight_payload
        tails = {
            name: _diagnostic_log_tail(root / name)
            for name in (
                "training.stdout.log",
                "training.stderr.log",
                "evaluation.stdout.log",
                "evaluation.stderr.log",
            )
        }
        _atomic_json(
            diagnostic,
            {
                "schema": "mdstats.mlff-preflight-retained-diagnostic.v1",
                "created_utc": _utc_now(),
                "preflight_record": payload,
                "log_tails": {key: value for key, value in tails.items() if value},
            },
        )
    keep_names = {
        "retained-diagnostic.json",
        "training.stdout.log",
        "training.stderr.log",
        "evaluation.stdout.log",
        "evaluation.stderr.log",
        "mace_config.preflight.yaml",
    }
    for child in tuple(root.iterdir()):
        if child.name in keep_names:
            continue
        _cleanup_remove(
            report,
            child,
            reason="completed preflight heavy artifact superseded by checksummed diagnostic record",
            cleanup_class="successful_preflight_temporary",
            preserved_capabilities=("preflight_pass_evidence", "preflight_reexecution", "training_diagnostics"),
        )


def _cleanup_obsolete_training_runtimes(
    report: _CampaignCleanupReport,
    paths: CampaignPaths,
    *,
    active_run_ids: set[str],
    run_roots: Sequence[Path] | None = None,
) -> None:
    if run_roots is None:
        if not paths.runs.is_dir():
            return
        run_roots = tuple(
            child for child in paths.runs.iterdir() if child.is_dir()
        )
    for run_root in run_roots:
        if not run_root.is_dir() or run_root.name in active_run_ids:
            continue
        diagnostic_root = run_root / "obsolete-runtime-diagnostics"
        for obsolete in run_root.glob("obsolete-runtime-*"):
            diagnostic = diagnostic_root / f"{obsolete.name}.json"
            _cleanup_remove(
                report,
                obsolete,
                reason="obsolete training runtime from superseded execution policy",
                diagnostic_path=diagnostic,
                cleanup_class="obsolete_runtime",
                preserved_capabilities=("current_training_restart", "compact_obsolete_runtime_diagnostics"),
            )


def _cleanup_checkpoint_model_caches(
    report: _CampaignCleanupReport,
    paths: CampaignPaths,
    *,
    active_run_ids: set[str],
    run_roots: Sequence[Path] | None = None,
) -> None:
    """Remove reconstructable whole-model checkpoint caches outside live runs."""

    if run_roots is None:
        if not paths.runs.is_dir():
            return
        run_roots = tuple(
            child for child in paths.runs.iterdir() if child.is_dir()
        )
    for run_root in run_roots:
        if not run_root.is_dir() or run_root.name in active_run_ids:
            continue
        _cleanup_remove(
            report,
            run_root / "checkpoint-model-cache",
            reason=(
                "reconstructable checkpoint-to-model evaluation cache; raw restart "
                "checkpoint and immutable DATA8 config are retained"
            ),
            cleanup_class="reconstructable_cache",
            preserved_capabilities=("exact_checkpoint_reevaluation", "training_restart", "target_head_reexport"),
        )


def _cleanup_evaluation_graph_cache(
    report: _CampaignCleanupReport,
    paths: CampaignPaths,
    store: CampaignStore,
) -> None:
    """Remove only the OPT-EVAL3 graph/view cache after authoritative evaluation."""

    try:
        evaluate_state, _ = store.stage("evaluate")
    except Exception:
        return
    if evaluate_state is not StageState.COMPLETE:
        return
    _cleanup_remove(
        report,
        paths.internal / "evaluation-graphs",
        reason=(
            "reconstructable evaluation graph/view cache after authoritative evaluation; "
            "authenticated monitor inputs and metric/prediction records are retained"
        ),
        cleanup_class="reconstructable_cache",
        preserved_capabilities=(
            "authoritative_checkpoint_metrics",
            "metric_only_recomputation_from_predictions",
            "checkpoint_reevaluation_from_monitors",
        ),
    )


def _append_cleanup_audit_manifest(
    report: _CampaignCleanupReport,
    paths: CampaignPaths,
    *,
    trigger: str,
) -> None:
    if report.dry_run or report.ownership_boundary is None:
        return
    destination = paths.results / "cleanup-manifest.jsonl"
    authorized, detail = report.ownership_boundary.destructive_authorization(destination)
    if not authorized:
        report.skipped.append(
            f"cleanup manifest append skipped by ownership boundary: {detail}: {destination}"
        )
        return
    payload = {
        "created_utc": _utc_now(),
        "phase": report.phase,
        "trigger": trigger,
        "workspace": str(paths.workspace),
        "reclaimed_bytes": report.reclaimed_bytes,
        "action_count": len(report.actions),
        "actions": list(report.actions),
        "protected_capabilities": [
            "external_user_inputs",
            "selected_production_models",
            "selected_production_checkpoints",
            "campaign_protocol_and_selection_records",
            "diagnostic_logs_and_histories",
            "active_training_restart",
            "authoritative_scientific_metrics",
            "qualified_selected_head_training_foundation",
            "foundation_identity_and_acceleration_realization",
        ],
        "capability_loss": sorted({
            str(capability)
            for action in report.actions
            for capability in action.get("capability_loss", [])
        }),
    }
    try:
        append_cleanup_manifest(destination, payload)
    except OSError as exc:
        report.skipped.append(f"cleanup manifest append failed: {exc}")


def _campaign_cleanup(
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    *,
    phase: str,
    dry_run: bool = False,
    include_preparation_caches: bool = False,
) -> _CampaignCleanupReport:
    """Conservatively remove only artifacts not needed by current continuation."""

    protected_inputs = configured_protected_inputs(
        cfg, config_dir=paths.config_dir, config_path=paths.config
    )
    report = _CampaignCleanupReport(
        phase=phase,
        dry_run=dry_run,
        ownership_boundary=CampaignOwnershipBoundary(
            paths.workspace, protected_inputs=protected_inputs
        ),
    )
    if not bool(_cfg(cfg, "cleanup", "enabled", True)):
        report.skipped.append("automatic cleanup disabled by [cleanup].enabled")
        return report
    stale_hours = max(0.25, float(_cfg(cfg, "cleanup", "stale_age_hours", 6.0)))
    stale_before = time.time() - stale_hours * 3600.0
    runs_authorized = True
    if report.ownership_boundary is not None:
        runs_authorized, detail = report.ownership_boundary.traversal_authorization(paths.runs)
        if not runs_authorized:
            report.skipped.append(
                f"run-tree cleanup skipped because the runs root failed ownership checks: {detail}: {paths.runs}"
            )
    run_roots = (
        tuple(
            child for child in paths.runs.iterdir()
            if child.is_dir() and not child.is_symlink()
        )
        if runs_authorized and paths.runs.is_dir()
        else ()
    )
    active_run_ids = _active_training_run_ids(
        paths,
        run_roots=run_roots,
        ownership_boundary=report.ownership_boundary,
    )

    _cleanup_orphan_record_storage(report, store, stale_before=stale_before)
    _cleanup_materialization_storage(
        report, paths, store, stale_before=stale_before
    )
    _cleanup_obsolete_training_runtimes(
        report, paths, active_run_ids=active_run_ids, run_roots=run_roots
    )
    _cleanup_checkpoint_model_caches(
        report, paths, active_run_ids=active_run_ids, run_roots=run_roots
    )
    if bool(_cfg(cfg, "cleanup", "remove_evaluation_graph_cache_after_evaluate", True)):
        _cleanup_evaluation_graph_cache(report, paths, store)

    if include_preparation_caches:
        if bool(
            _cfg(
                cfg,
                "cleanup",
                "remove_frame_cache_after_preflight",
                True,
            )
        ):
            _cleanup_remove(
                report,
                paths.internal / "frame-cache",
                reason="normalized source cache is not used by train/evaluate/verify",
                cleanup_class="reconstructable_cache",
                preserved_capabilities=("source_reparse", "data_preparation", "training_restart"),
            )
        if bool(
            _cfg(
                cfg,
                "cleanup",
                "remove_shared_data7_cache_after_prepare",
                True,
            )
        ):
            _cleanup_remove(
                report,
                paths.internal / "data7-cache",
                reason="shared DATA7 cache duplicated by promoted current materializations",
                cleanup_class="reconstructable_cache",
                preserved_capabilities=("data7_reselection", "current_data8_materialization", "training_restart"),
            )
        if bool(
            _cfg(
                cfg,
                "cleanup",
                "remove_shared_data8_fixed_file_cache_after_prepare",
                True,
            )
        ):
            _cleanup_remove(
                report,
                paths.internal / "data8-fixed-cache",
                reason="shared DATA8 fixed-file cache duplicated by promoted current materializations",
                cleanup_class="reconstructable_cache",
                preserved_capabilities=("data8_rematerialization", "training_restart"),
            )
        if bool(
            _cfg(
                cfg,
                "cleanup",
                "remove_preflight_heavy_artifacts_after_success",
                True,
            )
        ):
            _cleanup_preflight_heavy_artifacts(report, paths, store)

    if not dry_run:
        assert report.ownership_boundary is not None
        store_authorized, store_detail = report.ownership_boundary.destructive_authorization(store.path)
        if active_run_ids:
            report.skipped.append(
                "SQLite compaction skipped while live training children exist"
            )
        elif not store_authorized:
            report.skipped.append(
                f"SQLite compaction skipped because campaign state failed ownership checks: {store_detail}"
            )
        else:
            try:
                store.compact(
                    maximum_events=int(
                        _cfg(cfg, "cleanup", "maximum_event_records", 10_000)
                    )
                )
            except Exception as exc:
                report.skipped.append(f"SQLite compaction skipped: {exc}")
        cleanup_report_path = paths.results / f"cleanup-{phase}.json"
        output_authorized, output_detail = report.ownership_boundary.destructive_authorization(
            cleanup_report_path
        )
        if output_authorized:
            try:
                _atomic_json(cleanup_report_path, report.to_dict())
            except OSError as exc:
                report.skipped.append(f"cleanup report write failed: {exc}")
        else:
            report.skipped.append(
                f"cleanup report write skipped by ownership boundary: {output_detail}"
            )
        _append_cleanup_audit_manifest(
            report,
            paths,
            trigger=("manual" if phase == "manual" else "automatic_lifecycle"),
        )
    return report


def _attempt_stor3_disk_pressure_reclamation(
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    *,
    minimum_free_disk_gib: float,
) -> tuple[_CampaignCleanupReport, float, bool]:
    """Run the STOR3 safe policy before live training is interrupted for disk pressure."""

    report = _campaign_cleanup(
        cfg,
        paths,
        store,
        phase="disk-pressure",
        include_preparation_caches=True,
    )
    try:
        free_after = shutil.disk_usage(paths.workspace).free / (1024.0 ** 3)
    except OSError:
        free_after = 0.0
    return report, free_after, bool(free_after >= float(minimum_free_disk_gib))


def _print_cleanup_report(report: _CampaignCleanupReport) -> None:
    if report.actions:
        action = "would reclaim" if report.dry_run else "reclaimed"
        _ok(
            f"campaign cleanup {action} {_format_reclaimed_bytes(report.reclaimed_bytes)} "
            f"from {len(report.actions)} stale/cache artifact(s)"
        )
        for item in sorted(report.actions, key=lambda value: int(value["size_bytes"]), reverse=True)[:8]:
            print(
                f"  {_format_reclaimed_bytes(int(item['size_bytes'])):>10}  "
                f"{item['reason']}: {item['path']}",
                flush=True,
            )
    else:
        _ok("campaign cleanup found no removable stale/cache artifacts")
    for item in report.skipped[:8]:
        _warn(item)


class _ProgressReporter:
    """Compact elapsed/rate/ETA reporter for long campaign stages.

    Immediate cache/restart completions are treated as baseline work rather
    than throughput samples.  This avoids predicting an hours-long remaining
    run from a millisecond burst of already-complete items.
    """

    def __init__(self, label: str, total: int, *, minimum_interval_seconds: float = 15.0):
        self.label = str(label)
        self.total = max(0, int(total))
        self.started = time.monotonic()
        self.last_printed = self.started
        self.minimum_interval_seconds = float(minimum_interval_seconds)
        self._rate_tracker = ProgressRateTracker(
            completed=0,
            started_at=self.started,
            minimum_recent_window_seconds=1.0,
        )
        self._startup_baseline_seconds = 1.0

    @staticmethod
    def _duration(seconds: float) -> str:
        return format_progress_time(seconds)

    def item_start(self, index: int, name: str, detail: str = "") -> None:
        suffix = f"; detail={detail}" if detail else ""
        elapsed = max(0.0, time.monotonic() - self.started)
        completed = max(0, min(self.total, int(index) - 1))
        print(
            f"[{self.label} {index:>3}/{self.total}] {name}; status=start; "
            f"progress={format_progress_fraction(completed, self.total)}; "
            f"elapsed={format_progress_time(elapsed)}; eta=--:--:--{suffix}",
            flush=True,
        )

    def item_done(self, index: int, name: str, detail: str = "", *, force: bool = True) -> None:
        now = time.monotonic()
        if not force and index < self.total and now - self.last_printed < self.minimum_interval_seconds:
            return
        elapsed = now - self.started
        # Completed/recovered work reported immediately after reporter creation
        # is not a sample of current execution speed.  Move the rate baseline
        # past that startup burst.
        if elapsed <= self._startup_baseline_seconds and index < self.total:
            self._rate_tracker.reset(completed=index, now=now)
        timing = self._rate_tracker.snapshot(
            completed=index, total=self.total, now=now
        )
        suffix = f"; detail={detail}" if detail else ""
        print(
            f"[{self.label} {index:>3}/{self.total}] {name}; status=complete; "
            f"progress={format_progress_fraction(index, self.total)}; "
            f"elapsed={format_progress_time(elapsed)}; "
            f"eta={format_progress_time(timing.eta_seconds)}{suffix}",
            flush=True,
        )
        self.last_printed = now


def _manifest_inference_policy(cfg: Mapping[str, Any]) -> Any:
    import mdstats

    return mdstats.ManifestInferencePolicy(
        fixed_cell_relative_tolerance=float(
            _cfg(cfg, "manifest_inference", "fixed_cell_relative_tolerance", 1.0e-7)
        ),
        reference_cell_relative_tolerance=float(
            _cfg(cfg, "manifest_inference", "reference_cell_relative_tolerance", 1.0e-7)
        ),
        strain_matrix_absolute_tolerance=float(
            _cfg(cfg, "manifest_inference", "strain_matrix_absolute_tolerance", 5.0e-5)
        ),
        strain_volume_ratio_tolerance=float(
            _cfg(cfg, "manifest_inference", "strain_volume_ratio_tolerance", 5.0e-5)
        ),
        maximum_rotation_radians=float(
            _cfg(cfg, "manifest_inference", "maximum_rotation_radians", 1.0e-4)
        ),
        conventional_axis_orthogonality_tolerance=float(
            _cfg(cfg, "manifest_inference", "conventional_axis_orthogonality_tolerance", 5.0e-6)
        ),
        temperature_equality_tolerance_kelvin=float(
            _cfg(cfg, "manifest_inference", "temperature_equality_tolerance_kelvin", 1.0e-6)
        ),
        filename_values_at_or_above_one_are_percent=bool(
            _cfg(cfg, "manifest_inference", "filename_values_at_or_above_one_are_percent", True)
        ),
    )


def _print_manifest_inference(result: Any) -> None:
    _print_header("Manifest inference")
    print(f"XML metadata resolved: {result.resolved_xml_metadata_runs}")
    print(f"Fixed-cell runs:       {result.fixed_cell_runs}")
    print(f"Strain candidates:     {result.strain_candidate_runs}")
    print(f"Verified strains:      {result.verified_strain_runs}")
    print(f"Rejected strains:      {result.rejected_strain_runs}")
    print(f"Ambiguous strains:     {result.ambiguous_strain_runs}")
    for warning in result.warnings:
        _warn(warning)


def _ensure_manifest(
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    *,
    approve: bool,
    refresh_inferences: bool = False,
) -> Any:
    import mdstats

    training_root = _path_cfg(cfg, paths, "training_root")
    assert training_root is not None
    store = CampaignStore(paths.state_db)
    if not paths.manifest.is_file():
        pattern = str(_cfg(cfg, "data", "discovery_pattern", "**/*.xml"))
        discovered = mdstats.discover_vasp_manifest(
            training_root,
            dataset_id=str(_cfg(cfg, "data", "dataset_id", "mlff-dataset")),
            system_profile=str(_cfg(cfg, "campaign", "profile", "lta")),
            pattern=pattern,
        )
        inference = mdstats.infer_training_manifest_metadata(
            discovered,
            base_directory=training_root,
            policy=_manifest_inference_policy(cfg),
        )
        manifest = inference.manifest
        _atomic_json(paths.manifest, manifest.to_dict())
        _print_manifest_inference(inference)
        unresolved = inference.rejected_strain_runs + inference.ambiguous_strain_runs
        if unresolved:
            review_note = f" {unresolved} strain relationship(s) require inspection."
        elif inference.strain_candidate_runs:
            review_note = " All strain relationships passed geometry verification."
        else:
            review_note = " No filename strain candidates were present."
        raise CampaignCliError(
            f"Discovered {len(manifest.runs)} VASP runs, inferred reviewable metadata, and wrote {paths.manifest}."
            + review_note
            + " Review reference groups, independent replicas/realizations, and the populated inference evidence; "
            + "then rerun `prepare --approve-manifest`."
        )

    manifest = mdstats.TrainingDataManifest.load(paths.manifest)
    approved_digest = store.get_meta("approved_manifest_digest")
    if refresh_inferences:
        if approved_digest == manifest.content_digest:
            raise CampaignCliError(
                "The current manifest is already approved. Use --rebuild-catalog only after intentionally "
                "invalidating the campaign, or remove approval by starting a new workspace."
            )
        inference = mdstats.infer_training_manifest_metadata(
            manifest,
            base_directory=training_root,
            policy=_manifest_inference_policy(cfg),
        )
        manifest = inference.manifest
        _atomic_json(paths.manifest, manifest.to_dict())
        store.set_meta("approved_manifest_digest", None)
        _print_manifest_inference(inference)
        raise CampaignCliError(
            f"Refreshed XML and strain inferences in {paths.manifest}. Review the populated manifest, "
            "then rerun `prepare --approve-manifest`."
        )

    if approve:
        store.set_meta("approved_manifest_digest", manifest.content_digest)
        approved_digest = manifest.content_digest
    if approved_digest != manifest.content_digest:
        raise CampaignCliError(
            f"Manifest {paths.manifest} is not approved, or changed after approval. "
            "Review it and rerun `prepare --approve-manifest`."
        )
    return manifest


def _lta_contracts(cfg: Mapping[str, Any]) -> Any:
    import mdstats

    framework_numbers = tuple(int(v) for v in _cfg(cfg, "profile", "framework_atomic_numbers", (8, 13, 14)))
    mobile_numbers = tuple(int(v) for v in _cfg(cfg, "profile", "mobile_atomic_numbers", (3, 11, 19)))
    profile = mdstats.build_single_phase_material_profile(
        profile_id=str(_cfg(cfg, "profile", "profile_id", "dry-lta-alkali")),
        phase_kind=mdstats.MaterialPhaseKind.CRYSTALLINE_SOLID,
        geometry=mdstats.MaterialGeometryKind.BULK,
        chemistry_modifiers=(
            mdstats.ChemistryModifier.IONIC.value,
            mdstats.ChemistryModifier.COVALENT_NETWORK.value,
        ),
        extensions=(
            mdstats.StructuralExtension.POROUS_NETWORK.value,
            mdstats.StructuralExtension.ZEOLITE.value,
            mdstats.StructuralExtension.LTA.value,
        ),
        phase_id="lta_framework_and_guests",
    )
    groups = mdstats.AtomGroupCatalog(
        material_profile_digest=profile.content_digest,
        material_phase_ids=("lta_framework_and_guests",),
        groups=(
            mdstats.AtomGroupDefinition(
                group_id="all_atoms",
                label="All atoms",
                selector=mdstats.AtomGroupSelector(kind=mdstats.AtomGroupSelectorKind.ALL_ATOMS),
                phase_ids=("lta_framework_and_guests",),
            ),
            mdstats.AtomGroupDefinition(
                group_id="framework",
                label="LTA framework",
                selector=mdstats.AtomGroupSelector(
                    kind=mdstats.AtomGroupSelectorKind.ATOMIC_NUMBERS,
                    atomic_numbers=framework_numbers,
                ),
                phase_ids=("lta_framework_and_guests",),
                roles=("training_focus", "validation_focus"),
            ),
            mdstats.AtomGroupDefinition(
                group_id="mobile_ions",
                label="Li/Na/K mobile ions",
                selector=mdstats.AtomGroupSelector(
                    kind=mdstats.AtomGroupSelectorKind.ATOMIC_NUMBERS,
                    atomic_numbers=mobile_numbers,
                ),
                phase_ids=("lta_framework_and_guests",),
                roles=("mlff_focus", "training_focus", "validation_focus"),
            ),
        ),
        catalog_id="dry_lta_groups",
    )
    return mdstats.build_material_profile_contracts(profile, atom_groups=groups)


def _material_profile_contracts(cfg: Mapping[str, Any]) -> Any:
    profile = str(_cfg(cfg, "campaign", "profile", "lta")).lower()
    if profile != "lta":
        raise CampaignCliError(
            "The first campaign CLI profile is `lta`. Generic material profiles remain available through the Python API."
        )
    return _lta_contracts(cfg)


def _load_prepared(
    store: CampaignStore, *, include_data4: bool = True
) -> tuple[Any, Any, Any | None, Any]:
    """Restore only the prepared records required by the caller.

    DATA4 is by far the largest campaign object. Foundation sweeps and cache
    restoration do not consume it, so those paths must not pay its multi-hundred
    megabyte deserialization cost.
    """

    import mdstats

    return (
        store.get_record("source_catalog", mdstats.TrainingDataSourceCatalog),
        store.get_record("frame_catalog", mdstats.TrainingFrameCatalog),
        (store.get_record("data4", mdstats.Data4FeatureBundle) if include_data4 else None),
        store.get_record("data5", mdstats.Data5PartitionBundle),
    )


def _ensure_target_data_role_freeze(store: CampaignStore) -> Any:
    """Build or verify the immutable TARGET-DATA2A size-selection authority.

    This migration is deliberately cheap: it depends only on compact DATA2,
    DATA3, and DATA5 records.  A campaign prepared before TARGET-DATA2A can
    therefore adopt the role freeze without repeating DATA4-DATA9A work.
    """

    import mdstats

    sources, frames, _, data5 = _load_prepared(store, include_data4=False)
    expected = mdstats.build_target_data_role_freeze(sources, frames, data5)
    try:
        existing = store.get_record_optional(
            "target_data_role_freeze", mdstats.TargetDataRoleFreeze
        )
    except Exception as exc:
        print(
            f"[TARGET-DATA2A restart] stored role freeze cannot be restored ({exc}); rebuilding",
            flush=True,
        )
        existing = None
    if existing is not None and existing.content_digest == expected.content_digest:
        _ok(
            "TARGET-DATA2A role freeze reused: "
            f"{len(existing.size_development_frame_uids)} development frames; "
            f"digest={existing.content_digest[:12]}..."
        )
        return existing
    if existing is not None:
        print(
            "[TARGET-DATA2A restart] stored authority differs from live DATA5 lineage/policy; replacing it",
            flush=True,
        )
    store.put_record("target_data_role_freeze", expected)
    _ok(
        "TARGET-DATA2A role freeze persisted: "
        f"{len(expected.size_development_frame_uids)} development frames; "
        f"{len(expected.correlation_families)} tracked cross-unit correlation families; "
        f"digest={expected.content_digest[:12]}..."
    )
    return expected


def _load_verified_foundation_audit_authority(store: CampaignStore) -> Any:
    """Restore and authenticate the frozen FOUNDATION-AUDIT1 authority."""

    import mdstats

    sources, frames, _, data5 = _load_prepared(store, include_data4=False)
    role_freeze = store.get_record(
        "target_data_role_freeze", mdstats.TargetDataRoleFreeze
    )
    data6 = store.get_record("data6", mdstats.Data6FeatureBundle)
    audit = store.get_record("foundation_target_audit", mdstats.FoundationTargetAudit)
    mdstats.validate_foundation_target_audit_authority(
        audit,
        source_catalog=sources,
        frame_catalog=frames,
        data5_bundle=data5,
        data6_bundle=data6,
        target_data_role_freeze=role_freeze,
    )
    return audit


def _foundation_head_report_metadata(potential: Any) -> tuple[str, str]:
    """Return descriptive, non-authorizing source-head provenance labels.

    These labels are intentionally excluded from scientific identity.  They are
    reporting aids only; the inspected checkpoint/head remains authoritative.
    """

    family = str(getattr(potential, "model_family", "")).strip()
    head = str(getattr(potential, "foundation_head", "")).strip()
    if family == "mace_mh_1" and head == "omat_pbe":
        return "general inorganic/materials", "PBE/PBE+U materials"
    if family == "mace_mpa_0" and head == "default":
        return "general materials", "Materials Project PBE/PBE+U"
    return "checkpoint-defined domain", "checkpoint-defined theory/reference"


def _target_core_label_protocol_digests(source_catalog: Any) -> tuple[str, ...]:
    """Return authenticated target core-label protocol digests for reporting."""

    values = {
        str(source.electronic_structure.core_label_digest)
        for source in getattr(source_catalog, "sources", ())
        if getattr(source, "electronic_structure", None) is not None
    }
    return tuple(sorted(values))


def _ensure_foundation_target_audit(
    store: CampaignStore,
    *,
    cfg: Mapping[str, Any],
    sources: Any,
    frames: Any,
    data5: Any,
    data6: Any,
    sweep: Any,
    frame_data_resolver: Callable[[], Mapping[str, Any]],
    foundation_potential_identity: Any | None = None,
    foundation_inference_identity: Any | None = None,
) -> Any:
    """Build or reuse FOUNDATION-AUDIT1 without repeating foundation inference."""

    import mdstats

    def report_foundation_identity(audit: Any) -> None:
        potential = getattr(audit, "foundation_potential_identity", None)
        inference = getattr(audit, "foundation_inference_identity", None)
        if potential is None or inference is None:
            return
        domain_label, theory_label = _foundation_head_report_metadata(potential)
        target_protocols = _target_core_label_protocol_digests(sources)
        protocol_text = ",".join(value[:12] + "..." for value in target_protocols) or "unavailable"
        _ok(
            "FOUNDATION-AUDIT1 source: "
            f"family={potential.model_family}; head={potential.foundation_head}; "
            f"sha256={potential.sha256[:12]}...; backend={inference.backend}; "
            f"kernel={inference.resolved_kernel_mode}; dtype={inference.default_dtype}; "
            f"source-domain={domain_label}; source-theory={theory_label}; "
            f"target-core-label-protocol={protocol_text}; "
            f"target-role-freeze={audit.target_data_role_freeze_digest[:12]}..."
        )

    role_freeze = store.get_record(
        "target_data_role_freeze", mdstats.TargetDataRoleFreeze
    )
    try:
        existing = store.get_record_optional(
            "foundation_target_audit", mdstats.FoundationTargetAudit
        )
    except Exception as exc:
        print(
            f"[FOUNDATION-AUDIT1 restart] stored audit cannot be restored ({exc}); rebuilding",
            flush=True,
        )
        existing = None
    if existing is not None:
        if foundation_potential_identity is not None and existing.foundation_potential_identity is None:
            print(
                "[FOUNDATION-AUDIT1 restart] stored audit predates canonical foundation identities; rebuilding",
                flush=True,
            )
            existing = None
    if existing is not None:
        try:
            mdstats.validate_foundation_target_audit_authority(
                existing,
                source_catalog=sources,
                frame_catalog=frames,
                data5_bundle=data5,
                data6_bundle=data6,
                target_data_role_freeze=role_freeze,
            )
        except Exception as exc:
            print(
                f"[FOUNDATION-AUDIT1 restart] stored authority is stale ({exc}); rebuilding",
                flush=True,
            )
        else:
            _ok(
                "FOUNDATION-AUDIT1 reused: "
                f"{sum(item.metrics.configuration_count for item in existing.domains)} target configurations; "
                f"digest={existing.content_digest[:12]}..."
            )
            report_foundation_identity(existing)
            return existing

    _print_header("FOUNDATION-AUDIT1 foundation-model target adequacy baseline")
    started = time.monotonic()
    foundation_audit_temporary_ram_mib = int(
        _cfg(cfg, "performance", "foundation_audit_temporary_ram_mib", 512)
    )
    if foundation_audit_temporary_ram_mib <= 0:
        raise ValueError(
            "performance.foundation_audit_temporary_ram_mib must be positive"
        )
    audit = mdstats.build_foundation_target_audit(
        sources,
        frames,
        frame_data_resolver(),
        data5,
        data6,
        role_freeze,
        sweep,
        foundation_potential_identity=foundation_potential_identity,
        foundation_inference_identity=foundation_inference_identity,
        temporary_memory_threshold_bytes=(
            foundation_audit_temporary_ram_mib * 1024**2
        ),
    )
    store.put_record("foundation_target_audit", audit)
    report_foundation_identity(audit)
    for domain in audit.domains:
        tails = ", ".join(
            f"P{int(round(item.quantile * 100))}={item.vector_error_ev_per_angstrom * 1000.0:.1f} meV/A"
            for item in domain.metrics.force_tail_metrics
        )
        _ok(
            f"FOUNDATION-AUDIT1 {domain.label_domain_id}: "
            f"force RMSE={domain.metrics.force_component_rmse_ev_per_angstrom * 1000.0:.1f} meV/A; "
            f"species-macro={domain.metrics.species_macro_force_rmse_ev_per_angstrom * 1000.0:.1f} meV/A; "
            f"{tails}"
        )
    _ok(
        "FOUNDATION-AUDIT1 frozen before target training: "
        f"digest={audit.content_digest[:12]}...; elapsed={format_progress_time(time.monotonic() - started)}"
    )
    return audit



def _load_verified_target_coverage_reference_authority(store: CampaignStore) -> Any:
    """Restore and authenticate the frozen TARGET-DATA2B coverage authority."""

    import mdstats

    _, _, data4, data5 = _load_prepared(store, include_data4=True)
    assert data4 is not None
    role_freeze = store.get_record(
        "target_data_role_freeze", mdstats.TargetDataRoleFreeze
    )
    data6 = store.get_record("data6", mdstats.Data6FeatureBundle)
    audit = store.get_record("foundation_target_audit", mdstats.FoundationTargetAudit)
    reference = store.get_record(
        "target_coverage_reference", mdstats.TargetCoverageReference
    )
    mdstats.validate_target_coverage_reference_authority(
        reference,
        data4_bundle=data4,
        data5_bundle=data5,
        data6_bundle=data6,
        target_data_role_freeze=role_freeze,
        foundation_target_audit=audit,
    )
    return reference


def _target_coverage_query_workers(cfg: Mapping[str, Any]) -> tuple[int, Any]:
    """Resolve bounded native cKDTree workers for TARGET-DATA2B construction.

    Automatic mode deliberately caps the tree at eight native threads: this
    captures the useful cKDTree scaling regime on workstation CPUs without
    oversubscribing the rest of ``prepare``.  An explicit positive setting may
    request more, subject to the machine-visible CPU count.
    """

    resources = detect_system_resources(
        cpu_fraction=float(_cfg(cfg, "performance", "cpu_fraction", 0.90)),
        ram_fraction=float(_cfg(cfg, "performance", "ram_fraction", 0.80)),
        gpu_memory_fraction=float(_cfg(cfg, "performance", "gpu_memory_fraction", 0.90)),
        device="cpu",
    )
    requested = int(_cfg(cfg, "performance", "target_coverage_workers", 0))
    if requested < 0:
        raise CampaignCliError(
            "[performance].target_coverage_workers must be zero (automatic) or a positive integer."
        )
    workers = resolve_worker_count(
        task_count=max(1, int(resources.cpu_threads_available)),
        resources=resources,
        requested=requested,
        maximum_workers=8 if requested == 0 else None,
    )
    return workers, resources


def _target_coverage_reference_parallelism(cfg: Mapping[str, Any]) -> tuple[int, Any]:
    """Resolve COVREF-PAR1 outer block workers for TARGET-DATA2B construction.

    Reference construction is deliberately single-level: every Python lane
    owns an independent cKDTree query block with ``workers=1``.  Automatic
    mode uses the configured CPU budget rather than the historical eight-way
    native-tree cap; the existing ``target_coverage_workers`` option remains
    the execution-only explicit override.
    """

    resources = detect_system_resources(
        cpu_fraction=float(_cfg(cfg, "performance", "cpu_fraction", 0.90)),
        ram_fraction=float(_cfg(cfg, "performance", "ram_fraction", 0.80)),
        gpu_memory_fraction=float(_cfg(cfg, "performance", "gpu_memory_fraction", 0.90)),
        device="cpu",
    )
    requested = int(_cfg(cfg, "performance", "target_coverage_workers", 0))
    if requested < 0:
        raise CampaignCliError(
            "[performance].target_coverage_workers must be zero (automatic) or a positive integer."
        )
    budget = max(1, int(resources.cpu_threads_budget))
    available = max(1, int(resources.cpu_threads_available))
    workers = min(budget, available) if requested == 0 else min(requested, budget, available)
    return max(1, int(workers)), resources


def _target_multi_view_repair_parallelism(cfg: Mapping[str, Any]) -> tuple[int, Any]:
    """Resolve REPAIR-PAR1 immutable-proposal worker count.

    Repair winner application remains sequential.  Automatic mode gives the
    proposal queue the complete configured CPU budget; native numerical layers
    inside each proposal are constrained to one thread by StageResourceScope.
    """

    resources = detect_system_resources(
        cpu_fraction=float(_cfg(cfg, "performance", "cpu_fraction", 0.90)),
        ram_fraction=float(_cfg(cfg, "performance", "ram_fraction", 0.80)),
        gpu_memory_fraction=float(_cfg(cfg, "performance", "gpu_memory_fraction", 0.90)),
        device="cpu",
    )
    requested = int(_cfg(cfg, "performance", "target_multi_view_repair_workers", 0))
    if requested < 0:
        raise CampaignCliError(
            "[performance].target_multi_view_repair_workers must be zero (automatic) or a positive integer."
        )
    budget = max(1, int(resources.cpu_threads_budget))
    available = max(1, int(resources.cpu_threads_available))
    workers = min(budget, available) if requested == 0 else min(requested, budget, available)
    return max(1, int(workers)), resources


def _target_multi_view_qualification_parallelism(cfg: Mapping[str, Any]) -> tuple[int, Any]:
    """Resolve MVQUAL-PAR1 global same-N scoring worker count.

    Every outer scoring job owns one independent domain/selector/size rescore;
    nested cKDTree/BLAS layers are constrained to one native thread. Automatic
    mode uses a conservative four-lane automatic ceiling, while explicit positive
    values may request more and remain clipped by visible/budgeted CPUs.
    """

    resources = detect_system_resources(
        cpu_fraction=float(_cfg(cfg, "performance", "cpu_fraction", 0.90)),
        ram_fraction=float(_cfg(cfg, "performance", "ram_fraction", 0.80)),
        gpu_memory_fraction=float(_cfg(cfg, "performance", "gpu_memory_fraction", 0.90)),
        device="cpu",
    )
    requested = int(_cfg(cfg, "performance", "target_multi_view_qualification_workers", 0))
    if requested < 0:
        raise CampaignCliError(
            "[performance].target_multi_view_qualification_workers must be zero (automatic) or a positive integer."
        )
    budget = max(1, int(resources.cpu_threads_budget))
    available = max(1, int(resources.cpu_threads_available))
    # Same-N score jobs are memory-bandwidth and temporary-allocation heavy.
    # Qualification on the 4-lane cloud host saturated after two lanes, so
    # automatic mode uses a conservative four-lane ceiling while still
    # allowing explicit larger values on high-memory-bandwidth servers.
    workers = min(budget, available, 4) if requested == 0 else min(requested, budget, available)
    return max(1, int(workers)), resources


def _target_coverage_feasibility_parallelism(
    cfg: Mapping[str, Any],
    coverage_reference: Any,
    *,
    query_block_size: int,
) -> tuple[int, int, Any]:
    """Resolve FEAS1 single-level global work-queue parallelism.

    Automatic FEAS1 no longer nests Python block workers around multi-threaded
    cKDTree calls. Every CPU-budget lane is one independent global executor
    worker and each exact cKDTree query uses ``workers=1``. Blocks from every
    domain/profile share the queue, so profile tails cannot strand the other
    lanes. The historical block/family control remains an execution-only
    override for the global executor size.
    """

    resources = detect_system_resources(
        cpu_fraction=float(_cfg(cfg, "performance", "cpu_fraction", 0.90)),
        ram_fraction=float(_cfg(cfg, "performance", "ram_fraction", 0.80)),
        gpu_memory_fraction=float(_cfg(cfg, "performance", "gpu_memory_fraction", 0.90)),
        device="cpu",
    )
    requested_tree = int(_cfg(cfg, "performance", "target_coverage_workers", 0))
    requested_global = int(
        _cfg(cfg, "performance", "target_coverage_feasibility_global_workers", 0)
    )
    compatibility_block = int(
        _cfg(cfg, "performance", "target_coverage_feasibility_block_workers", 0)
    )
    compatibility_family = int(
        _cfg(cfg, "performance", "target_coverage_feasibility_family_workers", 0)
    )
    if requested_tree < 0:
        raise CampaignCliError(
            "[performance].target_coverage_workers must be zero (automatic) or a positive integer."
        )
    if requested_global < 0 or compatibility_block < 0 or compatibility_family < 0:
        raise CampaignCliError(
            "TARGET-DATA2B-FEAS1 global/block/family worker controls must be zero (automatic) or positive integers."
        )
    explicit_worker_values = {
        value for value in (requested_global, compatibility_block, compatibility_family) if value > 0
    }
    if len(explicit_worker_values) > 1:
        raise CampaignCliError(
            "TARGET-DATA2B-FEAS1 global/block/family worker controls disagree; "
            "set only target_coverage_feasibility_global_workers for new campaigns."
        )
    if requested_global == 0 and explicit_worker_values:
        requested_global = next(iter(explicit_worker_values))

    block = max(1, int(query_block_size))
    total_blocks = sum(
        math.ceil(len(family.values) / block)
        for domain in coverage_reference.domains
        for family in domain.families
    )
    budget = max(1, int(resources.cpu_threads_budget))
    available = max(1, int(resources.cpu_threads_available))

    if requested_global > 0:
        global_workers = min(requested_global, budget, available)
    else:
        # Use the entire configured CPU budget. ThreadPoolExecutor creates
        # workers lazily, so a small workload does not pay for idle OS threads;
        # a normal FEAS1 campaign has many more blocks than lanes.
        global_workers = min(budget, available)

    # Production parallel FEAS1 is deliberately single-level. A serial global
    # override may still use an explicitly requested native cKDTree width for
    # debugging/backwards-compatible direct tuning.
    if global_workers == 1 and requested_tree > 0:
        tree_workers = min(requested_tree, budget, available)
    else:
        tree_workers = 1

    if global_workers > budget:
        raise CampaignCliError(
            "TARGET-DATA2B-FEAS1 global worker count exceeds the configured CPU budget: "
            f"{global_workers} > {budget}."
        )
    if total_blocks <= 0:
        raise CampaignCliError("TARGET-DATA2B-FEAS1 coverage reference contains no query blocks.")
    return int(tree_workers), int(global_workers), resources


def _target_coverage_policy(cfg: Mapping[str, Any]) -> Any:
    """Resolve TARGET-DATA2B coverage semantics from the shared size-convergence table."""

    import mdstats

    target_data = cfg.get("target_data", {})
    size_convergence = target_data.get("size_convergence", {}) if isinstance(target_data, Mapping) else {}
    if not isinstance(size_convergence, Mapping):
        raise CampaignCliError("[target_data.size_convergence] must be a TOML table.")
    extent_tolerance = size_convergence.get("extent_default_tolerance", "none")
    if str(extent_tolerance).strip().lower() != "none":
        raise CampaignCliError(
            "Generated TARGET-DATA2B supports extent_default_tolerance='none' only; "
            "unit-bearing profile-specific tolerances must be declared by the profile authority."
        )
    return mdstats.TargetCoveragePolicy(
        coverage_metric=str(size_convergence.get("coverage_metric", "reference_mass_local_knn")),
        coverage_threshold=float(size_convergence.get("coverage_threshold", 0.95)),
        coverage_resolution_mass=float(size_convergence.get("coverage_resolution_mass", 1.0 / 128.0)),
        coverage_leave_one_out=bool(size_convergence.get("coverage_leave_one_out", True)),
        extent_quantile_alpha=float(size_convergence.get("extent_quantile_alpha", 0.01)),
    )


def _ensure_target_coverage_reference(
    store: CampaignStore,
    *,
    cfg: Mapping[str, Any],
    data4: Any,
    data5: Any,
    data6: Any,
    foundation_audit: Any,
) -> Any:
    """Build or reuse TARGET-DATA2B without touching protected evidence roles."""

    import mdstats

    role_freeze = store.get_record(
        "target_data_role_freeze", mdstats.TargetDataRoleFreeze
    )
    policy = _target_coverage_policy(cfg)
    try:
        existing = store.get_record_optional(
            "target_coverage_reference", mdstats.TargetCoverageReference
        )
    except Exception as exc:
        print(
            f"[TARGET-DATA2B restart] stored coverage reference cannot be restored ({exc}); rebuilding",
            flush=True,
        )
        existing = None
    if existing is not None:
        try:
            mdstats.validate_target_coverage_reference_authority(
                existing,
                data4_bundle=data4,
                data5_bundle=data5,
                data6_bundle=data6,
                target_data_role_freeze=role_freeze,
                foundation_target_audit=foundation_audit,
            )
            if existing.policy.policy_digest != policy.policy_digest:
                raise CampaignCliError("TARGET-DATA2B coverage policy changed.")
        except Exception as exc:
            print(
                f"[TARGET-DATA2B restart] stored authority is stale ({exc}); rebuilding",
                flush=True,
            )
        else:
            if existing.requires_native_persistence_migration:
                migrated = mdstats.TargetCoverageReference(
                    dataset_id=existing.dataset_id,
                    source_catalog_digest=existing.source_catalog_digest,
                    frame_catalog_digest=existing.frame_catalog_digest,
                    data4_bundle_digest=existing.data4_bundle_digest,
                    data5_bundle_digest=existing.data5_bundle_digest,
                    data6_bundle_digest=existing.data6_bundle_digest,
                    target_data_role_freeze_digest=existing.target_data_role_freeze_digest,
                    foundation_target_audit_digest=existing.foundation_target_audit_digest,
                    policy=existing.policy,
                    domains=existing.domains,
                )
                migration = mdstats.compare_target_coverage_references_exact(
                    existing, migrated
                )
                if not migration.exact_match:
                    raise CampaignCliError(
                        "TARGET-DATA2B v1-to-v2 migration changed scientific content."
                    )
                store.put_records(
                    {
                        "target_coverage_reference": migrated,
                        "target_coverage_migration": migration,
                    }
                )
                existing = migrated
                _ok(
                    "TARGET-DATA2B historical v1 authority migrated exactly to native v2: "
                    f"report={migration.content_digest[:12]}..."
                )
            _ok(
                "TARGET-DATA2B reference reused: "
                f"{sum(len(item.families) for item in existing.domains)} families; "
                f"digest={existing.content_digest[:12]}..."
            )
            return existing

    _print_header("TARGET-DATA2B hierarchical reference-mass coverage authority")
    coverage_workers, coverage_resources = _target_coverage_reference_parallelism(cfg)
    print(
        f"[TARGET-DATA2B] COVREF-PAR1 outer workers={coverage_workers}; native cKDTree workers/task=1; "
        f"CPU budget={coverage_resources.cpu_threads_budget}/{coverage_resources.cpu_threads_available}",
        flush=True,
    )
    started = time.monotonic()
    coverage_scope = build_stage_resource_scope(
        coverage_resources,
        stage_name="TARGET-DATA2B-COVREF-PAR1",
        python_workers=coverage_workers,
        tree_workers=1,
        blas_threads=1,
    )
    reference = mdstats.build_target_coverage_reference(
        data4,
        data5,
        data6,
        role_freeze,
        foundation_audit,
        policy=policy,
        progress_callback=lambda message: print(f"[TARGET-DATA2B] {message}", flush=True),
        query_workers=1,
        execution_scope=coverage_scope,
    )
    store.put_record("target_coverage_reference", reference)
    for domain in reference.domains:
        required = sum(item.required for item in domain.families)
        extent = sum(bool(item.extent_channels) for item in domain.families)
        _ok(
            f"TARGET-DATA2B {domain.label_domain_id}: "
            f"{len(domain.frame_uids)} reference frames; "
            f"{required} required families; {extent} extent-guarded; "
            f"{len(domain.strata)} support strata"
        )
    _ok(
        "TARGET-DATA2B frozen before target-size screening: "
        f"beta={reference.policy.coverage_resolution_mass:.8f}; "
        f"threshold={reference.policy.coverage_threshold:.3f}; "
        f"digest={reference.content_digest[:12]}...; "
        f"elapsed={format_progress_time(time.monotonic() - started)}"
    )
    return reference

def _ensure_target_coverage_feasibility(
    store: CampaignStore,
    *,
    cfg: Mapping[str, Any],
    coverage_reference: Any,
) -> Any:
    """Build or reuse TARGET-DATA2B-FEAS1 without changing DATA2C behavior."""

    import mdstats

    role_freeze = store.get_record("target_data_role_freeze", mdstats.TargetDataRoleFreeze)
    policy = mdstats.TargetCoverageFeasibilityPolicy()
    try:
        existing = store.get_record_optional(
            "target_coverage_feasibility", mdstats.TargetCoverageFeasibilityReport
        )
    except Exception as exc:
        print(
            f"[TARGET-DATA2B-FEAS1 restart] stored feasibility record cannot be restored ({exc}); rebuilding",
            flush=True,
        )
        existing = None
    if existing is not None:
        try:
            mdstats.validate_target_coverage_feasibility_authority(
                existing,
                target_coverage_reference=coverage_reference,
                target_data_role_freeze=role_freeze,
                policy=policy,
            )
        except Exception as exc:
            print(
                f"[TARGET-DATA2B-FEAS1 restart] stored authority is stale ({exc}); rebuilding",
                flush=True,
            )
        else:
            _ok(
                "TARGET-DATA2B-FEAS1 reused: "
                f"state={existing.terminal_state}; digest={existing.content_digest[:12]}..."
            )
            return existing

    _print_header("TARGET-DATA2B-FEAS1 support fragility and capacity lower bounds")
    block_size = int(_cfg(cfg, "performance", "target_coverage_feasibility_block_size", 512))
    if block_size < 1:
        raise CampaignCliError(
            "[performance].target_coverage_feasibility_block_size must be positive."
        )
    coverage_workers, block_workers, coverage_resources = _target_coverage_feasibility_parallelism(
        cfg, coverage_reference, query_block_size=block_size
    )
    progress_interval = float(_cfg(cfg, "performance", "progress_interval_seconds", 30.0))
    if progress_interval <= 0.0:
        raise CampaignCliError("[performance].progress_interval_seconds must be positive.")
    total_profiles = sum(len(domain.families) for domain in coverage_reference.domains)
    total_witnesses = sum(
        len(family.values)
        for domain in coverage_reference.domains
        for family in domain.families
    )
    total_blocks = sum(
        math.ceil(len(family.values) / block_size)
        for domain in coverage_reference.domains
        for family in domain.families
    )
    print(
        f"[TARGET-DATA2B-FEAS1] exact global work queue: workers={block_workers}/"
        f"{coverage_resources.cpu_threads_budget} CPU-budget lanes; tree-workers/task={coverage_workers}; "
        f"profiles={total_profiles}; blocks={total_blocks}; witnesses={total_witnesses}; "
        f"query block={block_size}; progress={progress_interval:g}s; "
        f"hard ceiling={policy.maximum_candidate_size}",
        flush=True,
    )
    started = time.monotonic()
    scope = build_stage_resource_scope(
        coverage_resources,
        stage_name="TARGET-DATA2B-FEAS1",
        python_workers=block_workers,
        tree_workers=coverage_workers,
        blas_threads=1,
    )
    report, neighborhoods = mdstats.build_target_coverage_feasibility_artifacts(
        coverage_reference,
        role_freeze,
        policy=policy,
        query_workers=coverage_workers,
        query_block_size=block_size,
        block_workers=block_workers,
        progress_interval_seconds=progress_interval,
        progress_callback=lambda message: print(
            f"[TARGET-DATA2B-FEAS1] {message}", flush=True
        ),
        resource_scope=scope,
    )
    store.put_records({
        "target_coverage_feasibility": report,
        "target_coverage_exact_neighborhoods": neighborhoods,
    })
    _ok(
        "NEIGHBOR1 forward CSR emitted with FEAS1: "
        f"families={sum(len(domain.families) for domain in neighborhoods.domains)}; "
        f"edges={neighborhoods.edge_count}; digest={neighborhoods.content_digest[:12]}..."
    )
    for domain in report.domains:
        fragile_mass = max(
            (
                item.correlation_excluded_support.zero_support_mass
                for item in domain.family_reports
                if item.required
            ),
            default=0.0,
        )
        _ok(
            f"TARGET-DATA2B-FEAS1 {domain.label_domain_id}: "
            f"state={domain.terminal_state}; K_lb={domain.k_min_lower_bound}; "
            f"ceiling={domain.effective_candidate_ceiling}; "
            f"fragile_required_families={len(domain.fragile_required_family_ids)}; "
            f"max_zero_cross-unit_mass={fragile_mass:.6f}"
        )
    _ok(
        "TARGET-DATA2B-FEAS1 frozen as diagnostic-only evidence: "
        f"state={report.terminal_state}; digest={report.content_digest[:12]}...; "
        f"elapsed={format_progress_time(time.monotonic() - started)}; TARGET-DATA2C v4 unchanged"
    )
    return report


def _target_data_ladder_policy(cfg: Mapping[str, Any]) -> Any:
    """Resolve the frozen TARGET-DATA2C ladder policy from campaign config."""

    import mdstats

    target_data = cfg.get("target_data", {})
    size_convergence = target_data.get("size_convergence", {}) if isinstance(target_data, Mapping) else {}
    if not isinstance(size_convergence, Mapping):
        raise CampaignCliError("[target_data.size_convergence] must be a TOML table.")
    return mdstats.TargetDataLadderPolicy(
        ladder_exponents=tuple(int(v) for v in size_convergence.get("ladder_exponents", (7, 8, 9, 10, 11, 12, 13))),
        minimum_materializable_rungs=int(size_convergence.get("minimum_materializable_rungs", 3)),
        reserve_required_strata=bool(size_convergence.get("reserve_required_strata", True)),
        reserve_correlation_intervals=bool(size_convergence.get("reserve_correlation_intervals", True)),
        fps_tie_tolerance=float(size_convergence.get("fps_tie_tolerance", 1.0e-12)),
    )


def _target_size_convergence_policy(cfg: Mapping[str, Any], *, ladder: Any | None = None) -> Any:
    """Resolve the frozen TARGET-DATA2D funnel-decision policy."""

    import mdstats

    target_data = cfg.get("target_data", {})
    size_convergence = target_data.get("size_convergence", {}) if isinstance(target_data, Mapping) else {}
    if not isinstance(size_convergence, Mapping):
        raise CampaignCliError("[target_data.size_convergence] must be a TOML table.")
    practical = float(size_convergence.get("practical_equivalence_mev_per_a", 1.0))
    coarse_equivalence = size_convergence.get("coarse_practical_equivalence_mev_per_a")
    migrated = bool(ladder is not None and getattr(ladder, "authority_version", None) == mdstats.TARGET_DATA_LADDER_MV_VERSION)
    policy = mdstats.TargetSizeConvergencePolicy(
        min_coverage_qualifiers=(4 if migrated else int(size_convergence.get("min_coverage_qualifiers", 3))),
        coarse_training_epochs=int(size_convergence.get("coarse_training_epochs", 3)),
        max_coarse_training_candidates=int(size_convergence.get("max_coarse_training_candidates", 4)),
        coarse_target_monitor_configurations=int(size_convergence.get("coarse_target_monitor_configurations", 256)),
        short_training_epochs=int(size_convergence.get("short_training_epochs", 10)),
        max_short_training_candidates=int(size_convergence.get("max_short_training_candidates", 2)),
        final_training_epochs=int(size_convergence.get("final_training_epochs", 30)),
        practical_equivalence_mev_per_a=practical,
        coarse_practical_equivalence_mev_per_a=(None if coarse_equivalence is None else float(coarse_equivalence)),
        screening_optimizer_seed=int(size_convergence.get("screening_optimizer_seed", 1)),
        policy_version=(mdstats.TARGET_SIZE_CONVERGENCE_MV_VERSION if migrated else mdstats.TARGET_SIZE_CONVERGENCE_VERSION),
    )
    training = cfg.get("training", {})
    if not isinstance(training, Mapping):
        raise CampaignCliError("[training] must be a TOML table.")
    warmup_end = float(training.get("train2_warmup_end_fraction", 0.05))
    coarse_fraction = policy.coarse_training_epochs / policy.final_training_epochs
    if coarse_fraction <= warmup_end + 1.0e-12:
        raise CampaignCliError(
            "TARGET-DATA2D coarse training boundary must be strictly past TRAIN2 LR warm-up: "
            f"coarse={coarse_fraction:.6g}, warmup_end={warmup_end:.6g}."
        )
    configured_epochs = int(training.get("max_num_epochs", policy.final_training_epochs))
    if configured_epochs != policy.final_training_epochs:
        raise CampaignCliError(
            "TARGET-DATA2D final_training_epochs must equal [training].max_num_epochs so 3/10/30 evidence "
            "is sampled from one frozen uninterrupted schedule."
        )
    return policy


def _load_verified_target_size_convergence_authority(store: CampaignStore) -> Any:
    """Restore TARGET-DATA2D and authenticate its active-ladder bridge."""

    import mdstats

    ladder = _load_verified_target_data_ladder_authority(store)
    plan = store.get_record("target_size_convergence", mdstats.TargetSizeConvergencePlan)
    if plan.outcome == "selected":
        _authoritative_materialization_selection_sizes(plan, ladder=ladder)
    else:
        mdstats.validate_target_size_convergence_authority(plan, ladder=ladder)
    return plan


def _authoritative_materialization_selection_sizes(
    convergence: Any, *, ladder: Any
) -> tuple[int, ...]:
    """Resolve the terminal TARGET-DATA2D size authorized for DATA7/DATA8."""

    import mdstats

    if convergence.outcome != "selected":
        raise CampaignCliError(
            "TARGET-DATA2D cannot authorize DATA7/DATA8 materialization before "
            "selected_target_size is terminally frozen; intermediate convergence "
            f"states are evidence only (outcome={convergence.outcome!r})."
        )
    if convergence.selected_target_size is None:
        raise CampaignCliError(
            "TARGET-DATA2D selected outcome has no selected_target_size for DATA7/DATA8 materialization."
        )

    convergence_dataset_id = str(getattr(convergence, "dataset_id", ""))
    ladder_dataset_id = str(getattr(ladder, "dataset_id", ""))
    if (
        convergence_dataset_id
        and ladder_dataset_id
        and convergence_dataset_id != ladder_dataset_id
    ):
        raise CampaignCliError(
            "TARGET-DATA2D selected target size belongs to a different dataset than "
            "the active TARGET-DATA2C ladder."
        )

    sizes = (int(convergence.selected_target_size),)

    ladder_sizes = tuple(int(value) for value in ladder.materialized_target_sizes)
    if sizes[0] not in set(ladder_sizes):
        raise CampaignCliError(
            f"TARGET-DATA2D selected target size {sizes[0]} is absent from the authoritative "
            f"TARGET-DATA2C materialized ladder {list(ladder_sizes)}; rerun `prepare` from current "
            "MVSEL2/REPAIR2/MVQUAL authorities."
        )

    # A terminal decision from the retired ladder generation is intentionally
    # bridged by dataset identity and selected-rung membership above. A
    # current-generation decision still receives the complete authority check.
    if getattr(convergence, "target_data_ladder_digest", None) == getattr(
        ladder, "content_digest", None
    ):
        mdstats.validate_target_size_convergence_authority(
            convergence, ladder=ladder
        )
    return sizes


def _load_target_multi_view_repair_authority(store: CampaignStore) -> Any:
    """Restore explicit v2 authority, falling back only for legacy campaigns."""

    import mdstats

    if store.has_record("target_multi_view_repair_v2"):
        return store.get_record("target_multi_view_repair_v2", mdstats.TargetMultiViewRepairPlanV2)
    return store.get_record("target_multi_view_repair", mdstats.TargetMultiViewRepairPlan)


def _target_production_migration_kwargs(store: CampaignStore, ladder: Any) -> dict[str, Any]:
    """Return generation-specific TARGET-DATA2E provenance inputs."""

    import mdstats

    if ladder.authority_version != mdstats.TARGET_DATA_LADDER_MV_VERSION:
        return {}
    repair = _load_target_multi_view_repair_authority(store)
    qualification = store.get_record("target_multi_view_qualification", mdstats.TargetMultiViewQualificationPlan)
    migration = store.get_record("target_multi_view_migration_plan", mdstats.TargetMultiViewMigrationPlan)
    activation = store.get_record("target_multi_view_migration_activation", mdstats.TargetMultiViewMigrationActivation)
    if not migration.activation_authorized or activation.migration_plan_digest != migration.content_digest:
        raise CampaignCliError("TARGET-DATA2E v3 requires the authorized MVMIGRATE1 activation receipt.")
    return {
        "target_multi_view_repair": repair,
        "target_multi_view_qualification": qualification,
        "migration_authority_digest": migration.content_digest,
    }


def _load_verified_target_production_corpus_decision(store: CampaignStore) -> Any:
    """Restore and authenticate a completed TARGET-DATA2E authority."""

    import mdstats

    role_freeze = store.get_record("target_data_role_freeze", mdstats.TargetDataRoleFreeze)
    foundation_audit = store.get_record("foundation_target_audit", mdstats.FoundationTargetAudit)
    coverage_reference = store.get_record("target_coverage_reference", mdstats.TargetCoverageReference)
    ladder = store.get_record("target_data_ladder", mdstats.TargetDataLadderPlan)
    convergence = store.get_record("target_size_convergence", mdstats.TargetSizeConvergencePlan)
    decision = store.get_record("target_production_corpus_decision", mdstats.TargetProductionCorpusDecision)
    migration_kwargs = _target_production_migration_kwargs(store, ladder)
    mdstats.validate_target_production_corpus_decision(
        decision,
        target_data_role_freeze=role_freeze,
        foundation_target_audit=foundation_audit,
        target_coverage_reference=coverage_reference,
        target_data_ladder=ladder,
        target_size_convergence=convergence,
        **migration_kwargs,
    )
    return decision


def _ensure_target_production_corpus_decision(store: CampaignStore) -> Any | None:
    """Materialize TARGET-DATA2E only after TARGET-DATA2D selects a winner.

    Waiting Stage-B/Stage-C states intentionally return ``None``; they do not
    create a provisional production corpus.  Failed/non-converged completed
    funnels fail closed for any attempt to claim a production target size.
    """

    import mdstats

    role_freeze = store.get_record("target_data_role_freeze", mdstats.TargetDataRoleFreeze)
    foundation_audit = store.get_record("foundation_target_audit", mdstats.FoundationTargetAudit)
    coverage_reference = store.get_record("target_coverage_reference", mdstats.TargetCoverageReference)
    ladder = store.get_record("target_data_ladder", mdstats.TargetDataLadderPlan)
    convergence = store.get_record("target_size_convergence", mdstats.TargetSizeConvergencePlan)
    migration_kwargs = _target_production_migration_kwargs(store, ladder)

    if convergence.outcome in {"awaiting_stage_b0_coarse_training", "awaiting_stage_b1_short_training", "awaiting_stage_c_full_training"}:
        if store.has_record("target_production_corpus_decision"):
            store.delete_record("target_production_corpus_decision")
        return None
    if convergence.outcome != "selected":
        if store.has_record("target_production_corpus_decision"):
            store.delete_record("target_production_corpus_decision")
        raise CampaignCliError(
            "TARGET-DATA2E cannot claim a production corpus because TARGET-DATA2D "
            f"completed without convergence: outcome={convergence.outcome}; {convergence.decision_reason}"
        )

    existing = store.get_record_optional("target_production_corpus_decision", mdstats.TargetProductionCorpusDecision)
    if existing is not None:
        try:
            mdstats.validate_target_production_corpus_decision(
                existing,
                target_data_role_freeze=role_freeze,
                foundation_target_audit=foundation_audit,
                target_coverage_reference=coverage_reference,
                target_data_ladder=ladder,
                target_size_convergence=convergence,
                **migration_kwargs,
            )
        except Exception as exc:
            print(f"[TARGET-DATA2E restart] stored production-corpus authority is stale ({exc}); rebuilding", flush=True)
        else:
            _ok(
                "TARGET-DATA2E production target corpus reused: "
                f"N_target={existing.selected_target_size}; digest={existing.content_digest[:12]}..."
            )
            return existing

    decision = mdstats.build_target_production_corpus_decision(
        target_data_role_freeze=role_freeze,
        foundation_target_audit=foundation_audit,
        target_coverage_reference=coverage_reference,
        target_data_ladder=ladder,
        target_size_convergence=convergence,
        **migration_kwargs,
    )
    store.put_record("target_production_corpus_decision", decision)
    _ok(
        "TARGET-DATA2E production target corpus frozen: "
        f"N_target={decision.selected_target_size}; domains={len(decision.domains)}; "
        f"digest={decision.content_digest[:12]}..."
    )
    return decision


def _ensure_target_size_convergence(
    store: CampaignStore,
    *,
    cfg: Mapping[str, Any],
    ladder: Any,
) -> Any:
    """Apply/reuse TARGET-DATA2D Stage A and freeze its training shortlist."""

    import mdstats

    policy = _target_size_convergence_policy(cfg, ladder=ladder)
    try:
        existing = store.get_record_optional("target_size_convergence", mdstats.TargetSizeConvergencePlan)
    except Exception as exc:
        print(
            f"[TARGET-DATA2D restart] stored convergence authority cannot be restored ({exc}); rebuilding Stage A",
            flush=True,
        )
        existing = None
    if existing is not None:
        if existing.outcome == "selected":
            try:
                _authoritative_materialization_selection_sizes(
                    existing, ladder=ladder
                )
                same_ladder = (
                    existing.target_data_ladder_digest == ladder.content_digest
                )
                if (
                    same_ladder
                    and existing.policy.policy_digest != policy.policy_digest
                ):
                    raise CampaignCliError(
                        "TARGET-DATA2D convergence policy changed."
                    )
            except Exception as exc:
                print(
                    f"[TARGET-DATA2D restart] stored terminal authority is stale ({exc}); rebuilding Stage A",
                    flush=True,
                )
            else:
                bridge = (
                    "current ladder"
                    if same_ladder
                    else "legacy-to-active selected-size bridge"
                )
                _ok(
                    "TARGET-DATA2D terminal authority reused through "
                    f"{bridge}: selected_target_size={existing.selected_target_size}; "
                    f"digest={existing.content_digest[:12]}..."
                )
                return existing
            existing = None
    if existing is not None:
        try:
            mdstats.validate_target_size_convergence_authority(existing, ladder=ladder)
            if existing.policy.policy_digest != policy.policy_digest:
                raise CampaignCliError("TARGET-DATA2D convergence policy changed.")
        except Exception as exc:
            print(
                f"[TARGET-DATA2D restart] stored authority is stale ({exc}); rebuilding Stage A",
                flush=True,
            )
        else:
            _ok(
                "TARGET-DATA2D authority reused: "
                f"coverage-qualified sizes={list(existing.stage_a_survivor_sizes)}; "
                f"outcome={existing.outcome}; digest={existing.content_digest[:12]}..."
            )
            return existing

    _print_header("TARGET-DATA2D bounded target-size convergence funnel")
    started = time.monotonic()
    plan = mdstats.build_target_size_convergence_plan(ladder, policy=policy)
    store.put_record("target_size_convergence", plan)
    stage_a = ", ".join(
        f"n{item.target_size}:{'PASS' if item.qualified else 'FAIL'}"
        for item in plan.stage_a_rungs
        if item.materializable
    )
    _ok(f"TARGET-DATA2D Stage A: {stage_a}")
    _ok(
        "TARGET-DATA2D hard-coverage admission frozen: "
        f"survivors={list(plan.stage_a_survivor_sizes)}; "
        f"screening_seed={policy.screening_optimizer_seed}; "
        f"3/10/30 epochs={policy.coarse_training_epochs}/{policy.short_training_epochs}/{policy.final_training_epochs}; "
        f"equivalence={policy.practical_equivalence_mev_per_a:.3f} meV/A; "
        f"digest={plan.content_digest[:12]}...; elapsed={format_progress_time(time.monotonic() - started)}"
    )
    _warn(
        "TARGET-DATA2D Stage B0/B1/C evidence is intentionally not executed through the legacy adaptive-stop trainer. "
        "The frozen shortlist will be consumed by TRAIN2/EVAL2/VERIFY gates, which must supply exact 10-of-30 and 30-of-30 evidence."
    )
    return plan


def _load_verified_target_data_ladder_authority(store: CampaignStore) -> Any:
    """Restore and authenticate the live TARGET-DATA2C generation."""

    import mdstats


    role_freeze = store.get_record("target_data_role_freeze", mdstats.TargetDataRoleFreeze)
    reference = store.get_record("target_coverage_reference", mdstats.TargetCoverageReference)
    ladder = store.get_record("target_data_ladder", mdstats.TargetDataLadderPlan)
    if ladder.authority_version == mdstats.TARGET_DATA_LADDER_VERSION:
        mdstats.validate_target_data_ladder_authority(
            ladder, reference=reference, target_data_role_freeze=role_freeze
        )
    elif ladder.authority_version == mdstats.TARGET_DATA_LADDER_MV_VERSION:
        repair = _load_target_multi_view_repair_authority(store)
        qualification = store.get_record("target_multi_view_qualification", mdstats.TargetMultiViewQualificationPlan)
        migration = store.get_record("target_multi_view_migration_plan", mdstats.TargetMultiViewMigrationPlan)
        activation = store.get_record("target_multi_view_migration_activation", mdstats.TargetMultiViewMigrationActivation)
        if not migration.activation_authorized or activation.migration_plan_digest != migration.content_digest:
            raise CampaignCliError("Live TARGET-DATA2C v5 exists without a matching authorized MVMIGRATE1 receipt.")
        mdstats.validate_migrated_target_data_ladder_authority(
            ladder,
            reference=reference,
            target_data_role_freeze=role_freeze,
            target_multi_view_repair=repair,
            target_multi_view_qualification=qualification,
            migration_authority_digest=migration.content_digest,
        )
        if activation.migrated_target_data_ladder_digest != ladder.content_digest:
            raise CampaignCliError("Live TARGET-DATA2C v5 digest differs from the MVMIGRATE1 activation receipt.")
    else:
        raise CampaignCliError(f"Unsupported live TARGET-DATA2C authority generation: {ladder.authority_version}.")
    return ladder


def _ensure_target_coverage_sparse_index(
    store: CampaignStore,
    *,
    cfg: Mapping[str, Any],
    coverage_reference: Any,
    feasibility: Any,
) -> Any:
    """Build/reuse TARGET-DATA2C-MVIDX1 without changing DATA2C v4 selection."""

    import mdstats

    role_freeze = store.get_record("target_data_role_freeze", mdstats.TargetDataRoleFreeze)
    policy = mdstats.TargetCoverageSparseIndexPolicy()
    try:
        existing = store.get_record_optional(
            "target_coverage_sparse_index", mdstats.TargetCoverageSparseIndex
        )
    except Exception as exc:
        print(
            f"[TARGET-DATA2C-MVIDX1 restart] stored sparse index cannot be restored ({exc}); rebuilding",
            flush=True,
        )
        existing = None
    if existing is not None:
        try:
            mdstats.validate_target_coverage_sparse_index_authority(
                existing,
                target_coverage_reference=coverage_reference,
                target_data_role_freeze=role_freeze,
                target_coverage_feasibility=feasibility,
                policy=policy,
                verify_geometry=False,
            )
        except Exception as exc:
            print(
                f"[TARGET-DATA2C-MVIDX1 restart] stored authority is stale ({exc}); rebuilding",
                flush=True,
            )
        else:
            family_count = sum(len(domain.families) for domain in existing.domains)
            edge_count = sum(item.edge_count for domain in existing.domains for item in domain.families)
            _ok(
                "TARGET-DATA2C-MVIDX1 reused: "
                f"families={family_count}; sparse_edges={edge_count}; digest={existing.content_digest[:12]}..."
            )
            return existing

    _print_header("TARGET-DATA2C-MVIDX1 exact sparse coverage and hard-obligation index")
    block_size = int(_cfg(cfg, "performance", "target_coverage_mvidx_block_size", 512))
    if block_size < 1:
        raise CampaignCliError(
            "[performance].target_coverage_mvidx_block_size must be positive."
        )
    progress_interval = float(_cfg(cfg, "performance", "progress_interval_seconds", 30.0))
    if progress_interval <= 0.0:
        raise CampaignCliError("[performance].progress_interval_seconds must be positive.")

    neighborhoods = None
    try:
        neighborhoods = store.get_record_optional(
            "target_coverage_exact_neighborhoods", mdstats.TargetCoverageExactNeighborhoodStore
        )
    except Exception as exc:
        print(
            f"[NEIGHBOR1 restart] stored exact-neighborhood cache cannot be restored ({exc}); rebuilding",
            flush=True,
        )
    if neighborhoods is not None:
        try:
            mdstats.validate_target_coverage_exact_neighborhood_store(
                neighborhoods, target_coverage_reference=coverage_reference, verify_geometry=False
            )
        except Exception as exc:
            print(
                f"[NEIGHBOR1 restart] stored exact-neighborhood cache is stale ({exc}); rebuilding",
                flush=True,
            )
            neighborhoods = None
    if neighborhoods is None:
        tree_workers, global_workers, neighbor_resources = _target_coverage_feasibility_parallelism(
            cfg, coverage_reference, query_block_size=block_size
        )
        neighbor_scope = build_stage_resource_scope(
            neighbor_resources,
            stage_name="TARGET-DATA2B-NEIGHBOR1",
            python_workers=global_workers,
            tree_workers=tree_workers,
            blas_threads=1,
        )
        print(
            f"[NEIGHBOR1] FEAS1 cache unavailable; rebuilding exact forward CSR once with "
            f"global-workers={global_workers}; tree-workers/task={tree_workers}; query-block={block_size}",
            flush=True,
        )
        neighborhoods = mdstats.build_target_coverage_exact_neighborhood_store(
            coverage_reference,
            global_workers=global_workers,
            query_workers=tree_workers,
            query_block_size=block_size,
            progress_interval_seconds=progress_interval,
            progress_callback=lambda message: print(f"[NEIGHBOR1] {message}", flush=True),
            resource_scope=neighbor_scope,
        )
        store.put_record("target_coverage_exact_neighborhoods", neighborhoods)
        _ok(
            "NEIGHBOR1 exact forward CSR rebuilt and persisted: "
            f"edges={neighborhoods.edge_count}; digest={neighborhoods.content_digest[:12]}..."
        )
    else:
        _ok(
            "NEIGHBOR1 exact forward CSR reused: "
            f"edges={neighborhoods.edge_count}; digest={neighborhoods.content_digest[:12]}..."
        )

    _, mvidx_workers, mvidx_resources = _target_coverage_feasibility_parallelism(
        cfg, coverage_reference, query_block_size=block_size
    )
    mvidx_scope = build_stage_resource_scope(
        mvidx_resources,
        stage_name="TARGET-DATA2C-MVIDX-REUSE1",
        python_workers=mvidx_workers,
        tree_workers=1,
        blas_threads=1,
    )
    required_inverse_edges = sum(
        neighborhoods.domain(domain.label_domain_id).family(family.family_id).edge_count
        for domain in coverage_reference.domains
        for family in domain.families
        if family.required
    )
    required_inverse_bytes = int(required_inverse_edges) * np.dtype("<u4").itemsize
    store.external_record_directory.mkdir(parents=True, exist_ok=True)
    disk_free = int(shutil.disk_usage(store.external_record_directory).free)
    disk_safety = max(1 * 1024**3, int(math.ceil(required_inverse_bytes * 0.05)))
    if disk_free < required_inverse_bytes + disk_safety:
        raise CampaignCliError(
            "TARGET-DATA2C-MVIDX1 out-of-core inverse requires approximately "
            f"{required_inverse_bytes / 1024**3:.1f} GiB plus "
            f"{disk_safety / 1024**3:.1f} GiB safety headroom, but only "
            f"{disk_free / 1024**3:.1f} GiB is free under {store.external_record_directory}."
        )
    print(
        f"[TARGET-DATA2C-MVIDX1] NEIGHBOR1 cache hit; geometry sweep=skipped; query block setting={block_size}; "
        f"layout=uint32 indices/uint64 offsets; MVIDX-REUSE1 inverse-workers={mvidx_workers}; "
        f"large-inverse-storage=file-backed; inverse-disk={required_inverse_bytes / 1024**3:.1f} GiB; "
        f"disk-free={disk_free / 1024**3:.1f} GiB",
        flush=True,
    )
    started = time.monotonic()
    mvidx_build_root = Path(
        tempfile.mkdtemp(prefix="mvidx-out-of-core-build-", dir=store.external_record_directory)
    )
    try:
        index = mdstats.build_target_coverage_sparse_index(
            coverage_reference,
            role_freeze,
            feasibility,
            policy=policy,
            exact_neighborhood_store=neighborhoods,
            query_workers=1,
            query_block_size=block_size,
            global_workers=mvidx_workers,
            resource_scope=mvidx_scope,
            out_of_core_directory=mvidx_build_root,
            progress_interval_seconds=progress_interval,
            progress_callback=lambda message: print(f"[TARGET-DATA2C-MVIDX1] {message}", flush=True),
        )
        store.put_record("target_coverage_sparse_index", index)
        # Reload the native record before removing transient build paths.  Large
        # arrays are now read-only memmaps owned by the durable campaign store.
        persisted = store.get_record("target_coverage_sparse_index", mdstats.TargetCoverageSparseIndex)
        if persisted.content_digest != index.content_digest:
            raise CampaignCliError(
                "TARGET-DATA2C-MVIDX1 persisted native authority changed during out-of-core handoff."
            )
        index = persisted
    finally:
        shutil.rmtree(mvidx_build_root, ignore_errors=True)
    for domain in index.domains:
        edge_count = sum(item.edge_count for item in domain.families)
        required_obligations = sum(item.required for item in domain.obligations)
        _ok(
            f"TARGET-DATA2C-MVIDX1 {domain.label_domain_id}: "
            f"{len(domain.families)} required families; {edge_count} exact coverage edges; "
            f"{required_obligations}/{len(domain.obligations)} required/total obligations; "
            f"{len(domain.correlation_unit_ids)} correlation units"
        )
    _ok(
        "TARGET-DATA2C-MVIDX1 frozen as diagnostic/index substrate; "
        f"digest={index.content_digest[:12]}...; elapsed={format_progress_time(time.monotonic() - started)}; "
        "TARGET-DATA2C v4 unchanged"
    )
    return index


def _ensure_target_multi_view_selection(
    store: CampaignStore,
    *,
    cfg: Mapping[str, Any],
    coverage_reference: Any,
    sparse_index: Any,
) -> Any:
    """Build/reuse TARGET-DATA2C-MVSEL1 plus reconstructible MVSTATE cache."""

    import mdstats

    policy = mdstats.TargetMultiViewSelectorPolicy()
    progress_interval = float(_cfg(cfg, "performance", "progress_interval_seconds", 30.0))
    if progress_interval <= 0.0:
        raise CampaignCliError("[performance].progress_interval_seconds must be positive.")
    def progress(message: str) -> None:
        print(f"[TARGET-DATA2C-MVSEL1] {message}", flush=True)
    existing = None
    try:
        existing = store.get_record_optional(
            "target_multi_view_selection", mdstats.TargetMultiViewSelectionPlan
        )
    except Exception as exc:
        print(
            f"[TARGET-DATA2C-MVSEL1 restart] stored selector evidence cannot be restored ({exc}); rebuilding",
            flush=True,
        )
    if existing is not None:
        try:
            mdstats.validate_target_multi_view_selection_authority(
                existing,
                target_coverage_reference=coverage_reference,
                target_coverage_sparse_index=sparse_index,
                policy=policy,
            )
        except Exception as exc:
            print(
                f"[TARGET-DATA2C-MVSEL1 restart] stored authority is stale ({exc}); rebuilding",
                flush=True,
            )
            existing = None
        else:
            try:
                state_cache = store.get_record_optional(
                    "target_multi_view_selection_state_cache", mdstats.TargetMultiViewSelectionStateCache
                )
                if state_cache is None:
                    raise CampaignCliError("MVSTATE-REUSE1 cache is missing")
                mdstats.validate_target_multi_view_selection_state_cache(
                    state_cache,
                    target_coverage_reference=coverage_reference,
                    target_coverage_sparse_index=sparse_index,
                    target_multi_view_selection=existing,
                )
            except Exception as exc:
                print(
                    f"[TARGET-DATA2C-MVSTATE-REUSE1 restart] selector authority is reusable but state cache is unavailable ({exc}); rebuilding exact execution cache",
                    flush=True,
                )
                _, selector_resources = _target_coverage_query_workers(cfg)
                selector_scope = build_stage_resource_scope(
                    selector_resources, stage_name="TARGET-DATA2C-MVSEL1/MVSTATE-REUSE1",
                    python_workers=1, structural_workers=1, tree_workers=1, blas_threads=1,
                )
                with stage_resource_scope(selector_scope):
                    rebuilt, state_cache = mdstats.build_target_multi_view_selection_artifacts(
                        coverage_reference,
                        sparse_index,
                        policy=policy,
                        execution_mode="optimized",
                        progress_callback=progress,
                        progress_interval_seconds=progress_interval,
                    )
                if rebuilt.content_digest != existing.content_digest:
                    raise CampaignCliError("MVSTATE-REUSE1 cache rebuild changed MVSEL scientific authority.")
                mdstats.validate_target_multi_view_selection_state_cache(
                    state_cache,
                    target_coverage_reference=coverage_reference,
                    target_coverage_sparse_index=sparse_index,
                    target_multi_view_selection=existing,
                )
                store.put_record("target_multi_view_selection_state_cache", state_cache)
            _ok(
                "TARGET-DATA2C-MVSEL1 reused: "
                f"domains={len(existing.domains)}; digest={existing.content_digest[:12]}...; "
                f"MVSTATE={state_cache.content_digest[:12]}...; TARGET-DATA2C v4 remains active"
            )
            return existing, state_cache

    _print_header("TARGET-DATA2C-MVSEL1 deterministic progressive multi-view selector")
    print(
        "[TARGET-DATA2C-MVSEL1] phases=hard-obligation/worst-view coverage -> "
        "harmonic density-aware representative fill; FP64 deterministic gains; ceiling=16384; "
        "MVSTATE rung checkpoints=on; diagnostic only",
        flush=True,
    )
    started = time.monotonic()
    _, selector_resources = _target_coverage_query_workers(cfg)
    selector_scope = build_stage_resource_scope(
        selector_resources, stage_name="TARGET-DATA2C-MVSEL1/MVSTATE-REUSE1",
        python_workers=1, structural_workers=1, tree_workers=1, blas_threads=1,
    )
    with stage_resource_scope(selector_scope):
        plan, state_cache = mdstats.build_target_multi_view_selection_artifacts(
            coverage_reference,
            sparse_index,
            policy=policy,
            execution_mode="optimized",
            progress_callback=progress,
            progress_interval_seconds=progress_interval,
        )
    mdstats.validate_target_multi_view_selection_authority(
        plan,
        target_coverage_reference=coverage_reference,
        target_coverage_sparse_index=sparse_index,
        policy=policy,
    )
    mdstats.validate_target_multi_view_selection_state_cache(
        state_cache,
        target_coverage_reference=coverage_reference,
        target_coverage_sparse_index=sparse_index,
        target_multi_view_selection=plan,
    )
    store.put_records({
        "target_multi_view_selection": plan,
        "target_multi_view_selection_state_cache": state_cache,
    })
    for domain in plan.domains:
        qualified = [rung.target_size for rung in domain.rungs if rung.materializable and rung.hard_coverage_qualified]
        _ok(
            f"TARGET-DATA2C-MVSEL1 {domain.label_domain_id}: selected={len(domain.master_order)}; "
            f"phase_A_completed_at={domain.phase_a_completed_at or 'not_within_ceiling'}; "
            f"qualified_rungs={qualified or 'none'}"
        )
    _ok(
        "TARGET-DATA2C-MVSEL1 + MVSTATE-REUSE1 frozen: "
        f"selection={plan.content_digest[:12]}...; state={state_cache.content_digest[:12]}...; "
        f"elapsed={format_progress_time(time.monotonic() - started)}; TARGET-DATA2C v4 unchanged"
    )
    return plan, state_cache

def _ensure_target_multi_view_repair(
    store: CampaignStore,
    *,
    cfg: Mapping[str, Any],
    coverage_reference: Any,
    sparse_index: Any,
    selection_plan: Any,
    selection_state_cache: Any = None,
) -> Any:
    """Build/reuse TARGET-DATA2C-REPAIR1 without migrating DATA2C v4."""

    import mdstats

    policy = mdstats.TargetMultiViewRepairPolicy()
    try:
        existing = store.get_record_optional(
            "target_multi_view_repair", mdstats.TargetMultiViewRepairPlan
        )
    except Exception as exc:
        print(
            f"[TARGET-DATA2C-REPAIR1 restart] stored repair evidence cannot be restored ({exc}); rebuilding",
            flush=True,
        )
        existing = None
    if existing is not None:
        try:
            mdstats.validate_target_multi_view_repair_authority(
                existing,
                target_coverage_reference=coverage_reference,
                target_coverage_sparse_index=sparse_index,
                target_multi_view_selection=selection_plan,
                policy=policy,
            )
        except Exception as exc:
            print(
                f"[TARGET-DATA2C-REPAIR1 restart] stored authority is stale ({exc}); rebuilding",
                flush=True,
            )
        else:
            swaps = sum(domain.total_swaps for domain in existing.domains)
            _ok(
                "TARGET-DATA2C-REPAIR1 reused: "
                f"domains={len(existing.domains)}; swaps={swaps}; digest={existing.content_digest[:12]}...; "
                "TARGET-DATA2C v4 remains active"
            )
            return existing

    _print_header("TARGET-DATA2C-REPAIR1 exact multiplicity repair and deficit-directed exchange")
    print(
        "[TARGET-DATA2C-REPAIR1] removal=zero-unique/hard-safe active shell only; "
        "replacement=exact current deficit frontier; rank inheritance=yes; diagnostic only",
        flush=True,
    )
    started = time.monotonic()
    try:
        if selection_state_cache is None:
            selection_state_cache = store.get_record_optional(
                "target_multi_view_selection_state_cache", mdstats.TargetMultiViewSelectionStateCache
            )
        if selection_state_cache is not None:
            mdstats.validate_target_multi_view_selection_state_cache(
                selection_state_cache,
                target_coverage_reference=coverage_reference,
                target_coverage_sparse_index=sparse_index,
                target_multi_view_selection=selection_plan,
            )
    except Exception as exc:
        print(
            f"[TARGET-DATA2C-MVSTATE-REUSE1] state cache unavailable ({exc}); falling back to exact selector replay",
            flush=True,
        )
        selection_state_cache = None
    repair_workers, repair_resources = _target_multi_view_repair_parallelism(cfg)
    repair_scope = build_stage_resource_scope(
        repair_resources, stage_name="TARGET-DATA2C-REPAIR-PAR1",
        python_workers=repair_workers, structural_workers=1, tree_workers=1, blas_threads=1,
    )
    print(
        f"[TARGET-DATA2C-REPAIR-PAR1] proposal_workers={repair_workers}; "
        f"MVSTATE={'hit' if selection_state_cache is not None else 'fallback-replay'}; "
        "winner application=sequential; native_threads/proposal=1",
        flush=True,
    )
    plan = mdstats.build_target_multi_view_repair_plan(
        coverage_reference,
        sparse_index,
        selection_plan,
        policy=policy,
        execution_mode="optimized",
        proposal_workers=repair_workers,
        resource_scope=repair_scope,
        selection_state_cache=selection_state_cache,
        progress_callback=lambda message: print(f"[TARGET-DATA2C-REPAIR1] {message}", flush=True),
    )
    mdstats.validate_target_multi_view_repair_authority(
        plan,
        target_coverage_reference=coverage_reference,
        target_coverage_sparse_index=sparse_index,
        target_multi_view_selection=selection_plan,
        policy=policy,
    )
    store.put_record("target_multi_view_repair", plan)
    for domain in plan.domains:
        qualified = [rung.target_size for rung in domain.rungs if rung.materializable and rung.hard_coverage_qualified]
        _ok(
            f"TARGET-DATA2C-REPAIR1 {domain.label_domain_id}: swaps={domain.total_swaps}; "
            f"qualified_rungs={qualified or 'none'}"
        )
    _ok(
        "TARGET-DATA2C-REPAIR1 frozen as diagnostic repair evidence; "
        f"digest={plan.content_digest[:12]}...; elapsed={format_progress_time(time.monotonic() - started)}; "
        "TARGET-DATA2C v4 unchanged"
    )
    return plan


def _ensure_target_multi_view_selection_v2(
    store: CampaignStore,
    *,
    cfg: Mapping[str, Any],
    coverage_reference: Any,
    sparse_index: Any,
) -> tuple[Any, dict[str, Any]]:
    """Build/reuse the production MVSEL2 authority and compact MVSTATE2 rungs."""

    import mdstats
    from .target_coverage_sparse_forward_view import target_coverage_sparse_forward_view

    policy = mdstats.TargetMultiViewSelectorPolicyV2()
    forward = target_coverage_sparse_forward_view(sparse_index)
    try:
        existing = store.get_record_optional(
            "target_multi_view_selection_v2", mdstats.TargetMultiViewSelectionPlanV2
        )
    except Exception as exc:
        print(f"[TARGET-DATA2C-MVSEL2 restart] stored v2 authority is unavailable ({exc}); rebuilding", flush=True)
        existing = None
    if existing is not None:
        try:
            mdstats.validate_target_multi_view_selection_authority_v2(
                existing, target_coverage_reference=coverage_reference,
                target_coverage_sparse_index=sparse_index, query_workers=1,
            )
        except Exception as exc:
            print(f"[TARGET-DATA2C-MVSEL2 restart] stored v2 authority is stale ({exc}); rebuilding", flush=True)
        else:
            _ok(f"TARGET-DATA2C-MVSEL2 reused: digest={existing.content_digest[:12]}...; legacy MVSEL1 records retained")
            return existing, {}

    _print_header("TARGET-DATA2C-MVSEL2 exact forward/lazy selector")
    checkpoint_pointers: dict[str, Any] = {}
    def checkpoint(reference_domain: Any, forward_domain: Any, state: Any, size: int) -> None:
        identity = mdstats.build_target_multi_view_selection_identity_v2(
            reference_domain, forward_domain, dataset_id=coverage_reference.dataset_id,
            selector_policy=policy.to_dict(),
        )
        frozen = mdstats.checkpoint_target_multi_view_forward_state_v2(state, identity)
        pointer = mdstats.write_target_multi_view_selection_checkpoint_v2(
            frozen, store.external_record_directory
        )
        key = f"target_multi_view_selection_state_v2:{reference_domain.label_domain_id}:{size}"
        store.put_record(key, pointer)
        checkpoint_pointers[key] = pointer

    workers, resources = _target_coverage_query_workers(cfg)
    scope = build_stage_resource_scope(
        resources, stage_name="TARGET-DATA2C-MVSEL2/MVSTATE2",
        python_workers=max(1, workers), structural_workers=1, tree_workers=1, blas_threads=1,
    )
    started = time.monotonic()
    with stage_resource_scope(scope):
        plan = mdstats.build_target_multi_view_selection_plan_v2(
            coverage_reference, forward, policy=policy,
            workers=max(1, workers), checkpoint_callback=checkpoint,
            progress_callback=lambda message: print(f"[TARGET-DATA2C-MVSEL2] {message}", flush=True),
            progress_interval_seconds=float(_cfg(cfg, "performance", "progress_interval_seconds", 30.0)),
        )
    mdstats.validate_target_multi_view_selection_authority_v2(
        plan, target_coverage_reference=coverage_reference,
        target_coverage_sparse_index=sparse_index, query_workers=1,
    )
    store.put_record("target_multi_view_selection_v2", plan)
    _ok(
        f"TARGET-DATA2C-MVSEL2 + MVSTATE2 accepted: digest={plan.content_digest[:12]}...; "
        f"checkpoints={len(checkpoint_pointers)}; elapsed={format_progress_time(time.monotonic() - started)}; "
        "legacy MVSEL1/MVSTATE-REUSE1 records retained"
    )
    return plan, checkpoint_pointers


