def _file_stat_identity(path: Path) -> dict[str, Any]:
    source = path.expanduser().resolve()
    try:
        stat = source.stat()
    except FileNotFoundError:
        return {"path": str(source), "missing": True}
    return {
        "path": str(source),
        "device": int(stat.st_dev),
        "inode": int(stat.st_ino),
        "size": int(stat.st_size),
        "mtime_ns": int(stat.st_mtime_ns),
        "ctime_ns": int(stat.st_ctime_ns),
    }


def _prepare_input_identities(
    cfg: Mapping[str, Any], paths: CampaignPaths, sources: Any
) -> list[dict[str, Any]]:
    candidates: set[Path] = {paths.config, paths.manifest}
    for key in ("foundation_model", "replay_set", "replay_train", "replay_monitor", "replay_true_labels"):
        value = _path_cfg(cfg, paths, key, required=False)
        if value is not None:
            candidates.add(value)
    training_root = _path_cfg(cfg, paths, "training_root", required=False)
    for source in sources.sources:
        locator = Path(str(source.source_locator)).expanduser()
        if not locator.is_absolute() and training_root is not None:
            locator = training_root / locator
        candidates.add(locator)
    return [_file_stat_identity(path) for path in sorted(candidates, key=lambda item: str(item))]


def _prepare_contract_signature() -> dict[str, Any]:
    import mdstats

    return {
        "prepare_contract_version": PREPARE_CONTRACT_VERSION,
        "data2_parser_version": mdstats.MLFF_DATA2_PARSER_VERSION,
        "data3_parser_version": mdstats.MLFF_DATA3_PARSER_VERSION,
        "data4_parser_version": mdstats.MLFF_DATA4_PARSER_VERSION,
        "data5_parser_version": mdstats.MLFF_DATA5_PARSER_VERSION,
        "target_data2a_role_freeze_version": mdstats.TARGET_DATA_ROLE_FREEZE_VERSION,
        "foundation_audit1_version": mdstats.FOUNDATION_AUDIT_VERSION,
        "target_data2b_coverage_version": mdstats.TARGET_COVERAGE_VERSION,
        "target_data2b_persistence_version": mdstats.TARGET_COVERAGE_PERSISTENCE_VERSION,
        "target_data2b_feas1_version": mdstats.TARGET_COVERAGE_FEASIBILITY_VERSION,
        "target_data2c_mvidx1_version": mdstats.TARGET_COVERAGE_SPARSE_INDEX_VERSION,
        "target_data2c_mvsel1_version": mdstats.TARGET_MULTI_VIEW_SELECTOR_VERSION,
        "target_data2c_repair1_version": mdstats.TARGET_MULTI_VIEW_REPAIR_VERSION,
        "target_data2c_mvqual1_version": mdstats.TARGET_MULTI_VIEW_QUALIFICATION_VERSION,
        "target_data2c_ladder_version": mdstats.TARGET_DATA_LADDER_VERSION,
        "target_data2c_mvmigrate1_version": mdstats.TARGET_MV_MIGRATION_VERSION,
        "target_data2c_migrated_ladder_version": mdstats.MIGRATED_TARGET_DATA2C_VERSION,
        "target_data2d_migrated_convergence_version": mdstats.MIGRATED_TARGET_DATA2D_VERSION,
        "target_data2e_migrated_production_version": mdstats.MIGRATED_TARGET_DATA2E_VERSION,
        "final_gpu1_version": mdstats.FINAL_GPU1_VERSION,
        "replay_unify_integration_version": "REPLAY-UNIFY1D-v1",
        "replay_single_source_config_schema": mdstats.REPLAY_SINGLE_SOURCE_CONFIG_SCHEMA,
        "replay_source_artifact_schema": mdstats.REPLAY_SOURCE_ARTIFACT_SCHEMA,
        "replay_split_manifest_schema": mdstats.REPLAY_SPLIT_MANIFEST_SCHEMA,
        "replay_true_label_cache_schema": mdstats.REPLAY_TRUE_LABEL_CACHE_SCHEMA,
        "replay_foundation_prediction_cache_schema": mdstats.REPLAY_FOUNDATION_PREDICTION_CACHE_SCHEMA,
        "replay_pseudolabel_qualification_schema": mdstats.REPLAY_PSEUDOLABEL_QUALIFICATION_SCHEMA,
        "data6_parser_version": mdstats.MLFF_DATA6_PARSER_VERSION,
        "data7_parser_version": mdstats.MLFF_DATA7_PARSER_VERSION,
        "data8_parser_version": mdstats.MLFF_DATA8_PARSER_VERSION,
    }


def _data8_receipt_snapshot(
    variants: Sequence[_VariantSpec],
    materializations: Sequence[Any],
    bundles: Sequence[Any],
) -> list[dict[str, Any]]:
    by_digest = {item.checkpoint.data8_artifact.bundle_digest: item for item in materializations}
    snapshot = []
    for variant, bundle in zip(variants, bundles, strict=True):
        variant_id = variant.variant_id
        record = by_digest[bundle.content_digest]
        artifact = record.checkpoint.data8_artifact
        assert artifact is not None
        snapshot.append(
            {
                "variant_id": variant_id,
                "bundle_digest": bundle.content_digest,
                "plan_digest": record.checkpoint.plan.content_digest,
                "tree_digest": artifact.tree_digest,
            }
        )
    return snapshot


def _write_prepare_restart_receipt(
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    *,
    sources: Any,
    variants: Sequence[_VariantSpec],
    materializations: Sequence[Any],
    bundles: Sequence[Any],
) -> None:
    sweep_pointer = store.get_payload("model_sweep_checkpoint")
    receipt = {
        "schema": PREPARE_RESTART_RECEIPT_SCHEMA,
        "contract": _prepare_contract_signature(),
        "config_sha256": _sha256(paths.config),
        "input_identities": _prepare_input_identities(cfg, paths, sources),
        "record_digests": {
            key: (store.record_digest(key) if store.has_record(key) else None)
            for key in (*_PREPARE_RECEIPT_RECORD_KEYS, *_PREPARE_RECEIPT_OPTIONAL_RECORD_KEYS)
        },
        "model_sweep": {
            key: sweep_pointer.get(key)
            for key in (
                "checkpoint_digest",
                "plan_digest",
                "status",
                "completed_frames",
                "requested_frames",
                "relative_directory",
            )
        },
        "data8": _data8_receipt_snapshot(
            variants, materializations, bundles
        ),
    }
    store.put_record("prepare_restart_receipt", receipt)


def _try_reuse_completed_prepare(
    cfg: Mapping[str, Any], paths: CampaignPaths, store: CampaignStore
) -> bool:
    """Fast no-op for an unchanged, already-qualified prepare stage."""

    if store.stage("prepare")[0] is not StageState.COMPLETE:
        return False
    if store.get_meta(_stage_config_key("prepare")) != _sha256(paths.config):
        return False
    if not store.has_record("prepare_restart_receipt"):
        # One-time migration for campaigns completed by 0.20.68a0.  The DATA8
        # parser and variant-identity checks below reject older incompatible
        # trees, while a valid production qualification proves that DATA6-
        # DATA9A had already completed under the same campaign.toml.
        try:
            import mdstats

            sources = store.get_record(
                "source_catalog", mdstats.TrainingDataSourceCatalog
            )
            qualification = store.get_record(
                "production_qualification",
                mdstats.ProductionCorpusQualificationRecord,
            )
            if (
                qualification.status.value != "passed"
                or not qualification.full_data9a_passed
            ):
                return False
            sweep_pointer = store.get_payload("model_sweep_checkpoint")
            if (
                sweep_pointer.get("status") != "complete"
                or sweep_pointer.get("completed_frames")
                != sweep_pointer.get("requested_frames")
            ):
                return False
            entries = _current_data8_entries(store)
            variants = _variant_specs(cfg)
            by_id = {entry.variant_id: entry for entry in entries}
            expected_ids = {variant.variant_id for variant in variants}
            if set(by_id) != expected_ids:
                return False
            ordered_entries = [
                by_id[variant.variant_id]
                for variant in variants
            ]
            if any(entry.materialization is None for entry in ordered_entries):
                return False
            if any(not store.has_record(key) for key in _PREPARE_RECEIPT_RECORD_KEYS):
                return False
            _write_prepare_restart_receipt(
                cfg,
                paths,
                store,
                sources=sources,
                variants=variants,
                materializations=[entry.materialization for entry in ordered_entries],
                bundles=[entry.bundle for entry in ordered_entries],
            )
            _ok(
                "adopted the completed 0.20.68a0 prepare artifacts into the new "
                "restart receipt; no DATA6/DATA7/DATA8 work repeated"
            )
        except Exception:
            return False
    try:
        receipt = store.get_payload("prepare_restart_receipt")
        if receipt.get("schema") != PREPARE_RESTART_RECEIPT_SCHEMA:
            return False
        if receipt.get("contract") != _prepare_contract_signature():
            return False
        if receipt.get("config_sha256") != _sha256(paths.config):
            return False
        import mdstats

        sources = store.get_record("source_catalog", mdstats.TrainingDataSourceCatalog)
        if receipt.get("input_identities") != _prepare_input_identities(cfg, paths, sources):
            return False
        expected_record_digests = receipt.get("record_digests", {})
        if any(
            (store.record_digest(key) if store.has_record(key) else None) != expected_record_digests.get(key)
            for key in (*_PREPARE_RECEIPT_RECORD_KEYS, *_PREPARE_RECEIPT_OPTIONAL_RECORD_KEYS)
        ):
            return False
        if store.get_payload("model_sweep_checkpoint") != receipt.get("model_sweep"):
            # Older pointers may contain additional fields; compare the frozen
            # subset rather than requiring mapping equality.
            pointer = store.get_payload("model_sweep_checkpoint")
            observed = {
                key: pointer.get(key) for key in receipt.get("model_sweep", {})
            }
            if observed != receipt.get("model_sweep"):
                return False
        entries = _current_data8_entries(store)
        expected_ids = {variant.variant_id for variant in _variant_specs(cfg)}
        if {entry.variant_id for entry in entries} != expected_ids:
            return False
        observed_data8 = []
        for entry in sorted(entries, key=lambda item: item.variant_id):
            materialization = entry.materialization
            if materialization is None:
                return False
            artifact = materialization.checkpoint.data8_artifact
            if artifact is None:
                return False
            observed_data8.append(
                {
                    "variant_id": entry.variant_id,
                    "bundle_digest": entry.bundle.content_digest,
                    "plan_digest": materialization.checkpoint.plan.content_digest,
                    "tree_digest": artifact.tree_digest,
                }
            )
        expected_data8 = sorted(
            receipt.get("data8", ()), key=lambda item: item["variant_id"]
        )
        if observed_data8 != expected_data8:
            return False
        qualification = store.get_record(
            "production_qualification",
            mdstats.ProductionCorpusQualificationRecord,
        )
        if qualification.status.value != "passed" or not qualification.full_data9a_passed:
            return False
    except Exception:
        return False
    _ok(
        "prepare is already complete and byte/current-input identities are unchanged; "
        "skipped DATA2-DATA9A without repeating DATA6 or DATA7/DATA8 work"
    )
    return True


def _select_production_gate_anchor(
    variants: Sequence[_VariantSpec],
    materializations: Sequence[Any],
    bundles: Sequence[Any],
) -> tuple[Any, bool, str]:
    """Choose the DATA8 artifact that proves campaign-wide replay binding.

    Production qualification currently records one representative DATA8
    materialization.  In mixed naive/replay campaigns the first configured
    variant may be intentionally replay-free, so using ``materializations[0]``
    makes the campaign-wide replay gate depend on variant ordering.  Select a
    genuine replay variant when replay is requested anywhere in the matrix;
    otherwise declare replay optional and use the first complete variant.
    """

    if not variants:
        raise CampaignCliError("Production qualification requires at least one DATA8 variant.")
    if not (len(variants) == len(materializations) == len(bundles)):
        raise CampaignCliError(
            "Production qualification variant/materialization/bundle counts disagree."
        )

    replay_anchor: tuple[Any, str] | None = None
    replay_required = False
    normalized_variants = tuple(_coerce_variant_spec(value) for value in variants)
    for variant, materialization, bundle in zip(
        normalized_variants, materializations, bundles, strict=True
    ):
        mode = variant.mode
        variant_id = variant.variant_id
        replay_bound = bundle.replay_plan.mode.value != "none"
        if mode == "multihead_replay":
            replay_required = True
            if not replay_bound:
                raise CampaignCliError(
                    f"DATA8 variant {variant_id} is configured for multihead replay "
                    "but its replay corpus is not bound."
                )
            if replay_anchor is None:
                replay_anchor = (materialization, variant_id)
        elif replay_bound:
            raise CampaignCliError(
                f"DATA8 variant {variant_id} is configured for naive fine-tuning "
                "but unexpectedly binds a replay corpus."
            )

    if replay_required:
        if replay_anchor is None:  # Defensive; the branch above should make this unreachable.
            raise CampaignCliError(
                "The training matrix requests replay, but no replay-bound DATA8 materialization exists."
            )
        return replay_anchor[0], True, replay_anchor[1]

    return materializations[0], False, normalized_variants[0].variant_id


def _prepare_materialization(
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    *,
    max_new_domains: int | None,
    frame_data_by_run: Mapping[str, Any] | None = None,
    sweep_artifacts: Any | None = None,
) -> bool:
    import mdstats

    sources, frames, data4, data5 = _load_prepared(store)
    training_root = _path_cfg(cfg, paths, "training_root")
    model_path = _path_cfg(cfg, paths, "foundation_model")
    assert training_root and model_path
    frame_data: dict[str, Any] | None = (
        dict(frame_data_by_run) if frame_data_by_run is not None else None
    )

    def resolved_frame_data() -> dict[str, Any]:
        nonlocal frame_data
        if frame_data is None:
            frame_data = _load_or_rebuild_frame_data(cfg, paths, sources)
        return frame_data

    _print_header("Restoring or finalizing DATA6 evidence")
    if sweep_artifacts is None:
        print(
            "Restoring model-sweep metadata; sidecars will be verified lazily on first use...",
            flush=True,
        )
        sweep = mdstats.load_data6_model_sweep_artifacts(
            paths.internal / "model-sweep",
            verify_sidecars=False,
        )
    else:
        sweep = sweep_artifacts
        print(
            "Reusing the just-completed in-memory sweep; no duplicate all-sidecar scan.",
            flush=True,
        )
    if not sweep.complete:
        return False
    data6_policy = mdstats.Data6Policy(
        build_universal_structural_features=True,
        build_lta_selection_features=True,
        build_mace_descriptors=True,
        build_training_difficulty=True,
        build_blinded_predictions=True,
    )
    data6 = None
    restored_data6 = None
    try:
        restored_data6 = store.get_record_optional(
            "data6", mdstats.Data6FeatureBundle
        )
    except Exception as exc:
        print(
            f"[DATA6 restart] finalized bundle cannot be restored ({exc}); rebuilding",
            flush=True,
        )
    else:
        if restored_data6 is not None:
            if _data6_bundle_matches_live_inputs(
                restored_data6,
                sources=sources,
                frames=frames,
                data4=data4,
                data5=data5,
                sweep=sweep,
                policy=data6_policy,
            ):
                data6 = restored_data6
                _ok(
                    "finalized DATA6 evidence reused; skipped structural recomputation "
                    "and sharded-record rewrite"
                )
            else:
                print(
                    "[DATA6 restart] stored bundle lineage/policy differs from the live inputs; rebuilding",
                    flush=True,
                )
    if data6 is None:
        provider, _ = _provider(
            cfg,
            paths,
            checkpoint_identity=sweep.checkpoint.plan.checkpoint_identity,
        )
        data6_start = time.monotonic()
        data6 = mdstats.build_data6_feature_bundle(
            sources,
            frames,
            resolved_frame_data(),
            data4,
            data5,
            policy=data6_policy,
            # Production selection consumes frame-level structural summaries and
            # event evidence.  Materializing one Python descriptor per atom would
            # create millions of redundant objects and is not needed by DATA7.
            universal_structural_policy=mdstats.UniversalStructuralSelectionPolicy(
                materialize_atomic_environments=False,
            ),
            lta_selection_policy=mdstats.LtaSelectionPolicy(
                materialize_atomic_environments=False,
            ),
            model_provider=provider,
            model_sweep_artifacts=sweep,
            progress_callback=lambda message: print(f"[DATA6 finalize] {message}", flush=True),
            structural_max_workers=int(_cfg(cfg, "selection", "structural_workers", 0)),
        )
        _ok(f"DATA6 evidence finalized; elapsed={format_progress_time(time.monotonic() - data6_start)}")
        print(
            "[DATA6 finalize] persisting finalized DATA6 evidence as checksummed array/JSONL shards",
            flush=True,
        )
        persist_start = time.monotonic()
        store.put_record("data6", data6)
        _ok(f"DATA6 campaign record persisted; elapsed={format_progress_time(time.monotonic() - persist_start)}")
    audit_potential = None
    audit_inference = None
    foundation_cfg = cfg.get("foundation")
    if isinstance(foundation_cfg, Mapping) and not bool(foundation_cfg.get("legacy_normalized", False)):
        audit_potential = _resolved_foundation_potential_identity(cfg, paths)
        audit_realization = _stored_acceleration_realization(cfg, paths, require_qualified=True)
        assert audit_realization is not None
        audit_inference = _foundation_inference_identity(
            cfg,
            audit_potential,
            adapter_version=mdstats.MACE_ADAPTER_VERSION,
            resolved_kernel_mode=audit_realization.resolved_kernel_mode,
        )
        if audit_realization.foundation_inference_identity_digest != audit_inference.content_digest:
            raise CampaignCliError("FOUNDATION-AUDIT1 inference identity disagrees with doctor-frozen acceleration realization.")
    foundation_audit = _ensure_foundation_target_audit(
        store,
        cfg=cfg,
        sources=sources,
        frames=frames,
        data5=data5,
        data6=data6,
        sweep=sweep,
        frame_data_resolver=resolved_frame_data,
        foundation_potential_identity=audit_potential,
        foundation_inference_identity=audit_inference,
    )
    coverage_reference = _ensure_target_coverage_reference(
        store,
        cfg=cfg,
        data4=data4,
        data5=data5,
        data6=data6,
        foundation_audit=foundation_audit,
    )
    target_coverage_feasibility = _ensure_target_coverage_feasibility(
        store,
        cfg=cfg,
        coverage_reference=coverage_reference,
    )
    target_coverage_sparse_index = _ensure_target_coverage_sparse_index(
        store,
        cfg=cfg,
        coverage_reference=coverage_reference,
        feasibility=target_coverage_feasibility,
    )
    target_multi_view_selection, target_multi_view_selection_state_cache = _ensure_target_multi_view_selection_v2(
        store,
        cfg=cfg,
        coverage_reference=coverage_reference,
        sparse_index=target_coverage_sparse_index,
    )
    target_multi_view_repair = _ensure_target_multi_view_repair_v2(
        store,
        cfg=cfg,
        coverage_reference=coverage_reference,
        sparse_index=target_coverage_sparse_index,
        selection_plan=target_multi_view_selection,
    )
    legacy_target_ladder = _ensure_target_data_ladder(
        store,
        cfg=cfg,
        coverage_reference=coverage_reference,
    )
    target_multi_view_qualification = _ensure_target_multi_view_qualification(
        store,
        cfg=cfg,
        coverage_reference=coverage_reference,
        sparse_index=target_coverage_sparse_index,
        feasibility=target_coverage_feasibility,
        repair_plan=target_multi_view_repair,
        legacy_ladder=legacy_target_ladder,
    )
    size_halve2_plan = _ensure_size_halve2_plan(
        store,
        cfg=cfg,
        repair_plan=target_multi_view_repair,
        qualification_plan=target_multi_view_qualification,
    )
    size_fidelity2_execution_plan = _ensure_size_fidelity2_execution_plan(
        store, size_halve2_plan=size_halve2_plan
    )
    migration_plan, migration_candidate = _ensure_target_multi_view_migration(
        store,
        cfg=cfg,
        coverage_reference=coverage_reference,
        repair_plan=target_multi_view_repair,
        qualification_plan=target_multi_view_qualification,
        legacy_ladder=legacy_target_ladder,
        size_halve2_plan=size_halve2_plan,
        size_fidelity2_execution_plan=size_fidelity2_execution_plan,
    )
    target_ladder = _resolve_active_target_data_ladder(
        store, legacy_ladder=legacy_target_ladder, migration_plan=migration_plan,
        candidate=migration_candidate,
    )
    size_convergence = _ensure_target_size_convergence(
        store,
        cfg=cfg,
        ladder=target_ladder,
    )
    # TARGET-DATA2D intentionally has an intermediate state between ladder
    # qualification and production materialization.  Do not treat a valid
    # waiting state as a failed prepare run: Stage B0/B1/C evaluation owns the
    # transition to the terminal selected_target_size authority.  The actual
    # materialization authorization remains fail-closed in
    # _authoritative_materialization_selection_sizes().
    authoritative_selection_sizes = None
    if _training_policy_generation(cfg) == "train2":
        if size_convergence.outcome in {
            "awaiting_stage_b0_coarse_training",
            "awaiting_stage_b1_short_training",
            "awaiting_stage_c_full_training",
        }:
            _ok(
                "TARGET-DATA2D convergence is awaiting training evidence; "
                "DATA7/DATA8 materialization is deferred until selected_target_size is frozen"
            )
            _mark_stage(
                store,
                paths,
                "prepare",
                StageState.WAITING,
                "TARGET-DATA2D convergence pending Stage B0/B1/C size-fidelity evidence",
            )
            return False
        authoritative_selection_sizes = _authoritative_materialization_selection_sizes(
            size_convergence, ladder=target_ladder
        )
    replay, replay_qualification, replay_failures, _ = _qualify_replay(cfg, paths)
    if replay_failures:
        raise CampaignCliError("Replay production gate did not pass: " + "; ".join(replay_failures))
    store.put_record("replay_plan", replay)
    store.put_record("replay_qualification", replay_qualification)
    _persist_single_source_replay_authority(store, cfg, paths)

    # ADAPT-MON1: every new production variant is bound to the same fixed
    # target/replay monitor policy. Replay monitoring uses independent true
    # labels even when gradient replay itself uses foundation pseudo labels.
    true_replay_resolution = _resolve_true_label_replay_inputs(
        cfg, paths, require_train=False
    )
    if true_replay_resolution is None:
        raise CampaignCliError(
            "ADAPT-MON1 preparation requires independent true DFT replay labels. "
            "New campaigns obtain them from [paths].replay_set; legacy campaigns use [paths].replay_true_labels."
        )
    online_monitor_policy = mdstats.OnlineMonitorPolicy(
        target_configurations=int(
            _cfg(cfg, "training", "online_target_monitor_configurations", 256)
        ),
        replay_configurations=int(
            _cfg(cfg, "training", "online_replay_monitor_configurations", 512)
        ),
        training_diagnostic_configurations=int(
            _cfg(cfg, "training", "training_diagnostic_monitor_configurations", 256)
        ),
        seed=int(_cfg(cfg, "random", "online_monitor_seed", 161803)),
    )
    store.put_record("online_monitor_policy", online_monitor_policy)
    store.put_record(
        "online_true_replay_source", true_replay_resolution.monitor_artifact
    )
    _ok(
        "ADAPT-MON1 monitor policy: "
        f"target={online_monitor_policy.target_configurations}, "
        f"true-replay={online_monitor_policy.replay_configurations}, "
        f"train-diagnostic={online_monitor_policy.training_diagnostic_configurations}, "
        f"seed={online_monitor_policy.seed}"
    )

    foundation = _resolved_foundation_potential_identity(cfg, paths)
    selected_head_qualification = _stored_selected_head_training_foundation(paths, foundation)
    mace_source = Path(__import__("mace").__file__).resolve().parent
    probe = mdstats.probe_mace_source_tree(mace_source.parent)
    all_numbers = tuple(int(v) for v in _cfg(cfg, "profile", "all_atomic_numbers", (3, 8, 11, 13, 14, 19)))
    foundation_e0 = _extract_foundation_e0(
        model_path, all_numbers, foundation_identity=foundation
    )
    store.put_record("foundation_e0", {"e0_ev": {str(k): v for k, v in foundation_e0.items()}, "model_sha256": _sha256(model_path)})

    early_blockers = _pre_materialization_corpus_blockers(frames, data5)
    if early_blockers:
        if "unresolved_frame_strain" in early_blockers:
            frame_by_uid = {item.frame_uid: item for item in frames.frames}
            affected = sorted({
                frame_by_uid[item.frame_uid].run_id
                for item in frames.strain_records
                if item.tensor_class.value == "unresolved"
            })
            _warn(
                "DATA3 contains unresolved strain for "
                f"{len(affected)} run(s): {', '.join(affected[:8])}"
                + (" ..." if len(affected) > 8 else "")
            )
        remediation = (
            " Rebuild DATA2-DATA6 with `prepare --rebuild-catalog` after installing the patched package."
            if "unresolved_frame_strain" in early_blockers
            else ""
        )
        raise CampaignCliError(
            "Pre-materialization production gate did not pass: "
            + ", ".join(early_blockers)
            + "."
            + remediation
        )

    data8_bundles = []
    materializations = []
    variants = _variant_specs(cfg, selection_sizes=authoritative_selection_sizes)
    expected_variant_ids = {variant.variant_id for variant in variants}
    # Remove pointers for variants no longer requested, but retain every
    # matching pointer so unchanged jobs can be restored without rehashing or
    # relinking their DATA7/DATA8 trees.
    for prefix in ("data8:", "materialization:"):
        for key in store.record_keys(prefix):
            if key.split(":", 1)[1] not in expected_variant_ids:
                store.delete_record(key)
    _print_header("DATA7/DATA8 selection, fitting, and MACE materialization")
    loader_workers, loader_resources, loader_estimate = _resolve_mace_loader_workers(cfg)
    print(f"Resource budget: {loader_resources.summary()}", flush=True)
    print(
        f"MACE DataLoader workers={loader_workers}; "
        f"estimated RAM/worker={loader_estimate / 1024**2:.0f} MiB",
        flush=True,
    )
    foundation_prediction_energy: dict[str, float] | None = None

    def resolved_foundation_prediction_energy() -> dict[str, float] | None:
        nonlocal foundation_prediction_energy
        if foundation_prediction_energy is not None or sweep.prediction_manifest is None:
            return foundation_prediction_energy
        print(
            "[DATA7 setup] reconstructing foundation energies from authenticated DATA6 evidence",
            flush=True,
        )
        energy_start = time.monotonic()
        from ._frame_access import build_frame_array_index

        frame_index = build_frame_array_index(frames, resolved_frame_data())
        values: dict[str, float] = {}
        for catalog in data6.training_difficulty_catalogs:
            for item in catalog.records:
                _frame_record, source_data, local_index = frame_index[item.frame_uid]
                if source_data.energies_ev is None:
                    raise CampaignCliError(
                        f"DATA6 difficulty evidence lacks its DFT energy for {item.frame_uid}."
                    )
                predicted = (
                    float(source_data.energies_ev[local_index])
                    + item.signed_energy_error_ev
                )
                previous = values.setdefault(item.frame_uid, predicted)
                if abs(previous - predicted) > 1.0e-10:
                    raise CampaignCliError(
                        f"Overlapping DATA6 domains disagree on foundation energy for {item.frame_uid}."
                    )
        for catalog in data6.blinded_prediction_catalogs:
            for item in catalog.records:
                previous = values.setdefault(
                    item.frame_uid, item.predicted_energy_ev
                )
                if abs(previous - item.predicted_energy_ev) > 1.0e-10:
                    raise CampaignCliError(
                        f"DATA6 prediction catalogs disagree on foundation energy for {item.frame_uid}."
                    )

        expected_energy_uids = {
            item.frame_uid for item in sweep.prediction_manifest.records
        }
        missing_energy_uids = sorted(expected_energy_uids - set(values))
        if missing_energy_uids:
            print(
                f"[DATA7 setup] {len(missing_energy_uids)} energies are absent from compact DATA6 "
                "summaries; authenticating only those sidecars",
                flush=True,
            )
            energy_cache = sweep.prediction_cache()
            for energy_index, frame_uid in enumerate(missing_energy_uids, start=1):
                values[frame_uid] = energy_cache.energy_for_frame(frame_uid)
                if energy_index == len(missing_energy_uids) or energy_index % 1000 == 0:
                    print(
                        f"[DATA7 setup {energy_index:>6}/{len(missing_energy_uids)}] "
                        "authenticated fallback energy sidecars",
                        flush=True,
                    )
        unexpected = set(values) - expected_energy_uids
        if unexpected:
            raise CampaignCliError(
                "DATA6 compact prediction evidence contains frames outside the completed sweep."
            )
        _ok(
            f"foundation energies prepared once; elapsed={format_progress_time(time.monotonic() - energy_start)}; "
            f"reused {len(expected_energy_uids) - len(missing_energy_uids)} compact summaries and "
            f"read {len(missing_energy_uids)} sidecars"
        )
        foundation_prediction_energy = values
        return foundation_prediction_energy

    shared_data7_artifacts: dict[str, Any] = {}
    shared_data7_cache = paths.internal / "data7-cache"
    shared_data8_fixed_file_cache = paths.internal / "data8-fixed-cache"
    shared_frame_array_index_cache: dict[str, Any] = {}
    cross_validation_cache: dict[tuple[int, int], tuple[Any, ...]] = {}
    variant_progress = _ProgressReporter("DATA8", len(variants))
    for variant_index, variant in enumerate(variants, start=1):
        mode = variant.mode
        size = variant.selection_size
        seed = variant.seed
        variant_id = variant.variant_id
        variant_progress.item_start(variant_index, variant_id, "selection + fold-local fit + ExtXYZ/YAML")
        variant_start = time.monotonic()
        require_replay = mode == "multihead_replay"
        fold_key = (
            variant.cross_validation_folds,
            variant.fold_partition_seed,
        )
        variant_cv_plans = cross_validation_cache.get(fold_key)
        if variant_cv_plans is None:
            variant_cv_plans = _variant_cross_validation_plans(
                data5, frames, data4, variant
            )
            cross_validation_cache[fold_key] = variant_cv_plans
        policy_generation = _training_policy_generation(cfg)
        adaptive_stop_policy = None
        training_budget_policy = None
        learning_rate_schedule_policy = None
        checkpoint_admissibility_policy = None
        checkpoint_selection_policy = None
        if policy_generation == "train2":
            (
                training_budget_policy,
                learning_rate_schedule_policy,
                checkpoint_admissibility_policy,
                checkpoint_selection_policy,
            ) = _train2_policy_set(cfg, require_replay=require_replay)
        else:
            adaptive_stop_policy = _adaptive_training_stop_policy(
                cfg, replay_head_name=("pt_head" if require_replay else "replay_monitor")
            )
        plan = mdstats.build_production_materialization_plan(
            sources,
            frames,
            data4,
            data5,
            data6,
            sweep,
            foundation_checkpoint=foundation,
            selected_head_qualification=selected_head_qualification,
            compatibility_probe=probe,
            replay_plan=replay,
            cross_validation_plans=variant_cv_plans,
            online_monitor_policy=online_monitor_policy,
            true_replay_monitor_artifact=true_replay_resolution.monitor_artifact,
            adaptive_stop_policy=adaptive_stop_policy,
            training_budget_policy=training_budget_policy,
            learning_rate_schedule_policy=learning_rate_schedule_policy,
            checkpoint_admissibility_policy=checkpoint_admissibility_policy,
            checkpoint_selection_policy=checkpoint_selection_policy,
            feature_metric_policy=mdstats.FeatureMetricPolicyTemplate(
                randomized_projection_seed=int(
                    _cfg(cfg, "random", "feature_projection_seed", 271828)
                )
            ),
            atomic_reference_policy=mdstats.AtomicReferenceFitPolicy(
                fit_mode=mdstats.AtomicReferenceFitMode.FOUNDATION_RESIDUAL
            ),
            objective_policy=mdstats.TrainingObjectivePolicy(
                energy_weight=float(_cfg(cfg, "objective", "energy_weight", 1.0)),
                forces_weight=float(_cfg(cfg, "objective", "forces_weight", 10.0)),
                stress_weight=float(_cfg(cfg, "objective", "stress_weight", 1.0)),
                group_aware_force_objective=True,
                focus_atom_group_ids=("mobile_ions",),
                focus_atomic_numbers=tuple(int(v) for v in _cfg(cfg, "profile", "mobile_atomic_numbers", (3, 11, 19))),
            ),
            configuration_weight_policy=mdstats.ConfigurationWeightPolicy(),
            checkpoint_metric_policy=mdstats.CheckpointMetricPolicy(
                focus_atom_group_ids=("mobile_ions",),
                focus_atomic_numbers=tuple(int(v) for v in _cfg(cfg, "profile", "mobile_atomic_numbers", (3, 11, 19))),
                maximum_energy_mae_ev_per_atom=_optional_float(_cfg(cfg, "acceptance", "maximum_energy_mae_ev_per_atom")),
                maximum_focus_force_rmse_ev_per_angstrom=_optional_float(_cfg(cfg, "acceptance", "maximum_focus_force_rmse_ev_per_angstrom")),
                maximum_stress_rmse_ev_per_angstrom3=_optional_float(_cfg(cfg, "acceptance", "maximum_stress_rmse_ev_per_angstrom3")),
                maximum_worst_condition_force_rmse_ev_per_angstrom=_optional_float(_cfg(cfg, "acceptance", "maximum_worst_condition_force_rmse_ev_per_angstrom")),
                maximum_replay_degradation_fraction=(
            None
            if _training_policy_generation(cfg) == "train2"
            else float(_cfg(cfg, "acceptance", "maximum_replay_degradation_fraction", 0.20))
        ),
            ),
            selection_budget_policy=mdstats.SelectionBudgetPolicy(
                target_sizes=(
                    authoritative_selection_sizes
                    if authoritative_selection_sizes is not None
                    else tuple(
                        sorted(
                            set(
                                int(v)
                                for v in _cfg(cfg, "selection", "sizes", (512,))
                            )
                        )
                    )
                ),
            ),
            optimizer_policy=_optimizer_policy(
                cfg, seed=seed, num_workers=loader_workers
            ),
            checkpoint_control_policy=mdstats.MaceCheckpointControlPolicy(),
            extxyz_policy=mdstats.MaceExtxyzPolicy(),
            foundation_reference_energies=foundation_e0,
            selection_size=size,
            require_foundation_residual_e0=True,
            require_replay=require_replay,
        )
        output = paths.data / variant_id / plan.content_digest[:12]
        reused = _reuse_materialization_if_current(
            store,
            variant_id=variant_id,
            plan=plan,
        )
        if reused is not None:
            record, bundle = reused
            registered_data7 = mdstats.register_reusable_data7_artifacts(
                record, shared_data7_artifacts
            )
            materializations.append(record)
            data8_bundles.append(bundle)
            suffix = (
                f"; registered {registered_data7} promoted DATA7 recipe(s) for later variants"
                if registered_data7
                else ""
            )
            variant_progress.item_done(
                variant_index,
                variant_id,
                "reused completed DATA7/DATA8; no tree scan or rematerialization" + suffix,
            )
            _ok(f"DATA7/DATA8 artifacts reused for {variant_id}{suffix}")
            continue
        record = mdstats.run_restartable_production_materialization(
            sources,
            frames,
            resolved_frame_data(),
            data4,
            data5,
            data6,
            sweep,
            plan,
            output,
            mace_descriptor_root=paths.internal / "model-sweep",
            foundation_prediction_energy_by_frame=resolved_foundation_prediction_energy(),
            shared_data7_cache_directory=shared_data7_cache,
            shared_data7_artifacts=shared_data7_artifacts,
            shared_data8_fixed_file_cache_directory=shared_data8_fixed_file_cache,
            shared_frame_array_index_cache=shared_frame_array_index_cache,
            execution_policy=mdstats.ProductionMaterializationExecutionPolicy(
                max_new_data7_domains=max_new_domains,
                materialize_data8=True,
                verify_existing=True,
                recompute_invalid=True,
            ),
            progress_callback=lambda message, variant_id=variant_id: print(
                f"[{variant_id}] {message}", flush=True
            ),
        )
        store.put_record(f"materialization:{variant_id}", record)
        materializations.append(record)
        if record.complete:
            bundle = record.load_data8_bundle()
            store.put_record(f"data8:{variant_id}", bundle)
            data8_bundles.append(bundle)
            variant_progress.item_done(
                variant_index, variant_id, f"elapsed={format_progress_time(time.monotonic() - variant_start)}"
            )
            _ok(f"DATA7/DATA8 artifacts materialized for {variant_id}; final DATA9A gate pending")
        else:
            _warn(f"materialization incomplete for {variant_id}; rerun `prepare`")
            return False

    anchor, replay_required, qualification_anchor_id = _select_production_gate_anchor(
        variants, materializations, data8_bundles
    )
    _ok(
        "production gate representative selected: "
        f"{qualification_anchor_id}; replay_required={str(replay_required).lower()}"
    )
    normalization = store.get_payload("normalization_manifest")
    reference = store.get_payload("reference_manifest")
    run_evidence = _run_evidence(sources)
    store.put_record("run_evidence", run_evidence)
    expected = tuple(
        mdstats.ProductionExpectedRun(
            run_id=v["run_id"],
            frame_count=int(v["frame_count"]),
            reduced_formula=str(v["reduced_formula"]),
            ensemble=str(v["ensemble"]),
            target_start_kelvin=v["target_start_kelvin"],
            target_end_kelvin=v["target_end_kelvin"],
        )
        for v in run_evidence["runs"]
    )
    from mdstats.training_data._common import digest
    production_plan = mdstats.ProductionCorpusPlan(
        plan_id=f"{_cfg(cfg, 'campaign', 'id', 'mlff-campaign')}-production",
        dataset_id=frames.dataset_id,
        source_catalog_digest=sources.content_digest,
        frame_catalog_digest=frames.content_digest,
        normalization_manifest_digest=digest(normalization),
        reference_manifest_digest=digest(reference),
        expected_runs=expected,
        expected_cross_validation_fold_count=sum(len(v.folds) for v in data5.cross_validation_plans),
        required_profile_extensions=(
            mdstats.ProfileExtensionEvidenceRequirement(extension_id="lta"),
        ),
        require_replay_corpus=replay_required,
    )
    qualification = mdstats.build_production_corpus_qualification_record(
        production_plan=production_plan,
        normalization_manifest=normalization,
        reference_manifest=reference,
        run_evidence_manifest=run_evidence,
        source_catalog=sources,
        frame_catalog=frames,
        data4_bundle=data4,
        data5_bundle=data5,
        data6_bundle=data6,
        production_materialization=anchor,
    )
    store.put_record("production_plan", production_plan)
    store.put_record("production_qualification", qualification)
    store.set_meta("data8_variants", [variant.variant_id for variant in variants])
    _update_benchmark(
        paths,
        "prepare_materialization",
        {
            "variant_count": len(variants),
            "production_gate_status": qualification.status.value,
            "production_gate_blockers": list(qualification.blockers),
            "data8_bundle_digests": [v.content_digest for v in data8_bundles],
        },
    )
    if qualification.status.value != "passed" or not qualification.full_data9a_passed:
        _print_production_gate_diagnostics(frames, qualification)
        raise CampaignCliError(
            "Production gate did not pass: " + ", ".join(qualification.blockers or ("unspecified blocker",))
        )
    _write_prepare_restart_receipt(
        cfg,
        paths,
        store,
        sources=sources,
        variants=variants,
        materializations=materializations,
        bundles=data8_bundles,
    )
    _ok("production DATA9A gate passed")
    return True


def command_prepare(args: argparse.Namespace) -> int:
    cfg, paths = _load_config(args.config)
    _binary_model_precision_contract(cfg)
    store = CampaignStore(paths.state_db)
    _require_stage_complete(store, paths, "doctor")
    _stored_acceleration_realization(cfg, paths, require_qualified=True)

    continue_after_approval = bool(getattr(args, "continue_after_approval", False))
    if args.approve_manifest and not continue_after_approval:
        manifest = _ensure_manifest(
            cfg,
            paths,
            approve=True,
            refresh_inferences=bool(getattr(args, "refresh_inferences", False)),
        )
        _mark_stage(
            store, paths, "prepare", StageState.WAITING,
            "manifest approved; run plain `prepare` to execute DATA2-DATA9A",
        )
        _ok(f"manifest approved: {manifest.content_digest}")
        print("Next: run `prepare` without --approve-manifest.", flush=True)
        return 0

    plain_restart = bool(
        not args.rebuild_catalog
        and not args.approve_manifest
        and not bool(getattr(args, "refresh_inferences", False))
        and args.max_new_frames is None
        and args.max_new_domains is None
    )
    if plain_restart and _try_reuse_completed_prepare(cfg, paths, store):
        return 0

    _mark_stage(store, paths, "prepare", StageState.RUNNING, "building production MACE data")
    precision_profile = _print_precision_profile(cfg)
    store.put_record("precision_profile", precision_profile)
    _atomic_json(paths.results / "precision-profile.json", precision_profile)
    frame_data: Mapping[str, Any] | None = None
    try:
        if not store.has_record("data5") or args.rebuild_catalog:
            frame_data = _prepare_catalog(
                cfg,
                paths,
                store,
                approve_manifest=args.approve_manifest,
                refresh_inferences=bool(getattr(args, "refresh_inferences", False)),
            )
        else:
            _ok(
                "DATA2-DATA5 records are present; normalized frame arrays will be "
                "restored only if DATA6 or a changed DATA7/DATA8 variant needs them"
            )
        _ensure_target_data_role_freeze(store)
        max_frames = args.max_new_frames
        if max_frames is None:
            configured = int(_cfg(cfg, "model", "max_new_frames", 0))
            max_frames = None if configured == 0 else configured
        sweep = _prepare_sweep(
            cfg, paths, store, max_new_frames=max_frames, frame_data_by_run=frame_data
        )
        if sweep is None:
            _mark_stage(store, paths, "prepare", StageState.WAITING, "foundation sweep is resumable and incomplete")
            return 2
        if not _prepare_materialization(
            cfg,
            paths,
            store,
            max_new_domains=args.max_new_domains,
            frame_data_by_run=frame_data,
            sweep_artifacts=sweep,
        ):
            _mark_stage(
                store,
                paths,
                "prepare",
                StageState.WAITING,
                "DATA7/DATA8 materialization deferred until TARGET-DATA2D selected_target_size is frozen",
            )
            return 0
    except CampaignCliError as exc:
        if "Manifest" in str(exc) or "manifest" in str(exc):
            _mark_stage(store, paths, "prepare", StageState.WAITING, str(exc))
            print(str(exc), flush=True)
            return 2
        _mark_stage(store, paths, "prepare", StageState.FAILED, str(exc))
        raise
    _mark_stage(store, paths, "prepare", StageState.COMPLETE, "production data gate passed")
    print("\nPreparation passed. Next: `preflight`.", flush=True)
    return 0

_DATA8_VARIANT_RE = re.compile(
    r"^(naive_fine_tuning|multihead_replay)-n(?P<size>[0-9]+)-seed(?P<seed>-?[0-9]+)$"
)


def _validate_data8_variant_identity(variant_id: str, bundle: Any) -> None:
    """Fail early when a DATA8 pointer disagrees with its frozen protocol.

    This catches stale 0.20.67a0 naive variants, which were materialized with a
    replay corpus and consequently identified themselves as multi-head replay.
    """

    match = _DATA8_VARIANT_RE.fullmatch(variant_id)
    if match is None:
        raise CampaignCliError(
            f"Unrecognized DATA8 variant identifier {variant_id!r}. Rerun `prepare`."
        )
    expected = (
        str(match.group(1)),
        int(match.group("size")),
        int(match.group("seed")),
    )
    observed = {
        (
            job.protocol.training_mode.value,
            int(job.protocol.selection_size),
            int(job.protocol.optimizer_policy.seed),
        )
        for job in bundle.jobs
    }
    if observed != {expected}:
        rendered = ", ".join(
            f"{mode}/n{size}/seed{seed}"
            for mode, size, seed in sorted(observed)
        ) or "no jobs"
        raise CampaignCliError(
            "DATA8 variant/protocol identity mismatch for "
            f"{variant_id}: stored jobs declare {rendered}. "
            "This can be produced by the pre-0.20.68a0 naive/replay aliasing defect. "
            "Run ordinary `prepare` once with the patched package; DATA3-DATA7 "
            "and the completed foundation sweep will be reused."
        )


def _data8_matrix_digest(entries: Sequence[_Data8RuntimeEntry]) -> str:
    """Digest the immutable DATA8 variant matrix authorized by preflight."""

    return digest(
        {
            "schema": "mdstats.campaign-data8-matrix.v1",
            "variants": [
                {
                    "variant_id": entry.variant_id,
                    "bundle_digest": entry.bundle.content_digest,
                }
                for entry in sorted(entries, key=lambda item: item.variant_id)
            ],
        }
    )


def _current_data8_entries(store: CampaignStore) -> list[_Data8RuntimeEntry]:
    import mdstats

    keys = store.record_keys("data8:")
    if not keys:
        raise CampaignCliError("No DATA8 bundles are available. Run `prepare` first.")
    entries: list[_Data8RuntimeEntry] = []
    for key in keys:
        variant_id = key.split(":", 1)[1]
        bundle = store.get_record(key, mdstats.Data8PreparationBundle)
        _validate_data8_variant_identity(variant_id, bundle)
        materialization_key = f"materialization:{variant_id}"
        materialization = None
        root = Path(bundle.output_directory)
        if store.has_record(materialization_key):
            materialization = store.get_record(
                materialization_key, mdstats.ProductionMaterializationRecord
            )
            artifact = materialization.checkpoint.data8_artifact
            if artifact is None:
                raise CampaignCliError(
                    f"DATA8 materialization has no promoted artifact: {variant_id}. "
                    "Rerun `prepare`."
                )
            if artifact.bundle_digest != bundle.content_digest:
                raise CampaignCliError(
                    f"DATA8 bundle/materialization lineage mismatch: {variant_id}. "
                    "Rerun `prepare`."
                )
            root = Path(materialization.root_directory) / artifact.relative_directory
        root = root.resolve()
        if not root.is_dir():
            raise CampaignCliError(
                f"DATA8 runtime directory is missing for {variant_id}: {root}. "
                "Rerun `prepare` to repair the promoted artifact pointer."
            )
        entries.append(
            _Data8RuntimeEntry(
                variant_id=variant_id,
                bundle=bundle,
                root=root,
                materialization=materialization,
            )
        )
    return entries


def _current_data8_bundles(store: CampaignStore) -> list[Any]:
    return [entry.bundle for entry in _current_data8_entries(store)]


def _terminate_process(process: subprocess.Popen[Any], *, grace_seconds: float) -> None:
    """Terminate a subprocess and its descendants without leaving GPU workers."""
    if process.poll() is not None:
        return
    if os.name == "posix":
        try:
            os.killpg(process.pid, signal.SIGTERM)
        except ProcessLookupError:
            return
    else:  # pragma: no cover - Windows fallback
        process.terminate()
    try:
        process.wait(timeout=grace_seconds)
        return
    except subprocess.TimeoutExpired:
        pass
    if os.name == "posix":
        try:
            os.killpg(process.pid, signal.SIGKILL)
        except ProcessLookupError:
            return
    else:  # pragma: no cover - Windows fallback
        process.kill()
    process.wait()


def _run_bounded_process(
    command: Sequence[str],
    *,
    cwd: Path,
    env: Mapping[str, str],
    stdout_path: Path,
    stderr_path: Path,
    timeout_seconds: float,
    grace_seconds: float,
    progress_label: str | None = None,
    progress_interval_seconds: float = 60.0,
    progress_probe: Callable[[], str | None] | None = None,
) -> dict[str, Any]:
    started = _utc_now()
    start_clock = time.monotonic()
    timed_out = False
    with stdout_path.open("wb") as stdout, stderr_path.open("wb") as stderr:
        process = subprocess.Popen(
            tuple(str(v) for v in command),
            cwd=cwd,
            env=dict(env),
            stdout=stdout,
            stderr=stderr,
            start_new_session=(os.name == "posix"),
        )
        deadline = start_clock + timeout_seconds
        try:
            while True:
                remaining = deadline - time.monotonic()
                if remaining <= 0.0:
                    timed_out = True
                    _terminate_process(process, grace_seconds=grace_seconds)
                    return_code = int(process.returncode if process.returncode is not None else -9)
                    break
                try:
                    return_code = int(process.wait(timeout=min(progress_interval_seconds, remaining)))
                    break
                except subprocess.TimeoutExpired:
                    if progress_label:
                        stdout.flush()
                        stderr.flush()
                        elapsed = _ProgressReporter._duration(time.monotonic() - start_clock)
                        detail = None
                        if progress_probe is not None:
                            try:
                                detail = progress_probe()
                            except Exception as exc:  # progress must never abort the child
                                detail = f"progress probe unavailable ({type(exc).__name__})"
                        if detail:
                            print(
                                f"[{progress_label}] status=running; elapsed={elapsed}; "
                                f"eta=--:--:--; {detail}",
                                flush=True,
                            )
                        else:
                            print(
                                f"[{progress_label}] status=running; elapsed={elapsed}; "
                                f"eta=--:--:--; stdout={_file_size_mib(stdout_path):.1f} MiB; "
                                f"stderr={_file_size_mib(stderr_path):.1f} MiB",
                                flush=True,
                            )
        except KeyboardInterrupt:
            _terminate_process(process, grace_seconds=grace_seconds)
            raise
    return {
        "command": [str(v) for v in command],
        "started_utc": started,
        "finished_utc": _utc_now(),
        "elapsed_seconds": time.monotonic() - start_clock,
        "return_code": return_code,
        "timed_out": timed_out,
        "stdout_path": str(stdout_path),
        "stdout_sha256": _sha256(stdout_path),
        "stderr_path": str(stderr_path),
        "stderr_sha256": _sha256(stderr_path),
        "passed": bool(return_code == 0 and not timed_out),
    }



def _resolve_mace_input_path(value: str | Path, *, cwd: Path) -> Path:
    path = Path(value).expanduser()
    return (path if path.is_absolute() else cwd / path).resolve()


def _write_bounded_extxyz_subset(
    source: Path,
    destination: Path,
    *,
    maximum_configurations: int,
    required_atomic_numbers: Iterable[int] = (),
) -> int:
    """Write a deterministic leading subset, extending only for element coverage."""

    from ase.io import iread, write

    if maximum_configurations <= 0:
        raise CampaignCliError("Preflight subset limits must be positive integers.")
    required = {int(value) for value in required_atomic_numbers}
    covered: set[int] = set()
    selected: list[Any] = []
    try:
        iterator = iread(source, index=":", format="extxyz")
        for atoms in iterator:
            numbers = {int(value) for value in atoms.numbers}
            introduces_required = bool((required - covered) & numbers)
            if len(selected) < maximum_configurations or introduces_required:
                selected.append(atoms.copy())
                covered.update(numbers)
            if len(selected) >= maximum_configurations and required <= covered:
                break
    except Exception as exc:
        raise CampaignCliError(
            f"Could not read preflight smoke source {source}: {type(exc).__name__}: {exc}"
        ) from exc
    if not selected:
        raise CampaignCliError(f"Preflight smoke source contains no configurations: {source}")
    missing = sorted(required - covered)
    if missing:
        raise CampaignCliError(
            f"Preflight target subset could not cover atomic numbers {missing}: {source}"
        )
    destination.parent.mkdir(parents=True, exist_ok=True)
    write(destination, selected, format="extxyz")
    return len(selected)


def _bounded_preflight_configuration(
    cfg: Mapping[str, Any],
    *,
    source_config_path: Path,
    job_dir: Path,
    smoke_root: Path,
    job: Any,
) -> tuple[Path, dict[str, Any], int | None, Path | None]:
    """Build a small, real DATA8 smoke configuration without altering DATA8.

    DATA8 byte verification already proves the complete production tree.  The
    preflight child only needs enough real target/replay configurations to
    exercise graph construction, multi-head loss, backward propagation,
    checkpoint export, head extraction, and finite evaluation on the selected
    accelerator.  Running a full epoch over a ~10k replay corpus is not a
    bounded smoke test and can waste hours before production training begins.
    """

    try:
        import yaml

        payload = yaml.safe_load(source_config_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise CampaignCliError(
            f"Could not parse the DATA8 MACE configuration for bounded preflight: {exc}"
        ) from exc
    if not isinstance(payload, dict):
        raise CampaignCliError("DATA8 MACE configuration is not a mapping.")
    if "heads" not in payload:
        # Keep the helper compatible with synthetic/unit-test configurations.
        return source_config_path, {"bounded": False}, None, None
    try:
        heads_value = payload["heads"]
        heads = heads_value if isinstance(heads_value, dict) else ast.literal_eval(str(heads_value))
    except Exception as exc:
        raise CampaignCliError(f"Could not parse DATA8 MACE head definitions: {exc}") from exc
    if not isinstance(heads, dict) or not heads:
        raise CampaignCliError("DATA8 MACE heads must be a non-empty mapping.")

    loader = getattr(job, "loader_dry_run", None)
    target_head_name = str(getattr(loader, "target_head_name", "target_head"))
    if target_head_name not in heads:
        raise CampaignCliError(
            f"Preflight could not find target head {target_head_name!r} in DATA8 configuration."
        )
    target_head = dict(heads[target_head_name])
    try:
        required_target_numbers = {
            int(value) for value in ast.literal_eval(str(target_head.get("atomic_numbers", "[]")))
        }
    except Exception as exc:
        raise CampaignCliError(f"Could not parse target-head atomic numbers: {exc}") from exc

    limits = {
        "target_train": int(_cfg(cfg, "preflight", "target_train_configurations", 32)),
        "target_valid": int(_cfg(cfg, "preflight", "target_valid_configurations", 8)),
        "replay_train": int(_cfg(cfg, "preflight", "replay_train_configurations", 64)),
        "replay_valid": int(_cfg(cfg, "preflight", "replay_valid_configurations", 8)),
    }
    if any(value <= 0 for value in limits.values()):
        raise CampaignCliError(
            "[preflight] target/replay train/valid configuration limits must all be positive."
        )

    source_target_train = _resolve_mace_input_path(target_head["train_file"], cwd=job_dir)
    source_target_valid = _resolve_mace_input_path(target_head["valid_file"], cwd=job_dir)
    smoke_target_train = smoke_root / "target_train.smoke.xyz"
    smoke_target_valid = smoke_root / "target_valid.smoke.xyz"
    target_train_count = _write_bounded_extxyz_subset(
        source_target_train,
        smoke_target_train,
        maximum_configurations=limits["target_train"],
        required_atomic_numbers=required_target_numbers,
    )
    target_valid_count = _write_bounded_extxyz_subset(
        source_target_valid,
        smoke_target_valid,
        maximum_configurations=limits["target_valid"],
    )
    target_head["train_file"] = str(smoke_target_train)
    target_head["valid_file"] = str(smoke_target_valid)
    heads[target_head_name] = target_head

    replay_train_count = 0
    replay_valid_count = 0
    if payload.get("pt_train_file") and payload.get("pt_valid_file"):
        source_replay_train = _resolve_mace_input_path(payload["pt_train_file"], cwd=job_dir)
        source_replay_valid = _resolve_mace_input_path(payload["pt_valid_file"], cwd=job_dir)
        smoke_replay_train = smoke_root / "replay_train.smoke.xyz"
        smoke_replay_valid = smoke_root / "replay_valid.smoke.xyz"
        replay_train_count = _write_bounded_extxyz_subset(
            source_replay_train,
            smoke_replay_train,
            maximum_configurations=limits["replay_train"],
        )
        replay_valid_count = _write_bounded_extxyz_subset(
            source_replay_valid,
            smoke_replay_valid,
            maximum_configurations=limits["replay_valid"],
        )
        payload["pt_train_file"] = str(smoke_replay_train)
        payload["pt_valid_file"] = str(smoke_replay_valid)

    payload["heads"] = repr(heads)
    payload["max_num_epochs"] = 1
    payload["plot"] = False
    payload["save_all_checkpoints"] = True
    smoke_config_path = smoke_root / "mace_config.preflight.yaml"
    smoke_config_path.write_text(
        yaml.safe_dump(payload, sort_keys=False), encoding="utf-8"
    )

    batch_size = max(1, int(payload.get("batch_size", 1)))
    target_factor = 1
    threshold = float(payload.get("real_pt_data_ratio_threshold", 0.0))
    if replay_train_count > 0:
        ratio = target_train_count / replay_train_count
        if ratio > 0.0 and ratio < threshold:
            target_factor += int(threshold / ratio)
    effective_train_count = target_train_count * target_factor + replay_train_count
    expected_updates = max(1, effective_train_count // batch_size)
    metadata = {
        "bounded": True,
        "source_config_path": str(source_config_path),
        "smoke_config_path": str(smoke_config_path),
        "smoke_config_sha256": _sha256(smoke_config_path),
        "target_train_configurations": target_train_count,
        "target_valid_configurations": target_valid_count,
        "replay_train_configurations": replay_train_count,
        "replay_valid_configurations": replay_valid_count,
        "target_duplication_factor": target_factor,
        "effective_train_configurations": effective_train_count,
        "batch_size": batch_size,
        "expected_gradient_updates": expected_updates,
    }
    return smoke_config_path, metadata, expected_updates, smoke_target_valid


def _training_device_description(device: str, acceleration: Any, dtype: str) -> str:
    requested = str(device)
    backend = getattr(getattr(acceleration, "backend", None), "value", "unknown")
    if not requested.startswith("cuda"):
        try:
            import torch

            suffix = " (CUDA is available but the frozen campaign selects CPU)" if torch.cuda.is_available() else ""
        except Exception:
            suffix = ""
        return f"device=cpu{suffix}; backend={backend}; dtype={dtype}"
    try:
        import torch

        if not torch.cuda.is_available():
            return f"device={requested} requested but CUDA is unavailable; backend={backend}; dtype={dtype}"
        index = torch.cuda.current_device()
        if ":" in requested:
            try:
                index = int(requested.split(":", 1)[1])
            except ValueError:
                pass
        props = torch.cuda.get_device_properties(index)
        return (
            f"device=cuda:{index} ({torch.cuda.get_device_name(index)}, "
            f"{props.total_memory / 1024**3:.1f} GiB); backend={backend}; dtype={dtype}"
        )
    except Exception as exc:
        return f"device={requested}; backend={backend}; dtype={dtype}; probe={type(exc).__name__}"


def _gpu_telemetry(device: str) -> str | None:
    sample = query_gpu_telemetry(device)
    return None if sample is None else sample.summary()


@dataclass(frozen=True)
class _MaceTrainingProgressSnapshot:
    updates: int
    latest_epoch: int | None
    phase: str
    true_epoch_active: bool
    seconds_since_last_update: float | None


@dataclass
class _MaceTrainingProgressProbe:
    log_dir: Path
    result_dir: Path
    expected_updates: int | None
    device: str
    max_epochs: int = 1
    checkpoint_dir: Path | None = None
    epoch_activity_timeout_seconds: float = 120.0
    _lock: threading.Lock = field(default_factory=threading.Lock, init=False, repr=False)
    _file_offsets: dict[Path, int] = field(default_factory=dict, init=False, repr=False)
    _file_partials: dict[Path, bytes] = field(default_factory=dict, init=False, repr=False)
    _file_segments: dict[Path, list[dict[int, int]]] = field(default_factory=dict, init=False, repr=False)
    _file_latest_raw_epoch: dict[Path, int | None] = field(default_factory=dict, init=False, repr=False)
    _raw_updates_total: int = field(default=0, init=False, repr=False)
    _updates_total: int = field(default=0, init=False, repr=False)
    _latest_epoch: int | None = field(default=None, init=False, repr=False)
    _last_update_monotonic: float | None = field(default=None, init=False, repr=False)
    _primed: bool = field(default=False, init=False, repr=False)

    def __post_init__(self) -> None:
        # Existing rows can span several interrupted attempts.  Prime the full
        # attempt history, but do not label the new child as active until it
        # appends a fresh optimizer row.
        self._refresh_gradient_updates(mark_activity=False)
        self._primed = True

    def _log_tail(self) -> str:
        candidates = [path for path in self.log_dir.glob("*.log") if "_debug" not in path.name]
        if not candidates:
            candidates = list(self.log_dir.glob("*.log"))
        if not candidates:
            return ""
        latest = max(candidates, key=lambda path: path.stat().st_mtime_ns)
        try:
            with latest.open("rb") as handle:
                size = latest.stat().st_size
                handle.seek(max(0, size - 131072))
                return handle.read().decode("utf-8", errors="replace")
        except OSError:
            return ""

    def _latest_checkpoint_epoch(self) -> int | None:
        if self.checkpoint_dir is None or not self.checkpoint_dir.is_dir():
            return None
        regex = re.compile(r"(?:epoch[-_]?)(\d+)", re.IGNORECASE)
        epochs: list[int] = []
        try:
            paths = tuple(self.checkpoint_dir.rglob("*.pt"))
        except OSError:
            return None
        for path in paths:
            match = regex.search(path.name)
            if match is not None and path.is_file():
                epochs.append(int(match.group(1)))
        return max(epochs) if epochs else None

    def _reset_file(self, path: Path) -> None:
        self._file_offsets[path] = 0
        self._file_partials[path] = b""
        self._file_segments[path] = [dict()]
        self._file_latest_raw_epoch[path] = None

    def _canonical_progress(self, checkpoint_epoch: int | None) -> tuple[int, int | None]:
        total = 0
        latest_epochs: list[int] = []
        for path, segments in self._file_segments.items():
            if not segments:
                continue
            latest_segment = segments[-1]
            if checkpoint_epoch is None:
                # No durable checkpoint means earlier attempt segments cannot
                # be continued and must not inflate progress.
                total += sum(latest_segment.values())
                latest_epochs.extend(latest_segment)
                continue

            all_epochs = {epoch for segment in segments for epoch in segment}
            for epoch in all_epochs:
                if epoch <= checkpoint_epoch:
                    # A checkpoint commits one realization of the epoch.  Rows
                    # from a replayed attempt are duplicate evidence, not new
                    # gradient progress.
                    total += max(segment.get(epoch, 0) for segment in segments)
            for epoch, count in latest_segment.items():
                if epoch > checkpoint_epoch:
                    total += count
                    latest_epochs.append(epoch)
        if checkpoint_epoch is not None:
            latest_epochs.append(checkpoint_epoch)
        return total, (max(latest_epochs) if latest_epochs else None)

    def _refresh_gradient_updates(self, *, mark_activity: bool = True) -> tuple[int, int | None, int | None]:
        previous_raw_total = self._raw_updates_total
        paths = tuple(sorted(self.result_dir.glob("*_train.txt")))
        live = set(paths)
        for stale in tuple(self._file_offsets):
            if stale not in live:
                self._file_offsets.pop(stale, None)
                self._file_partials.pop(stale, None)
                self._file_segments.pop(stale, None)
                self._file_latest_raw_epoch.pop(stale, None)

        for path in paths:
            try:
                size = path.stat().st_size
                if path not in self._file_offsets:
                    self._reset_file(path)
                offset = self._file_offsets[path]
                if size < offset:
                    self._reset_file(path)
                    offset = 0
                with path.open("rb") as handle:
                    handle.seek(offset)
                    chunk = handle.read()
                    self._file_offsets[path] = handle.tell()
            except OSError:
                continue
            if not chunk:
                continue
            payload = self._file_partials.get(path, b"") + chunk
            lines = payload.split(b"\n")
            self._file_partials[path] = lines.pop() if lines else b""
            segments = self._file_segments.setdefault(path, [dict()])
            latest_raw_epoch = self._file_latest_raw_epoch.get(path)
            for raw in lines:
                if not raw.strip():
                    continue
                try:
                    item = json.loads(raw.decode("utf-8", errors="replace"))
                except (json.JSONDecodeError, UnicodeDecodeError):
                    continue
                if item.get("mode") != "opt":
                    continue
                try:
                    epoch = int(item.get("epoch"))
                except (TypeError, ValueError):
                    continue
                if latest_raw_epoch is not None and epoch < latest_raw_epoch:
                    segments.append({})
                segments[-1][epoch] = segments[-1].get(epoch, 0) + 1
                latest_raw_epoch = epoch
            self._file_latest_raw_epoch[path] = latest_raw_epoch

        self._raw_updates_total = sum(
            sum(sum(segment.values()) for segment in segments)
            for segments in self._file_segments.values()
        )
        checkpoint_epoch = self._latest_checkpoint_epoch()
        self._updates_total, self._latest_epoch = self._canonical_progress(checkpoint_epoch)
        if mark_activity and self._primed and self._raw_updates_total > previous_raw_total:
            self._last_update_monotonic = time.monotonic()
        return self._updates_total, self._latest_epoch, checkpoint_epoch

    def snapshot(self, *, now: float | None = None) -> _MaceTrainingProgressSnapshot:
        current = time.monotonic() if now is None else float(now)
        with self._lock:
            updates, epoch, checkpoint_epoch = self._refresh_gradient_updates(mark_activity=True)
            tail = self._log_tail()
            age = (
                None
                if self._last_update_monotonic is None
                else max(0.0, current - self._last_update_monotonic)
            )
            expected_complete = (
                self.expected_updates is not None
                and updates >= self.expected_updates
            )
            fresh_optimizer_activity = (
                self._raw_updates_total > 0
                and age is not None
                and age <= float(self.epoch_activity_timeout_seconds)
                and not expected_complete
            )
            latest_raw_epochs = [
                value for value in self._file_latest_raw_epoch.values() if value is not None
            ]
            latest_raw_epoch = max(latest_raw_epochs) if latest_raw_epochs else None
            replaying_committed_epoch = (
                fresh_optimizer_activity
                and checkpoint_epoch is not None
                and latest_raw_epoch is not None
                and latest_raw_epoch <= checkpoint_epoch
            )

            if expected_complete:
                phase = "post-epoch validation/checkpoint"
            elif replaying_committed_epoch:
                phase = (
                    f"restart checkpoint epoch {checkpoint_epoch + 1}/{self.max_epochs} "
                    "(duplicate updates excluded)"
                )
            elif fresh_optimizer_activity:
                current_epoch = min(self.max_epochs, (epoch or 0) + 1)
                phase = f"epoch {current_epoch}/{self.max_epochs}"
            elif "Saving model to" in tail or "Computing metrics for training" in tail:
                phase = "saving/exporting model"
            elif "Training complete" in tail:
                phase = "post-epoch evaluation/checkpoint"
            elif updates > 0:
                current_epoch = min(self.max_epochs, (epoch or 0) + 1)
                phase = f"epoch {current_epoch}/{self.max_epochs} (inactive)"
            elif "===========TRAINING===========" in tail:
                phase = "initial validation / first update"
            elif "OPTIMIZER INFORMATION" in tail:
                phase = "model and optimizer setup"
            elif "Processing datasets for head" in tail:
                phase = "building graph datasets"
            elif "LOADING INPUT DATA" in tail:
                phase = "loading input data"
            elif tail:
                phase = "initializing MACE"
            else:
                phase = "starting MACE child"

            return _MaceTrainingProgressSnapshot(
                updates=updates,
                latest_epoch=epoch,
                phase=phase,
                true_epoch_active=fresh_optimizer_activity,
                seconds_since_last_update=age,
            )

    def __call__(self) -> str:
        state = self.snapshot()
        expected = self.expected_updates
        if expected is not None and expected > 0:
            bounded = min(state.updates, expected)
            progress = f"progress={bounded:,}/{expected:,} ({100.0 * bounded / expected:.1f}%); unit=gradient-update"
        else:
            progress = f"progress={state.updates:,}; unit=gradient-update"
        telemetry = _gpu_telemetry(self.device)
        return "; ".join(
            item for item in (f"phase={state.phase}", progress, telemetry) if item
        )

def _run_local_preflight_smoke(
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    bundle: Any,
    job: Any,
    *,
    data8_root: str | Path | None = None,
) -> dict[str, Any]:
    """Run one epoch through the production wrappers and reload its target head."""
    import numpy as np
    from ase.io import read

    root = Path(bundle.output_directory if data8_root is None else data8_root).resolve()
    job_dir = (root / job.relative_directory).resolve()
    config_path = (root / job.config_relative_path).resolve()
    if not config_path.is_file() or _sha256(config_path) != job.config_sha256:
        raise CampaignCliError("Preflight refused a missing or changed DATA8 MACE configuration.")

    smoke_root = paths.internal / "preflight-smoke"
    if smoke_root.exists():
        shutil.rmtree(smoke_root)
    model_dir = smoke_root / "models"
    checkpoint_dir = smoke_root / "checkpoints"
    log_dir = smoke_root / "logs"
    result_dir = smoke_root / "results"
    for directory in (model_dir, checkpoint_dir, log_dir, result_dir):
        directory.mkdir(parents=True, exist_ok=True)

    name = "mdstats_campaign_preflight"
    wrappers = _ensure_local_wrappers(paths)
    device = str(_cfg(cfg, "training", "device", "cuda"))
    dtype = str(_cfg(cfg, "training", "dtype", "float32"))
    training_acceleration = _training_acceleration_policy(cfg)
    source_acceleration = _acceleration_policy(cfg)
    smoke_config_path, smoke_dataset, expected_updates, smoke_evaluation_path = (
        _bounded_preflight_configuration(
            cfg,
            source_config_path=config_path,
            job_dir=job_dir,
            smoke_root=smoke_root,
            job=job,
        )
    )
    loader_workers, loader_resources, loader_estimate = _resolve_mace_loader_workers(cfg)
    print(f"Resource budget: {loader_resources.summary()}", flush=True)
    print(
        f"Preflight MACE DataLoader workers={loader_workers}; "
        f"estimated RAM/worker={loader_estimate / 1024**2:.0f} MiB",
        flush=True,
    )
    device_description = _training_device_description(device, training_acceleration, dtype)
    if smoke_dataset.get("bounded"):
        print(
            "[PREFLIGHT train] bounded one-epoch smoke: "
            f"target={smoke_dataset['target_train_configurations']} train/"
            f"{smoke_dataset['target_valid_configurations']} valid; "
            f"replay={smoke_dataset['replay_train_configurations']} train/"
            f"{smoke_dataset['replay_valid_configurations']} valid; "
            f"expected gradient updates={smoke_dataset['expected_gradient_updates']}; "
            f"{device_description}",
            flush=True,
        )
    else:
        print(f"[PREFLIGHT train] one-epoch smoke; {device_description}", flush=True)
    timeout = float(_cfg(cfg, "preflight", "timeout_seconds", 1800.0))
    grace = float(_cfg(cfg, "execution", "terminate_grace_seconds", 30.0))
    env = dict(os.environ)
    job_protocol = getattr(job, "protocol", None)
    job_optimizer = getattr(job_protocol, "optimizer_policy", None)
    fallback_seed = _variant_specs(cfg)[0].seed
    env.setdefault("PYTHONHASHSEED", str(getattr(job_optimizer, "seed", fallback_seed)))
    threads = str(int(_cfg(cfg, "preflight", "num_threads", 1)))
    for key in ("OMP_NUM_THREADS", "MKL_NUM_THREADS", "OPENBLAS_NUM_THREADS", "NUMEXPR_NUM_THREADS"):
        env[key] = threads

    training_command = (
        str(wrappers["mdstats-mace-train"]),
        "--config", str(smoke_config_path),
        "--name", name,
        "--max_num_epochs", "1",
        "--device", device,
        "--default_dtype", dtype,
        "--model_dir", str(model_dir),
        "--checkpoints_dir", str(checkpoint_dir),
        "--log_dir", str(log_dir),
        "--results_dir", str(result_dir),
        "--num_workers", str(loader_workers),
        "--keep_checkpoints",
        "--save_all_checkpoints",
        "--save_cpu",
    )
    training = _run_bounded_process(
        training_command,
        cwd=job_dir,
        env=env,
        stdout_path=smoke_root / "training.stdout.log",
        stderr_path=smoke_root / "training.stderr.log",
        timeout_seconds=timeout,
        grace_seconds=grace,
        progress_label="PREFLIGHT train",
        progress_interval_seconds=float(_cfg(cfg, "execution", "progress_interval_seconds", 60.0)),
        progress_probe=_MaceTrainingProgressProbe(
            log_dir=log_dir,
            result_dir=result_dir,
            checkpoint_dir=checkpoint_dir,
            expected_updates=expected_updates,
            device=device,
        ),
    )

    models = tuple(sorted(model_dir.glob("*.model")))
    checkpoints = tuple(sorted(checkpoint_dir.rglob("*.pt"))) + tuple(sorted(checkpoint_dir.rglob("*.model")))
    expected_model = model_dir / f"{name}.model"
    selected_model = expected_model if expected_model.is_file() else (models[0] if models else None)
    head_names: tuple[str, ...] = ()
    extraction: dict[str, Any] | None = None
    target_model = selected_model
    if training["passed"] and selected_model is not None:
        extracted_model = smoke_root / "target_head.model"
        extraction_command = (
            str(wrappers["mdstats-mace-select-head"]),
            str(selected_model),
            "--head_name", "target_head",
            "--target_device", device,
            "--output_file", str(extracted_model),
        )
        extraction = _run_bounded_process(
            extraction_command,
            cwd=smoke_root,
            env=env,
            stdout_path=smoke_root / "select-head.stdout.log",
            stderr_path=smoke_root / "select-head.stderr.log",
            timeout_seconds=timeout,
            grace_seconds=grace,
            progress_label="PREFLIGHT head extraction",
            progress_interval_seconds=float(_cfg(cfg, "execution", "progress_interval_seconds", 60.0)),
        )
        if extraction["passed"] and extracted_model.is_file():
            target_model = extracted_model
            head_names = ("target_head",)
        else:
            # MACE 0.3.16 rejects head removal from an already single-head model.
            # The original model remains a valid target-head candidate and is
            # accepted only if the independent wrapped evaluation succeeds.
            target_model = selected_model

    evaluation: dict[str, Any] | None = None
    evaluation_count = 0
    finite_round_trip = False
    evaluation_error: str | None = None
    if training["passed"] and target_model is not None:
        monitor = smoke_evaluation_path
        if monitor is None or not monitor.is_file():
            monitor = job_dir / "fold_evaluation.xyz"
        if not monitor.is_file():
            monitor = job_dir / "target_valid.xyz"
        prediction = smoke_root / "evaluation_predictions.xyz"
        evaluation_command = [
            str(wrappers["mdstats-mace-eval"]),
            "--configs", str(monitor),
            "--model", str(target_model),
            "--output", str(prediction),
            "--device", device,
            "--default_dtype", dtype,
            "--compute_stress",
        ]
        if source_acceleration.enable_cueq:
            evaluation_command.append("--enable_cueq")
        evaluation = _run_bounded_process(
            tuple(evaluation_command),
            cwd=smoke_root,
            env=env,
            stdout_path=smoke_root / "evaluation.stdout.log",
            stderr_path=smoke_root / "evaluation.stderr.log",
            timeout_seconds=timeout,
            grace_seconds=grace,
            progress_label="PREFLIGHT evaluation",
            progress_interval_seconds=float(_cfg(cfg, "execution", "progress_interval_seconds", 60.0)),
        )
        if evaluation["passed"] and prediction.is_file():
            try:
                atoms_list = read(prediction, index=":", format="extxyz")
                if not isinstance(atoms_list, list):
                    atoms_list = [atoms_list]
                evaluation_count = len(atoms_list)
                finite_round_trip = bool(atoms_list)
                for atoms in atoms_list:
                    energy = atoms.info.get("MACE_energy")
                    forces = atoms.arrays.get("MACE_forces")
                    stress = atoms.info.get("MACE_stress")
                    finite_round_trip = finite_round_trip and energy is not None and np.all(np.isfinite(np.asarray(energy, dtype=float)))
                    finite_round_trip = finite_round_trip and forces is not None and np.all(np.isfinite(np.asarray(forces, dtype=float)))
                    finite_round_trip = finite_round_trip and stress is not None and np.all(np.isfinite(np.asarray(stress, dtype=float)))
            except Exception as exc:
                evaluation_error = f"{type(exc).__name__}: {exc}"

    cueq_log_evidence = not training_acceleration.enable_cueq
    if training_acceleration.enable_cueq:
        evidence_paths = [
            smoke_root / "training.stdout.log",
            smoke_root / "training.stderr.log",
            *sorted(log_dir.rglob("*")),
        ]
        for evidence_path in evidence_paths:
            if evidence_path.is_file():
                try:
                    if "Converting model to CUEQ for accelerated training" in evidence_path.read_text(
                        encoding="utf-8", errors="replace"
                    ):
                        cueq_log_evidence = True
                        break
                except OSError:
                    continue

    passed = bool(
        training["passed"]
        and selected_model is not None
        and checkpoints
        and target_model is not None
        and evaluation is not None
        and evaluation["passed"]
        and finite_round_trip
        and cueq_log_evidence
    )
    return {
        "schema": "mdstats.mlff-campaign-preflight-smoke.v4",
        "config_path": str(config_path),
        "config_sha256": job.config_sha256,
        "smoke_config_path": str(smoke_config_path),
        "smoke_config_sha256": _sha256(smoke_config_path),
        "smoke_dataset": smoke_dataset,
        "device": device,
        "dtype": dtype,
        "training_acceleration_policy": training_acceleration.to_dict(),
        "source_acceleration_policy": source_acceleration.to_dict(),
        # Historical key retained as an alias for the training-side policy.
        "acceleration_policy": training_acceleration.to_dict(),
        "cueq_training_log_evidence": bool(cueq_log_evidence),
        "training": training,
        "extraction": extraction,
        "evaluation": evaluation,
        "model_paths": [str(v) for v in models],
        "model_sha256": [] if selected_model is None else [_sha256(selected_model)],
        "target_model_path": None if target_model is None else str(target_model),
        "target_model_sha256": None if target_model is None else _sha256(target_model),
        "checkpoint_count": len(checkpoints),
        "head_names": list(head_names),
        "model_load_error": None,
        "evaluation_configuration_count": evaluation_count,
        "finite_round_trip": bool(finite_round_trip),
        "evaluation_error": evaluation_error,
        "passed": passed,
    }

def _mace_config_e0_coverage_failures(
    config_payload: Mapping[str, Any],
) -> tuple[str, ...]:
    """Return explicit-head E0 coverage failures for MACE v0.3.16.

    MACE builds one element table across every head.  Any explicit E0 mapping
    must therefore contain every configured atomic number, even when some of
    those elements occur only in another head.  ``pt_head`` is excluded here
    because MACE replaces it with the foundation-backed head at runtime.
    """

    try:
        atomic_numbers = {
            int(value) for value in ast.literal_eval(str(config_payload["atomic_numbers"]))
        }
        heads = ast.literal_eval(str(config_payload["heads"]))
    except (KeyError, SyntaxError, TypeError, ValueError) as exc:
        return (f"could not parse MACE atomic_numbers/heads literals: {exc}",)
    failures: list[str] = []
    for head_name, head in heads.items():
        if str(head_name) == "pt_head":
            continue
        value = head.get("E0s")
        if value is None or str(value).lower() in {"foundation", "estimated"}:
            continue
        try:
            mapping = ast.literal_eval(str(value))
            available = {int(number) for number in mapping}
            required_value = head.get("atomic_numbers")
            required = (
                atomic_numbers
                if required_value is None
                else {int(number) for number in ast.literal_eval(str(required_value))}
            )
        except (SyntaxError, TypeError, ValueError) as exc:
            failures.append(f"{head_name} has an invalid E0s/atomic_numbers mapping: {exc}")
            continue
        missing = sorted(required - available)
        if missing:
            failures.append(
                f"{head_name} E0s omit global atomic numbers {missing}; "
                "regenerate DATA8 with mdstats >= 0.20.66a0"
            )
    return tuple(failures)


def _preflight_error_summary(path: Path) -> str:
    """Extract a concise root-cause line from a child-process stderr log."""

    try:
        lines = [
            line.strip()
            for line in path.read_text(encoding="utf-8", errors="replace").splitlines()
            if line.strip()
        ]
    except OSError:
        return "training child failed without a readable stderr log"
    prefixes = (
        "KeyError:",
        "ValueError:",
        "RuntimeError:",
        "AssertionError:",
        "TrainingDataInputError:",
        "CampaignCliError:",
    )
    for line in reversed(lines):
        if line.startswith(prefixes):
            return line
    return lines[-1] if lines else "training child exited without stderr output"


def command_preflight(args: argparse.Namespace) -> int:
    import mdstats

    cfg, paths = _load_config(args.config)
    _binary_model_precision_contract(cfg)
    store = CampaignStore(paths.state_db)
    _require_stage_complete(store, paths, "prepare")
    try:
        foundation_audit = _load_verified_foundation_audit_authority(store)
    except Exception as exc:
        raise CampaignCliError(
            "FOUNDATION-AUDIT1 is missing or stale; rerun `prepare` before preflight: "
            f"{exc}"
        ) from exc
    _ok(
        "FOUNDATION-AUDIT1 authority verified before preflight: "
        f"{foundation_audit.content_digest[:12]}..."
    )
    try:
        coverage_reference = _load_verified_target_coverage_reference_authority(store)
    except Exception as exc:
        raise CampaignCliError(
            "TARGET-DATA2B is missing or stale; rerun `prepare` before preflight: "
            f"{exc}"
        ) from exc
    _ok(
        "TARGET-DATA2B authority verified before preflight: "
        f"{coverage_reference.content_digest[:12]}..."
    )
    try:
        target_ladder = _load_verified_target_data_ladder_authority(store)
    except Exception as exc:
        raise CampaignCliError(
            "TARGET-DATA2C is missing or stale; rerun `prepare` before preflight: "
            f"{exc}"
        ) from exc
    _ok(
        "TARGET-DATA2C authority verified before preflight: "
        f"{target_ladder.content_digest[:12]}..."
    )
    try:
        size_convergence = _load_verified_target_size_convergence_authority(store)
    except Exception as exc:
        raise CampaignCliError(
            "TARGET-DATA2D is missing or stale; rerun `prepare` before preflight: "
            f"{exc}"
        ) from exc
    _ok(
        "TARGET-DATA2D authority verified before preflight: "
        f"coverage-qualified sizes={list(size_convergence.stage_a_survivor_sizes)}; "
        f"outcome={size_convergence.outcome}; {size_convergence.content_digest[:12]}..."
    )
    _mark_stage(store, paths, "preflight", StageState.RUNNING, "running bounded training preflight")
    failures: list[str] = []
    _print_header("Production preflight")
    _print_precision_profile(cfg)
    doctor_result = command_doctor(argparse.Namespace(config=args.config, embedded=True))
    if doctor_result != 0:
        failures.append("doctor failed")
    entries = _current_data8_entries(store)
    bundles = [entry.bundle for entry in entries]
    data8_matrix_digest = _data8_matrix_digest(entries)
    job_count = sum(len(v.jobs) for v in bundles)
    acceleration = _training_acceleration_policy(cfg)
    for entry in entries:
        for job in entry.bundle.jobs:
            label = f"{entry.variant_id}/{job.job_id}"
            config_path = entry.root / job.config_relative_path
            if not config_path.is_file():
                message = f"DATA8 config is missing: {label}: {config_path}"
                failures.append(message)
                _fail(message)
                continue
            observed_sha256 = _sha256(config_path)
            if observed_sha256 != job.config_sha256:
                message = (
                    f"DATA8 config failed byte verification: {label}: "
                    f"expected={job.config_sha256[:12]} observed={observed_sha256[:12]}"
                )
                failures.append(message)
                _fail(message)
                continue
            try:
                import yaml

                config_payload = yaml.safe_load(config_path.read_text(encoding="utf-8"))
                if bool(config_payload.get("enable_cueq", False)) != acceleration.enable_cueq:
                    message = f"DATA8 config acceleration mismatch: {label}"
                    failures.append(message)
                    _fail(message)
                if bool(config_payload.get("only_cueq", False)) != acceleration.only_cueq:
                    message = f"DATA8 config only_cueq mismatch: {label}"
                    failures.append(message)
                    _fail(message)
                for coverage_failure in _mace_config_e0_coverage_failures(config_payload):
                    message = f"DATA8 config E0 coverage mismatch: {label}: {coverage_failure}"
                    failures.append(message)
                    _fail(message)
            except Exception as exc:
                message = f"DATA8 config could not be inspected for acceleration: {label}: {exc}"
                failures.append(message)
                _fail(message)
    if failures:
        _mark_stage(store, paths, "preflight", StageState.FAILED, "; ".join(failures))
        print(
            "\nPreflight stopped before launching MACE because DATA8 runtime verification failed.",
            flush=True,
        )
        return 1
    _ok(f"verified {job_count} MACE job configurations across {len(entries)} variants")

    run_smoke = not bool(getattr(args, "check_only", False))
    smoke_payload: dict[str, Any] = {
        "requested": run_smoke,
        "passed": None,
        "data8_matrix_digest": data8_matrix_digest,
    }
    if run_smoke:
        first_entry = entries[0]
        first_bundle = first_entry.bundle
        first_job = next(
            (v for v in first_bundle.jobs if v.kind is mdstats.MaceJobKind.FINAL_DEVELOPMENT),
            first_bundle.jobs[0],
        )
        smoke_payload = _run_local_preflight_smoke(
            cfg, paths, first_bundle, first_job, data8_root=first_entry.root
        )
        smoke_payload["data8_matrix_digest"] = data8_matrix_digest
        store.put_record("preflight_smoke", smoke_payload)
        if not smoke_payload["passed"]:
            stderr_path = paths.internal / "preflight-smoke" / "training.stderr.log"
            child_detail = _preflight_error_summary(stderr_path)
            detail = (
                smoke_payload.get("model_load_error")
                or smoke_payload.get("evaluation_error")
                or child_detail
            )
            _fail(f"one-epoch real-MACE smoke failed: {detail}")
            _mark_stage(
                store, paths, "preflight", StageState.FAILED,
                f"one-epoch MACE smoke failed: {detail}",
            )
            raise CampaignCliError(
                "One-epoch real-MACE preflight failed: "
                f"{detail}. Full log: .mdstats/preflight-smoke/training.stderr.log"
            )
        _ok(
            "one-epoch real-MACE smoke passed "
            f"({smoke_payload['checkpoint_count']} checkpoints; finite target-head reload)"
        )
    else:
        _warn("check-only verification passed, but the real one-epoch smoke was not run")
        _update_benchmark(paths, "preflight", {"job_count": job_count, "smoke": smoke_payload})
        _mark_stage(
            store, paths, "preflight", StageState.WAITING,
            "DATA8 bytes passed; run `preflight` without --check-only to authorize training",
        )
        print("\nCheck-only preflight passed. Run `preflight` to execute the required one-epoch MACE smoke.")
        return 2
    _update_benchmark(paths, "preflight", {"job_count": job_count, "smoke": smoke_payload})
    _mark_stage(store, paths, "preflight", StageState.COMPLETE, "environment, DATA8, and real-MACE smoke passed")
    print("\nPreflight passed. Next: `train --dry-run`, then `train`.")
    return 0

def _build_campaign(cfg: Mapping[str, Any], store: CampaignStore, data8_bundles: Sequence[Any]) -> Any:
    import mdstats
    qualification = store.get_record("production_qualification", mdstats.ProductionCorpusQualificationRecord)
    acceleration_probe_digest = None
    acceleration_probe_record = store.get_record_optional(
        "acceleration_probe", mdstats.MaceAccelerationProbe
    )
    if acceleration_probe_record is not None:
        acceleration_probe_digest = acceleration_probe_record.content_digest
    authoritative_selection_sizes = None
    if _training_policy_generation(cfg) == "train2":
        ladder = _load_verified_target_data_ladder_authority(store)
        size_convergence = store.get_record(
            "target_size_convergence", mdstats.TargetSizeConvergencePlan
        )
        authoritative_selection_sizes = _authoritative_materialization_selection_sizes(
            size_convergence, ladder=ladder
        )
    variants = _variant_specs(cfg, selection_sizes=authoritative_selection_sizes)
    modes = tuple(
        sorted(
            {mdstats.TrainingMode(item.mode) for item in variants},
            key=lambda item: item.value,
        )
    )
    seeds = tuple(sorted({item.seed for item in variants}))
    policy = mdstats.TrainingCampaignPolicy(
        required_seeds=seeds,
        required_training_modes=modes,
        required_selection_sizes=tuple(sorted({item.selection_size for item in variants})),
        required_variants=tuple(
            (
                mdstats.TrainingMode(item.mode),
                item.selection_size,
                item.seed,
                item.cross_validation_folds,
            )
            for item in variants
        ),
        require_final_development=True,
        require_cross_validation=True,
        required_execution_wrapper="mdstats-mace-train",
        acceleration_probe_digest=acceleration_probe_digest,
    )
    return mdstats.build_training_campaign_plan(
        qualification,
        data8_bundles,
        campaign_id=str(_cfg(cfg, "campaign", "id", "mlff-campaign")),
        policy=policy,
    )


def _training_config_input_failures(config_path: Path, job_root: Path) -> tuple[str, ...]:
    """Return missing immutable MACE inputs resolved from the DATA8 job cwd."""

    try:
        import yaml

        payload = yaml.safe_load(config_path.read_text(encoding="utf-8"))
    except Exception as exc:
        return (f"could not parse {config_path}: {type(exc).__name__}: {exc}",)
    if not isinstance(payload, dict):
        return (f"MACE config is not a mapping: {config_path}",)

    candidates: list[tuple[str, Any]] = []
    for key in ("foundation_model", "pt_train_file", "pt_valid_file", "train_file", "valid_file", "test_file"):
        if payload.get(key) not in (None, ""):
            candidates.append((key, payload[key]))
    heads_value = payload.get("heads")
    try:
        heads = heads_value if isinstance(heads_value, dict) else ast.literal_eval(str(heads_value))
    except Exception as exc:
        return (f"could not parse MACE heads in {config_path}: {type(exc).__name__}: {exc}",)
    if isinstance(heads, dict):
        for head_name, head_payload in heads.items():
            if not isinstance(head_payload, Mapping):
                continue
            for key in ("train_file", "valid_file", "test_file"):
                if head_payload.get(key) not in (None, ""):
                    candidates.append((f"heads.{head_name}.{key}", head_payload[key]))

    failures: list[str] = []
    for label, raw in candidates:
        path = Path(str(raw)).expanduser()
        resolved = (path if path.is_absolute() else job_root / path).resolve()
        if not resolved.is_file():
            failures.append(f"{label} -> {resolved}")
    return tuple(failures)


def _archive_obsolete_training_runtime(run_root: Path, policy_digest: str) -> Path | None:
    """Discard heavy obsolete runtime bytes after retaining compact diagnostics.

    Older releases moved complete failed models/checkpoints/results into an
    ``obsolete-runtime-*`` directory. Repeated failures could therefore retain
    gigabytes of data that cannot participate in the current execution policy.
    This implementation inventories those bytes, preserves bounded log tails
    and the prior execution JSON, then deletes the heavy runtime immediately.
    """

    candidates = [
        *sorted(run_root.glob("attempt-*.stdout.log")),
        *sorted(run_root.glob("attempt-*.stderr.log")),
        run_root / "training_execution.json",
        run_root / "models",
        run_root / "logs",
        run_root / "results",
        run_root / "checkpoints",
    ]
    existing = [item for item in candidates if item.exists()]
    if not existing:
        return None

    diagnostic_root = run_root / "obsolete-runtime-diagnostics"
    diagnostic_root.mkdir(parents=True, exist_ok=True)
    base = diagnostic_root / f"obsolete-runtime-{policy_digest[:12]}.json"
    diagnostic = base
    suffix = 1
    while diagnostic.exists():
        diagnostic = diagnostic_root / f"{base.stem}-{suffix:02d}.json"
        suffix += 1

    files: list[dict[str, Any]] = []
    log_tails: dict[str, str] = {}
    maximum_inventory_entries = 2000
    maximum_log_tails = 16
    omitted_file_count = 0
    omitted_file_bytes = 0
    logical_size = 0
    prior_execution: Any | None = None
    for candidate in existing:
        size = _path_size_bytes(candidate)
        logical_size += size
        if candidate.is_file():
            if len(files) < maximum_inventory_entries:
                files.append({"relative_path": candidate.name, "size_bytes": size})
            else:
                omitted_file_count += 1
                omitted_file_bytes += size
            if candidate.name == "training_execution.json":
                try:
                    prior_execution = json.loads(candidate.read_text(encoding="utf-8"))
                except Exception:
                    prior_execution = None
            if candidate.suffix == ".log" and len(log_tails) < maximum_log_tails:
                tail = _diagnostic_log_tail(candidate)
                if tail:
                    log_tails[candidate.name] = tail
        elif candidate.is_dir():
            for item in sorted(candidate.rglob("*")):
                if not item.is_file():
                    continue
                try:
                    relative = item.relative_to(run_root).as_posix()
                    item_size = int(item.stat().st_size)
                except OSError:
                    continue
                if len(files) < maximum_inventory_entries:
                    files.append({"relative_path": relative, "size_bytes": item_size})
                else:
                    omitted_file_count += 1
                    omitted_file_bytes += item_size
                if item.suffix == ".log" and len(log_tails) < maximum_log_tails:
                    tail = _diagnostic_log_tail(item)
                    if tail:
                        log_tails[relative] = tail

    _atomic_json(
        diagnostic,
        {
            "schema": "mdstats.obsolete-training-runtime-diagnostic.v2",
            "created_utc": _utc_now(),
            "execution_policy_digest": policy_digest,
            "logical_size_bytes_removed": logical_size,
            "files": files,
            "omitted_file_count": omitted_file_count,
            "omitted_file_bytes": omitted_file_bytes,
            "log_tails": log_tails,
            "prior_execution": prior_execution,
        },
    )
    for item in existing:
        if item.is_file() or item.is_symlink():
            item.unlink(missing_ok=True)
        else:
            shutil.rmtree(item, ignore_errors=False)

    # Diagnostics are intentionally compact, but cap their count so repeated
    # incompatible retries cannot accumulate indefinitely.
    diagnostics = sorted(
        diagnostic_root.glob("obsolete-runtime-*.json"),
        key=lambda item: item.stat().st_mtime_ns,
        reverse=True,
    )
    for stale in diagnostics[5:]:
        stale.unlink(missing_ok=True)
    return diagnostic



@dataclass(frozen=True)
class _PendingTrainingTask:
    display_index: int
    run: Any
    job: Any
    data8_root: Path
    run_root: Path
    auxiliary_replay_monitor_path: Path | None
    replay_light_path: Path | None
    replay_light_sha256: str | None
    foundation_full_replay_path: Path | None
    foundation_model_sha256: str | None
    foundation_baseline_cache_path: Path | None
    state_key: str
    prior_record: Any | None
    expected_updates: int
    progress_probe: _MaceTrainingProgressProbe
    train2_execution_epoch_limit: int | None = None
    allow_successful_continuation: bool = False


def _training_concurrency_policy(cfg: Mapping[str, Any]) -> TrainingConcurrencyPolicy:
    """Resolve runtime-only adaptive training concurrency controls."""

    configured_training_window = _cfg(
        cfg,
        "execution",
        "parallel_training_epoch_stabilization_seconds",
        None,
    )
    if configured_training_window is None:
        training_window_seconds = 60.0
    else:
        training_window_seconds = float(configured_training_window)
        # 0.20.87a0 generated 180 seconds as the package default. Migrate that
        # exact generated value to the new one-minute policy while preserving
        # every genuinely customized value.
        if math.isclose(
            training_window_seconds,
            180.0,
            rel_tol=0.0,
            abs_tol=1.0e-12,
        ):
            training_window_seconds = 60.0

    try:
        return TrainingConcurrencyPolicy(
            requested_jobs=int(_cfg(cfg, "execution", "parallel_training_jobs", 0)),
            minimum_auto_jobs=int(_cfg(cfg, "execution", "minimum_parallel_training_jobs", 1)),
            maximum_auto_jobs=int(_cfg(cfg, "execution", "maximum_parallel_training_jobs", 4)),
            gpu_memory_fraction=float(
                _cfg(
                    cfg,
                    "execution",
                    "training_gpu_memory_fraction",
                    0.90,
                )
            ),
            gpu_utilization_fraction=float(
                _cfg(cfg, "execution", "training_gpu_utilization_fraction", 0.90)
            ),
            estimated_gpu_memory_mib_per_job=float(
                _cfg(cfg, "execution", "estimated_training_vram_mib_per_job", 6144.0)
            ),
            estimated_ram_mib_per_job=float(
                _cfg(cfg, "execution", "estimated_training_ram_mib_per_job", 8192.0)
            ),
            epoch_stabilization_seconds=training_window_seconds,
            stability_samples=int(
                _cfg(cfg, "execution", "parallel_training_epoch_stability_samples", 12)
            ),
            stability_relative_tolerance=float(
                _cfg(cfg, "execution", "parallel_training_stability_relative_tolerance", 0.10)
            ),
            utilization_stability_absolute_tolerance=float(
                _cfg(
                    cfg,
                    "execution",
                    "parallel_training_utilization_stability_absolute_tolerance",
                    8.0,
                )
            ),
            observed_memory_growth_margin=float(
                _cfg(cfg, "execution", "parallel_training_memory_growth_margin", 1.05)
            ),
            observed_utilization_growth_margin=float(
                _cfg(cfg, "execution", "parallel_training_utilization_growth_margin", 1.05)
            ),
            monitor_interval_seconds=float(
                _cfg(cfg, "execution", "parallel_training_monitor_interval_seconds", 10.0)
            ),
        )
    except ValueError as exc:
        raise CampaignCliError(str(exc)) from exc


def _inference_concurrency_policy(
    cfg: Mapping[str, Any], phase: str
) -> InferenceConcurrencyPolicy:
    """Resolve runtime-only evaluation/verification concurrency controls."""

    if phase not in {"evaluation", "verification"}:
        raise CampaignCliError(f"Unsupported inference concurrency phase: {phase}")

    def value(suffix: str, default: Any) -> Any:
        specific = _cfg(cfg, "execution", f"{phase}_{suffix}", None)
        if specific is not None:
            return specific
        return _cfg(cfg, "execution", f"inference_{suffix}", default)

    def calibration_window_seconds() -> float:
        """Resolve the one-job CUDA calibration duration.

        Evaluation and verification calibrate one CUDA job for five minutes
        and reuse a peak-trimmed upper-band per-job estimate for the remaining
        queue. Exact shared defaults emitted by 0.20.86a0--0.20.89a0
        (10, 60, 20, and 180 seconds) migrate to 300 seconds. Explicit
        phase-specific values remain authoritative for users who intentionally
        tuned a phase.
        """

        specific_new = _cfg(
            cfg,
            "execution",
            f"parallel_{phase}_calibration_window_seconds",
            None,
        )
        if specific_new is not None:
            return float(specific_new)
        shared_new = _cfg(
            cfg,
            "execution",
            "parallel_inference_calibration_window_seconds",
            None,
        )
        if shared_new is not None:
            shared_value = float(shared_new)
            if any(
                math.isclose(shared_value, old, rel_tol=0.0, abs_tol=1.0e-12)
                for old in (20.0, 60.0, 180.0)
            ):
                return 300.0
            return shared_value
        specific_legacy = _cfg(
            cfg,
            "execution",
            f"parallel_{phase}_stabilization_seconds",
            None,
        )
        if specific_legacy is not None:
            return float(specific_legacy)
        shared_legacy = _cfg(
            cfg,
            "execution",
            "parallel_inference_stabilization_seconds",
            None,
        )
        if shared_legacy is None:
            return 300.0
        legacy_value = float(shared_legacy)
        if math.isclose(legacy_value, 10.0, rel_tol=0.0, abs_tol=1.0e-12):
            return 300.0
        return legacy_value

    def cpu_calibration_window_seconds() -> float:
        """Resolve the shorter CPU workload window with legacy compatibility."""

        specific_cpu = _cfg(
            cfg,
            "execution",
            f"parallel_{phase}_cpu_calibration_window_seconds",
            None,
        )
        if specific_cpu is not None:
            return float(specific_cpu)
        shared_cpu = _cfg(
            cfg,
            "execution",
            "parallel_inference_cpu_calibration_window_seconds",
            None,
        )
        if shared_cpu is not None:
            return float(shared_cpu)

        # Before 0.20.89a0 the same calibration-window key controlled CPU and
        # CUDA admission. Preserve deliberate phase-specific/custom values, but
        # migrate generated shared defaults back to the new 20-second CPU
        # default rather than inheriting the new five-minute CUDA window.
        specific_new = _cfg(
            cfg,
            "execution",
            f"parallel_{phase}_calibration_window_seconds",
            None,
        )
        if specific_new is not None:
            return float(specific_new)
        specific_legacy = _cfg(
            cfg,
            "execution",
            f"parallel_{phase}_stabilization_seconds",
            None,
        )
        if specific_legacy is not None:
            return float(specific_legacy)
        shared_new = _cfg(
            cfg,
            "execution",
            "parallel_inference_calibration_window_seconds",
            None,
        )
        if shared_new is not None:
            shared_value = float(shared_new)
            if any(
                math.isclose(shared_value, old, rel_tol=0.0, abs_tol=1.0e-12)
                for old in (20.0, 60.0)
            ):
                return 20.0
            return shared_value
        shared_legacy = _cfg(
            cfg,
            "execution",
            "parallel_inference_stabilization_seconds",
            None,
        )
        if shared_legacy is not None:
            legacy_value = float(shared_legacy)
            if math.isclose(legacy_value, 10.0, rel_tol=0.0, abs_tol=1.0e-12):
                return 20.0
            return legacy_value
        return 20.0

    def gpu_calibration_peak_trim_fraction() -> float:
        """Resolve peak trimming with 0.20.91 generated-default migration.

        The 0.20.91a0 generated TOML wrote the shared value 0.10.  The new
        default trims only the highest 5% so the fixed estimate moves upward
        to the 85th--95th percentile band.  Explicit phase-specific values
        remain authoritative; other custom shared values are preserved.
        """

        specific = _cfg(
            cfg, "execution", f"{phase}_gpu_calibration_peak_trim_fraction", None
        )
        if specific is not None:
            return float(specific)
        shared = _cfg(
            cfg, "execution", "inference_gpu_calibration_peak_trim_fraction", None
        )
        if shared is None:
            return 0.05
        shared_value = float(shared)
        if math.isclose(shared_value, 0.10, rel_tol=0.0, abs_tol=1.0e-12):
            return 0.05
        return shared_value

    def gpu_calibration_band_fraction() -> float:
        """Resolve upper-band width while accepting the 0.20.90 legacy key."""

        specific_new = _cfg(
            cfg, "execution", f"{phase}_gpu_calibration_band_fraction", None
        )
        if specific_new is not None:
            return float(specific_new)
        specific_legacy = _cfg(
            cfg, "execution", f"{phase}_gpu_calibration_upper_tail_fraction", None
        )
        if specific_legacy is not None:
            return float(specific_legacy)
        shared_new = _cfg(
            cfg, "execution", "inference_gpu_calibration_band_fraction", None
        )
        if shared_new is not None:
            return float(shared_new)
        shared_legacy = _cfg(
            cfg, "execution", "inference_gpu_calibration_upper_tail_fraction", None
        )
        if shared_legacy is not None:
            return float(shared_legacy)
        return 0.10

    try:
        return InferenceConcurrencyPolicy(
            requested_jobs=int(
                _cfg(
                    cfg,
                    "execution",
                    f"parallel_{phase}_jobs",
                    _cfg(cfg, "execution", "parallel_inference_jobs", 0),
                )
            ),
            maximum_auto_jobs=int(
                _cfg(
                    cfg,
                    "execution",
                    f"maximum_parallel_{phase}_jobs",
                    _cfg(cfg, "execution", "maximum_parallel_inference_jobs", 0),
                )
            ),
            cpu_utilization_fraction=float(value("cpu_utilization_fraction", 0.90)),
            gpu_memory_fraction=float(value("gpu_memory_fraction", 0.90)),
            gpu_utilization_fraction=float(value("gpu_utilization_fraction", 0.90)),
            estimated_gpu_memory_mib_per_job=float(
                value("estimated_vram_mib_per_job", 4096.0)
            ),
            estimated_ram_mib_per_job=float(
                value("estimated_ram_mib_per_job", 4096.0)
            ),
            stabilization_seconds=calibration_window_seconds(),
            cpu_stabilization_seconds=cpu_calibration_window_seconds(),
            minimum_gpu_activity_fraction=float(
                value("gpu_minimum_activity_fraction", 0.01)
            ),
            gpu_calibration_peak_trim_fraction=gpu_calibration_peak_trim_fraction(),
            gpu_calibration_band_fraction=gpu_calibration_band_fraction(),
            stability_samples=int(
                _cfg(
                    cfg,
                    "execution",
                    f"parallel_{phase}_stability_samples",
                    _cfg(
                        cfg,
                        "execution",
                        "parallel_inference_stability_samples",
                        3,
                    ),
                )
            ),
            observed_memory_growth_margin=float(
                value("memory_growth_margin", 1.05)
            ),
            observed_utilization_growth_margin=float(
                value("utilization_growth_margin", 1.05)
            ),
            monitor_interval_seconds=float(
                _cfg(
                    cfg,
                    "execution",
                    f"parallel_{phase}_monitor_interval_seconds",
                    _cfg(
                        cfg,
                        "execution",
                        "parallel_inference_monitor_interval_seconds",
                        2.0,
                    ),
                )
            ),
        )
    except ValueError as exc:
        raise CampaignCliError(str(exc)) from exc


def _configure_inference_thread_budget(plan: Any) -> None:
    """Bound nested native pools so outer inference jobs respect the CPU cap."""

    bounded = configure_worker_thread_environment(
        os.environ, threads=plan.cpu_threads_per_job
    )
    for key, value in bounded.items():
        if key in {
            "OMP_NUM_THREADS",
            "MKL_NUM_THREADS",
            "OPENBLAS_NUM_THREADS",
            "NUMEXPR_NUM_THREADS",
            "VECLIB_MAXIMUM_THREADS",
            "BLIS_NUM_THREADS",
        }:
            os.environ[key] = value
    os.environ["TORCH_NUM_THREADS"] = str(plan.cpu_threads_per_job)
    try:
        import torch

        torch.set_num_threads(max(1, int(plan.cpu_threads_per_job)))
        try:
            torch.set_num_interop_threads(1)
        except RuntimeError:
            # PyTorch permits this setting only before inter-op work begins.
            pass
    except (ModuleNotFoundError, RuntimeError):
        pass


@dataclass(frozen=True)
class _AdaptiveInferenceTask:
    display_index: int
    key: str
    label: str
    start_detail: str
    execute: Callable[[], Any]
    done_detail: Callable[[Any, float], str]
    on_success: Callable[[Any], None] | None = None


@dataclass
class _InferenceWorkerStatus:
    """Thread-safe stage and telemetry status for one adaptive worker."""

    workload_started: threading.Event = field(default_factory=threading.Event)
    _phase: str = "starting worker"
    _lock: threading.Lock = field(default_factory=threading.Lock)

    def set_phase(self, phase: str) -> bool:
        normalized = str(phase).strip() or "initializing"
        with self._lock:
            changed = normalized != self._phase
            self._phase = normalized
            return changed

    def mark_workload_started(self) -> None:
        self.workload_started.set()

    def phase(self) -> str:
        with self._lock:
            return self._phase


def _post_calibration_gpu_poll_seconds(
    cfg: Mapping[str, Any], policy: InferenceConcurrencyPolicy
) -> float:
    """Return the cheaper live-VRAM polling cadence after calibration."""

    configured = float(
        _cfg(
            cfg,
            "execution",
            "parallel_inference_post_calibration_monitor_interval_seconds",
            30.0,
        )
    )
    if not math.isfinite(configured) or configured <= 0.0:
        raise CampaignCliError(
            "[execution].parallel_inference_post_calibration_monitor_interval_seconds "
            "must be positive."
        )
    return max(float(policy.monitor_interval_seconds), configured)


def _maybe_query_inference_gpu_telemetry(
    *,
    cfg: Mapping[str, Any],
    policy: InferenceConcurrencyPolicy,
    controller: AdaptiveInferenceConcurrency,
    device: str,
    active_jobs: int,
    now: float,
    last_sample_monotonic: float,
) -> tuple[Any | None, float]:
    if not str(device).startswith("cuda") or int(active_jobs) <= 0:
        return None, last_sample_monotonic
    interval = (
        _post_calibration_gpu_poll_seconds(cfg, policy)
        if controller.gpu_calibrated
        else float(policy.monitor_interval_seconds)
    )
    if last_sample_monotonic > 0.0 and now - last_sample_monotonic < interval:
        return None, last_sample_monotonic
    return query_gpu_telemetry(device), now


def _run_adaptive_inference_tasks(
    tasks: Sequence[_AdaptiveInferenceTask],
    *,
    cfg: Mapping[str, Any],
    phase: str,
    device: str,
    progress: Any,
) -> dict[str, Any]:
    """Execute independent inference tasks under adaptive CPU/GPU admission."""

    if not tasks:
        return {}
    policy = _inference_concurrency_policy(cfg, phase)
    try:
        resources = detect_system_resources(
            cpu_fraction=float(_cfg(cfg, "performance", "cpu_fraction", 0.90)),
            ram_fraction=float(_cfg(cfg, "performance", "ram_fraction", 0.80)),
            gpu_memory_fraction=float(policy.gpu_memory_fraction),
            device=device,
        )
    except ValueError as exc:
        raise CampaignCliError(str(exc)) from exc
    cpu_probe = CpuTelemetryProbe(
        capacity_threads=resources.cpu_threads_available
    )
    cpu_sample = cpu_probe.sample(blocking_seconds=0.10)
    gpu_sample = query_gpu_telemetry(device)
    plan = build_inference_concurrency_plan(
        task_count=len(tasks),
        device=device,
        resources=resources,
        policy=policy,
        gpu_sample=gpu_sample,
        cpu_sample=cpu_sample,
    )
    _ok(f"{phase} concurrency: {plan.summary()}")
    _configure_inference_thread_budget(plan)
    controller = AdaptiveInferenceConcurrency(plan, policy)
    pending = deque(tasks)
    active: dict[
        Future[Any], tuple[_AdaptiveInferenceTask, float, _InferenceWorkerStatus]
    ] = {}
    results: dict[str, Any] = {}
    failures: list[str] = []
    stage_events: deque[tuple[str, str]] = deque()
    stage_events_lock = threading.Lock()
    stop_scheduling = False
    last_report = 0.0
    scheduler_started = time.monotonic()
    telemetry_ready_active_jobs: int | None = None
    last_gpu_poll = 0.0

    def execute_task(
        task: _AdaptiveInferenceTask,
        status: _InferenceWorkerStatus,
    ) -> Any:
        def update_phase(stage: str) -> None:
            if status.set_phase(stage):
                with stage_events_lock:
                    stage_events.append((task.label, status.phase()))

        with inference_start_signal(
            status.mark_workload_started,
            phase_callback=update_phase,
        ):
            update_phase(f"preparing {phase} inputs")
            if not str(device).startswith("cuda"):
                return task.execute()
            # Independent CUDA streams make the admitted outer jobs genuinely
            # overlap-capable instead of serializing every kernel on the legacy
            # default stream.  The adaptive scheduler still controls aggregate
            # VRAM and GPU utilization before admitting more work.
            try:
                import torch

                cuda_device = torch.device(device)
                if not torch.cuda.is_available():
                    return task.execute()
                stream = torch.cuda.Stream(device=cuda_device)
                with torch.cuda.device(cuda_device), torch.cuda.stream(stream):
                    result = task.execute()
                stream.synchronize()
                return result
            except ModuleNotFoundError:
                return task.execute()

    def report_stage_events() -> None:
        with stage_events_lock:
            events = tuple(stage_events)
            stage_events.clear()
        for task_label, stage in events:
            print(
                f"[{phase.upper()} stage] status=phase; item={task_label}; phase={stage}",
                flush=True,
            )

    def launch(pool: ThreadPoolExecutor) -> None:
        while (
            pending
            and not stop_scheduling
            and len(active) < controller.target_jobs
        ):
            task = pending.popleft()
            progress.item_start(
                task.display_index,
                task.label,
                f"{task.start_detail}; active={len(active) + 1}/{controller.target_jobs}",
            )
            status = _InferenceWorkerStatus()
            if str(device).startswith("cuda"):
                controller.start_calibration(now=time.monotonic())
            active[pool.submit(execute_task, task, status)] = (
                task,
                time.monotonic(),
                status,
            )

    with ThreadPoolExecutor(
        max_workers=max(1, plan.maximum_jobs),
        thread_name_prefix=f"mdstats-{phase}",
    ) as pool:
        while active or pending:
            launch(pool)
            report_stage_events()
            if not active:
                break
            done, _ = wait(
                tuple(active),
                timeout=float(policy.monitor_interval_seconds),
                return_when=FIRST_COMPLETED,
            )
            completed_successfully: list[tuple[_AdaptiveInferenceTask, Any, float]] = []
            for future in done:
                task, started, status = active.pop(future)
                wall = time.monotonic() - started
                try:
                    result = future.result()
                except Exception as exc:
                    failures.append(
                        f"{task.label}: {type(exc).__name__}: {exc} "
                        f"(stage={status.phase()})"
                    )
                    _fail(failures[-1])
                    stop_scheduling = True
                    continue
                results[task.key] = result
                completed_successfully.append((task, result, wall))

            # Pop the whole completed wave before doing any parent-side result
            # work, then refill every newly empty slot at once.  This matters
            # when a completion callback performs run selection or starts a model
            # export: another already-completed sibling must not remain counted as
            # active while that callback runs, otherwise its slot can sit idle.
            launch(pool)

            for task, result, wall in completed_successfully:
                try:
                    if task.on_success is not None:
                        task.on_success(result)
                    progress.item_done(
                        task.display_index,
                        task.label,
                        task.done_detail(result, wall),
                    )
                except Exception as exc:
                    failures.append(
                        f"{task.label} result finalization: {type(exc).__name__}: {exc}"
                    )
                    _fail(failures[-1])
                    stop_scheduling = True

            now = time.monotonic()
            workload_active_jobs = sum(
                1
                for _, _, status in active.values()
                if status.workload_started.is_set()
            )
            uses_cuda = str(device).startswith("cuda")
            telemetry_ready = bool(active) and workload_active_jobs >= len(active)
            cpu_probe_just_reset = False
            if uses_cuda:
                # CUDA calibration intentionally samples from task launch, not
                # from a later workload marker. Near-zero setup/IO samples are
                # filtered by the controller's 1% activity floor, while real
                # GPU/VRAM bursts anywhere in the five-minute single-job
                # calibration remain visible. The controller discards the highest
                # 5% of retained activity and averages the next 10% band.
                telemetry_ready_active_jobs = None
            elif not telemetry_ready:
                telemetry_ready_active_jobs = None
            elif telemetry_ready_active_jobs != len(active):
                telemetry_ready_active_jobs = len(active)
                # CPU calibration still begins at the first computation-heavy
                # stage so lightweight launch overhead does not distort host
                # utilization.
                cpu_probe.reset()
                cpu_probe_just_reset = True
            cpu_runtime_sample = None
            if (
                telemetry_ready
                and not uses_cuda
                and not cpu_probe_just_reset
                and telemetry_ready_active_jobs == len(active)
            ):
                cpu_runtime_sample = cpu_probe.sample()
            gpu_runtime_sample = None
            if uses_cuda:
                gpu_runtime_sample, last_gpu_poll = _maybe_query_inference_gpu_telemetry(
                    cfg=cfg,
                    policy=policy,
                    controller=controller,
                    device=device,
                    active_jobs=len(active),
                    now=now,
                    last_sample_monotonic=last_gpu_poll,
                )
            decision = controller.observe(
                active_jobs=len(active),
                workload_active_jobs=workload_active_jobs,
                gpu_sample=gpu_runtime_sample,
                cpu_sample=cpu_runtime_sample,
                now=now,
            )
            if decision.changed and uses_cuda:
                # Force a prompt live-VRAM sample after a concurrency transition.
                last_gpu_poll = 0.0
            if decision.changed:
                projected_memory = _format_bytes_gib(
                    decision.predicted_memory_bytes_at_target
                )
                projected_util = (
                    "unknown"
                    if decision.predicted_utilization_percent_at_target is None
                    else f"{decision.predicted_utilization_percent_at_target:.1f}%"
                )
                print(
                    f"[{phase.upper()} scheduler] status=concurrency-change; "
                    f"progress={format_progress_fraction(len(results), len(tasks))}; "
                    f"elapsed={format_progress_time(now - scheduler_started)}; eta=--:--:--; "
                    f"workers={decision.previous_target}->{decision.target_jobs}; reason={decision.reason}; "
                    f"projected_memory={projected_memory}; projected_utilization={projected_util}",
                    flush=True,
                )
            elif now - last_report >= 30.0 and active:
                active_phases = Counter(
                    status.phase()
                    for _, _, status in active.values()
                )
                phase_detail = ""
                if active_phases:
                    phase_detail = "; stages=" + ", ".join(
                        f"{name} x{count}"
                        for name, count in sorted(active_phases.items())
                    )
                print(
                    f"[{phase.upper()} scheduler] status=running; "
                    f"progress={format_progress_fraction(len(results), len(tasks))}; "
                    f"elapsed={format_progress_time(now - scheduler_started)}; eta=--:--:--; "
                    f"active={len(active)}/{controller.target_jobs}; pending={len(pending)}; "
                    f"reason={decision.reason}{phase_detail}",
                    flush=True,
                )
                last_report = now
            # A telemetry decision may have raised the fixed target (for example
            # when the single-job CUDA calibration just completed).  Fill any new
            # slots in the same scheduler iteration rather than waiting through
            # another monitor interval.
            launch(pool)
            report_stage_events()

    report_stage_events()
    if failures:
        raise CampaignCliError(
            f"{phase.capitalize()} parallel execution failed: {failures[0]}"
        )
    if pending:
        raise CampaignCliError(
            f"{phase.capitalize()} stopped before {len(pending)} pending task(s) ran."
        )
    return results


@dataclass(frozen=True)
class _StagedEvaluationTask:
    """One OPT-EVAL4 checkpoint flowing through prepare/infer/finalize stages."""

    display_index: int
    key: str
    label: str
    start_detail: str
    prepare: Callable[[], Any]
    requires_inference: Callable[[Any], bool]
    infer: Callable[[Any], Any]
    finalize: Callable[[Any, Any], Any]
    done_detail: Callable[[Any, float], str]
    on_success: Callable[[Any], None] | None = None


@dataclass
class _StagedEvaluationTiming:
    started: float
    prepared_seconds: float = 0.0
    inference_seconds: float = 0.0
    finalized_seconds: float = 0.0


def _run_staged_evaluation_tasks(
    tasks: Sequence[_StagedEvaluationTask],
    *,
    cfg: Mapping[str, Any],
    device: str,
    progress: Any,
) -> dict[str, Any]:
    """Run evaluation as a bounded CPU -> accelerator -> CPU pipeline.

    CPU checkpoint/model preparation stays ahead of inference, accelerator work
    retains the existing adaptive CUDA/CPU admission controller, and prediction
    persistence/metric reduction runs behind it.  No mutable calculator crosses
    an inference-worker boundary.
    """

    phase = "evaluation"
    if not tasks:
        return {}
    policy = _inference_concurrency_policy(cfg, phase)
    try:
        resources = detect_system_resources(
            cpu_fraction=float(_cfg(cfg, "performance", "cpu_fraction", 0.90)),
            ram_fraction=float(_cfg(cfg, "performance", "ram_fraction", 0.80)),
            gpu_memory_fraction=float(policy.gpu_memory_fraction),
            device=device,
        )
    except ValueError as exc:
        raise CampaignCliError(str(exc)) from exc
    cpu_probe = CpuTelemetryProbe(capacity_threads=resources.cpu_threads_available)
    cpu_sample = cpu_probe.sample(blocking_seconds=0.10)
    gpu_sample = query_gpu_telemetry(device)
    plan = build_inference_concurrency_plan(
        task_count=len(tasks),
        device=device,
        resources=resources,
        policy=policy,
        gpu_sample=gpu_sample,
        cpu_sample=cpu_sample,
    )
    _configure_inference_thread_budget(plan)
    controller = AdaptiveInferenceConcurrency(plan, policy)

    def _positive_stage_workers(key: str, default: int) -> int:
        value = int(_cfg(cfg, "execution", key, 0))
        if value < 0:
            raise CampaignCliError(
                f"[execution].{key} must be zero (auto) or positive."
            )
        if value == 0:
            return max(1, default)
        return value

    # These workers do not own MACE calculators.  Keep them deliberately small:
    # their job is to overlap hashing/parsing/materialization and metric I/O with
    # accelerator work, not to create a second CPU oversubscription problem.
    auto_cpu_stage_workers = max(1, min(2, int(resources.cpu_threads_available)))
    prepare_workers = min(
        len(tasks),
        _positive_stage_workers(
            "parallel_evaluation_prepare_jobs", auto_cpu_stage_workers
        ),
    )
    finalize_workers = min(
        len(tasks),
        _positive_stage_workers(
            "parallel_evaluation_finalize_jobs", auto_cpu_stage_workers
        ),
    )
    configured_buffer = int(
        _cfg(cfg, "execution", "evaluation_pipeline_buffer_jobs", 0)
    )
    if configured_buffer < 0:
        raise CampaignCliError(
            "[execution].evaluation_pipeline_buffer_jobs must be zero (auto) or positive."
        )
    auto_buffer = max(2, min(8, max(1, int(plan.maximum_jobs)) * 2))
    pipeline_buffer = min(
        len(tasks), configured_buffer if configured_buffer > 0 else auto_buffer
    )
    pipeline_buffer = max(1, pipeline_buffer)
    finalize_backlog_limit = max(
        finalize_workers,
        min(pipeline_buffer, max(2, int(plan.maximum_jobs) * 2)),
    )

    _ok(
        "evaluation pipeline: "
        f"{plan.summary()}; CPU prepare={prepare_workers}, "
        f"CPU finalize={finalize_workers}, prepared buffer={pipeline_buffer}"
    )

    pending = deque(tasks)
    ready_inference: deque[tuple[_StagedEvaluationTask, Any, _StagedEvaluationTiming]] = deque()
    waiting_finalize: deque[
        tuple[_StagedEvaluationTask, Any, Any | None, _StagedEvaluationTiming]
    ] = deque()
    active_prepare: dict[Future[Any], tuple[_StagedEvaluationTask, _StagedEvaluationTiming]] = {}
    active_inference: dict[
        Future[Any], tuple[_StagedEvaluationTask, Any, _StagedEvaluationTiming, _InferenceWorkerStatus]
    ] = {}
    active_finalize: dict[
        Future[Any], tuple[_StagedEvaluationTask, _StagedEvaluationTiming]
    ] = {}
    results: dict[str, Any] = {}
    failures: list[str] = []
    stop_scheduling = False
    stage_events: deque[tuple[str, str]] = deque()
    stage_events_lock = threading.Lock()
    last_report = 0.0
    pipeline_started = time.monotonic()
    telemetry_ready_active_jobs: int | None = None
    last_gpu_poll = 0.0

    def report_stage_events() -> None:
        with stage_events_lock:
            events = tuple(stage_events)
            stage_events.clear()
        for task_label, stage in events:
            print(
                f"[EVALUATION stage] status=phase; item={task_label}; phase={stage}",
                flush=True,
            )

    def execute_prepare(task: _StagedEvaluationTask, timing: _StagedEvaluationTiming) -> Any:
        started = time.monotonic()
        try:
            return task.prepare()
        finally:
            timing.prepared_seconds += time.monotonic() - started

    def execute_inference(
        task: _StagedEvaluationTask,
        prepared: Any,
        timing: _StagedEvaluationTiming,
        status: _InferenceWorkerStatus,
    ) -> Any:
        def update_phase(stage: str) -> None:
            if status.set_phase(stage):
                with stage_events_lock:
                    stage_events.append((task.label, status.phase()))

        started = time.monotonic()
        try:
            with inference_start_signal(
                status.mark_workload_started,
                phase_callback=update_phase,
            ):
                update_phase("accelerator model conversion / inference")
                if not str(device).startswith("cuda"):
                    return task.infer(prepared)
                try:
                    import torch

                    cuda_device = torch.device(device)
                    if not torch.cuda.is_available():
                        return task.infer(prepared)
                    stream = torch.cuda.Stream(device=cuda_device)
                    with torch.cuda.device(cuda_device), torch.cuda.stream(stream):
                        result = task.infer(prepared)
                    stream.synchronize()
                    return result
                except ModuleNotFoundError:
                    return task.infer(prepared)
        finally:
            timing.inference_seconds += time.monotonic() - started

    def execute_finalize(
        task: _StagedEvaluationTask,
        prepared: Any,
        inference_result: Any | None,
        timing: _StagedEvaluationTiming,
    ) -> Any:
        started = time.monotonic()
        try:
            # A cache-only prepared evaluation intentionally bypasses accelerator
            # admission. Its prediction stage is a cheap bundle assembly and is
            # safe to execute in this CPU worker before metric reduction.
            active_result = (
                task.infer(prepared)
                if inference_result is None
                else inference_result
            )
            return task.finalize(prepared, active_result)
        finally:
            timing.finalized_seconds += time.monotonic() - started

    def launch_prepare(pool: ThreadPoolExecutor) -> None:
        if stop_scheduling:
            return
        while pending and len(active_prepare) < prepare_workers:
            buffered = len(active_prepare) + len(ready_inference) + len(waiting_finalize)
            if buffered >= pipeline_buffer:
                break
            task = pending.popleft()
            timing = _StagedEvaluationTiming(started=time.monotonic())
            progress.item_start(
                task.display_index,
                task.label,
                f"{task.start_detail}; stage=CPU prepare",
            )
            future = pool.submit(execute_prepare, task, timing)
            active_prepare[future] = (task, timing)

    def launch_finalize(pool: ThreadPoolExecutor) -> None:
        while waiting_finalize and len(active_finalize) < finalize_workers:
            task, prepared, inference_result, timing = waiting_finalize.popleft()
            future = pool.submit(
                execute_finalize, task, prepared, inference_result, timing
            )
            active_finalize[future] = (task, timing)

    def launch_inference(pool: ThreadPoolExecutor) -> None:
        if stop_scheduling:
            return
        while ready_inference and len(active_inference) < controller.target_jobs:
            if len(waiting_finalize) + len(active_finalize) >= finalize_backlog_limit:
                break
            task, prepared, timing = ready_inference.popleft()
            status = _InferenceWorkerStatus()
            if str(device).startswith("cuda"):
                controller.start_calibration(now=time.monotonic())
            future = pool.submit(execute_inference, task, prepared, timing, status)
            active_inference[future] = (task, prepared, timing, status)

    with (
        ThreadPoolExecutor(
            max_workers=max(1, prepare_workers),
            thread_name_prefix="mdstats-eval-prepare",
        ) as prepare_pool,
        ThreadPoolExecutor(
            max_workers=max(1, plan.maximum_jobs),
            thread_name_prefix="mdstats-eval-infer",
        ) as inference_pool,
        ThreadPoolExecutor(
            max_workers=max(1, finalize_workers),
            thread_name_prefix="mdstats-eval-finalize",
        ) as finalize_pool,
    ):
        launch_prepare(prepare_pool)
        while (
            pending
            or active_prepare
            or ready_inference
            or active_inference
            or waiting_finalize
            or active_finalize
        ):
            launch_finalize(finalize_pool)
            launch_inference(inference_pool)
            launch_prepare(prepare_pool)
            report_stage_events()

            all_futures = (
                tuple(active_prepare)
                + tuple(active_inference)
                + tuple(active_finalize)
            )
            if not all_futures:
                if stop_scheduling:
                    break
                raise CampaignCliError(
                    "Evaluation pipeline stalled with queued work but no active stage."
                )
            done, _ = wait(
                all_futures,
                timeout=float(policy.monitor_interval_seconds),
                return_when=FIRST_COMPLETED,
            )

            completed_parent_callbacks: list[tuple[_StagedEvaluationTask, Any, _StagedEvaluationTiming]] = []

            for future in tuple(done):
                if future in active_prepare:
                    task, timing = active_prepare.pop(future)
                    try:
                        prepared = future.result()
                        if task.requires_inference(prepared):
                            ready_inference.append((task, prepared, timing))
                        else:
                            waiting_finalize.append((task, prepared, None, timing))
                    except Exception as exc:
                        failures.append(
                            f"{task.label}: {type(exc).__name__}: {exc} (stage=CPU preparation)"
                        )
                        _fail(failures[-1])
                        stop_scheduling = True
                elif future in active_inference:
                    task, prepared, timing, status = active_inference.pop(future)
                    try:
                        inference_result = future.result()
                        waiting_finalize.append(
                            (task, prepared, inference_result, timing)
                        )
                    except Exception as exc:
                        failures.append(
                            f"{task.label}: {type(exc).__name__}: {exc} "
                            f"(stage={status.phase()})"
                        )
                        _fail(failures[-1])
                        stop_scheduling = True
                elif future in active_finalize:
                    task, timing = active_finalize.pop(future)
                    try:
                        result = future.result()
                        results[task.key] = result
                        completed_parent_callbacks.append((task, result, timing))
                    except Exception as exc:
                        failures.append(
                            f"{task.label}: {type(exc).__name__}: {exc} (stage=CPU finalization)"
                        )
                        _fail(failures[-1])
                        stop_scheduling = True

            # Refill GPU and CPU stage slots before parent-side publication or
            # SQLite callbacks. This preserves work conservation even if the last
            # checkpoint of a run triggers target-model export.
            launch_finalize(finalize_pool)
            launch_inference(inference_pool)
            launch_prepare(prepare_pool)

            for task, result, timing in completed_parent_callbacks:
                try:
                    if task.on_success is not None:
                        task.on_success(result)
                    wall = time.monotonic() - timing.started
                    progress.item_done(
                        task.display_index,
                        task.label,
                        task.done_detail(result, wall)
                        + "; pipeline="
                        + f"prepare {_ProgressReporter._duration(timing.prepared_seconds)}, "
                        + f"infer {_ProgressReporter._duration(timing.inference_seconds)}, "
                        + f"finalize {_ProgressReporter._duration(timing.finalized_seconds)}",
                    )
                except Exception as exc:
                    failures.append(
                        f"{task.label} result finalization: {type(exc).__name__}: {exc}"
                    )
                    _fail(failures[-1])
                    stop_scheduling = True

            now = time.monotonic()
            workload_active_jobs = sum(
                1
                for _, _, _, status in active_inference.values()
                if status.workload_started.is_set()
            )
            uses_cuda = str(device).startswith("cuda")
            telemetry_ready = bool(active_inference) and workload_active_jobs >= len(active_inference)
            cpu_probe_just_reset = False
            if uses_cuda:
                telemetry_ready_active_jobs = None
            elif not telemetry_ready:
                telemetry_ready_active_jobs = None
            elif telemetry_ready_active_jobs != len(active_inference):
                telemetry_ready_active_jobs = len(active_inference)
                cpu_probe.reset()
                cpu_probe_just_reset = True
            cpu_runtime_sample = None
            if (
                telemetry_ready
                and not uses_cuda
                and not cpu_probe_just_reset
                and telemetry_ready_active_jobs == len(active_inference)
            ):
                cpu_runtime_sample = cpu_probe.sample()
            gpu_runtime_sample = None
            if uses_cuda:
                gpu_runtime_sample, last_gpu_poll = _maybe_query_inference_gpu_telemetry(
                    cfg=cfg,
                    policy=policy,
                    controller=controller,
                    device=device,
                    active_jobs=len(active_inference),
                    now=now,
                    last_sample_monotonic=last_gpu_poll,
                )
            decision = controller.observe(
                active_jobs=len(active_inference),
                workload_active_jobs=workload_active_jobs,
                gpu_sample=gpu_runtime_sample,
                cpu_sample=cpu_runtime_sample,
                now=now,
            )
            if decision.changed and uses_cuda:
                last_gpu_poll = 0.0
            if decision.changed:
                projected_memory = _format_bytes_gib(
                    decision.predicted_memory_bytes_at_target
                )
                projected_util = (
                    "unknown"
                    if decision.predicted_utilization_percent_at_target is None
                    else f"{decision.predicted_utilization_percent_at_target:.1f}%"
                )
                print(
                    "[EVALUATION scheduler] status=concurrency-change; "
                    f"progress={format_progress_fraction(len(results), len(tasks))}; "
                    f"elapsed={format_progress_time(now - pipeline_started)}; eta=--:--:--; "
                    f"workers={decision.previous_target}->{decision.target_jobs}; reason={decision.reason}; "
                    f"projected_memory={projected_memory}; projected_utilization={projected_util}",
                    flush=True,
                )
            elif now - last_report >= 30.0 and (
                active_prepare or active_inference or active_finalize
            ):
                active_phases = Counter(
                    status.phase()
                    for _, _, _, status in active_inference.values()
                )
                phase_detail = ""
                if active_phases:
                    phase_detail = "; accelerator stages=" + ", ".join(
                        f"{name} x{count}"
                        for name, count in sorted(active_phases.items())
                    )
                print(
                    "[EVALUATION pipeline] status=running; "
                    f"progress={format_progress_fraction(len(results), len(tasks))}; "
                    f"elapsed={format_progress_time(now - pipeline_started)}; eta=--:--:--; "
                    f"prepare={len(active_prepare)}; ready={len(ready_inference)}; "
                    f"infer={len(active_inference)}/{controller.target_jobs}; "
                    f"finalize={len(active_finalize)}; final_backlog={len(waiting_finalize)}; "
                    f"pending={len(pending)}; reason={decision.reason}{phase_detail}",
                    flush=True,
                )
                last_report = now
            launch_inference(inference_pool)
            report_stage_events()

    report_stage_events()
    if failures:
        raise CampaignCliError(
            f"Evaluation staged execution failed: {failures[0]}"
        )
    unfinished = (
        len(pending)
        + len(active_prepare)
        + len(ready_inference)
        + len(active_inference)
        + len(waiting_finalize)
        + len(active_finalize)
    )
    if unfinished:
        raise CampaignCliError(
            f"Evaluation pipeline stopped before {unfinished} queued/active task(s) completed."
        )
    return results

def _training_environment_for_plan(plan: Any) -> dict[str, str]:
    env = configure_worker_thread_environment({}, threads=plan.cpu_threads_per_job)
    # Avoid one process silently taking the complete CPU through PyTorch's
    # intra/inter-op pools when several independent GPU jobs share the host.
    env["TORCH_NUM_THREADS"] = str(plan.cpu_threads_per_job)
    return env


def _format_bytes_gib(value: int | None) -> str:
    return "unknown" if value is None else f"{value / 1024**3:.1f} GiB"


def _load_local_training_execution(
    run_root: Path,
    run: Any,
    job: Any,
    execution_policy: Any,
) -> Any | None:
    """Recover a checksummed run-local record if SQLite commit was interrupted."""

    import mdstats

    path = run_root / "training_execution.json"
    if not path.is_file():
        return None
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
        record = mdstats.TrainingRunExecutionRecord.from_dict(payload)
        if record.run_plan_digest != run.content_digest:
            return None
        if record.mace_job_artifact_digest != job.content_digest:
            return None
        if record.execution_policy_digest != execution_policy.policy_digest:
            return None
        if record.state is mdstats.TrainingRunState.SUCCEEDED:
            catalog = mdstats.inventory_mace_checkpoints(
                run,
                run_root / "checkpoints",
                pattern=execution_policy.checkpoint_glob,
            )
            if catalog.content_digest != record.checkpoint_catalog.content_digest:
                return None
        return record
    except Exception:
        return None


def _load_adaptive_stop_state(
    run_root: Path,
    job: Any,
    *,
    require_terminal: bool,
) -> Any | None:
    """Load and lineage-check one ADAPT-STOP1 run-local state."""

    import mdstats

    policy = job.protocol.adaptive_stop_policy
    if policy is None:
        return None
    path = run_root / "adaptive_training_stop.json"
    if not path.is_file():
        if require_terminal:
            raise CampaignCliError(
                f"Completed adaptive training run {job.job_id} is missing {path.name}."
            )
        return None
    try:
        state = mdstats.AdaptiveTrainingStopState.from_dict(
            json.loads(path.read_text(encoding="utf-8"))
        )
    except Exception as exc:
        raise CampaignCliError(
            f"Invalid adaptive-stop state for {job.job_id}: {type(exc).__name__}: {exc}"
        ) from exc
    if state.policy_digest != policy.policy_digest:
        raise CampaignCliError(
            f"Adaptive-stop state for {job.job_id} belongs to another policy."
        )
    if require_terminal and (state.stop_reason is None or state.stop_epoch is None):
        raise CampaignCliError(
            f"Completed adaptive training run {job.job_id} lacks terminal stop evidence."
        )
    return state


def _reconcile_lightweight_run_champion(
    run: Any,
    job: Any,
    run_root: Path,
    adaptive_state: Any | None,
    checkpoint_catalog: Any | None,
) -> Any | None:
    """Create or verify the ADAPT-RANK1 run-local decision artifact.

    This is a pure transformation of persisted STOP1 history plus the frozen
    checkpoint catalog. It never opens checkpoint bytes and launches no inference.
    """

    import mdstats

    if job.protocol.adaptive_stop_policy is None:
        return None
    if adaptive_state is None:
        raise CampaignCliError(
            f"ADAPT-RANK1 requires adaptive-stop evidence for {run.run_id}."
        )
    if checkpoint_catalog is None:
        raise CampaignCliError(
            f"ADAPT-RANK1 requires the frozen checkpoint catalog for {run.run_id}."
        )
    try:
        derived = mdstats.rank_lightweight_run_topk(
            run, job.protocol, adaptive_state, checkpoint_catalog
        )
    except Exception as exc:
        raise CampaignCliError(
            f"Could not derive ADAPT-RANK1 evidence for {run.run_id}: "
            f"{type(exc).__name__}: {exc}"
        ) from exc
    path = run_root / "lightweight_run_champion.json"
    if path.is_file():
        try:
            existing = mdstats.LightweightRunChampionRecord.from_dict(
                json.loads(path.read_text(encoding="utf-8"))
            )
        except Exception as exc:
            raise CampaignCliError(
                f"Invalid ADAPT-RANK1 evidence for {run.run_id}: "
                f"{type(exc).__name__}: {exc}"
            ) from exc
        # Historical v1 champion evidence remains authoritative for the campaign
        # that created it.  MLCV-RANK1 never silently rewrites a completed run
        # into v2 top-K semantics.
        if existing.serialization_schema != mdstats.LIGHTWEIGHT_RUN_CHAMPION_SCHEMA:
            return existing
        if existing.content_digest != derived.content_digest:
            raise CampaignCliError(
                f"MLCV-RANK1 evidence for {run.run_id} disagrees with the persisted "
                "stop history or checkpoint catalog; reconciliation is fail-closed."
            )
        return existing
    _atomic_json(path, derived.to_dict())
    return derived


def _completed_model_path(job: Any, run_root: Path, config_path: Path) -> Path | None:
    try:
        import yaml

        payload = yaml.safe_load(config_path.read_text(encoding="utf-8"))
        if not isinstance(payload, Mapping):
            return None
        name = str(payload.get("name", job.job_id)).strip()
        if not name:
            return None
        return run_root / "models" / f"{name}.model"
    except Exception:
        return None


def _recover_completed_training_artifacts(
    run: Any,
    job: Any,
    *,
    data8_root: Path,
    run_root: Path,
    execution_policy: Any,
    prior_record: Any | None,
) -> Any | None:
    """Recognize a fully completed MACE child after a parent-process interruption."""

    import mdstats
    from .critical_precision_cli import _valid_mace_model

    config_path = (data8_root / job.config_relative_path).resolve()
    model_path = _completed_model_path(job, run_root, config_path)
    if model_path is None or not _valid_mace_model(model_path):
        return None
    try:
        catalog = mdstats.inventory_mace_checkpoints(
            run,
            run_root / "checkpoints",
            pattern=execution_policy.checkpoint_glob,
        )
    except Exception:
        return None
    if not catalog.checkpoints:
        return None

    attempts = [] if prior_record is None else list(prior_record.attempts)
    attempt_index = len(attempts) + 1
    stdout_path = run_root / f"attempt-{attempt_index:02d}.stdout.log"
    stderr_path = run_root / f"attempt-{attempt_index:02d}.stderr.log"
    if not stdout_path.is_file():
        stdout_path.write_text(
            "mdstats recovered a complete stable MACE model and checkpoint catalog "
            "after the campaign parent was interrupted before committing SQLite state.\n",
            encoding="utf-8",
        )
    if not stderr_path.is_file():
        stderr_path.write_bytes(b"")
    job_root = (data8_root / job.relative_directory).resolve()
    command = (
        execution_policy.required_wrapper,
        "--config", str(config_path),
        "--model_dir", str(run_root / "models"),
        "--checkpoints_dir", str(run_root / "checkpoints"),
        "--log_dir", str(run_root / "logs"),
        "--results_dir", str(run_root / "results"),
    )
    command_digest = digest(
        {"schema": "mdstats.training-command.v1", "argv": list(command)}
    )
    environment_values = {
        key: os.environ.get(key) for key in execution_policy.environment_allowlist
    }
    environment_digest = digest(
        {"schema": "mdstats.training-environment.v1", "values": environment_values}
    )
    modified = datetime.fromtimestamp(
        model_path.stat().st_mtime, timezone.utc
    ).isoformat().replace("+00:00", "Z")
    attempt = mdstats.TrainingRunAttemptRecord(
        run_plan_digest=run.content_digest,
        attempt_index=attempt_index,
        execution_policy_digest=execution_policy.policy_digest,
        command=command,
        command_digest=command_digest,
        working_directory=str(job_root),
        config_sha256=job.config_sha256,
        environment_digest=environment_digest,
        started_at_utc=modified,
        finished_at_utc=modified,
        elapsed_seconds=0.0,
        state=mdstats.TrainingRunState.SUCCEEDED,
        return_code=0,
        stdout_relative_path=stdout_path.name,
        stdout_sha256=_sha256(stdout_path),
        stderr_relative_path=stderr_path.name,
        stderr_sha256=_sha256(stderr_path),
        failure_reason=None,
    )
    attempts.append(attempt)
    record = mdstats.TrainingRunExecutionRecord(
        run_plan_digest=run.content_digest,
        mace_job_artifact_digest=job.content_digest,
        execution_policy_digest=execution_policy.policy_digest,
        attempts=tuple(attempts),
        state=mdstats.TrainingRunState.SUCCEEDED,
        successful_attempt_index=attempt_index,
        checkpoint_catalog=catalog,
    )
    _atomic_json(run_root / "training_execution.json", record.to_dict())
    return record


def _live_training_process(run_root: Path) -> int | None:
    marker = run_root / "active_process.json"
    if not marker.is_file():
        return None
    try:
        payload = json.loads(marker.read_text(encoding="utf-8"))
        pid = int(payload.get("pid", -1))
    except Exception:
        marker.unlink(missing_ok=True)
        return None
    if _pid_alive(pid):
        return pid
    marker.unlink(missing_ok=True)
    return None


def _training_execution_policy(cfg: Mapping[str, Any]) -> Any:
    import mdstats

    return mdstats.TrainingExecutionPolicy(
        max_attempts=int(_cfg(cfg, "execution", "max_attempts", 2)),
        timeout_seconds=_optional_positive_float(_cfg(cfg, "execution", "timeout_seconds")),
        terminate_grace_seconds=float(
            _cfg(cfg, "execution", "terminate_grace_seconds", 30.0)
        ),
        resume_latest_on_retry=True,
        require_checkpoint_on_success=True,
    )


def _available_successful_executions(
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    campaign: Any,
    jobs: Mapping[str, tuple[Any, Any, Path]],
) -> dict[str, Any]:
    """Return completed runs, recovering child-complete artifacts when possible."""

    import mdstats

    policy = _training_execution_policy(cfg)
    result: dict[str, Any] = {}
    for run in campaign.runs:
        bundle, job, data8_root = jobs[run.mace_job_artifact_digest]
        del bundle
        run_root = (paths.runs / run.run_id).resolve()
        if _live_training_process(run_root) is not None:
            continue
        key = f"execution:{run.run_id}"
        record = (
            store.get_record(key, mdstats.TrainingRunExecutionRecord)
            if store.has_record(key)
            else None
        )
        local = _load_local_training_execution(run_root, run, job, policy)
        if local is not None and (
            record is None
            or local.state is mdstats.TrainingRunState.SUCCEEDED
            or len(local.attempts) > len(record.attempts)
        ):
            record = local
            store.put_record(key, local)
        if record is None or record.state is not mdstats.TrainingRunState.SUCCEEDED:
            recovered = _recover_completed_training_artifacts(
                run,
                job,
                data8_root=Path(data8_root).resolve(),
                run_root=run_root,
                execution_policy=policy,
                prior_record=record,
            )
            if recovered is not None:
                record = recovered
                store.put_record(key, recovered)
                store.put_record(
                    f"checkpoint_catalog:{run.run_id}", recovered.checkpoint_catalog
                )
                store.event(
                    "warning",
                    "evaluate",
                    f"recovered completed MACE artifacts for {run.run_id} before partial evaluation",
                )
        if record is not None and record.state is mdstats.TrainingRunState.SUCCEEDED:
            adaptive_state = _load_adaptive_stop_state(
                run_root, job, require_terminal=True
            )
            if adaptive_state is not None:
                store.put_record(f"adaptive_stop:{run.run_id}", adaptive_state)
            lightweight_rank = _reconcile_lightweight_run_champion(
                run, job, run_root, adaptive_state, record.checkpoint_catalog
            )
            if lightweight_rank is not None:
                store.put_record(f"lightweight_rank:{run.run_id}", lightweight_rank)
            result[run.content_digest] = record
    return result


def _available_execution_digest(executions: Mapping[str, Any]) -> str:
    return digest(
        {
            "schema": "mdstats.available-training-executions.v1",
            "records": [
                [run_digest, executions[run_digest].content_digest]
                for run_digest in sorted(executions)
            ],
        }
    )


def _variant_availability(
    campaign: Any,
    completed_run_digests: Iterable[str],
    *,
    training_mode: str | None = None,
    seed: int | None = None,
    selection_size: int | None = None,
) -> tuple[_VariantAvailability, ...]:
    import mdstats

    completed = set(completed_run_digests)
    grouped: dict[str, list[Any]] = {}
    for run in campaign.runs:
        if training_mode is not None and run.training_mode.value != training_mode:
            continue
        if seed is not None and run.seed != int(seed):
            continue
        if selection_size is not None and run.selection_size != int(selection_size):
            continue
        grouped.setdefault(run.protocol_variant_digest, []).append(run)
    result: list[_VariantAvailability] = []
    for variant_digest, expected_values in grouped.items():
        expected = tuple(
            sorted(
                expected_values,
                key=lambda run: (
                    1 if run.fold_index is None else 0,
                    -1 if run.fold_index is None else int(run.fold_index),
                ),
            )
        )
        available = tuple(
            run for run in expected if run.content_digest in completed
        )
        if not available:
            continue
        folds = tuple(run for run in available if run.fold_index is not None)
        final = next((run for run in available if run.fold_index is None), None)
        expected_folds = sum(1 for run in expected if run.fold_index is not None)
        full = bool(final is not None and len(folds) == expected_folds and len(available) == len(expected))
        if full:
            level = mdstats.VerificationEvidenceLevel.COMPLETE_VARIANT
        elif len(folds) >= 2:
            level = mdstats.VerificationEvidenceLevel.PARTIAL_CROSS_VALIDATION
        else:
            level = mdstats.VerificationEvidenceLevel.SINGLE_MODEL
        first = expected[0]
        result.append(
            _VariantAvailability(
                protocol_variant_digest=variant_digest,
                protocol_family_digest=first.protocol_family_digest,
                training_mode=first.training_mode,
                selection_size=first.selection_size,
                seed=first.seed,
                expected_runs=expected,
                completed_runs=available,
                completed_folds=folds,
                final_run=final,
                evidence_level=level,
            )
        )
    return tuple(
        sorted(
            result,
            key=lambda value: (
                -value.rank,
                value.training_mode.value,
                value.selection_size,
                value.seed,
                value.protocol_variant_digest,
            ),
        )
    )


def _partial_evidence_warnings(availability: _VariantAvailability) -> tuple[str, ...]:
    warnings: list[str] = []
    if availability.evidence_level.value == "complete_variant":
        warnings.append(
            "The selected seed/method variant is complete, but other configured campaign variants remain unfinished; no cross-protocol production freeze was made."
        )
    elif availability.evidence_level.value == "partial_cross_validation":
        warnings.append(
            f"Only {len(availability.completed_folds)}/{availability.expected_fold_count} cross-validation folds are complete; uncertainty and worst-fold evidence are weaker than configured."
        )
        if not availability.final_completed:
            warnings.append(
                "The final-development model is incomplete; bounded verification uses completed fold models only and is not a deployment freeze."
            )
    else:
        warnings.append(
            "Fewer than two cross-validation folds are complete; no cross-fold estimate is available. Verification is limited to per-model monitor metrics and bounded stability tests."
        )
    return tuple(warnings)


def command_train(args: argparse.Namespace) -> int:
    import mdstats

    cfg, paths = _load_config(args.config)
    _binary_model_precision_contract(cfg)
    store = CampaignStore(paths.state_db)
    _require_stage_complete(store, paths, "preflight")
    try:
        foundation_audit = _load_verified_foundation_audit_authority(store)
    except Exception as exc:
        raise CampaignCliError(
            "Training refused because FOUNDATION-AUDIT1 authority is missing or stale; "
            f"rerun `prepare` and `preflight`: {exc}"
        ) from exc
    try:
        coverage_reference = _load_verified_target_coverage_reference_authority(store)
    except Exception as exc:
        raise CampaignCliError(
            "Training refused because TARGET-DATA2B authority is missing or stale; "
            f"rerun `prepare` and `preflight`: {exc}"
        ) from exc
    _ok(
        "TARGET-DATA2B authority verified before training: "
        f"{coverage_reference.content_digest[:12]}..."
    )
    try:
        target_ladder = _load_verified_target_data_ladder_authority(store)
    except Exception as exc:
        raise CampaignCliError(
            "Training refused because TARGET-DATA2C authority is missing or stale; "
            f"rerun `prepare` and `preflight`: {exc}"
        ) from exc
    _ok(
        "TARGET-DATA2C authority verified before training: "
        f"{target_ladder.content_digest[:12]}..."
    )
    try:
        size_convergence = _load_verified_target_size_convergence_authority(store)
    except Exception as exc:
        raise CampaignCliError(
            "Training refused because TARGET-DATA2D authority is missing or stale; "
            f"rerun `prepare` and `preflight`: {exc}"
        ) from exc
    _ok(
        "TARGET-DATA2D authority verified before training: "
        f"coverage-qualified sizes={list(size_convergence.stage_a_survivor_sizes)}; "
        f"outcome={size_convergence.outcome}; {size_convergence.content_digest[:12]}..."
    )
    if not store.has_record("preflight_smoke"):
        raise CampaignCliError("The required one-epoch MACE preflight record is missing. Run `preflight` before training.")
    smoke = store.get_payload("preflight_smoke")
    if not smoke.get("passed", False):
        raise CampaignCliError("The real one-epoch MACE preflight has not passed. Run `preflight` before training.")
    cleanup_report = _campaign_cleanup(
        cfg, paths, store, phase="train-start", include_preparation_caches=True
    )
    _print_cleanup_report(cleanup_report)
    data8_entries = _current_data8_entries(store)
    data8_bundles = [entry.bundle for entry in data8_entries]
    transitional_jobs: list[str] = []
    for bundle in data8_bundles:
        if getattr(bundle, "mlcv_role_catalog", None) is None or getattr(bundle, "mlcv_monitor_catalog", None) is None:
            continue
        for job in bundle.jobs:
            stop_policy = getattr(job.protocol, "adaptive_stop_policy", None)
            if (
                stop_policy is not None
                and getattr(stop_policy, "serialization_schema", "") != mdstats.ADAPTIVE_STOP_POLICY_SCHEMA
            ):
                transitional_jobs.append(job.job_id)
    if transitional_jobs:
        preview = ", ".join(transitional_jobs[:6])
        suffix = "" if len(transitional_jobs) <= 6 else f", ... ({len(transitional_jobs)} total)"
        raise CampaignCliError(
            "MLCV-MIGRATE1 detected transitional DATA8 jobs with historical absolute-replay "
            "STOP1 policy semantics. They will not be silently reinterpreted as degradation evidence. "
            f"Re-run `mdstats mlff campaign prepare` under mdstats >=0.20.140a0 to regenerate only "
            f"replay-dependent authority while preserving historical evidence. Affected jobs: {preview}{suffix}"
        )
    campaign = _build_campaign(cfg, store, data8_bundles)
    store.put_record("training_campaign", campaign)
    policy_family = _campaign_training_policy_family(campaign)
    train2_execution_epoch_limit: int | None = None
    train2_allow_successful_continuation = False
    train2_stage_label: str | None = None
    train2_allowed_run_ids: set[str] | None = None
    if policy_family == "train2":
        active_modes = sorted({run.training_mode.value for run in campaign.runs})
        if len(active_modes) != 1:
            raise CampaignCliError(
                "TRAIN2 target-size convergence currently requires exactly one enabled training mode; "
                f"found {active_modes}."
            )
        try:
            perf_p2r_stage = mdstats.build_perf_p2r_stage_plan(size_convergence)
        except Exception as exc:
            raise CampaignCliError(
                "TRAIN2 training is blocked because TARGET-DATA2D has no trainable PERF-P2R state: "
                f"outcome={size_convergence.outcome}; {size_convergence.decision_reason}; "
                f"{type(exc).__name__}: {exc}"
            ) from exc
        train2_execution_epoch_limit = int(perf_p2r_stage.target_epoch)
        train2_allow_successful_continuation = bool(perf_p2r_stage.continuation_required)
        stage_labels = {
            "coarse": f"TARGET-DATA2D Stage B0 ({perf_p2r_stage.target_epoch}-of-{perf_p2r_stage.planned_final_epoch})",
            "short": f"TARGET-DATA2D Stage B1 continuation ({perf_p2r_stage.target_epoch}-of-{perf_p2r_stage.planned_final_epoch})",
            "final": f"TARGET-DATA2D Stage C continuation ({perf_p2r_stage.target_epoch}-of-{perf_p2r_stage.planned_final_epoch})",
            "production": "production fixed-budget training",
        }
        train2_stage_label = stage_labels[perf_p2r_stage.stage]
        allowed_sizes = set(int(v) for v in perf_p2r_stage.candidate_sizes)
        if perf_p2r_stage.stage == "production":
            train2_allowed_run_ids = {
                run.run_id for run in campaign.runs if run.selection_size in allowed_sizes
            }
        else:
            screening_seed = int(perf_p2r_stage.screening_optimizer_seed)
            train2_allowed_run_ids = {
                run.run_id for run in campaign.runs
                if run.kind is mdstats.MaceJobKind.FINAL_DEVELOPMENT
                and run.seed == screening_seed
                and run.selection_size in allowed_sizes
            }
        if not train2_allowed_run_ids:
            raise CampaignCliError(
                f"{train2_stage_label} has no matching materialized DATA8 runs. "
                "Rerun `prepare` so Stage-A target-size survivors are materialized under TRAIN2."
            )
        _ok(
            f"TRAIN2B runtime active: {train2_stage_label}; epoch limit={train2_execution_epoch_limit}/"
            f"{size_convergence.policy.final_training_epochs}; runs={len(train2_allowed_run_ids)}"
        )

    def _train2_stage_summary(run_root: Path, job: Any, run_id: str) -> Any | None:
        if policy_family != "train2":
            return None
        if train2_execution_epoch_limit is None:
            raise CampaignCliError("TRAIN2B stage is missing its execution epoch limit.")
        try:
            summary = mdstats.load_train2_runtime_summary(run_root / "checkpoints")
        except Exception as exc:
            raise CampaignCliError(
                f"TRAIN2B run {job.job_id} has successful/recoverable MACE artifacts but no valid "
                f"runtime continuation summary: {type(exc).__name__}: {exc}"
            ) from exc
        if summary.training_protocol_digest != job.protocol.content_digest:
            raise CampaignCliError(f"TRAIN2B runtime summary for {job.job_id} belongs to a different protocol.")
        if summary.optimizer_policy_digest != job.protocol.optimizer_policy.policy_digest:
            raise CampaignCliError(f"TRAIN2B runtime summary for {job.job_id} belongs to a different optimizer policy.")
        if job.protocol.training_budget_policy is None or job.protocol.learning_rate_schedule_policy is None:
            raise CampaignCliError(f"TRAIN2B run {job.job_id} is missing its frozen budget/LR authorities.")
        if summary.budget_policy_digest != job.protocol.training_budget_policy.policy_digest:
            raise CampaignCliError(f"TRAIN2B runtime summary for {job.job_id} changed its training-budget policy.")
        if summary.lr_policy_digest != job.protocol.learning_rate_schedule_policy.policy_digest:
            raise CampaignCliError(f"TRAIN2B runtime summary for {job.job_id} changed its LR-schedule policy.")
        if summary.planned_epochs != job.protocol.training_budget_policy.planned_epochs:
            raise CampaignCliError(f"TRAIN2B runtime summary for {job.job_id} changed its frozen epoch horizon.")
        if summary.planned_updates != summary.updates_per_epoch * summary.planned_epochs:
            raise CampaignCliError(f"TRAIN2B runtime summary for {job.job_id} has inconsistent update geometry.")
        expected_structures_per_epoch = (
            int(job.loader_dry_run.target_train_count_effective)
            + int(job.loader_dry_run.replay_train_count_effective)
        )
        if (
            summary.structures_per_epoch != expected_structures_per_epoch
            or summary.planned_structures_presented != expected_structures_per_epoch * summary.planned_epochs
            or summary.structures_presented != expected_structures_per_epoch * summary.completed_epochs
        ):
            raise CampaignCliError(f"TRAIN2B runtime summary for {job.job_id} changed its structures-presented geometry.")
        if summary.completed_epochs > int(train2_execution_epoch_limit):
            raise CampaignCliError(
                f"TRAIN2B run {job.job_id} is already at epoch {summary.completed_epochs}, beyond the "
                f"current {train2_stage_label} boundary {train2_execution_epoch_limit}."
            )
        store.put_record(f"train2_runtime:{run_id}", summary)
        return summary

    _reconcile_mlcv_lifecycle_authority(
        campaign, data8_bundles, store,
        requested_checkpoint_strategy=str(_cfg(cfg, "evaluation", "checkpoint_strategy", "bounded")),
    )
    lookup = _job_lookup(data8_entries)

    def _current_train_stage_run_ids() -> set[str]:
        if policy_family == "train2":
            return set(train2_allowed_run_ids or ())
        return {run.run_id for run in campaign.runs}

    def _current_train_stage_complete_count() -> int:
        required_ids = _current_train_stage_run_ids()
        count = 0
        for planned_run in campaign.runs:
            if planned_run.run_id not in required_ids:
                continue
            record = store.get_record_optional(
                f"execution:{planned_run.run_id}", mdstats.TrainingRunExecutionRecord
            )
            if record is None or record.state is not mdstats.TrainingRunState.SUCCEEDED:
                continue
            if policy_family == "train2":
                _, planned_job, _ = lookup[planned_run.mace_job_artifact_digest]
                planned_root = (paths.runs / planned_run.run_id).resolve()
                summary = _train2_stage_summary(planned_root, planned_job, planned_run.run_id)
                if summary.completed_epochs != int(train2_execution_epoch_limit):
                    continue
            count += 1
        return count

    selected_runs = [
        v for v in campaign.runs
        if (train2_allowed_run_ids is None or v.run_id in train2_allowed_run_ids)
        and (args.run_id is None or v.run_id == args.run_id)
        and (getattr(args, "training_mode", None) is None or v.training_mode.value == str(args.training_mode))
        and (getattr(args, "seed", None) is None or v.seed == int(args.seed))
        and (getattr(args, "selection_size", None) is None or v.selection_size == int(args.selection_size))
    ]
    if args.max_runs is not None:
        selected_runs = selected_runs[: args.max_runs]
    if not selected_runs:
        raise CampaignCliError("No campaign runs matched the requested filters.")

    _print_precision_profile(cfg)
    execution_policy = _training_execution_policy(cfg)
    runtime_input_failures: list[str] = []
    for run in selected_runs:
        _, job, data8_root = lookup[run.mace_job_artifact_digest]
        job_root = (data8_root / job.relative_directory).resolve()
        config_path = (data8_root / job.config_relative_path).resolve()
        if not config_path.is_file() or _sha256(config_path) != job.config_sha256:
            runtime_input_failures.append(
                f"{run.run_id}: DATA8 config is missing or changed: {config_path}"
            )
            continue
        for failure in _training_config_input_failures(config_path, job_root):
            runtime_input_failures.append(f"{run.run_id}: {failure}")
    if runtime_input_failures:
        preview = "; ".join(runtime_input_failures[:8])
        suffix = "" if len(runtime_input_failures) <= 8 else f"; ... ({len(runtime_input_failures)} total)"
        raise CampaignCliError(
            "Training refused to launch because immutable DATA8 inputs do not resolve "
            f"from their job directories: {preview}{suffix}"
        )

    heartbeat_seconds = float(
        _cfg(cfg, "execution", "training_progress_interval_seconds", 10.0)
    )
    if heartbeat_seconds <= 0.0:
        raise CampaignCliError(
            "execution.training_progress_interval_seconds must be positive."
        )
    concurrency_policy = _training_concurrency_policy(cfg)
    stop_after_failure = bool(_cfg(cfg, "execution", "stop_scheduling_after_failure", True))
    training_progress = _ProgressReporter("TRAIN", len(selected_runs))
    pending_tasks: deque[_PendingTrainingTask] = deque()
    completed_progress = 0

    for display_index, run in enumerate(selected_runs, start=1):
        data8_bundle, job, data8_root = lookup[run.mace_job_artifact_digest]
        data8_root = Path(data8_root).resolve()
        replay_artifact = getattr(data8_bundle, "online_replay_monitor_artifact", None)
        replay_light_path = None
        replay_light_sha256 = None
        auxiliary_replay_monitor_path = None
        if replay_artifact is not None:
            replay_light_path = _resolve_data8_runtime_member(
                data8_bundle, data8_root, replay_artifact.path
            )
            if not replay_light_path.is_file():
                raise CampaignCliError(
                    f"Adaptive/TRAIN2 run {run.run_id} cannot resolve its TRUE_DFT R_light monitor: {replay_light_path}"
                )
            if _sha256(replay_light_path) != replay_artifact.sha256:
                raise CampaignCliError(
                    f"TRUE_DFT R_light monitor changed after DATA8 materialization for {run.run_id}."
                )
            replay_light_sha256 = replay_artifact.sha256
        if job.protocol.replay_plan_digest is None:
            if replay_artifact is None or replay_light_path is None:
                raise CampaignCliError(
                    f"Naive adaptive run {run.run_id} is missing the ADAPT-MON1 true-replay monitor artifact."
                )
            auxiliary_replay_monitor_path = replay_light_path
        foundation_full_replay_path = None
        foundation_model_sha256 = None
        foundation_baseline_cache_path = None
        stop_policy = job.protocol.adaptive_stop_policy
        if (
            stop_policy is not None
            and getattr(stop_policy, "serialization_schema", "")
            == mdstats.ADAPTIVE_STOP_POLICY_SCHEMA
        ):
            replay_full_artifact = getattr(data8_bundle, "replay_full_validation_artifact", None)
            if replay_full_artifact is None:
                raise CampaignCliError(
                    f"Adaptive run {run.run_id} is missing MLCV-MON1 full TRUE_DFT replay validation (R_full)."
                )
            foundation_full_replay_path = _resolve_data8_runtime_member(
                data8_bundle, data8_root, replay_full_artifact.path
            )
            if not foundation_full_replay_path.is_file():
                raise CampaignCliError(
                    f"Adaptive run {run.run_id} cannot resolve R_full TRUE_DFT replay validation: "
                    f"{foundation_full_replay_path}"
                )
            if replay_artifact is None or replay_light_path is None:
                raise CampaignCliError(
                    f"Adaptive run {run.run_id} is missing MLCV-MON1 TRUE_DFT R_light replay validation."
                )
            foundation_model_sha256 = str(job.protocol.foundation_checkpoint.sha256)
            baseline_key = (
                f"{foundation_model_sha256[:16]}-{replay_artifact.sha256[:16]}-"
                f"{replay_full_artifact.sha256[:16]}"
            )
            foundation_baseline_cache_path = (
                paths.internal / "replay_foundation_baselines" / f"{baseline_key}.json"
            ).resolve()
        run_root = (paths.runs / run.run_id).resolve()
        run_root.mkdir(parents=True, exist_ok=True)
        live_pid = _live_training_process(run_root)
        if live_pid is not None:
            raise CampaignCliError(
                f"Training run {run.run_id} already has a live MACE child (pid={live_pid}). "
                "Do not launch a duplicate campaign parent; wait for or stop that process first."
            )

        key = f"execution:{run.run_id}"
        database_record = store.get_record_optional(
            key, mdstats.TrainingRunExecutionRecord
        )
        local_record = _load_local_training_execution(
            run_root, run, job, execution_policy
        )
        previous = database_record
        if local_record is not None and (
            previous is None
            or local_record.state is mdstats.TrainingRunState.SUCCEEDED
            or len(local_record.attempts) > len(previous.attempts)
        ):
            previous = local_record
            store.put_record(key, local_record)
            store.event(
                "info",
                "train",
                f"recovered run-local execution state for {run.run_id}",
            )

        if previous is not None and previous.execution_policy_digest != execution_policy.policy_digest:
            archive = _archive_obsolete_training_runtime(
                run_root, previous.execution_policy_digest
            )
            detail = (
                "resetting failed attempts after training runtime-layout upgrade"
                if archive is None
                else f"removed obsolete failed runtime; compact diagnostic retained at {archive}"
            )
            print(f"[TRAIN {run.run_id}] {detail}", flush=True)
            previous = None
            store.delete_record(key)

        train2_existing_summary = None
        train2_needs_continuation = False
        if previous is not None and previous.state is mdstats.TrainingRunState.SUCCEEDED and policy_family == "train2":
            train2_existing_summary = _train2_stage_summary(run_root, job, run.run_id)
            train2_needs_continuation = (
                train2_existing_summary.completed_epochs < int(train2_execution_epoch_limit)
            )
            if train2_needs_continuation and not train2_allow_successful_continuation:
                raise CampaignCliError(
                    f"TRAIN2B run {run.run_id} stopped at epoch {train2_existing_summary.completed_epochs} "
                    f"before the required {train2_execution_epoch_limit}-epoch boundary."
                )

        if previous is not None and previous.state is mdstats.TrainingRunState.SUCCEEDED and not train2_needs_continuation:
            adaptive_state = _load_adaptive_stop_state(
                run_root, job, require_terminal=True
            )
            if adaptive_state is not None:
                store.put_record(f"adaptive_stop:{run.run_id}", adaptive_state)
            if previous.checkpoint_catalog is None:
                raise CampaignCliError(
                    f"Completed training run {run.run_id} is missing its frozen checkpoint catalog."
                )
            lightweight_rank = _reconcile_lightweight_run_champion(
                run, job, run_root, adaptive_state, previous.checkpoint_catalog
            )
            if lightweight_rank is not None:
                store.put_record(f"lightweight_rank:{run.run_id}", lightweight_rank)
            storage_ok, storage_detail = _completed_checkpoint_storage_matches(
                paths, store, run.run_id, previous.checkpoint_catalog
            )
            if not storage_ok:
                raise CampaignCliError(
                    f"Completed training run {run.run_id} has changed or missing checkpoint "
                    f"representations ({storage_detail}). mdstats will not recalculate or overwrite "
                    "a completed run; restore the recorded raw checkpoint/capsule bytes or inspect "
                    "the run directory."
                )
            completed_progress += 1
            rank_detail = ""
            if lightweight_rank is not None:
                rank_detail = (
                    (
                        f"; topK={len(lightweight_rank.eligible_candidates)}/"
                        f"{lightweight_rank.rankable_checkpoint_count} "
                        f"rank1=epoch{lightweight_rank.selected_checkpoint_epoch} "
                        f"score={lightweight_rank.selected_score_ev_per_angstrom * 1e3:.2f} meV/A"
                        if lightweight_rank.rankable_checkpoint_count is not None
                        else f"; champion=epoch{lightweight_rank.selected_checkpoint_epoch} "
                             f"score={lightweight_rank.selected_score_ev_per_angstrom * 1e3:.2f} meV/A"
                    )
                    if lightweight_rank.outcome == "champion_selected"
                    else "; topK=none (no finite rankable epoch)"
                )
            training_progress.item_done(
                completed_progress, run.run_id, f"already complete; {storage_detail}{rank_detail}"
            )
            continue

        recovered = _recover_completed_training_artifacts(
            run,
            job,
            data8_root=data8_root,
            run_root=run_root,
            execution_policy=execution_policy,
            prior_record=previous,
        )
        if recovered is not None:
            adaptive_state = _load_adaptive_stop_state(
                run_root, job, require_terminal=True
            )
            lightweight_rank = _reconcile_lightweight_run_champion(
                run, job, run_root, adaptive_state, recovered.checkpoint_catalog
            )
            store.put_record(key, recovered)
            store.put_record(
                f"checkpoint_catalog:{run.run_id}", recovered.checkpoint_catalog
            )
            if adaptive_state is not None:
                store.put_record(f"adaptive_stop:{run.run_id}", adaptive_state)
            if lightweight_rank is not None:
                store.put_record(f"lightweight_rank:{run.run_id}", lightweight_rank)
            store.event(
                "warning",
                "train",
                f"recovered completed MACE artifacts for {run.run_id} after parent interruption",
            )
            if policy_family == "train2":
                recovered_summary = _train2_stage_summary(run_root, job, run.run_id)
                if recovered_summary.completed_epochs < int(train2_execution_epoch_limit):
                    if not train2_allow_successful_continuation:
                        raise CampaignCliError(
                            f"Recovered TRAIN2B run {run.run_id} stopped at epoch "
                            f"{recovered_summary.completed_epochs} before required boundary "
                            f"{train2_execution_epoch_limit}."
                        )
                    previous = recovered
                    # Stage-B success is a durable continuation point, not completion of
                    # the Stage-C 30-of-30 trajectory.  Fall through and enqueue restart.
                else:
                    completed_progress += 1
                    training_progress.item_done(
                        completed_progress, run.run_id,
                        f"recovered completed TRAIN2B child at epoch {recovered_summary.completed_epochs}; no epochs repeated"
                    )
                    continue
            if policy_family != "train2":
                completed_progress += 1
            rank_detail = ""
            if lightweight_rank is not None:
                rank_detail = (
                    (
                        f"; topK={len(lightweight_rank.eligible_candidates)}/"
                        f"{lightweight_rank.rankable_checkpoint_count} "
                        f"rank1=epoch{lightweight_rank.selected_checkpoint_epoch} "
                        f"score={lightweight_rank.selected_score_ev_per_angstrom * 1e3:.2f} meV/A"
                        if lightweight_rank.rankable_checkpoint_count is not None
                        else f"; champion=epoch{lightweight_rank.selected_checkpoint_epoch} "
                             f"score={lightweight_rank.selected_score_ev_per_angstrom * 1e3:.2f} meV/A"
                    )
                    if lightweight_rank.outcome == "champion_selected"
                    else "; topK=none (no finite rankable epoch)"
                )
            if policy_family != "train2":
                training_progress.item_done(
                    completed_progress, run.run_id,
                    f"recovered completed child; no epochs repeated{rank_detail}"
                )
                continue

        optimizer = job.protocol.optimizer_policy
        effective_per_epoch = (
            job.loader_dry_run.target_train_count_effective
            + job.loader_dry_run.replay_train_count_effective
        )
        expected_training_updates = max(
            1,
            (effective_per_epoch // optimizer.batch_size) * optimizer.max_num_epochs,
        )
        pending_tasks.append(
            _PendingTrainingTask(
                display_index=display_index,
                run=run,
                job=job,
                data8_root=data8_root,
                run_root=run_root,
                auxiliary_replay_monitor_path=auxiliary_replay_monitor_path,
                replay_light_path=replay_light_path,
                replay_light_sha256=replay_light_sha256,
                foundation_full_replay_path=foundation_full_replay_path,
                foundation_model_sha256=foundation_model_sha256,
                foundation_baseline_cache_path=foundation_baseline_cache_path,
                state_key=key,
                prior_record=previous,
                expected_updates=expected_training_updates,
                progress_probe=_MaceTrainingProgressProbe(
                    log_dir=run_root / "logs",
                    result_dir=run_root / "results",
                    checkpoint_dir=run_root / "checkpoints",
                    expected_updates=expected_training_updates,
                    device=optimizer.device,
                    max_epochs=optimizer.max_num_epochs,
                    epoch_activity_timeout_seconds=float(
                        _cfg(
                            cfg,
                            "execution",
                            "parallel_training_epoch_activity_timeout_seconds",
                            120.0,
                        )
                    ),
                ),
                train2_execution_epoch_limit=(
                    train2_execution_epoch_limit if policy_family == "train2" else None
                ),
                allow_successful_continuation=(
                    train2_allow_successful_continuation if policy_family == "train2" else False
                ),
            )
        )

    devices = {
        str(task.job.protocol.optimizer_policy.device) for task in pending_tasks
    }
    if len(devices) > 1:
        raise CampaignCliError(
            "Automatic parallel training requires one frozen device across selected jobs; "
            f"found {sorted(devices)}."
        )
    device = next(iter(devices), str(_cfg(cfg, "training", "device", "cuda")))
    loader_workers = max(
        (int(task.job.protocol.optimizer_policy.num_workers) for task in pending_tasks),
        default=0,
    )
    try:
        resources = detect_system_resources(
            cpu_fraction=float(_cfg(cfg, "performance", "cpu_fraction", 0.90)),
            ram_fraction=float(_cfg(cfg, "performance", "ram_fraction", 0.80)),
            gpu_memory_fraction=float(concurrency_policy.gpu_memory_fraction),
            device=device,
        )
        initial_gpu_sample = query_gpu_telemetry(device)
        concurrency_plan = build_training_concurrency_plan(
            task_count=len(pending_tasks),
            device=device,
            loader_workers_per_job=loader_workers,
            resources=resources,
            policy=concurrency_policy,
            gpu_sample=initial_gpu_sample,
        )
    except ValueError as exc:
        raise CampaignCliError(str(exc)) from exc

    _print_header("Training campaign")
    print(f"Runs selected: {len(selected_runs)} / {len(campaign.runs)}")
    print(f"Pending runs:  {len(pending_tasks)}")
    print(f"Scheduler:     {concurrency_plan.summary()}")
    if initial_gpu_sample is not None:
        print(f"GPU at start:  {initial_gpu_sample.summary()}")
    print(
        "Safety policy: CUDA starts with one job. A second or later job is admitted "
        "only after every active job has sustained true epoch updates for the full "
        "averaging window and the projected mean aggregate VRAM and GPU utilization "
        "are both below their admission ceilings.",
        flush=True,
    )
    for run in selected_runs:
        _, job, data8_root = lookup[run.mace_job_artifact_digest]
        job_root = (data8_root / job.relative_directory).resolve()
        run_root = (paths.runs / run.run_id).resolve()
        command = (
            f"mdstats-mace-train --config {data8_root / job.config_relative_path} "
            f"--model_dir {run_root / 'models'} --checkpoints_dir {run_root / 'checkpoints'} "
            f"--log_dir {run_root / 'logs'} --results_dir {run_root / 'results'}"
        )
        print(f"  {run.run_id}: (cwd={job_root}) {command}")
    if args.dry_run:
        print("\nDry run only. No training process was launched.")
        return 0

    if not pending_tasks:
        complete_count = _current_train_stage_complete_count()
        required_count = len(_current_train_stage_run_ids())
        if complete_count == required_count:
            if policy_family == "train2" and size_convergence.outcome != "selected":
                _mark_stage(
                    store, paths, "train", StageState.WAITING,
                    f"{train2_stage_label} execution complete ({complete_count}/{required_count}); awaiting evaluation evidence",
                )
                print(f"\n{train2_stage_label} execution complete. Next: `evaluate`.")
                return 0
            _mark_stage(store, paths, "train", StageState.COMPLETE, f"all {required_count} required runs complete")
            print("\nTraining complete. Next: `evaluate`.")
            return 0
        _mark_stage(store, paths, "train", StageState.WAITING, f"{complete_count}/{required_count} required runs complete")
        return 2

    _mark_stage(
        store,
        paths,
        "train",
        StageState.RUNNING,
        f"executing restartable MACE jobs with adaptive concurrency up to {concurrency_plan.maximum_jobs}",
    )
    failures: list[str] = []
    controller = AdaptiveTrainingConcurrency(concurrency_plan, concurrency_policy)
    wrapper_path = _ensure_local_wrappers(paths)["mdstats-mace-train"]
    worker_environment = _training_environment_for_plan(concurrency_plan)
    active: dict[Future[Any], _PendingTrainingTask] = {}
    scheduler_started = time.monotonic()
    last_scheduler_report = 0.0
    stop_scheduling = False
    interrupted = False
    disk_stop = False
    cancel_event = threading.Event()
    minimum_free_disk_gib = float(
        _cfg(cfg, "execution", "minimum_free_disk_gib", 20.0)
    )

    def _execute_task(task: _PendingTrainingTask) -> tuple[Any, float]:
        run_started = time.monotonic()
        optimizer = task.job.protocol.optimizer_policy
        print(
            f"[TRAIN {task.run.run_id}] expected gradient updates={task.expected_updates}; "
            f"{_training_device_description(optimizer.device, optimizer.acceleration_policy, optimizer.default_dtype)}",
            flush=True,
        )

        def _training_heartbeat(
            attempt_index: int,
            elapsed_seconds: float,
            stdout_path: Path,
            stderr_path: Path,
        ) -> None:
            detail = task.progress_probe()
            print(
                f"[TRAIN {task.run.run_id}] status=running; {detail}; "
                f"attempt={attempt_index}; elapsed={format_progress_time(elapsed_seconds)}; "
                "eta=--:--:--",
                flush=True,
            )

        task_environment = dict(worker_environment)
        if task.auxiliary_replay_monitor_path is not None:
            task_environment["MDSTATS_ADAPTIVE_STOP_AUXILIARY_REPLAY_PATH"] = str(
                task.auxiliary_replay_monitor_path.resolve()
            )
        if task.replay_light_path is not None and task.job.protocol.adaptive_stop_policy is not None:
            task_environment["MDSTATS_ADAPTIVE_STOP_REPLAY_LIGHT_PATH"] = str(
                task.replay_light_path.resolve()
            )
        else:
            task_environment.pop("MDSTATS_ADAPTIVE_STOP_REPLAY_LIGHT_PATH", None)
        if task.foundation_full_replay_path is not None:
            task_environment["MDSTATS_ADAPTIVE_STOP_FOUNDATION_REPLAY_FULL_PATH"] = str(
                task.foundation_full_replay_path.resolve()
            )
        if task.foundation_model_sha256 is not None:
            task_environment["MDSTATS_ADAPTIVE_STOP_FOUNDATION_MODEL_SHA256"] = str(
                task.foundation_model_sha256
            )
        if task.foundation_baseline_cache_path is not None:
            task_environment["MDSTATS_ADAPTIVE_STOP_FOUNDATION_BASELINE_PATH"] = str(
                task.foundation_baseline_cache_path.resolve()
            )
        if task.job.protocol.training_budget_policy is not None:
            replay_enabled = bool(task.job.protocol.checkpoint_admissibility_policy.replay_enabled)
            if replay_enabled and (task.replay_light_path is None or task.replay_light_sha256 is None):
                raise CampaignCliError(
                    f"TRAIN2B run {task.run.run_id} is missing its authenticated TRUE_DFT replay monitor."
                )
            runtime_plan = mdstats.build_train2_runtime_plan(
                task.job,
                execution_epoch_limit=task.train2_execution_epoch_limit,
                true_replay_monitor_sha256=(task.replay_light_sha256 if replay_enabled else None),
            )
            task_environment[mdstats.TRAIN2_RUNTIME_ENVIRONMENT_VARIABLE] = json.dumps(
                runtime_plan.to_dict(), sort_keys=True, separators=(",", ":")
            )
            if replay_enabled:
                task_environment[mdstats.TRAIN2_TRUE_REPLAY_PATH_ENVIRONMENT_VARIABLE] = str(
                    task.replay_light_path.resolve()
                )
            else:
                task_environment.pop(mdstats.TRAIN2_TRUE_REPLAY_PATH_ENVIRONMENT_VARIABLE, None)
        else:
            task_environment.pop(mdstats.TRAIN2_RUNTIME_ENVIRONMENT_VARIABLE, None)
            task_environment.pop(mdstats.TRAIN2_TRUE_REPLAY_PATH_ENVIRONMENT_VARIABLE, None)
        training_diagnostic_path = (
            task.data8_root / "jobs" / task.job.job_id / "target_training_diagnostic.xyz"
        ).resolve()
        if training_diagnostic_path.is_file():
            task_environment["MDSTATS_MLCV_TRAINING_DIAGNOSTIC_PATH"] = str(
                training_diagnostic_path
            )
        record = mdstats.execute_training_run(
            task.run,
            task.job,
            data8_root=task.data8_root,
            execution_root=task.run_root,
            checkpoint_directory=task.run_root / "checkpoints",
            policy=execution_policy,
            environment=task_environment,
            wrapper_path=wrapper_path,
            prior_record=task.prior_record,
            progress_callback=_training_heartbeat,
            progress_interval_seconds=heartbeat_seconds,
            stop_requested=cancel_event.is_set,
            allow_successful_continuation=task.allow_successful_continuation,
        )
        return record, time.monotonic() - run_started

    def _launch_ready(pool: ThreadPoolExecutor) -> None:
        while (
            pending_tasks
            and not stop_scheduling
            and len(active) < controller.target_jobs
        ):
            task = pending_tasks.popleft()
            training_progress.item_start(
                task.display_index,
                task.run.run_id,
                f"logs={task.run_root}; heartbeat={heartbeat_seconds:g}s; "
                f"active={len(active) + 1}/{controller.target_jobs}",
            )
            active[pool.submit(_execute_task, task)] = task

    def _request_interruption() -> None:
        nonlocal interrupted, stop_scheduling
        first_request = not interrupted
        interrupted = True
        stop_scheduling = True
        cancel_event.set()
        if first_request:
            print(
                "[TRAIN scheduler] interruption received; stopping active MACE children "
                "at their latest durable checkpoints and committing resumable records...",
                flush=True,
            )

    with _interrupt_guard(_request_interruption), ThreadPoolExecutor(
        max_workers=max(1, concurrency_plan.maximum_jobs),
        thread_name_prefix="mdstats-mace-train",
    ) as pool:
        _launch_ready(pool)
        while active:
            try:
                done, _ = wait(
                    tuple(active),
                    timeout=float(concurrency_policy.monitor_interval_seconds),
                    return_when=FIRST_COMPLETED,
                )
            except KeyboardInterrupt:
                # Fallback for platforms where the temporary SIGINT handler is
                # unavailable. POSIX main-thread execution uses _interrupt_guard.
                _request_interruption()
                done = set()

            # Commit completed work first.  Scheduler telemetry must describe
            # processes that are still running, not futures that have already
            # exited but have not yet been removed from the active map.
            for future in done:
                task = active.pop(future)
                completed_progress += 1
                try:
                    record, run_wall = future.result()
                except Exception as exc:
                    failures.append(
                        f"{task.run.run_id}:exception:{type(exc).__name__}:{exc}"
                    )
                    _fail(
                        f"{task.run.run_id}: {type(exc).__name__}: {exc}"
                    )
                    if stop_after_failure:
                        stop_scheduling = True
                    continue

                records_to_commit = {task.state_key: record}
                adaptive_state = None
                lightweight_rank = None
                if record.state is mdstats.TrainingRunState.SUCCEEDED:
                    if task.job.protocol.training_budget_policy is not None:
                        train2_summary = _train2_stage_summary(
                            task.run_root, task.job, task.run.run_id
                        )
                        if train2_summary.completed_epochs != int(task.train2_execution_epoch_limit):
                            raise CampaignCliError(
                                f"TRAIN2B child {task.run.run_id} returned success at epoch "
                                f"{train2_summary.completed_epochs}; required exact boundary "
                                f"{task.train2_execution_epoch_limit}."
                            )
                        records_to_commit[f"train2_runtime:{task.run.run_id}"] = train2_summary
                    adaptive_state = _load_adaptive_stop_state(
                        task.run_root, task.job, require_terminal=True
                    )
                    if adaptive_state is not None:
                        records_to_commit[f"adaptive_stop:{task.run.run_id}"] = adaptive_state
                    lightweight_rank = _reconcile_lightweight_run_champion(
                        task.run, task.job, task.run_root, adaptive_state, record.checkpoint_catalog
                    )
                    if lightweight_rank is not None:
                        records_to_commit[f"lightweight_rank:{task.run.run_id}"] = lightweight_rank
                if record.checkpoint_catalog is not None:
                    records_to_commit[
                        f"checkpoint_catalog:{task.run.run_id}"
                    ] = record.checkpoint_catalog
                store.put_records(records_to_commit)
                if record.state is mdstats.TrainingRunState.SUCCEEDED:
                    stop_detail = ""
                    if adaptive_state is not None:
                        metric = next(
                            item for item in adaptive_state.epochs
                            if item.epoch == adaptive_state.stop_epoch
                        )
                        replay_text = (
                            ""
                            if metric.replay_force_rmse_ev_per_angstrom is None
                            else f", replay={metric.replay_force_rmse_ev_per_angstrom * 1e3:.2f} meV/A"
                        )
                        stop_detail = (
                            f"; stop={adaptive_state.stop_reason}@epoch{adaptive_state.stop_epoch} "
                            f"(target={metric.target_force_rmse_ev_per_angstrom * 1e3:.2f} meV/A"
                            f"{replay_text}); outcome={adaptive_state.run_outcome}"
                        )
                    rank_detail = ""
                    if lightweight_rank is not None:
                        if lightweight_rank.outcome == "champion_selected":
                            if lightweight_rank.rankable_checkpoint_count is not None:
                                rank_detail = (
                                    f"; topK={len(lightweight_rank.eligible_candidates)}/"
                                    f"{lightweight_rank.rankable_checkpoint_count}"
                                    f" rank1=epoch{lightweight_rank.selected_checkpoint_epoch}"
                                    f" score={lightweight_rank.selected_score_ev_per_angstrom * 1e3:.2f} meV/A"
                                )
                            else:
                                rank_detail = (
                                    f"; champion=epoch{lightweight_rank.selected_checkpoint_epoch}"
                                    f" score={lightweight_rank.selected_score_ev_per_angstrom * 1e3:.2f} meV/A"
                                )
                        else:
                            rank_detail = "; topK=none (no finite rankable epoch)"
                    training_progress.item_done(
                        completed_progress,
                        task.run.run_id,
                        f"{len(record.checkpoint_catalog.checkpoints)} checkpoints; "
                        f"run_elapsed={format_progress_time(run_wall)}{stop_detail}{rank_detail}",
                    )
                elif record.state is mdstats.TrainingRunState.INTERRUPTED:
                    _warn(
                        f"{task.run.run_id}: interrupted after preserving its latest checkpoint; "
                        "rerun `train` to continue with --restart_latest"
                    )
                else:
                    failures.append(f"{task.run.run_id}:{record.state.value}")
                    _fail(f"{task.run.run_id}: {record.state.value}")
                    if stop_after_failure:
                        stop_scheduling = True

            now = time.monotonic()
            sample = query_gpu_telemetry(device)
            try:
                free_disk_gib = shutil.disk_usage(paths.workspace).free / (1024.0 ** 3)
            except OSError:
                free_disk_gib = float("inf")
            if (
                not cancel_event.is_set()
                and free_disk_gib < minimum_free_disk_gib
            ):
                # STOR3: attempt capability-preserving reclamation before interrupting
                # live training. Active run roots are excluded by _campaign_cleanup.
                pressure_cleanup, free_disk_after_cleanup, pressure_recovered = (
                    _attempt_stor3_disk_pressure_reclamation(
                        cfg,
                        paths,
                        store,
                        minimum_free_disk_gib=minimum_free_disk_gib,
                    )
                )
                if pressure_cleanup.actions:
                    _print_cleanup_report(pressure_cleanup)
                if pressure_recovered:
                    print(
                        f"[TRAIN scheduler] STOR3 safe reclamation restored free disk to "
                        f"{free_disk_after_cleanup:.1f} GiB; active jobs continue.",
                        flush=True,
                    )
                    free_disk_gib = free_disk_after_cleanup
                else:
                    disk_stop = True
                    stop_scheduling = True
                    cancel_event.set()
                    print(
                        f"[TRAIN scheduler] free disk remains {free_disk_after_cleanup:.1f} GiB after "
                        f"STOR3 safe reclamation, below the {minimum_free_disk_gib:.1f} GiB reserve; "
                        "stopping active jobs at their latest durable checkpoints.",
                        flush=True,
                    )
                    free_disk_gib = free_disk_after_cleanup
            epoch_states = [
                task.progress_probe.snapshot(now=now) for task in active.values()
            ]
            epoch_active_jobs = sum(
                1 for state in epoch_states if state.true_epoch_active
            )
            decision = controller.observe(
                sample,
                active_jobs=len(active),
                epoch_active_jobs=epoch_active_jobs,
                now=now,
            )
            if decision.changed:
                predicted_memory = (
                    "unknown"
                    if decision.predicted_bytes_at_target is None
                    else _format_bytes_gib(decision.predicted_bytes_at_target)
                )
                predicted_utilization = (
                    "unknown"
                    if decision.predicted_utilization_percent_at_target is None
                    else f"{decision.predicted_utilization_percent_at_target:.1f}%"
                )
                print(
                    f"[TRAIN scheduler] status=concurrency-change; "
                    f"progress={format_progress_fraction(completed_progress, training_progress.total)}; "
                    f"elapsed={format_progress_time(now - scheduler_started)}; eta=--:--:--; "
                    f"workers={decision.previous_target}->{decision.target_jobs}; reason={decision.reason}; "
                    f"predicted_vram={predicted_memory}; predicted_gpu_utilization={predicted_utilization}; "
                    f"ceilings={_format_bytes_gib(concurrency_plan.gpu_memory_budget_bytes)} / "
                    f"{concurrency_plan.gpu_utilization_budget_percent:.0f}%",
                    flush=True,
                )
            if (
                now - last_scheduler_report >= heartbeat_seconds
                or decision.changed
            ):
                telemetry = "GPU telemetry unavailable" if sample is None else sample.summary()
                print(
                    f"[TRAIN scheduler] status=running; "
                    f"progress={format_progress_fraction(completed_progress, training_progress.total)}; "
                    f"elapsed={format_progress_time(now - scheduler_started)}; eta=--:--:--; "
                    f"active={len(active)}; true_epoch={epoch_active_jobs}/{len(active)}; "
                    f"target={controller.target_jobs}; queued={len(pending_tasks)}; "
                    f"decision={decision.reason}; free_disk={free_disk_gib:.1f} GiB; {telemetry}",
                    flush=True,
                )
                last_scheduler_report = now

            if stop_scheduling and pending_tasks:
                print(
                    f"[TRAIN scheduler] holding {len(pending_tasks)} queued run(s) after a failure; "
                    "fix the first failure and rerun `train` to resume.",
                    flush=True,
                )
            _launch_ready(pool)

    complete_count = _current_train_stage_complete_count()
    required_run_count = len(_current_train_stage_run_ids())
    _update_benchmark(
        paths,
        "train",
        {
            "complete_runs": complete_count,
            "total_runs": required_run_count,
            "failures": failures,
            "parallel_initial_jobs": concurrency_plan.initial_jobs,
            "parallel_maximum_jobs": concurrency_plan.maximum_jobs,
            "parallel_final_target_jobs": controller.target_jobs,
            "peak_observed_vram_bytes_per_job": controller.peak_observed_bytes_per_job,
        },
    )
    cleanup_report = _campaign_cleanup(
        cfg, paths, store, phase="train-end", include_preparation_caches=True
    )
    _print_cleanup_report(cleanup_report)
    if interrupted or disk_stop:
        reason = (
            "user interruption" if interrupted
            else f"free disk below {minimum_free_disk_gib:.1f} GiB reserve"
        )
        _mark_stage(
            store,
            paths,
            "train",
            StageState.WAITING,
            f"{complete_count}/{required_run_count} required runs complete; resumable after {reason}",
        )
        return 130 if interrupted else 2
    if failures:
        _mark_stage(store, paths, "train", StageState.FAILED, "; ".join(failures))
        return 1
    if complete_count < required_run_count:
        _mark_stage(store, paths, "train", StageState.WAITING, f"{complete_count}/{required_run_count} required runs complete")
        return 2
    if policy_family == "train2" and size_convergence.outcome != "selected":
        _mark_stage(
            store, paths, "train", StageState.WAITING,
            f"{train2_stage_label} execution complete ({complete_count}/{required_run_count}); awaiting evaluation evidence",
        )
        print(f"\n{train2_stage_label} execution complete. Next: `evaluate`.")
        return 0
    _mark_stage(store, paths, "train", StageState.COMPLETE, f"all {required_run_count} required runs complete")
    print("\nTraining complete. Next: `evaluate`.")
    return 0

def _artifact_lookup(bundle: Any) -> tuple[dict[str, Any], Any | None]:
    target = {v.content_digest: v for v in bundle.target_artifacts}
    replay = bundle.replay_plan.monitor_artifact
    return target, replay


def _checkpoint_capsule_key(run_id: str, checkpoint_sha256: str) -> str:
    return f"checkpoint_capsule:{run_id}:{checkpoint_sha256}"


def _checkpoint_source_for_evaluation(
    paths: CampaignPaths,
    store: CampaignStore,
    run_id: str,
    checkpoint: Any,
    catalog: Any,
) -> tuple[Path, Any | None]:
    """Resolve raw checkpoint bytes or a qualified STOR2 evaluation capsule.

    The original ``CheckpointFileRecord`` remains the scientific identity.  A
    capsule is only a storage representation of that exact model state.
    """

    import mdstats

    root = Path(catalog.root_directory).resolve()
    raw = (root / checkpoint.relative_path).resolve()
    try:
        raw.relative_to(root)
    except ValueError as exc:
        raise CampaignCliError(
            f"Checkpoint path escaped its catalog root for {run_id}: {raw}"
        ) from exc
    if raw.is_file():
        if _sha256(raw) != checkpoint.sha256:
            raise CampaignCliError(
                f"Checkpoint bytes no longer match the frozen inventory: {run_id} epoch {checkpoint.epoch}."
            )
        return raw, None

    record = store.get_record_optional(
        _checkpoint_capsule_key(run_id, checkpoint.sha256),
        mdstats.EvaluationStateCapsuleRecord,
    )
    if record is None:
        return raw, None
    run_root = (paths.runs / run_id).resolve()
    capsule = Path(record.capsule_path).resolve()
    try:
        capsule.relative_to(run_root)
    except ValueError as exc:
        raise CampaignCliError(
            f"STOR2 capsule escaped the campaign run root for {run_id}: {capsule}"
        ) from exc
    if (
        record.run_plan_digest != checkpoint.run_plan_digest
        or record.source_checkpoint_sha256 != checkpoint.sha256
        or record.source_checkpoint_epoch != checkpoint.epoch
    ):
        raise CampaignCliError(
            f"STOR2 capsule lineage mismatch for {run_id} epoch {checkpoint.epoch}."
        )
    if not capsule.is_file() or _sha256(capsule) != record.capsule_sha256:
        raise CampaignCliError(
            f"STOR2 capsule bytes are missing or changed for {run_id} epoch {checkpoint.epoch}."
        )
    return capsule, record


def _completed_checkpoint_storage_matches(
    paths: CampaignPaths,
    store: CampaignStore,
    run_id: str,
    catalog: Any,
) -> tuple[bool, str]:
    """Validate a completed run after STOR2/legacy post-evaluation retention."""

    import mdstats

    root = Path(catalog.root_directory).resolve()
    retention = store.get_payload(f"checkpoint_retention:{run_id}") if store.has_record(
        f"checkpoint_retention:{run_id}"
    ) else None
    legacy_removed: set[str] = set()
    selected_sha: str | None = None
    if isinstance(retention, Mapping):
        selected_sha = str(retention.get("selected_checkpoint_sha256") or "") or None
        if retention.get("schema") == "mdstats.mlff-checkpoint-retention.v1":
            legacy_removed = {
                str(item.get("sha256"))
                for item in retention.get("removed_checkpoints", ())
                if isinstance(item, Mapping) and item.get("sha256")
            }

    for checkpoint in catalog.checkpoints:
        raw = (root / checkpoint.relative_path).resolve()
        if raw.is_file():
            if _sha256(raw) != checkpoint.sha256:
                return False, f"changed raw checkpoint at epoch {checkpoint.epoch}"
            continue
        record = store.get_record_optional(
            _checkpoint_capsule_key(run_id, checkpoint.sha256),
            mdstats.EvaluationStateCapsuleRecord,
        )
        if record is not None:
            capsule = Path(record.capsule_path).resolve()
            run_root = (paths.runs / run_id).resolve()
            try:
                capsule.relative_to(run_root)
            except ValueError:
                return False, f"capsule escapes run root at epoch {checkpoint.epoch}"
            if (
                record.run_plan_digest != checkpoint.run_plan_digest
                or record.source_checkpoint_sha256 != checkpoint.sha256
                or record.source_checkpoint_epoch != checkpoint.epoch
                or not capsule.is_file()
                or _sha256(capsule) != record.capsule_sha256
            ):
                return False, f"invalid capsule at epoch {checkpoint.epoch}"
            continue
        if checkpoint.sha256 in legacy_removed:
            # 0.20.112 and earlier intentionally deleted these after evaluation.
            # Preserve restart compatibility with those already-compacted campaigns;
            # STOR2 cannot reconstruct lost optimizer/model bytes retroactively.
            continue
        compact_payload = store.get_payload_optional("manual_reclamation:compact")
        compacted_runs = (
            set(str(value) for value in compact_payload.get("compacted_run_ids", ()))
            if isinstance(compact_payload, Mapping)
            else set()
        )
        if (
            selected_sha is not None
            and checkpoint.sha256 != selected_sha
            and run_id in compacted_runs
        ):
            # STOR4 compact deliberately permits loss of nonselected checkpoint
            # representations for this run only after protocol freeze.  The selected
            # production raw checkpoint remains restart-capable and is validated below.
            continue
        return False, f"missing checkpoint representation at epoch {checkpoint.epoch}"

    if selected_sha is not None:
        selected = next(
            (item for item in catalog.checkpoints if item.sha256 == selected_sha), None
        )
        if selected is not None:
            selected_path = (root / selected.relative_path).resolve()
            if not selected_path.is_file() or _sha256(selected_path) != selected.sha256:
                return False, "selected production checkpoint is not restart-capable"
    return True, "raw/capsule checkpoint representations verified"


def _evaluation_checkpoint_catalog(
    store: CampaignStore,
    run_id: str,
    execution: Any,
) -> Any:
    """Return the original catalog after post-evaluation byte compaction."""

    import mdstats

    key = f"checkpoint_retention:{run_id}"
    if not store.has_record(key):
        return execution.checkpoint_catalog
    payload = store.get_payload(key)
    try:
        return mdstats.CandidateCheckpointCatalog.from_dict(
            payload["original_checkpoint_catalog"]
        )
    except Exception as exc:
        raise CampaignCliError(
            f"Checkpoint-retention record is invalid for {run_id}: {exc}"
        ) from exc


def _compact_evaluated_checkpoints(
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    campaign: Any,
    *,
    dry_run: bool = False,
    run_ids: set[str] | None = None,
) -> _CampaignCleanupReport:
    """STOR2: replace nonselected full checkpoints with verified evaluation capsules.

    The selected production checkpoint remains byte-for-byte restart-capable.  No
    raw checkpoint is removed until its model-only capsule has been atomically
    written, independently reconstructed, committed to campaign state, and read
    back with matching authentication metadata.
    """

    import mdstats

    report = _CampaignCleanupReport(
        phase="stor2-checkpoint-compaction",
        dry_run=dry_run,
        ownership_boundary=CampaignOwnershipBoundary(
            paths.workspace,
            protected_inputs=configured_protected_inputs(
                cfg, config_dir=paths.config_dir, config_path=paths.config
            ),
        ),
    )
    assert report.ownership_boundary is not None
    store_authorized, store_detail = report.ownership_boundary.destructive_authorization(store.path)
    if not store_authorized:
        report.skipped.append(
            f"STOR2 refused because campaign state is outside ownership boundary: {store_detail}"
        )
        return report
    if not bool(
        _cfg(cfg, "cleanup", "prune_unselected_checkpoints_after_evaluate", True)
    ):
        report.skipped.append("STOR2 checkpoint compaction disabled by cleanup policy")
        return report
    if store.has_record("mlcv_lifecycle_authority"):
        report.skipped.append(
            "STOR2 retained MLCV checkpoints: top-five candidates and frozen run representatives "
            "remain protected under MLCV-MIGRATE1 lifecycle authority"
        )
        return report

    try:
        job_lookup = _job_lookup(_current_data8_entries(store))
    except Exception as exc:
        report.skipped.append(f"STOR2 could not resolve immutable DATA8 jobs: {exc}")
        return report

    for run in campaign.runs:
        if run_ids is not None and run.run_id not in run_ids:
            continue
        selection_key = f"selection:{run.run_id}"
        execution_key = f"execution:{run.run_id}"
        if not store.has_record(selection_key) or not store.has_record(execution_key):
            report.skipped.append(
                f"STOR2 skipped {run.run_id}: selection/execution missing"
            )
            continue
        selection = store.get_record(selection_key, mdstats.CheckpointSelectionRecord)
        execution = store.get_record(execution_key, mdstats.TrainingRunExecutionRecord)
        if execution.state is not mdstats.TrainingRunState.SUCCEEDED:
            report.skipped.append(
                f"STOR2 skipped {run.run_id}: training is not durably complete"
            )
            continue
        original = _evaluation_checkpoint_catalog(store, run.run_id, execution)
        selected = next(
            (
                item for item in original.checkpoints
                if item.sha256 == selection.selected_checkpoint_sha256
            ),
            None,
        )
        if selected is None:
            report.skipped.append(
                f"STOR2 skipped {run.run_id}: selected checkpoint unavailable"
            )
            continue

        root = Path(original.root_directory).resolve()
        root_authorized, root_detail = report.ownership_boundary.traversal_authorization(root)
        if not root_authorized:
            report.skipped.append(
                f"STOR2 refused {run.run_id}: checkpoint root failed ownership checks: {root_detail}: {root}"
            )
            continue
        selected_path = (root / selected.relative_path).resolve()
        if not selected_path.is_file() or _sha256(selected_path) != selected.sha256:
            report.skipped.append(
                f"STOR2 skipped {run.run_id}: selected production checkpoint is missing or changed"
            )
            continue

        try:
            _bundle, job, data8_root = job_lookup[run.mace_job_artifact_digest]
        except KeyError:
            report.skipped.append(
                f"STOR2 skipped {run.run_id}: immutable DATA8 job lookup is missing"
            )
            continue
        job_root = (Path(data8_root).resolve() / job.relative_directory).resolve()
        config_path = (Path(data8_root).resolve() / job.config_relative_path).resolve()
        if not config_path.is_file() or _sha256(config_path) != job.config_sha256:
            report.skipped.append(
                f"STOR2 skipped {run.run_id}: immutable DATA8 MACE config is missing or changed"
            )
            continue

        run_root = (paths.runs / run.run_id).resolve()
        capsule_root = run_root / "evaluation-capsules"
        capsule_authorized, capsule_detail = report.ownership_boundary.destructive_authorization(
            capsule_root
        )
        if not capsule_authorized:
            report.skipped.append(
                f"STOR2 refused {run.run_id}: capsule destination failed ownership checks: {capsule_detail}"
            )
            continue
        if not dry_run:
            capsule_root.mkdir(parents=True, exist_ok=True)

        capsule_records: list[Any] = []
        all_nonselected_ready = True
        for checkpoint in original.checkpoints:
            if checkpoint.sha256 == selection.selected_checkpoint_sha256:
                continue
            raw = (root / checkpoint.relative_path).resolve()
            try:
                raw.relative_to(root)
            except ValueError:
                all_nonselected_ready = False
                report.skipped.append(
                    f"STOR2 retained unsafe checkpoint path for {run.run_id}: {raw}"
                )
                continue

            key = _checkpoint_capsule_key(run.run_id, checkpoint.sha256)
            existing = store.get_record_optional(key, mdstats.EvaluationStateCapsuleRecord)
            if existing is not None:
                capsule = Path(existing.capsule_path).resolve()
                try:
                    capsule.relative_to(run_root)
                    mdstats.load_validated_capsule_payload(
                        existing,
                        capsule,
                        expected_run_plan_digest=checkpoint.run_plan_digest,
                        expected_checkpoint_sha256=checkpoint.sha256,
                        expected_epoch=checkpoint.epoch,
                        expected_config_sha256=job.config_sha256,
                    )
                    capsule_records.append(existing)
                    if raw.is_file():
                        if _sha256(raw) != checkpoint.sha256:
                            all_nonselected_ready = False
                            report.skipped.append(
                                f"STOR2 retained changed redundant raw checkpoint: {raw}"
                            )
                        else:
                            _cleanup_remove(
                                report,
                                raw,
                                reason=(
                                    f"STOR2 verified capsule already exists for {run.run_id}; "
                                    f"remove redundant optimizer checkpoint epoch={checkpoint.epoch}"
                                ),
                            )
                    continue
                except Exception:
                    store.delete_record(key)
                    existing = None

            if not raw.is_file():
                all_nonselected_ready = False
                report.skipped.append(
                    f"STOR2 cannot compact {run.run_id} epoch {checkpoint.epoch}: raw checkpoint and valid capsule are both unavailable"
                )
                continue
            if _sha256(raw) != checkpoint.sha256:
                all_nonselected_ready = False
                report.skipped.append(
                    f"STOR2 retained changed checkpoint for diagnostics: {raw}"
                )
                continue
            if dry_run:
                report.add(
                    raw,
                    reason=(
                        f"STOR2 dry-run: would create authenticated model-state capsule then remove "
                        f"optimizer checkpoint for {run.run_id} epoch={checkpoint.epoch}"
                    ),
                    size_bytes=checkpoint.size_bytes,
                )
                continue

            capsule_path = capsule_root / (
                f"epoch-{checkpoint.epoch:04d}-{checkpoint.sha256[:20]}.eval-state.pt"
            )
            try:
                record = mdstats.create_mace_evaluation_state_capsule(
                    checkpoint,
                    raw,
                    mace_config_path=config_path,
                    cache_directory=run_root / "checkpoint-model-cache",
                    capsule_path=capsule_path,
                    allow_checkpoint_dtype_template_cast=(
                        getattr(job.protocol.optimizer_policy, "precision_schedule_policy", None)
                        is not None
                    ),
                )
                # Commit the replacement before source deletion, then independently
                # reload the committed record and capsule.  A crash between commit
                # and unlink leaves redundant bytes, never lost capability.
                store.put_record(key, record)
                committed = store.get_record(key, mdstats.EvaluationStateCapsuleRecord)
                mdstats.load_validated_capsule_payload(
                    committed,
                    capsule_path,
                    expected_run_plan_digest=checkpoint.run_plan_digest,
                    expected_checkpoint_sha256=checkpoint.sha256,
                    expected_epoch=checkpoint.epoch,
                    expected_config_sha256=job.config_sha256,
                )
                capsule_records.append(committed)
                _cleanup_remove(
                    report,
                    raw,
                    reason=(
                        f"STOR2 authenticated evaluation-state capsule committed for {run.run_id}; "
                        f"remove nonselected optimizer checkpoint epoch={checkpoint.epoch}"
                    ),
                )
            except Exception as exc:
                all_nonselected_ready = False
                capsule_path.unlink(missing_ok=True)
                store.delete_record(key)
                report.skipped.append(
                    f"STOR2 retained raw checkpoint {run.run_id} epoch {checkpoint.epoch}: {type(exc).__name__}: {exc}"
                )

        if dry_run:
            continue
        retention_payload = {
            "schema": "mdstats.mlff-checkpoint-retention.v2",
            "run_id": run.run_id,
            "created_utc": _utc_now(),
            "original_checkpoint_catalog": original.to_dict(),
            "selected_checkpoint_sha256": selection.selected_checkpoint_sha256,
            "selected_checkpoint_epoch": selection.selected_checkpoint_epoch,
            "selected_checkpoint_restart_capable": True,
            "evaluation_capsules": [
                value.to_dict()
                for value in sorted(
                    capsule_records,
                    key=lambda item: (item.source_checkpoint_epoch, item.source_checkpoint_sha256),
                )
            ],
            "all_nonselected_capsules_ready": bool(all_nonselected_ready),
            "raw_checkpoint_count_retained": sum(
                1
                for item in original.checkpoints
                if (root / item.relative_path).is_file()
            ),
            "checkpoint_catalog_identity_preserved": True,
        }
        store.put_record(f"checkpoint_retention:{run.run_id}", retention_payload)

        # Remove empty checkpoint subdirectories only; never touch capsule/model/log trees.
        for directory in sorted(root.rglob("*"), reverse=True):
            if directory.is_dir():
                try:
                    directory.rmdir()
                except OSError:
                    pass

    if not dry_run:
        cleanup_report_path = paths.results / "cleanup-post-evaluate-checkpoints.json"
        output_authorized, output_detail = report.ownership_boundary.destructive_authorization(
            cleanup_report_path
        )
        if output_authorized:
            _atomic_json(cleanup_report_path, report.to_dict())
        else:
            report.skipped.append(
                f"STOR2 report write skipped by ownership boundary: {output_detail}"
            )
    return report


def _availability_metric_evidence(
    availability: _VariantAvailability,
    selections: Mapping[str, Any],
) -> tuple[str, tuple[Any, ...], tuple[float, ...], float, float]:
    evidence_runs = availability.completed_folds or availability.completed_runs
    names: list[str] = []
    values: list[float] = []
    for run in evidence_runs:
        selection = selections[run.content_digest]
        decision = next(
            value
            for value in selection.decisions
            if value.checkpoint_sha256 == selection.selected_checkpoint_sha256
        )
        names.append(decision.primary_metric_name)
        values.append(float(selection.selected_primary_metric_value))
    if len(set(names)) != 1:
        raise CampaignCliError(
            "Completed runs in one protocol variant use incompatible primary metrics."
        )
    array = tuple(values)
    return names[0], tuple(evidence_runs), array, sum(array) / len(array), max(array)


def _select_available_variant(
    availabilities: Sequence[_VariantAvailability],
    selections: Mapping[str, Any],
) -> tuple[_VariantAvailability, str, tuple[Any, ...], tuple[float, ...], float, float]:
    ranked = []
    for availability in availabilities:
        primary, evidence_runs, values, mean_value, worst_value = _availability_metric_evidence(
            availability, selections
        )
        ranked.append(
            (
                -availability.rank,
                mean_value,
                worst_value,
                availability.training_mode.value,
                availability.selection_size,
                availability.seed,
                availability.protocol_variant_digest,
                availability,
                primary,
                evidence_runs,
                values,
            )
        )
    if not ranked:
        raise CampaignCliError("No completed protocol variant is available for evaluation.")
    selected = min(ranked, key=lambda value: value[:7])
    return selected[7], selected[8], selected[9], selected[10], selected[1], selected[2]



@dataclass(frozen=True)
class _CheckpointShortlist:
    catalog: Any
    original_catalog_digest: str
    original_count: int
    selected_epochs: tuple[int, ...]
    reasons_by_epoch: tuple[tuple[int, tuple[str, ...]], ...]
    history_files: tuple[str, ...]
    used_training_history: bool
    strategy: str = "bounded"

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema": "mdstats.mlff-checkpoint-shortlist.v1",
            "original_checkpoint_count": self.original_count,
            "shortlisted_checkpoint_count": len(self.catalog.checkpoints),
            "selected_epochs": list(self.selected_epochs),
            "reasons_by_epoch": {
                str(epoch): list(reasons) for epoch, reasons in self.reasons_by_epoch
            },
            "history_files": list(self.history_files),
            "used_training_history": self.used_training_history,
            "strategy": self.strategy,
            "shortlist_catalog_digest": self.catalog.content_digest,
            "original_catalog_digest": self.original_catalog_digest,
            "checkpoint_sha256s": [item.sha256 for item in self.catalog.checkpoints],
        }


def _read_mace_validation_history(result_directory: Path) -> tuple[dict[tuple[int, str], dict[str, Any]], tuple[str, ...]]:
    """Read the latest validation row for every epoch/head from MACE JSONL.

    MACE appends to ``*_train.txt`` across restarts.  When an epoch is replayed,
    the later row corresponds to the checkpoint bytes that remain on disk, so
    later rows intentionally replace earlier rows with the same epoch/head.
    """

    history: dict[tuple[int, str], dict[str, Any]] = {}
    files: list[str] = []
    for path in sorted(result_directory.glob("*_train.txt")):
        if not path.is_file():
            continue
        files.append(str(path.resolve()))
        try:
            handle = path.open("r", encoding="utf-8", errors="replace")
        except OSError:
            continue
        with handle:
            for line in handle:
                if not line.strip():
                    continue
                try:
                    item = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if item.get("mode") != "eval" or item.get("epoch") is None:
                    continue
                try:
                    epoch = int(item["epoch"])
                except (TypeError, ValueError):
                    continue
                head = str(item.get("head", "Default"))
                history[(epoch, head)] = dict(item)
    return history, tuple(files)


def _finite_history_metric(item: Mapping[str, Any] | None, key: str) -> float | None:
    if item is None:
        return None
    try:
        value = float(item[key])
    except (KeyError, TypeError, ValueError):
        return None
    if value < 0.0 or value != value or value in (float("inf"), float("-inf")):
        return None
    return value


def _checkpoint_shortlist(
    run: Any,
    catalog: Any,
    result_directory: Path,
    *,
    maximum_candidates: int,
    target_head_name: str = "target_head",
    replay_head_name: str = "pt_head",
) -> _CheckpointShortlist:
    """Shortlist expensive checkpoint evaluations from training-time validation.

    The full target/replay monitor metrics remain authoritative.  MACE's already
    computed validation history is used only as a cheap screen, and the latest
    checkpoint is retained as a guard against a missing or incomplete history.
    """

    import mdstats

    checkpoints = tuple(catalog.checkpoints)
    limit = int(maximum_candidates)
    if limit <= 0 or len(checkpoints) <= limit:
        return _CheckpointShortlist(
            catalog=catalog,
            original_catalog_digest=catalog.content_digest,
            original_count=len(checkpoints),
            selected_epochs=tuple(item.epoch for item in checkpoints),
            reasons_by_epoch=tuple((item.epoch, ("all_checkpoints_requested",)) for item in checkpoints),
            history_files=(),
            used_training_history=False,
        )

    by_epoch = {item.epoch: item for item in checkpoints}
    history, files = _read_mace_validation_history(result_directory)
    heads = {head for _, head in history}
    target_heads = [target_head_name]
    if target_head_name not in heads:
        non_replay = sorted(
            head for head in heads
            if head not in {replay_head_name, "replay_head", "pt_head"}
        )
        if non_replay:
            target_heads = [non_replay[0]]
    replay_heads = [head for head in (replay_head_name, "replay_head", "pt_head") if head in heads]

    reasons: dict[int, list[str]] = {}
    ranked: list[tuple[int, str]] = []

    def add(epoch: int, reason: str) -> None:
        if epoch in by_epoch:
            reasons.setdefault(epoch, []).append(reason)

    def best(head_names: Sequence[str], metric: str, reason: str) -> None:
        candidates: list[tuple[float, int]] = []
        for epoch in by_epoch:
            values = [
                _finite_history_metric(history.get((epoch, head)), metric)
                for head in head_names
            ]
            finite = [value for value in values if value is not None]
            if finite:
                candidates.append((min(finite), epoch))
        if candidates:
            value, epoch = min(candidates, key=lambda pair: (pair[0], pair[1]))
            add(epoch, reason)
            ranked.append((epoch, reason))

    best(target_heads, "rmse_f", "best_training_validation_target_force_rmse")
    best(target_heads, "loss", "best_training_validation_target_loss")
    if run.replay_monitor_artifact_digest is not None and replay_heads:
        best(replay_heads, "rmse_f", "best_training_validation_replay_force_rmse")
        best(replay_heads, "loss", "best_training_validation_replay_loss")

    latest_epoch = max(by_epoch)
    add(latest_epoch, "latest_durable_checkpoint")

    # Prefer distinct scientifically motivated extrema.  Fill any remaining
    # slots by the best target-force history, then by evenly spaced epochs when
    # old/incomplete MACE logs do not contain enough validation records.
    selected: list[int] = []
    # Preserve semantic priority across unlike metrics rather than comparing raw
    # loss and force-RMSE magnitudes. Reserve one slot for the latest durable
    # checkpoint whenever the user allows more than one candidate.
    priority_budget = max(1, limit - 1) if limit > 1 else 1
    for epoch, _ in ranked:
        if epoch not in selected:
            selected.append(epoch)
        if len(selected) >= priority_budget:
            break
    if limit > 1 and latest_epoch not in selected:
        selected.append(latest_epoch)
    elif not selected:
        selected.append(latest_epoch)
    if len(selected) < limit:
        target_rank: list[tuple[float, int]] = []
        for epoch in by_epoch:
            values = [
                _finite_history_metric(history.get((epoch, head)), "rmse_f")
                for head in target_heads
            ]
            finite = [value for value in values if value is not None]
            if finite:
                target_rank.append((min(finite), epoch))
        for _, epoch in sorted(target_rank, key=lambda value: (value[0], value[1])):
            if epoch not in selected:
                add(epoch, "training_validation_target_force_rank_fill")
                selected.append(epoch)
            if len(selected) >= limit:
                break
    if len(selected) < limit:
        ordered = sorted(by_epoch)
        if limit == 1:
            fill_epochs = [ordered[-1]]
        else:
            fill_epochs = [ordered[round(index * (len(ordered) - 1) / (limit - 1))] for index in range(limit)]
        for epoch in fill_epochs:
            if epoch not in selected:
                add(epoch, "deterministic_epoch_spacing_fallback")
                selected.append(epoch)
            if len(selected) >= limit:
                break

    selected = sorted(selected[:limit])
    shortlisted = tuple(by_epoch[epoch] for epoch in selected)
    subset = mdstats.CandidateCheckpointCatalog(
        run_plan_digest=catalog.run_plan_digest,
        root_directory=catalog.root_directory,
        checkpoints=shortlisted,
        pattern=catalog.pattern,
    )
    return _CheckpointShortlist(
        catalog=subset,
        original_catalog_digest=catalog.content_digest,
        original_count=len(checkpoints),
        selected_epochs=tuple(selected),
        reasons_by_epoch=tuple(
            (epoch, tuple(sorted(set(reasons.get(epoch, ("bounded_fallback",))))))
            for epoch in selected
        ),
        history_files=files,
        used_training_history=bool(history),
    )



def _multi_fidelity_policy(cfg: Mapping[str, Any]) -> Any:
    import mdstats

    raw = _cfg(cfg, "evaluation", "multi_fidelity_round_fractions", [0.10, 0.33, 1.0])
    if isinstance(raw, (int, float)):
        fractions = (float(raw),)
    else:
        fractions = tuple(float(value) for value in raw)
    return mdstats.MultiFidelityEvaluationPolicy(
        round_fractions=fractions,
        survival_fraction=float(
            _cfg(cfg, "evaluation", "multi_fidelity_survival_fraction", 1.0 / 3.0)
        ),
        minimum_finalists=int(
            _cfg(cfg, "evaluation", "multi_fidelity_minimum_finalists", 4)
        ),
        guard_band_enabled=bool(
            _cfg(cfg, "evaluation", "multi_fidelity_guard_band_enabled", True)
        ),
        guard_standard_error_multiplier=float(
            _cfg(cfg, "evaluation", "multi_fidelity_guard_standard_error_multiplier", 2.0)
        ),
        guard_relative_margin=float(
            _cfg(cfg, "evaluation", "multi_fidelity_guard_relative_margin", 0.02)
        ),
        guard_minimum_blocks=int(
            _cfg(cfg, "evaluation", "multi_fidelity_guard_minimum_blocks", 4)
        ),
        instability_inversion_fraction=float(
            _cfg(cfg, "evaluation", "multi_fidelity_instability_inversion_fraction", 0.25)
        ),
        instability_survival_fraction=float(
            _cfg(cfg, "evaluation", "multi_fidelity_instability_survival_fraction", 0.50)
        ),
    )


def _monitor_order_metadata(
    monitor_path: Path,
    geometry_identities: Sequence[str],
    *,
    condition_keys: Sequence[str],
    sidecar_path: Path | None = None,
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[int, ...]]:
    """Return label-independent stratum/source/time metadata for one monitor."""

    try:
        from ase.io import read as ase_read
    except ModuleNotFoundError as exc:  # pragma: no cover - campaign already needs ASE
        raise CampaignCliError("ASE is required for multi-fidelity monitor planning.") from exc

    atoms_list = tuple(ase_read(str(monitor_path), index=":"))
    if len(atoms_list) != len(tuple(geometry_identities)):
        raise CampaignCliError(
            f"Multi-fidelity monitor metadata count changed for {monitor_path}."
        )
    strata: list[str] = []
    sources: list[str] = []
    temporal: list[int] = []
    source_keys = ("run_id", "source_id", "trajectory_id", "source")
    temporal_keys = ("source_frame_index", "frame_index", "step", "timestep")
    for index, atoms in enumerate(atoms_list):
        values = [str(atoms.info.get("config_type", "missing:config_type"))]
        values.extend(
            str(atoms.info.get(key, f"missing:{key}")) for key in condition_keys
        )
        strata.append("|".join(values))
        source_value = "all"
        for key in source_keys:
            value = atoms.info.get(key)
            if value not in (None, ""):
                source_value = str(value)
                break
        sources.append(source_value)
        temporal_value = index
        for key in temporal_keys:
            value = atoms.info.get(key)
            if value in (None, ""):
                continue
            try:
                temporal_value = int(value)
            except (TypeError, ValueError):
                continue
            break
        temporal.append(temporal_value)

    if sidecar_path is not None and sidecar_path.is_file():
        try:
            import mdstats

            sidecar = mdstats.MaceSidecarManifest.from_dict(
                json.loads(sidecar_path.read_text(encoding="utf-8"))
            )
            sidecar_by_uid = {uid: dict(values) for uid, values in sidecar.records}
            for index, identity in enumerate(geometry_identities):
                payload = sidecar_by_uid.get(str(identity))
                if payload is None:
                    continue
                sources[index] = str(payload.get("run_id", "all"))
                temporal[index] = int(payload.get("source_frame_index", index))
                domain = payload.get("label_domain_id")
                if domain not in (None, ""):
                    strata[index] = f"{strata[index]}|domain:{domain}"
        except Exception as exc:
            _warn(
                f"multi-fidelity target sidecar metadata unavailable; falling back to "
                f"extxyz-only deterministic ordering ({exc})"
            )
    return tuple(strata), tuple(sources), tuple(temporal)


def _load_or_build_multi_fidelity_ladder(
    store: CampaignStore,
    *,
    domain: str,
    monitor_path: Path,
    monitor_artifact_digest: str,
    geometry_identities: Sequence[str],
    policy: Any,
    condition_keys: Sequence[str],
    sidecar_path: Path | None = None,
) -> Any:
    import mdstats

    key = f"multifidelity_ladder:{domain}:{monitor_artifact_digest}:{policy.policy_digest}"
    if store.has_record(key):
        try:
            ladder = mdstats.MultiFidelityMonitorLadder.from_dict(store.get_payload(key))
            if (
                ladder.monitor_artifact_digest == monitor_artifact_digest
                and ladder.round_fractions == policy.round_fractions
                and ladder.geometry_identities == tuple(str(value) for value in geometry_identities)
                and getattr(ladder, "metadata_version", 1) >= 2
                and len(getattr(ladder, "block_labels", ())) == len(tuple(geometry_identities))
            ):
                return ladder
            store.delete_record(key)
        except Exception:
            store.delete_record(key)
    strata, sources, temporal = _monitor_order_metadata(
        monitor_path,
        geometry_identities,
        condition_keys=condition_keys,
        sidecar_path=sidecar_path,
    )
    ladder = mdstats.build_monitor_ladder(
        domain=domain,
        monitor_artifact_digest=monitor_artifact_digest,
        geometry_identities=geometry_identities,
        policy=policy,
        stratum_labels=strata,
        source_labels=sources,
        temporal_indices=temporal,
    )
    store.put_record(key, ladder.to_dict())
    return ladder


def _multi_fidelity_screen_run(
    *,
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    run: Any,
    original_catalog: Any,
    bundle: Any,
    job: Any,
    root: Path,
    execution: Any,
    evaluation_policy: Any,
    metric_policy: Any,
    true_replay_resolution: Any,
    baseline_model: Path | None,
    prediction_cache_directory: Path,
    graph_cache_directory: Path,
    foundation_prediction_manifest: Any,
    foundation_prediction_root: Path | None,
    local_wrappers: Mapping[str, Path],
) -> _CheckpointShortlist:
    """Execute EVAL-MF1 and return the full-fidelity finalist catalog.

    Partial round records are stored only under ``multifidelity_round:*`` keys.
    The final 1.0 round additionally publishes the ordinary ``evaluation:*``
    record, so the unchanged authoritative selection/export pipeline consumes
    only complete-monitor evidence.
    """

    import mdstats

    mf_policy = _multi_fidelity_policy(cfg)
    target_artifacts, training_replay_artifact = _artifact_lookup(bundle)
    target_artifact = target_artifacts[run.target_monitor_artifact_digest]
    job_root = (root / job.relative_directory).resolve()
    target_path = (job_root / target_artifact.relative_path).resolve()
    target_sidecar_path = (job_root / target_artifact.sidecar_relative_path).resolve()

    active_training_replay_artifact = None
    evaluation_replay_artifact = None
    training_replay_path = None
    replay_path = None
    if run.replay_monitor_artifact_digest is not None:
        if training_replay_artifact is None:
            raise CampaignCliError(
                f"{run.run_id}: replay run is missing its frozen DATA8 replay monitor artifact."
            )
        active_training_replay_artifact = training_replay_artifact
        evaluation_replay_artifact = training_replay_artifact
        training_replay_path = _resolve_data8_runtime_member(
            bundle, root, training_replay_artifact.path
        )
        replay_path = training_replay_path
        if true_replay_resolution is not None:
            candidate_true_artifact = true_replay_resolution.monitor_artifact
            if (
                candidate_true_artifact.configuration_count
                != active_training_replay_artifact.configuration_count
                or candidate_true_artifact.geometry_identities
                != active_training_replay_artifact.geometry_identities
            ):
                raise CampaignCliError(
                    f"{run.run_id}: configured true-label replay monitor does not match "
                    "the frozen DATA8 replay geometry/order."
                )
            evaluation_replay_artifact = candidate_true_artifact
            replay_path = Path(true_replay_resolution.monitor_path).resolve()

    requires_foundation_baseline = bool(
        evaluation_policy.evaluate_foundation_on_target
        or run.replay_monitor_artifact_digest is not None
    )
    baseline_for_evaluation = baseline_model if requires_foundation_baseline else None

    target_ladder = _load_or_build_multi_fidelity_ladder(
        store,
        domain="target",
        monitor_path=target_path,
        monitor_artifact_digest=target_artifact.content_digest,
        geometry_identities=target_artifact.frame_uids,
        policy=mf_policy,
        condition_keys=evaluation_policy.condition_keys,
        sidecar_path=target_sidecar_path,
    )
    replay_ladder = None
    if evaluation_replay_artifact is not None and replay_path is not None:
        replay_ladder = _load_or_build_multi_fidelity_ladder(
            store,
            domain="replay",
            monitor_path=Path(replay_path),
            monitor_artifact_digest=evaluation_replay_artifact.content_digest,
            geometry_identities=evaluation_replay_artifact.geometry_identities,
            policy=mf_policy,
            condition_keys=evaluation_policy.condition_keys,
            sidecar_path=None,
        )

    store.put_record(
        f"multifidelity_policy:{run.run_id}",
        {
            "schema": "mdstats.mlff-multi-fidelity-run-plan.v1",
            "run_plan_digest": run.content_digest,
            "evaluation_policy_digest": evaluation_policy.policy_digest,
            "checkpoint_metric_policy_digest": metric_policy.policy_digest,
            "multi_fidelity_policy": mf_policy.to_dict(),
            "target_ladder_digest": target_ladder.content_digest,
            "replay_ladder_digest": None if replay_ladder is None else replay_ladder.content_digest,
        },
    )

    survivors = list(original_catalog.checkpoints)
    reasons: dict[int, list[str]] = {item.epoch: ["multifidelity_round1_entry"] for item in survivors}
    previous_ranking_sha256s: tuple[str, ...] = ()
    config_path = (root / job.config_relative_path).resolve()
    checkpoint_model_cache = paths.runs / run.run_id / "checkpoint-model-cache"

    for round_index, fraction in enumerate(mf_policy.round_fractions):
        is_final = round_index == len(mf_policy.round_fractions) - 1
        target_indices = target_ladder.round_indices[round_index]
        target_delta = target_ladder.round_delta_indices[round_index]
        replay_indices = None if replay_ladder is None else replay_ladder.round_indices[round_index]
        replay_delta = None if replay_ladder is None else replay_ladder.round_delta_indices[round_index]
        round_records: dict[str, Any] = {}
        tasks: list[_StagedEvaluationTask] = []
        progress = _ProgressReporter(f"EVAL-MF{round_index + 1}", len(survivors))
        print(
            f"[EVAL-MF ROUND {round_index + 1}/{len(mf_policy.round_fractions)}] "
            f"{run.run_id}: candidates={len(survivors)}; target={len(target_indices)}/{target_artifact.configuration_count} "
            f"({fraction:.0%}); replay="
            f"{0 if replay_indices is None else len(replay_indices)}/"
            f"{0 if evaluation_replay_artifact is None else evaluation_replay_artifact.configuration_count} "
            f"({fraction:.0%})",
            flush=True,
        )

        for display_index, checkpoint in enumerate(survivors, start=1):
            record_key = (
                f"multifidelity_round:{run.run_id}:{mf_policy.policy_digest}:"
                f"{round_index}:{checkpoint.sha256}"
            )
            cached = None
            if store.has_record(record_key):
                try:
                    candidate = mdstats.MultiFidelityCheckpointRoundRecord.from_dict(
                        store.get_payload(record_key)
                    )
                    valid = bool(
                        candidate.run_plan_digest == run.content_digest
                        and candidate.checkpoint_sha256 == checkpoint.sha256
                        and candidate.round_index == round_index
                        and candidate.round_fraction == fraction
                        and candidate.target_ladder_digest == target_ladder.content_digest
                        and candidate.replay_ladder_digest
                        == (None if replay_ladder is None else replay_ladder.content_digest)
                        and candidate.evaluation_record.evaluation_policy_digest
                        == evaluation_policy.policy_digest
                    )
                    if valid:
                        cached = candidate
                except Exception:
                    cached = None
                if cached is None:
                    store.delete_record(record_key)
            if cached is not None:
                round_records[checkpoint.sha256] = cached
                progress.item_start(display_index, f"{run.run_id}:epoch{checkpoint.epoch}", "verified cached round")
                progress.item_done(
                    display_index,
                    f"{run.run_id}:epoch{checkpoint.epoch}",
                    f"cached; force={cached.metric_record.force_component_rmse_ev_per_angstrom * 1000:.1f} meV/A",
                )
                if is_final:
                    store.put_record(f"evaluation:{run.run_id}:{checkpoint.sha256}", cached.evaluation_record)
                continue

            model_path, capsule_record = _checkpoint_source_for_evaluation(
                paths, store, run.run_id, checkpoint, execution.checkpoint_catalog
            )
            label = f"{run.run_id}:epoch{checkpoint.epoch}"

            def prepare_delta(
                *, active_checkpoint=checkpoint,
                active_model_path=model_path,
                active_capsule_record=capsule_record,
                active_target_delta=target_delta,
                active_replay_delta=replay_delta,
            ):
                return mdstats.prepare_mace_checkpoint_evaluation(
                    run,
                    active_checkpoint,
                    candidate_model_path=active_model_path,
                    calculator_model_path=None,
                    evaluation_state_capsule=active_capsule_record,
                    target_monitor_path=target_path,
                    target_monitor_artifact=target_artifact,
                    policy=evaluation_policy,
                    replay_monitor_path=replay_path,
                    replay_monitor_artifact=evaluation_replay_artifact,
                    training_replay_monitor_artifact=active_training_replay_artifact,
                    training_replay_monitor_path=training_replay_path,
                    replay_baseline_model_path=baseline_for_evaluation,
                    prediction_cache_directory=prediction_cache_directory,
                    graph_cache_directory=graph_cache_directory,
                    foundation_prediction_manifest=foundation_prediction_manifest,
                    foundation_prediction_root=foundation_prediction_root,
                    target_configuration_indices=active_target_delta,
                    replay_configuration_indices=active_replay_delta,
                )

            def infer_delta(
                prepared,
                *, active_checkpoint=checkpoint,
                active_model_path=model_path,
                active_capsule_record=capsule_record,
            ):
                calculator_model = None
                if prepared.requires_candidate_inference:
                    calculator_model = mdstats.materialize_mace_checkpoint_model(
                        active_checkpoint,
                        active_model_path,
                        mace_config_path=config_path,
                        job_working_directory=job_root,
                        cache_directory=checkpoint_model_cache,
                        wrapper_path=local_wrappers["mdstats-mace-train"],
                        allow_checkpoint_dtype_template_cast=False,
                        evaluation_state_capsule=active_capsule_record,
                    )
                return mdstats.run_prepared_mace_checkpoint_inference(
                    prepared, calculator_model_path=calculator_model
                )

            def finalize_round(
                prepared,
                predictions,
                *, active_checkpoint=checkpoint,
                active_model_path=model_path,
                active_capsule_record=capsule_record,
                active_target_indices=target_indices,
                active_replay_indices=replay_indices,
                active_record_key=record_key,
            ):
                delta_result = mdstats.finalize_prepared_mace_checkpoint_evaluation(
                    prepared, predictions
                )
                delta_result = mdstats.bind_checkpoint_evaluation_replay_provenance(
                    delta_result,
                    None
                    if prepared.replay_monitor_artifact is None
                    else prepared.replay_monitor_artifact.label_mode,
                    training_replay_monitor_artifact_digest=run.replay_monitor_artifact_digest,
                )
                if (
                    tuple(active_target_indices) == tuple(prepared.target_configuration_indices)
                    and (
                        active_replay_indices is None
                        or tuple(active_replay_indices)
                        == tuple(prepared.replay_configuration_indices or ())
                    )
                ):
                    cumulative = delta_result
                    evidence_prepared = prepared
                    evidence_bundle = predictions
                else:
                    cumulative_prepared = mdstats.prepare_mace_checkpoint_evaluation(
                        run,
                        active_checkpoint,
                        candidate_model_path=active_model_path,
                        calculator_model_path=None,
                        evaluation_state_capsule=active_capsule_record,
                        target_monitor_path=target_path,
                        target_monitor_artifact=target_artifact,
                        policy=evaluation_policy,
                        replay_monitor_path=replay_path,
                        replay_monitor_artifact=evaluation_replay_artifact,
                        training_replay_monitor_artifact=active_training_replay_artifact,
                        training_replay_monitor_path=training_replay_path,
                        replay_baseline_model_path=baseline_for_evaluation,
                        prediction_cache_directory=prediction_cache_directory,
                        graph_cache_directory=graph_cache_directory,
                        foundation_prediction_manifest=foundation_prediction_manifest,
                        foundation_prediction_root=foundation_prediction_root,
                        target_configuration_indices=active_target_indices,
                        replay_configuration_indices=active_replay_indices,
                    )
                    if cumulative_prepared.requires_model_inference:
                        raise CampaignCliError(
                            f"{run.run_id} epoch {active_checkpoint.epoch}: nested prediction "
                            "coverage is incomplete after the round delta was persisted."
                        )
                    cumulative_bundle = mdstats.run_prepared_mace_checkpoint_inference(
                        cumulative_prepared
                    )
                    cumulative = mdstats.finalize_prepared_mace_checkpoint_evaluation(
                        cumulative_prepared, cumulative_bundle
                    )
                    cumulative = mdstats.bind_checkpoint_evaluation_replay_provenance(
                        cumulative,
                        None
                        if cumulative_prepared.replay_monitor_artifact is None
                        else cumulative_prepared.replay_monitor_artifact.label_mode,
                        training_replay_monitor_artifact_digest=run.replay_monitor_artifact_digest,
                    )
                    evidence_prepared = cumulative_prepared
                    evidence_bundle = cumulative_bundle

                target_blocks = tuple(
                    target_ladder.block_labels[index] for index in active_target_indices
                )
                target_block_values = mdstats.target_primary_block_values(
                    evidence_prepared.target_view,
                    evidence_bundle.target_candidate_predictions,
                    target_blocks,
                    primary_metric=metric_policy.primary_metric,
                    combined_energy_weight=evaluation_policy.combined_energy_weight,
                    combined_force_weight=evaluation_policy.combined_force_weight,
                    combined_stress_weight=evaluation_policy.combined_stress_weight,
                )
                replay_block_values = ()
                if (
                    replay_ladder is not None
                    and active_replay_indices is not None
                    and evidence_prepared.replay_view is not None
                    and evidence_bundle.replay_candidate_predictions is not None
                    and evidence_bundle.replay_foundation_predictions is not None
                    and evaluation_replay_artifact is not None
                    and evaluation_replay_artifact.label_mode
                    is not mdstats.ReplayLabelMode.FOUNDATION_PSEUDOLABEL
                ):
                    replay_blocks = tuple(
                        replay_ladder.block_labels[index] for index in active_replay_indices
                    )
                    replay_metric_name = (
                        "euclidean_bundle"
                        if evaluation_policy.replay_metric == "energy_force_stress"
                        else evaluation_policy.replay_metric
                    )
                    replay_block_values = mdstats.replay_degradation_block_values(
                        evidence_prepared.replay_view,
                        evidence_bundle.replay_candidate_predictions,
                        evidence_bundle.replay_foundation_predictions,
                        replay_blocks,
                        replay_metric=replay_metric_name,
                        replay_baseline_floor=evaluation_policy.replay_baseline_floor,
                        combined_energy_weight=evaluation_policy.combined_energy_weight,
                        combined_force_weight=evaluation_policy.combined_force_weight,
                        combined_stress_weight=evaluation_policy.combined_stress_weight,
                    )
                return mdstats.MultiFidelityCheckpointRoundRecord(
                    run_plan_digest=run.content_digest,
                    checkpoint_sha256=active_checkpoint.sha256,
                    round_index=round_index,
                    round_fraction=fraction,
                    target_ladder_digest=target_ladder.content_digest,
                    replay_ladder_digest=None if replay_ladder is None else replay_ladder.content_digest,
                    target_configuration_count=len(active_target_indices),
                    replay_configuration_count=0 if active_replay_indices is None else len(active_replay_indices),
                    evaluation_record=cumulative,
                    full_fidelity=is_final,
                    target_primary_block_values=target_block_values,
                    replay_degradation_block_values=replay_block_values,
                )

            def commit_round(result, *, active_sha=checkpoint.sha256, active_key=record_key):
                store.put_record(active_key, result)
                round_records[active_sha] = result
                if result.full_fidelity:
                    store.put_record(f"evaluation:{run.run_id}:{active_sha}", result.evaluation_record)

            tasks.append(
                _StagedEvaluationTask(
                    display_index=display_index,
                    key=f"mf:{run.content_digest}:{round_index}:{checkpoint.sha256}",
                    label=label,
                    start_detail=f"nested monitor round {round_index + 1}",
                    prepare=prepare_delta,
                    requires_inference=lambda prepared: bool(prepared.requires_model_inference),
                    infer=infer_delta,
                    finalize=finalize_round,
                    done_detail=lambda result, wall: (
                        f"force={result.metric_record.force_component_rmse_ev_per_angstrom * 1000:.1f} meV/A; "
                        f"fidelity={result.round_fraction:.0%}; elapsed={format_progress_time(wall)}"
                    ),
                    on_success=commit_round,
                )
            )

        _run_staged_evaluation_tasks(
            tasks,
            cfg=cfg,
            device=evaluation_policy.device,
            progress=progress,
        )
        if set(round_records) != {checkpoint.sha256 for checkpoint in survivors}:
            raise CampaignCliError(
                f"{run.run_id}: multi-fidelity round {round_index + 1} did not produce complete candidate coverage."
            )
        if is_final:
            break

        ranked = sorted(
            survivors,
            key=lambda checkpoint: mdstats.provisional_ranking_key(
                round_records[checkpoint.sha256].metric_record,
                checkpoint.epoch,
                checkpoint.sha256,
                metric_policy,
            ),
        )
        next_round_is_final = round_index + 1 == len(mf_policy.round_fractions) - 1
        decision = mdstats.conservative_survivor_decision(
            tuple(item.sha256 for item in ranked),
            round_records,
            metric_policy=metric_policy,
            policy=mf_policy,
            next_round_is_final=next_round_is_final,
            previous_ranking_sha256s=previous_ranking_sha256s,
            maximum_replay_degradation_fraction=metric_policy.maximum_replay_degradation_fraction,
        )
        retained_sha = set(decision.retained_checkpoint_sha256s)
        guard_sha = set(decision.guard_retained_checkpoint_sha256s)
        replay_rescue_sha = set(decision.replay_rescued_checkpoint_sha256s)
        retained = [item for item in ranked if item.sha256 in retained_sha]
        for item in survivors:
            if item.sha256 in retained_sha:
                reasons.setdefault(item.epoch, []).append(
                    f"multifidelity_round{round_index + 1}_survivor"
                )
                if item.sha256 in guard_sha:
                    reasons[item.epoch].append(
                        f"multifidelity_round{round_index + 1}_guard_retained"
                    )
                if item.sha256 in replay_rescue_sha:
                    reasons[item.epoch].append(
                        f"multifidelity_round{round_index + 1}_replay_rescued"
                    )
                if decision.instability_expanded:
                    nominal_sha = {value.sha256 for value in ranked[: decision.nominal_keep_count]}
                    if item.sha256 not in nominal_sha and item.sha256 not in guard_sha and item.sha256 not in replay_rescue_sha:
                        reasons[item.epoch].append(
                            f"multifidelity_round{round_index + 1}_instability_expanded"
                        )
            else:
                reasons.setdefault(item.epoch, []).append(
                    f"multifidelity_round{round_index + 1}_screened_out"
                )
        diagnostic_by_sha = {sha: dict(values) for sha, values in decision.candidate_diagnostics}
        ranking_payload = []
        for rank, item in enumerate(ranked, start=1):
            record = round_records[item.sha256]
            metric_record = record.metric_record
            key = mdstats.provisional_ranking_key(
                metric_record, item.epoch, item.sha256, metric_policy
            )
            if item.sha256 not in retained_sha:
                reason_code = f"multifidelity_round{round_index + 1}_screened_out"
            elif item.sha256 in guard_sha:
                reason_code = f"multifidelity_round{round_index + 1}_guard_retained"
            elif item.sha256 in replay_rescue_sha:
                reason_code = f"multifidelity_round{round_index + 1}_replay_rescued"
            elif rank > decision.nominal_keep_count and decision.instability_expanded:
                reason_code = f"multifidelity_round{round_index + 1}_instability_expanded"
            else:
                reason_code = f"multifidelity_round{round_index + 1}_survivor"
            ranking_payload.append(
                {
                    "rank": rank,
                    "checkpoint_sha256": item.sha256,
                    "epoch": item.epoch,
                    "primary_metric_value": float(key[0]),
                    "replay_degradation_fraction": (
                        None if key[1] == float("inf") else float(key[1])
                    ),
                    "outcome": "retained" if item.sha256 in retained_sha else "screened_out",
                    "reason_code": reason_code,
                    "guard_diagnostics": diagnostic_by_sha.get(item.sha256, {}),
                }
            )
        store.put_record(
            f"multifidelity_survivors:{run.run_id}:{mf_policy.policy_digest}:{round_index}",
            {
                "schema": "mdstats.mlff-multi-fidelity-survivors.v2",
                "run_plan_digest": run.content_digest,
                "round_index": round_index,
                "round_fraction": fraction,
                "candidate_checkpoint_sha256s": [item.sha256 for item in survivors],
                "survivor_checkpoint_sha256s": [item.sha256 for item in retained],
                "survivor_epochs": [item.epoch for item in retained],
                "nominal_keep_count": decision.nominal_keep_count,
                "guard_retained_checkpoint_sha256s": list(decision.guard_retained_checkpoint_sha256s),
                "replay_rescued_checkpoint_sha256s": list(decision.replay_rescued_checkpoint_sha256s),
                "instability_expanded": decision.instability_expanded,
                "inversion_fraction": decision.inversion_fraction,
                "cutoff_checkpoint_sha256": decision.cutoff_checkpoint_sha256,
                "survivor_decision": decision.to_dict(),
                "ranking": ranking_payload,
                "screening_evidence_only": True,
            },
        )
        previous_ranking_sha256s = tuple(item.sha256 for item in ranked)
        survivors = retained

    finalist_catalog = mdstats.CandidateCheckpointCatalog(
        run_plan_digest=original_catalog.run_plan_digest,
        root_directory=original_catalog.root_directory,
        checkpoints=tuple(sorted(survivors, key=lambda item: (item.epoch, item.sha256))),
        pattern=original_catalog.pattern,
    )
    for item in survivors:
        reasons.setdefault(item.epoch, []).append("multifidelity_full_fidelity_finalist")
    return _CheckpointShortlist(
        catalog=finalist_catalog,
        original_catalog_digest=original_catalog.content_digest,
        original_count=len(original_catalog.checkpoints),
        selected_epochs=tuple(item.epoch for item in finalist_catalog.checkpoints),
        reasons_by_epoch=tuple(
            (item.epoch, tuple(sorted(set(reasons.get(item.epoch, ())))))
            for item in finalist_catalog.checkpoints
        ),
        history_files=(),
        used_training_history=False,
        strategy="multi_fidelity",
    )


def _write_multi_fidelity_epoch_report(
    *,
    paths: CampaignPaths,
    store: CampaignStore,
    run: Any,
    original_catalog: Any,
    policy: Any,
    evaluation_policy: Any,
    metric_policy: Any,
    selection: Any | None = None,
    selection_failure: Mapping[str, Any] | None = None,
) -> tuple[Path, Path, Path]:
    """Write the EVAL-MF2 comprehensive per-epoch JSON/CSV/Markdown report."""

    import mdstats

    history, history_files = _read_mace_validation_history(
        paths.runs / run.run_id / "results"
    )
    heads = {head for _, head in history}
    target_head = evaluation_policy.target_head_name
    if target_head not in heads:
        non_replay = sorted(
            head
            for head in heads
            if head not in {evaluation_policy.replay_head_name, "replay_head", "pt_head"}
        )
        if non_replay:
            target_head = non_replay[0]
    replay_head = next(
        (
            head
            for head in (
                evaluation_policy.replay_head_name,
                "replay_head",
                "pt_head",
            )
            if head in heads
        ),
        None,
    )

    survivor_payloads: dict[int, Mapping[str, Any]] = {}
    for round_index in range(len(policy.round_fractions) - 1):
        key = f"multifidelity_survivors:{run.run_id}:{policy.policy_digest}:{round_index}"
        if store.has_record(key):
            survivor_payloads[round_index] = store.get_payload(key)

    selection_failure_by_sha: dict[str, Mapping[str, Any]] = {}
    if selection_failure is not None:
        selection_failure_by_sha = {
            str(item.get("checkpoint_sha256", "")): item
            for item in selection_failure.get("candidates", ())
            if isinstance(item, Mapping)
        }

    selected_sha = None if selection is None else str(selection.selected_checkpoint_sha256)
    rows: list[dict[str, Any]] = []
    for checkpoint in sorted(original_catalog.checkpoints, key=lambda item: (item.epoch, item.sha256)):
        target_history = history.get((checkpoint.epoch, target_head))
        replay_history = None if replay_head is None else history.get((checkpoint.epoch, replay_head))
        rounds: list[dict[str, Any]] = []
        last_outcome = "not_evaluated"
        last_reason = ""
        full_metric = None
        full_decision = None
        for round_index, fraction in enumerate(policy.round_fractions):
            key = (
                f"multifidelity_round:{run.run_id}:{policy.policy_digest}:"
                f"{round_index}:{checkpoint.sha256}"
            )
            if not store.has_record(key):
                continue
            payload = store.get_payload(key)
            record = mdstats.MultiFidelityCheckpointRoundRecord.from_dict(payload)
            metric = record.metric_record
            target_metrics = record.evaluation_record.target_candidate_metrics
            replay_metrics = record.evaluation_record.replay_candidate_metrics
            block_target = dict(record.target_primary_block_values)
            block_replay = dict(record.replay_degradation_block_values)
            rounds.append(
                {
                    "round_index": round_index,
                    "fraction": float(fraction),
                    "full_fidelity": bool(record.full_fidelity),
                    "target_configuration_count": record.target_configuration_count,
                    "replay_configuration_count": record.replay_configuration_count,
                    "target_energy_mae_ev_per_atom": (
                        metric.energy_mae_ev_per_atom
                        if target_metrics is None
                        else target_metrics.energy_mae_ev_per_atom
                    ),
                    "target_force_rmse_ev_per_angstrom": (
                        metric.force_component_rmse_ev_per_angstrom
                        if target_metrics is None
                        else target_metrics.force_component_rmse_ev_per_angstrom
                    ),
                    "target_focus_force_rmse_ev_per_angstrom": dict(
                        metric.focus_force_rmse_ev_per_angstrom
                        if target_metrics is None
                        else target_metrics.focus_force_rmse_ev_per_angstrom
                    ),
                    "target_worst_condition_force_rmse_ev_per_angstrom": (
                        metric.worst_condition_force_rmse_ev_per_angstrom
                        if target_metrics is None
                        else target_metrics.worst_condition_force_rmse_ev_per_angstrom
                    ),
                    "target_combined_loss": metric.target_combined_loss,
                    "replay_candidate_metric": metric.replay_candidate_metric,
                    "replay_baseline_metric": metric.replay_baseline_metric,
                    "replay_degradation_fraction": metric.replay_degradation_fraction,
                    "replay_force_rmse_ev_per_angstrom": (
                        None if replay_metrics is None else replay_metrics.force_component_rmse_ev_per_angstrom
                    ),
                    "target_primary_block_values": block_target,
                    "replay_degradation_block_values": block_replay,
                }
            )
            if record.full_fidelity:
                full_metric = metric
                try:
                    full_decision = mdstats.assess_checkpoint_admissibility(
                        run, checkpoint, metric, metric_policy
                    )
                except Exception:
                    full_decision = None

        for round_index, payload in survivor_payloads.items():
            for item in payload.get("ranking", ()):
                if str(item.get("checkpoint_sha256", "")) == checkpoint.sha256:
                    last_outcome = str(item.get("outcome", last_outcome))
                    last_reason = str(item.get("reason_code", last_reason))
        if full_metric is not None:
            last_outcome = "full_fidelity"
            last_reason = "multifidelity_full_fidelity_finalist"
        if checkpoint.sha256 == selected_sha:
            last_outcome = "selected"
            last_reason = "selected_production_checkpoint"
        failure_item = selection_failure_by_sha.get(checkpoint.sha256)
        if failure_item is not None:
            last_outcome = "full_fidelity_rejected"
            last_reason = ",".join(str(v) for v in failure_item.get("rejection_reasons", ()))

        rows.append(
            {
                "epoch": checkpoint.epoch,
                "checkpoint_sha256": checkpoint.sha256,
                "mace_target_head": target_head if target_history is not None else None,
                "mace_target_rmse_f_ev_per_angstrom": _finite_history_metric(target_history, "rmse_f"),
                "mace_target_rmse_e_per_atom_ev": _finite_history_metric(target_history, "rmse_e_per_atom"),
                "mace_target_loss": _finite_history_metric(target_history, "loss"),
                "mace_replay_head": replay_head if replay_history is not None else None,
                "mace_replay_rmse_f_ev_per_angstrom": _finite_history_metric(replay_history, "rmse_f"),
                "mace_replay_rmse_e_per_atom_ev": _finite_history_metric(replay_history, "rmse_e_per_atom"),
                "mace_replay_loss": _finite_history_metric(replay_history, "loss"),
                "rounds": rounds,
                "final_admissibility": (
                    None
                    if full_decision is None
                    else full_decision.outcome.value
                ),
                "final_rejection_reasons": (
                    []
                    if full_decision is None
                    else list(full_decision.rejection_reasons)
                ),
                "outcome": last_outcome,
                "reason": last_reason,
                "selected": checkpoint.sha256 == selected_sha,
            }
        )

    payload = {
        "schema": "mdstats.mlff-multi-fidelity-epoch-report.v1",
        "run_id": run.run_id,
        "run_plan_digest": run.content_digest,
        "multi_fidelity_policy": policy.to_dict(),
        "evaluation_policy_digest": evaluation_policy.policy_digest,
        "checkpoint_metric_policy_digest": metric_policy.policy_digest,
        "history_files": list(history_files),
        "selected_checkpoint_sha256": selected_sha,
        "selected_checkpoint_epoch": None if selection is None else selection.selected_checkpoint_epoch,
        "selection_failure": None if selection_failure is None else dict(selection_failure),
        "epochs": rows,
        "created_at_utc": _utc_now(),
    }
    payload["content_digest"] = digest(payload)
    json_path = paths.results / f"{run.run_id}-epoch-evaluation.json"
    csv_path = paths.results / f"{run.run_id}-epoch-evaluation.csv"
    md_path = paths.results / f"{run.run_id}-epoch-evaluation.md"
    _atomic_json(json_path, payload)

    flat_rows: list[dict[str, Any]] = []
    for row in rows:
        flat = {
            "epoch": row["epoch"],
            "checkpoint_sha256": row["checkpoint_sha256"],
            "mace_target_rmse_f_ev_per_angstrom": row["mace_target_rmse_f_ev_per_angstrom"],
            "mace_target_rmse_e_per_atom_ev": row["mace_target_rmse_e_per_atom_ev"],
            "mace_replay_rmse_f_ev_per_angstrom": row["mace_replay_rmse_f_ev_per_angstrom"],
            "outcome": row["outcome"],
            "reason": row["reason"],
            "selected": row["selected"],
        }
        for round_data in row["rounds"]:
            prefix = f"round{int(round_data['round_index']) + 1}"
            flat[f"{prefix}_fraction"] = round_data["fraction"]
            flat[f"{prefix}_target_count"] = round_data["target_configuration_count"]
            flat[f"{prefix}_replay_count"] = round_data["replay_configuration_count"]
            flat[f"{prefix}_target_energy_mae_ev_per_atom"] = round_data["target_energy_mae_ev_per_atom"]
            flat[f"{prefix}_target_force_rmse_ev_per_angstrom"] = round_data["target_force_rmse_ev_per_angstrom"]
            flat[f"{prefix}_replay_degradation_fraction"] = round_data["replay_degradation_fraction"]
        flat_rows.append(flat)
    fieldnames = sorted({key for row in flat_rows for key in row})
    csv_path.parent.mkdir(parents=True, exist_ok=True)
    temporary_csv = csv_path.with_name(f".{csv_path.name}.tmp-{os.getpid()}-{time.time_ns()}")
    with temporary_csv.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(flat_rows)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temporary_csv, csv_path)

    def _fmt(value: Any, scale: float = 1.0) -> str:
        if value is None:
            return "-"
        return f"{float(value) * scale:.3f}"

    round_headers = [f"R{i + 1} F RMSE (meV/A)" for i in range(len(policy.round_fractions))]
    lines = [
        f"# Checkpoint evaluation history: {run.run_id}",
        "",
        "Partial rounds are screening evidence only. Final admissibility and selection use the 100% round.",
        "",
        "| Epoch | MACE val F (meV/A) | " + " | ".join(round_headers) + " | Outcome |",
        "|---:|---:|" + "---:|" * len(round_headers) + "---|",
    ]
    for row in rows:
        round_map = {int(value["round_index"]): value for value in row["rounds"]}
        round_cells = [
            _fmt(
                None if index not in round_map else round_map[index]["target_force_rmse_ev_per_angstrom"],
                1000.0,
            )
            for index in range(len(policy.round_fractions))
        ]
        lines.append(
            f"| {row['epoch']} | {_fmt(row['mace_target_rmse_f_ev_per_angstrom'], 1000.0)} | "
            + " | ".join(round_cells)
            + f" | {row['outcome']} |"
        )
    lines.extend(
        [
            "",
            f"Selected epoch: {payload['selected_checkpoint_epoch'] if payload['selected_checkpoint_epoch'] is not None else 'not yet selected'}",
            "",
        ]
    )
    temporary_md = md_path.with_name(f".{md_path.name}.tmp-{os.getpid()}-{time.time_ns()}")
    temporary_md.write_text("\n".join(lines), encoding="utf-8")
    os.replace(temporary_md, md_path)
    return json_path, csv_path, md_path


def _available_checkpoint_refresh_shortlist(
    run: Any,
    shortlist: _CheckpointShortlist,
    original_catalog: Any,
    store: CampaignStore,
) -> tuple[_CheckpointShortlist, int]:
    """Limit a post-cleanup metric refresh to checkpoint bytes still retained.

    Older completed campaigns may have deleted every unselected optimizer snapshot
    after committing their first evaluation.  A newly configured independent
    true-label replay corpus intentionally invalidates those pseudo-label records,
    but it cannot reconstruct deleted checkpoint bytes.  Re-evaluate every
    shortlisted checkpoint that remains and always add the previously selected
    retained checkpoint when necessary.
    """

    import mdstats

    root = Path(original_catalog.root_directory).resolve()

    def available(checkpoint: Any) -> bool:
        path = (root / checkpoint.relative_path).resolve()
        try:
            path.relative_to(root)
        except ValueError:
            return False
        if path.is_file() and _sha256(path) == checkpoint.sha256:
            return True
        capsule = store.get_record_optional(
            _checkpoint_capsule_key(run.run_id, checkpoint.sha256),
            mdstats.EvaluationStateCapsuleRecord,
        )
        if capsule is None:
            return False
        capsule_path = Path(capsule.capsule_path).resolve()
        try:
            capsule_path.relative_to(root.parent.resolve())
        except ValueError:
            return False
        return bool(
            capsule.run_plan_digest == checkpoint.run_plan_digest
            and capsule.source_checkpoint_sha256 == checkpoint.sha256
            and capsule.source_checkpoint_epoch == checkpoint.epoch
            and capsule_path.is_file()
            and _sha256(capsule_path) == capsule.capsule_sha256
        )

    shortlisted = tuple(shortlist.catalog.checkpoints)
    unavailable = tuple(item for item in shortlisted if not available(item))
    if not unavailable:
        return shortlist, 0

    retention_key = f"checkpoint_retention:{run.run_id}"
    if not store.has_record(retention_key):
        raise CampaignCliError(
            f"{run.run_id}: checkpoint bytes are missing or changed before an "
            "authenticated post-evaluation cleanup record exists. Restore the "
            "checkpoint files or rerun training; evaluation will not silently "
            "reduce scientific coverage."
        )
    retention = store.get_payload(retention_key)
    intentionally_removed = {
        str(item.get("sha256", ""))
        for item in retention.get("removed_checkpoints", ())
        if isinstance(item, Mapping)
    }
    unexpected = [
        item for item in unavailable if item.sha256 not in intentionally_removed
    ]
    if unexpected:
        raise CampaignCliError(
            f"{run.run_id}: {len(unexpected)} checkpoint(s) are missing or changed "
            "without authenticated cleanup evidence. Restore them or rerun training."
        )

    retained = [item for item in shortlisted if available(item)]
    selection_key = f"selection:{run.run_id}"
    if store.has_record(selection_key):
        payload = store.get_payload(selection_key)
        selected_sha256 = str(payload.get("selected_checkpoint_sha256", ""))
        selected = next(
            (
                item
                for item in original_catalog.checkpoints
                if item.sha256 == selected_sha256 and available(item)
            ),
            None,
        )
        if selected is not None and all(item.sha256 != selected.sha256 for item in retained):
            retained.append(selected)

    if not retained:
        raise CampaignCliError(
            f"{run.run_id}: independent true-label replay evaluation invalidated the "
            "old pseudo-label metrics, but no authenticated checkpoint bytes remain. "
            "Restore a retained checkpoint or rerun training before evaluation."
        )

    retained = sorted(
        {item.sha256: item for item in retained}.values(),
        key=lambda item: (item.epoch, item.sha256),
    )
    reasons = {epoch: list(values) for epoch, values in shortlist.reasons_by_epoch}
    for item in retained:
        reasons.setdefault(item.epoch, []).append(
            "retained_checkpoint_available_for_true_label_refresh"
        )
    catalog = mdstats.CandidateCheckpointCatalog(
        run_plan_digest=original_catalog.run_plan_digest,
        root_directory=original_catalog.root_directory,
        checkpoints=tuple(retained),
        pattern=original_catalog.pattern,
    )
    refreshed = _CheckpointShortlist(
        catalog=catalog,
        original_catalog_digest=shortlist.original_catalog_digest,
        original_count=shortlist.original_count,
        selected_epochs=tuple(item.epoch for item in retained),
        reasons_by_epoch=tuple(
            (item.epoch, tuple(sorted(set(reasons[item.epoch]))))
            for item in retained
        ),
        history_files=shortlist.history_files,
        used_training_history=shortlist.used_training_history,
        strategy=shortlist.strategy,
    )
    return refreshed, len(unavailable)


def _checkpoint_selection_failure_payload(
    run: Any,
    shortlist: _CheckpointShortlist,
    catalog: Any,
    metric_records: Sequence[Any],
    decisions: Sequence[Any],
    policy: Any,
) -> dict[str, Any]:
    """Return a durable, human-readable record for an inadmissible run.

    A bounded shortlist proves only that the evaluated candidates failed the
    frozen constraints.  It must not be misreported as proof that every saved
    epoch is inadmissible.
    """

    metric_by_sha = {value.checkpoint_sha256: value for value in metric_records}
    checkpoint_by_sha = {value.sha256: value for value in catalog.checkpoints}
    reason_counts = Counter(
        reason
        for decision in decisions
        for reason in decision.rejection_reasons
    )
    candidates = []
    for decision in sorted(
        decisions,
        key=lambda value: (
            checkpoint_by_sha[value.checkpoint_sha256].epoch,
            value.checkpoint_sha256,
        ),
    ):
        checkpoint = checkpoint_by_sha[decision.checkpoint_sha256]
        metric = metric_by_sha[decision.checkpoint_sha256]
        candidates.append(
            {
                "epoch": checkpoint.epoch,
                "checkpoint_sha256": checkpoint.sha256,
                "primary_metric_name": decision.primary_metric_name,
                "primary_metric_value": decision.primary_metric_value,
                "energy_mae_ev_per_atom": metric.energy_mae_ev_per_atom,
                "force_component_rmse_ev_per_angstrom": metric.force_component_rmse_ev_per_angstrom,
                "maximum_focus_force_rmse_ev_per_angstrom": metric.maximum_focus_force_rmse,
                "stress_rmse_ev_per_angstrom3": metric.stress_rmse_ev_per_angstrom3,
                "worst_condition_force_rmse_ev_per_angstrom": metric.worst_condition_force_rmse_ev_per_angstrom,
                "replay_label_mode": (
                    None if metric.replay_label_mode is None else metric.replay_label_mode.value
                ),
                "replay_baseline_metric": metric.replay_baseline_metric,
                "replay_candidate_metric": metric.replay_candidate_metric,
                "replay_degradation_fraction": metric.replay_degradation_fraction,
                "rejection_reasons": list(decision.rejection_reasons),
            }
        )
    payload = {
        "schema": "mdstats.mlff-checkpoint-selection-failure.v1",
        "run_id": run.run_id,
        "run_plan_digest": run.content_digest,
        "checkpoint_metric_policy_digest": policy.policy_digest,
        "shortlist_catalog_digest": catalog.content_digest,
        "original_catalog_digest": shortlist.original_catalog_digest,
        "evaluated_checkpoint_count": len(catalog.checkpoints),
        "available_checkpoint_count": shortlist.original_count,
        "bounded_shortlist": len(catalog.checkpoints) < shortlist.original_count,
        "reason_counts": dict(sorted(reason_counts.items())),
        "candidates": candidates,
        "created_at_utc": _utc_now(),
    }
    return {**payload, "content_digest": digest(payload)}


def _checkpoint_selection_or_failure(
    run: Any,
    shortlist: _CheckpointShortlist,
    catalog: Any,
    metric_records: Sequence[Any],
    policy: Any,
) -> tuple[Any | None, dict[str, Any] | None]:
    """Select an admissible checkpoint or return a durable failure record."""

    import mdstats

    metric_by_sha = {value.checkpoint_sha256: value for value in metric_records}
    if set(metric_by_sha) != {value.sha256 for value in catalog.checkpoints}:
        raise CampaignCliError(
            f"{run.run_id}: checkpoint metric coverage does not match the evaluated catalog."
        )
    decisions = tuple(
        mdstats.assess_checkpoint_admissibility(
            run, checkpoint, metric_by_sha[checkpoint.sha256], policy
        )
        for checkpoint in catalog.checkpoints
    )
    if not any(
        decision.outcome is mdstats.CheckpointAdmissibilityOutcome.ADMISSIBLE
        for decision in decisions
    ):
        return None, _checkpoint_selection_failure_payload(
            run, shortlist, catalog, metric_records, decisions, policy
        )
    return (
        mdstats.select_checkpoint(run, catalog, metric_records, policy),
        None,
    )


def _format_checkpoint_selection_failure(payload: Mapping[str, Any]) -> str:
    counts = payload.get("reason_counts", {})
    reasons = ", ".join(
        f"{name}={int(count)}" for name, count in sorted(counts.items())
    ) or "unspecified_constraint_failure"
    scope = (
        f"{payload['evaluated_checkpoint_count']}/{payload['available_checkpoint_count']} shortlisted checkpoints"
        if payload.get("bounded_shortlist")
        else f"all {payload['available_checkpoint_count']} checkpoints"
    )
    return f"{payload['run_id']}: no admissible checkpoint among {scope}; {reasons}"

def _verification_case_digest(payload: Mapping[str, Any]) -> str:
    return digest({"schema": "mdstats.mlff-verification-case.v1", **dict(payload)})


def _verification_full_members(
    members: Sequence[Any],
    store: CampaignStore,
    *,
    full_verification: bool,
) -> tuple[Any, ...]:
    """Return models requiring the expensive full NVE matrix.

    Production committee members are deployment candidates and all receive full
    verification.  Interim fold evidence uses all models for a short smoke, but
    only the final-development model (or the best selected fold when no final is
    complete) receives the full structure/temperature matrix.
    """

    import mdstats

    if full_verification:
        return tuple(members)
    finals = tuple(
        member for member in members
        if getattr(getattr(member, "kind", None), "value", "") == "final_development"
    )
    if finals:
        return finals
    ranked: list[tuple[float, str, Any]] = []
    for member in members:
        run_id = str(getattr(member, "run_id", ""))
        try:
            selection = store.get_record(
                f"selection:{run_id}", mdstats.CheckpointSelectionRecord
            )
            value = float(selection.selected_primary_metric_value)
        except Exception:
            value = float("inf")
        ranked.append((value, run_id, member))
    return (min(ranked, key=lambda item: (item[0], item[1]))[2],) if ranked else ()

def _adaptive_full_evaluation_policy(
    cfg: Mapping[str, Any], stop_policy: Any, metric_policy: Any
) -> Any:
    """Freeze ADAPT-EVAL1 batching/scoring around the training-time score geometry."""
    import mdstats

    replay_max = (
        float(stop_policy.target_score_weight)
        / float(stop_policy.replay_score_weight)
        * float(stop_policy.maximum_target_force_rmse_ev_per_angstrom)
    )
    return mdstats.AdaptiveFullEvaluationPolicy(
        finalist_count=int(_cfg(cfg, "evaluation", "finalist_count", 5)),
        finalist_rescue_batch_size=int(
            _cfg(cfg, "evaluation", "finalist_rescue_batch_size", 5)
        ),
        target_score_weight=float(stop_policy.target_score_weight),
        replay_score_weight=float(stop_policy.replay_score_weight),
        maximum_target_force_rmse_ev_per_angstrom=float(
            stop_policy.maximum_target_force_rmse_ev_per_angstrom
        ),
        maximum_replay_force_rmse_ev_per_angstrom=replay_max,
        retained_checkpoint_metric_policy_digest=metric_policy.policy_digest,
    )



def _mlcv_run_selection_policy(stop_policy: Any, metric_policy: Any) -> Any:
    """Freeze MLCV-SELECT1 full-validation geometry from training authority."""
    import mdstats

    replay_budget = stop_policy.replay_degradation_budget_force_rmse_ev_per_angstrom
    if replay_budget is None:
        raise CampaignCliError("MLCV-SELECT1 requires a resolved replay degradation budget.")
    return mdstats.MlcvRunSelectionPolicy(
        maximum_target_force_rmse_ev_per_angstrom=float(
            stop_policy.maximum_target_force_rmse_ev_per_angstrom
        ),
        replay_degradation_budget_ev_per_angstrom=float(replay_budget),
        target_score_weight=float(stop_policy.target_score_weight),
        replay_score_weight=float(stop_policy.replay_score_weight),
        retained_checkpoint_metric_policy_digest=metric_policy.policy_digest,
    )


def _mlcv_target_full_artifact(bundle: Any, job: Any) -> tuple[Any, Any]:
    """Return the role-correct complete target checkpoint-selection artifact."""
    import mdstats

    catalog = getattr(bundle, "mlcv_monitor_catalog", None)
    if catalog is None:
        raise CampaignCliError(
            f"{job.job_id}: MLCV-SELECT1 requires an MLCV-MON1 monitor catalog."
        )
    record = catalog.run(job.job_id)
    matches = tuple(
        artifact
        for artifact in bundle.target_artifacts
        if artifact.role == "target_checkpoint_full"
        and artifact.frame_uids == record.target_full_frame_uids
    )
    if len(matches) != 1:
        raise CampaignCliError(
            f"{job.job_id}: expected exactly one target_checkpoint_full artifact bound to MLCV-MON1."
        )
    if job.kind is mdstats.MaceJobKind.CROSS_VALIDATION_FOLD:
        role = mdstats.MlcvDataRole.TARGET_CHECKPOINT_SELECTION
    else:
        role = mdstats.MlcvDataRole.TARGET_FINAL_VALIDATION
    mdstats.require_mlcv_topk_selection_role(role)
    return matches[0], role



def _mlcv_outer_fold_artifact(bundle: Any, job: Any) -> Any:
    """Return one immutable untouched outer-fold target artifact."""
    import mdstats

    if job.kind is not mdstats.MaceJobKind.CROSS_VALIDATION_FOLD or job.fold_index is None:
        raise CampaignCliError(f"{job.job_id}: MLCV-AGG1 outer evidence requires a fold job.")
    mdstats.require_mlcv_outer_cv_evaluation_role(
        mdstats.MlcvDataRole.TARGET_OUTER_CV_EVALUATION
    )
    matches = tuple(
        artifact
        for artifact in bundle.fold_evaluation_artifacts
        if artifact.content_digest == job.fold_evaluation_artifact_digest
    )
    if len(matches) != 1 or matches[0].role != "cross_validation_evaluation":
        raise CampaignCliError(
            f"{job.job_id}: expected exactly one immutable cross_validation_evaluation artifact."
        )
    return matches[0]


def _mlcv_cross_validation_policy(runs: Sequence[Any], jobs: Mapping[str, tuple[Any, Any, Path]]) -> Any:
    """Freeze AGG1 geometry from the same full-threshold/score authority as SELECT1."""
    import mdstats

    folds = tuple(run for run in runs if run.kind is mdstats.MaceJobKind.CROSS_VALIDATION_FOLD)
    if not folds:
        # Zero-fold campaigns intentionally trade away CV evidence; retain the
        # generated full threshold/weights from any final run for identity.
        folds = tuple(runs[:1])
    if not folds:
        raise CampaignCliError("MLCV-AGG1 cannot resolve a CV policy from an empty campaign.")
    geometries: list[tuple[float, float, float, float]] = []
    for run in folds:
        _bundle, job, _root = jobs[run.mace_job_artifact_digest]
        stop = job.protocol.adaptive_stop_policy
        if stop is None:
            raise CampaignCliError(f"{run.run_id}: MLCV-AGG1 requires protocol-frozen STOP1 geometry.")
        geometries.append((
            float(stop.maximum_target_force_rmse_ev_per_angstrom),
            float(stop.target_score_weight),
            float(stop.replay_score_weight),
            float(stop.replay_degradation_budget_force_rmse_ev_per_angstrom),
        ))
    if any(value != geometries[0] for value in geometries[1:]):
        raise CampaignCliError(
            "MLCV-AGG1 cannot aggregate fold representatives with different target/score geometry."
        )
    target_max, target_weight, replay_weight, replay_budget = geometries[0]
    return mdstats.MlcvCrossValidationPolicy(
        maximum_target_force_rmse_ev_per_angstrom=target_max,
        replay_degradation_budget_ev_per_angstrom=replay_budget,
        target_score_weight=target_weight,
        replay_score_weight=replay_weight,
        require_all_folds=True,
        dispersion_gate_enabled=False,
    )


def _command_evaluate_mlcv_agg1(
    *,
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    campaign: Any,
    jobs: Mapping[str, tuple[Any, Any, Path]],
    execution_records: Mapping[str, Any],
    selections: Sequence[Any],
    model_dtype: str,
) -> int:
    """MLCV-AGG1: evaluate frozen fold representatives once on untouched outer folds."""
    import mdstats

    policy = _mlcv_cross_validation_policy(tuple(campaign.runs), jobs)
    selection_by_run = {item.run_plan_digest: item for item in selections}
    if len(selection_by_run) != len(selections):
        raise CampaignCliError("MLCV-AGG1 received duplicate SELECT1 run evidence.")
    missing = [run.run_id for run in campaign.runs if run.content_digest not in selection_by_run]
    if missing:
        raise CampaignCliError(
            "MLCV-AGG1 requires complete SELECT1 evidence for the full campaign; missing: "
            + ", ".join(missing[:8])
        )

    prediction_cache_directory = paths.internal / "evaluation-predictions"
    graph_cache_directory = paths.internal / "evaluation-graphs"
    local_wrappers = _ensure_local_wrappers(paths)
    acceleration = _acceleration_policy(cfg)
    critical_precision = _critical_precision_policy(cfg)
    outer_records: list[Any] = []

    folds = tuple(
        sorted(
            (run for run in campaign.runs if run.kind is mdstats.MaceJobKind.CROSS_VALIDATION_FOLD),
            key=lambda run: (run.training_mode.value, run.selection_size, run.seed, int(run.fold_index)),
        )
    )
    if folds:
        _print_header(f"MLCV-AGG1 outer cross-validation ({len(folds)} fold representative(s))")
    for run in folds:
        selection = selection_by_run[run.content_digest]
        execution = execution_records.get(run.content_digest)
        if execution is None:
            raise CampaignCliError(f"{run.run_id}: missing successful execution evidence for AGG1.")
        bundle, job, root = jobs[run.mace_job_artifact_digest]
        outer_artifact = _mlcv_outer_fold_artifact(bundle, job)
        outer_path = _resolve_data8_job_member(
            bundle, root, job, outer_artifact.relative_path
        )
        if not outer_path.is_file() or _sha256(outer_path) != outer_artifact.sha256:
            raise CampaignCliError(f"{run.run_id}: outer CV artifact is missing or stale.")

        if selection.outcome == "no_representative":
            fold_record = mdstats.build_mlcv_outer_fold_record(
                run,
                selection,
                None,
                policy,
                outer_target_artifact_digest=outer_artifact.content_digest,
                outer_target_sha256=outer_artifact.sha256,
            )
            _warn(f"{run.run_id}: CV fold fails because SELECT1 produced no representative")
        else:
            representative = selection.representative_candidate
            assert representative is not None
            catalog = _evaluation_checkpoint_catalog(store, run.run_id, execution)
            checkpoint = next(
                (
                    value for value in catalog.checkpoints
                    if value.sha256 == representative.checkpoint_sha256
                    and value.epoch == representative.checkpoint_epoch
                ),
                None,
            )
            if checkpoint is None:
                raise CampaignCliError(
                    f"{run.run_id}: frozen SELECT1 representative is absent from checkpoint inventory."
                )
            stop = job.protocol.adaptive_stop_policy
            assert stop is not None
            eval_policy = mdstats.CheckpointEvaluationPolicy(
                target_head_name=stop.target_head_name,
                replay_head_name=stop.replay_head_name,
                replay_baseline_head_name=None,
                focus_atomic_numbers=tuple(
                    int(v) for v in _cfg(cfg, "profile", "mobile_atomic_numbers", (3, 11, 19))
                ),
                device=str(_cfg(cfg, "evaluation", "device", _cfg(cfg, "training", "device", "cuda"))),
                default_dtype=model_dtype,
                batch_size=int(_cfg(cfg, "evaluation", "batch_size", 8)),
                cache_monitor_datasets=bool(_cfg(cfg, "evaluation", "cache_monitor_datasets", True)),
                cache_replay_baseline=False,
                evaluate_foundation_on_target=False,
                acceleration_policy=acceleration,
                **_evaluation_acceleration_binding(cfg, paths),
                critical_precision_policy=critical_precision,
            )
            record_key = f"mlcv_agg1_outer_evaluation:{run.run_id}:{checkpoint.sha256}"
            evaluation = store.get_record_optional(record_key, mdstats.CheckpointEvaluationRecord)
            reusable = bool(
                evaluation is not None
                and evaluation.run_plan_digest == run.content_digest
                and evaluation.checkpoint_sha256 == checkpoint.sha256
                and evaluation.evaluation_policy_digest == eval_policy.policy_digest
                and evaluation.target_monitor_artifact_digest == outer_artifact.content_digest
                and evaluation.target_monitor_sha256 == outer_artifact.sha256
                and evaluation.replay_monitor_artifact_digest is None
                and evaluation.replay_configuration_count == 0
                and evaluation.target_candidate_metrics is not None
            )
            if not reusable:
                if evaluation is not None:
                    store.delete_record(record_key)
                source, capsule = _checkpoint_source_for_evaluation(
                    paths, store, run.run_id, checkpoint, execution.checkpoint_catalog
                )
                job_root = (root / job.relative_directory).resolve()
                config_path = (root / job.config_relative_path).resolve()
                checkpoint_model_cache = paths.runs / run.run_id / "checkpoint-model-cache"
                prepared = mdstats.prepare_mace_checkpoint_evaluation(
                    run,
                    checkpoint,
                    candidate_model_path=source,
                    evaluation_state_capsule=capsule,
                    target_monitor_path=outer_path,
                    target_monitor_artifact=outer_artifact,
                    policy=eval_policy,
                    prediction_cache_directory=prediction_cache_directory,
                    graph_cache_directory=graph_cache_directory,
                    # AGG1 evaluates only the sealed outer target fold. Full replay
                    # authority was already frozen by SELECT1 and is reused by
                    # build_mlcv_outer_fold_record; re-evaluating replay here would
                    # violate the conventional-CV role contract.
                    allow_target_monitor_override=True,
                    allow_target_only_evaluation=True,
                )
                calculator_model = None
                try:
                    if prepared.requires_candidate_inference:
                        calculator_model = mdstats.materialize_mace_checkpoint_model(
                            checkpoint,
                            source,
                            mace_config_path=config_path,
                            job_working_directory=job_root,
                            cache_directory=checkpoint_model_cache,
                            wrapper_path=local_wrappers["mdstats-mace-train"],
                            allow_checkpoint_dtype_template_cast=False,
                            evaluation_state_capsule=capsule,
                        )
                    predictions = mdstats.run_prepared_mace_checkpoint_inference(
                        prepared, calculator_model_path=calculator_model
                    )
                    evaluation = mdstats.finalize_prepared_mace_checkpoint_evaluation(prepared, predictions)
                finally:
                    if calculator_model is not None and Path(calculator_model).resolve() != Path(source).resolve():
                        mdstats.remove_materialized_mace_checkpoint_model(calculator_model)
                store.put_record(record_key, evaluation)
            fold_record = mdstats.build_mlcv_outer_fold_record(
                run,
                selection,
                evaluation,
                policy,
                outer_target_artifact_digest=outer_artifact.content_digest,
                outer_target_sha256=outer_artifact.sha256,
            )
            _ok(
                f"{run.run_id}: outer target={fold_record.outer_target_force_rmse_ev_per_angstrom*1000:.2f} meV/A; "
                f"replay(full SELECT1)={fold_record.representative_replay_full_rmse_ev_per_angstrom*1000:.2f}; "
                f"{'PASS' if fold_record.survived else 'FAIL'}"
            )
        fold_key = f"mlcv_outer_fold:{run.run_id}"
        existing = store.get_record_optional(fold_key, mdstats.MlcvOuterFoldEvaluationRecord)
        if existing is not None and existing.content_digest != fold_record.content_digest:
            raise CampaignCliError(
                f"{run.run_id}: immutable MLCV-AGG1 outer-fold evidence disagrees with the frozen representative."
            )
        store.put_record(fold_key, fold_record)
        outer_records.append(fold_record)

    records_by_run = {record.run_plan_digest: record for record in outer_records}
    grouped: dict[str, list[Any]] = {}
    for run in campaign.runs:
        grouped.setdefault(run.protocol_variant_digest, []).append(run)
    seed_aggregates: list[Any] = []
    for variant_digest, variant_runs in sorted(grouped.items()):
        fold_records = tuple(
            records_by_run[run.content_digest]
            for run in variant_runs
            if run.kind is mdstats.MaceJobKind.CROSS_VALIDATION_FOLD
        )
        aggregate = mdstats.aggregate_mlcv_seed_cv(
            campaign, tuple(variant_runs), fold_records, policy
        )
        key = f"mlcv_seed_cv:{variant_digest}"
        existing = store.get_record_optional(key, mdstats.MlcvSeedCvAggregateRecord)
        if existing is not None and existing.content_digest != aggregate.content_digest:
            raise CampaignCliError("Existing immutable MLCV seed-CV aggregate disagrees with current evidence.")
        store.put_record(key, aggregate)
        seed_aggregates.append(aggregate)
        if aggregate.outcome == "cv_robust":
            summary = aggregate.target_summary
            assert summary is not None
            sd = summary.sample_standard_deviation_ev_per_angstrom
            _ok(
                f"seed {aggregate.seed}: CV robust; target mean={summary.mean_ev_per_angstrom*1000:.2f} meV/A, "
                f"sample SD={(0.0 if sd is None else sd)*1000:.2f}, worst={summary.maximum_ev_per_angstrom*1000:.2f}"
            )
        elif aggregate.outcome == "cv_not_performed":
            _warn(f"seed {aggregate.seed}: CV not performed (zero-fold campaign)")
        else:
            _warn(f"seed {aggregate.seed}: CV robustness FAILED ({', '.join(aggregate.failure_reasons)})")

    campaign_cv = mdstats.aggregate_mlcv_campaign_cv(campaign, tuple(seed_aggregates), policy)
    existing_campaign_cv = store.get_record_optional(
        "mlcv_campaign_cv", mdstats.MlcvCampaignCvAggregateRecord
    )
    if existing_campaign_cv is not None and existing_campaign_cv.content_digest != campaign_cv.content_digest:
        raise CampaignCliError("Existing immutable MLCV campaign CV aggregate disagrees with current evidence.")
    store.put_record("mlcv_campaign_cv", campaign_cv)
    _atomic_json(paths.results / "mlcv-agg1.json", campaign_cv.to_dict())
    return _command_evaluate_mlcv_final1(
        cfg=cfg,
        paths=paths,
        store=store,
        campaign=campaign,
        jobs=jobs,
        execution_records=execution_records,
        selections=selections,
        campaign_cv=campaign_cv,
        seed_aggregates=tuple(seed_aggregates),
        model_dtype=model_dtype,
    )



def _command_evaluate_mlcv_final1(
    *,
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    campaign: Any,
    jobs: Mapping[str, tuple[Any, Any, Path]],
    execution_records: Mapping[str, Any],
    selections: Sequence[Any],
    campaign_cv: Any,
    seed_aggregates: Sequence[Any],
    model_dtype: str,
) -> int:
    """MLCV-FINAL1: compare/export only qualified final-development representatives."""
    import mdstats

    final_runs = tuple(
        run for run in campaign.runs
        if run.kind is mdstats.MaceJobKind.FINAL_DEVELOPMENT
    )
    selection_by_run = {item.run_plan_digest: item for item in selections}
    final_selections = tuple(selection_by_run[run.content_digest] for run in final_runs)
    policy = mdstats.MlcvFinalSelectionPolicy(
        require_campaign_cv_robust=True,
        allow_cv_not_performed=True,
    )
    final_selection = mdstats.build_mlcv_final_selection(
        campaign, campaign_cv, tuple(seed_aggregates), final_selections, policy
    )
    existing = store.get_record_optional("mlcv_final_selection", mdstats.MlcvFinalSelectionRecord)
    if existing is not None and existing.content_digest != final_selection.content_digest:
        raise CampaignCliError(
            "Existing immutable MLCV-FINAL1 selection disagrees with current CV/final evidence."
        )
    store.put_record("mlcv_final_selection", final_selection)
    _atomic_json(paths.results / "mlcv-final1-selection.json", final_selection.to_dict())

    if final_selection.outcome == "cv_failed":
        _mark_stage(
            store, paths, "evaluate", StageState.FAILED,
            "MLCV-FINAL1 refused production selection because configured CV robustness failed",
        )
        _warn(
            "MLCV-FINAL1: campaign CV failed; no final seed is exported or promoted. "
            "Review outer-fold evidence before creating a new protocol/campaign identity."
        )
        return 1
    if final_selection.outcome != "production_candidate_selected":
        _mark_stage(
            store, paths, "evaluate", StageState.FAILED,
            "MLCV-FINAL1 found no qualified final-development representative",
        )
        _warn("MLCV-FINAL1: no qualified final-development representative; no committee exported")
        return 1

    local_wrappers = _ensure_local_wrappers(paths)
    run_by_digest = {run.content_digest: run for run in final_runs}
    candidate_by_digest = {item.content_digest: item for item in final_selection.qualified_candidates}
    committee_root = paths.models / "mlcv-final1-committee"
    committee_root.mkdir(parents=True, exist_ok=True)
    members: list[Any] = []
    for candidate in final_selection.qualified_candidates:
        run = run_by_digest[candidate.final_run_plan_digest]
        selection = selection_by_run[run.content_digest]
        execution = execution_records[run.content_digest]
        bundle, job, root = jobs[run.mace_job_artifact_digest]
        catalog = _evaluation_checkpoint_catalog(store, run.run_id, execution)
        checkpoint = next((value for value in catalog.checkpoints if (
            value.sha256 == candidate.checkpoint_sha256
            and value.epoch == candidate.checkpoint_epoch
        )), None)
        if checkpoint is None:
            raise CampaignCliError(
                f"{run.run_id}: FINAL1 representative is absent from the frozen checkpoint inventory."
            )
        stop = job.protocol.adaptive_stop_policy
        if stop is None:
            raise CampaignCliError(f"{run.run_id}: FINAL1 requires protocol-frozen target-head identity.")
        output = committee_root / f"seed-{run.seed}-{run.run_id}-target.model"
        member_key = f"mlcv_final_committee_member:{run.run_id}"
        member = store.get_record_optional(member_key, mdstats.MlcvFinalCommitteeMemberRecord)
        reusable = bool(
            member is not None
            and member.final_candidate_digest == candidate.content_digest
            and member.run_selection_record_digest == selection.content_digest
            and member.checkpoint_sha256 == checkpoint.sha256
            and Path(member.exported_model_path).resolve() == output.resolve()
            and output.is_file()
            and _sha256(output) == member.exported_model_sha256
        )
        if not reusable:
            if member is not None:
                store.delete_record(member_key)
            source, capsule = _checkpoint_source_for_evaluation(
                paths, store, run.run_id, checkpoint, execution.checkpoint_catalog
            )
            job_root = (root / job.relative_directory).resolve()
            config_path = (root / job.config_relative_path).resolve()
            cache = paths.runs / run.run_id / "checkpoint-model-cache"
            model_path = mdstats.materialize_mace_checkpoint_model(
                checkpoint,
                source,
                mace_config_path=config_path,
                job_working_directory=job_root,
                cache_directory=cache,
                wrapper_path=local_wrappers["mdstats-mace-train"],
                allow_checkpoint_dtype_template_cast=False,
                evaluation_state_capsule=capsule,
            )
            try:
                model_sha, byte_size = mdstats.export_target_head_model_artifact(
                    model_path,
                    output,
                    target_head_name=stop.target_head_name,
                    target_device="cpu",
                    wrapper_path=local_wrappers["mdstats-mace-select-head"],
                    deployment_dtype=model_dtype,
                )
            finally:
                if Path(model_path).resolve() != Path(source).resolve():
                    mdstats.remove_materialized_mace_checkpoint_model(model_path)
            member = mdstats.MlcvFinalCommitteeMemberRecord(
                final_candidate_digest=candidate.content_digest,
                seed=run.seed,
                final_run_plan_digest=run.content_digest,
                run_selection_record_digest=selection.content_digest,
                checkpoint_sha256=checkpoint.sha256,
                checkpoint_epoch=checkpoint.epoch,
                full_score_ev_per_angstrom=float(candidate.full_score_ev_per_angstrom),
                replay_absolute_full_rmse_ev_per_angstrom=float(candidate.replay_full_rmse_ev_per_angstrom),
                replay_foundation_full_rmse_ev_per_angstrom=float(candidate.replay_foundation_full_rmse_ev_per_angstrom),
                replay_degradation_full_rmse_ev_per_angstrom=float(candidate.replay_degradation_full_rmse_ev_per_angstrom),
                replay_degradation_budget_ev_per_angstrom=float(candidate.replay_degradation_budget_ev_per_angstrom),
                target_head_name=stop.target_head_name,
                exported_model_path=str(output.resolve()),
                exported_model_sha256=model_sha,
                byte_size=byte_size,
            )
            store.put_record(member_key, member)
            _ok(
                f"seed {run.seed}: exported qualified FINAL1 committee member "
                f"(score={candidate.full_score_ev_per_angstrom*1000:.2f}, "
                f"replay_abs={candidate.replay_full_rmse_ev_per_angstrom*1000:.2f}, "
                f"replay_Delta={candidate.replay_degradation_full_rmse_ev_per_angstrom*1000:.2f} meV/A)"
            )
        else:
            _ok(f"seed {run.seed}: reused authenticated FINAL1 committee export")
        members.append(member)

    member_by_candidate = {value.final_candidate_digest: value for value in members}
    best_candidate = final_selection.production_best_candidate
    assert best_candidate is not None
    best_member = member_by_candidate[best_candidate.content_digest]
    committee = mdstats.MlcvFinalCommitteeRecord(
        campaign_plan_digest=campaign.content_digest,
        final_selection_record_digest=final_selection.content_digest,
        members=tuple(members),
        production_best_member_digest=best_member.content_digest,
        production_model_published=False,
    )
    existing_committee = store.get_record_optional("mlcv_final_committee", mdstats.MlcvFinalCommitteeRecord)
    if existing_committee is not None and existing_committee.content_digest != committee.content_digest:
        raise CampaignCliError("Existing immutable MLCV-FINAL1 committee disagrees with current exports.")
    store.put_record("mlcv_final_committee", committee)
    payload = {
        "schema": "mdstats.mlcv-final1-summary.v1",
        "campaign_plan_digest": campaign.content_digest,
        "selection": final_selection.to_dict(),
        "committee": committee.to_dict(),
        "production_best": {
            "seed": best_candidate.seed,
            "run_id": best_candidate.final_run_id,
            "checkpoint_epoch": best_candidate.checkpoint_epoch,
            "checkpoint_sha256": best_candidate.checkpoint_sha256,
            "full_score_ev_per_angstrom": best_candidate.full_score_ev_per_angstrom,
            "committee_model_path": best_member.exported_model_path,
            "committee_model_sha256": best_member.exported_model_sha256,
            "verified_production_model_published": False,
        },
        "next_gate": "MLCV-VERIFY1",
    }
    payload["content_digest"] = digest(payload)
    _atomic_json(paths.results / "mlcv-final1.json", payload)
    _mark_stage(
        store, paths, "evaluate", StageState.WAITING,
        f"MLCV-FINAL1 selected seed {best_candidate.seed} as production verification candidate; "
        f"exported {len(members)} qualified final-seed committee member(s); ready for MLCV-VERIFY1",
    )
    return 0


def _command_evaluate_mlcv_select1(
    args: argparse.Namespace,
    *,
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    campaign: Any,
    jobs: Mapping[str, tuple[Any, Any, Path]],
    execution_records: Mapping[str, Any],
    runs_to_evaluate: Sequence[Any],
    full_evaluation: bool,
    model_dtype: str,
    precision_profile: Mapping[str, Any],
) -> int:
    """MLCV-SELECT1: full-evaluate every retained run-local RANK1 candidate."""
    import mdstats

    if not runs_to_evaluate:
        raise CampaignCliError("MLCV-SELECT1 has no completed runs to evaluate.")
    metric_policy = _checkpoint_metric_policy(cfg)
    baseline_model = _path_cfg(cfg, paths, "foundation_model")
    assert baseline_model is not None
    prediction_cache_directory = paths.internal / "evaluation-predictions"
    graph_cache_directory = paths.internal / "evaluation-graphs"
    local_wrappers = _ensure_local_wrappers(paths)
    acceleration = _acceleration_policy(cfg)
    critical_precision = _critical_precision_policy(cfg)
    selections: list[Any] = []

    for run in runs_to_evaluate:
        execution = execution_records[run.content_digest]
        bundle, job, root = jobs[run.mace_job_artifact_digest]
        run_root = paths.runs / run.run_id
        state = _load_adaptive_stop_state(run_root, job, require_terminal=True)
        ranking = _reconcile_lightweight_run_champion(
            run, job, run_root, state, execution.checkpoint_catalog
        )
        if ranking is None:
            raise CampaignCliError(f"{run.run_id}: missing durable RANK1 evidence.")
        if ranking.serialization_schema != mdstats.LIGHTWEIGHT_RUN_CHAMPION_SCHEMA:
            raise CampaignCliError(
                f"{run.run_id}: MLCV-SELECT1 requires RANK1 v2 top-five evidence; "
                "historical v1 campaigns remain owned by ADAPT-EVAL1."
            )
        stop_policy = job.protocol.adaptive_stop_policy
        if stop_policy is None:
            raise CampaignCliError(f"{run.run_id}: missing protocol-frozen adaptive-stop policy.")
        selection_policy = _mlcv_run_selection_policy(stop_policy, metric_policy)

        target_full_artifact, target_role = _mlcv_target_full_artifact(bundle, job)
        target_full_path = _resolve_data8_job_member(
            bundle, root, job, target_full_artifact.relative_path
        )
        if (
            not target_full_path.is_file()
            or _sha256(target_full_path) != target_full_artifact.sha256
        ):
            raise CampaignCliError(f"{run.run_id}: V_i_full/D_full target artifact is missing or stale.")

        replay_full_artifact = getattr(bundle, "replay_full_validation_artifact", None)
        if replay_full_artifact is None:
            raise CampaignCliError(
                f"{run.run_id}: MLCV-SELECT1 requires complete TRUE_DFT R_full replay evidence."
            )
        if replay_full_artifact.label_mode.value != "true_dft":
            raise CampaignCliError(f"{run.run_id}: R_full is not independently TRUE_DFT labeled.")
        mdstats.require_mlcv_topk_selection_role(mdstats.MlcvDataRole.REPLAY_TRUE_VALIDATION)
        replay_full_path = _resolve_data8_runtime_member(
            bundle, root, replay_full_artifact.path
        ).resolve()
        if (
            not replay_full_path.is_file()
            or _sha256(replay_full_path) != replay_full_artifact.sha256
        ):
            raise CampaignCliError(f"{run.run_id}: R_full replay artifact is missing or stale.")

        catalog = _evaluation_checkpoint_catalog(store, run.run_id, execution)
        checkpoint_by_identity = {
            (item.epoch, item.sha256): item for item in catalog.checkpoints
        }
        evaluations: list[Any] = []
        _print_header(
            f"MLCV-SELECT1 {run.run_id}: {len(ranking.eligible_candidates)} retained checkpoint(s)"
        )
        for lightweight in ranking.eligible_candidates:
            checkpoint = checkpoint_by_identity.get((lightweight.epoch, lightweight.checkpoint_sha256))
            if checkpoint is None:
                raise CampaignCliError(
                    f"{run.run_id}: retained RANK1 epoch {lightweight.epoch} is absent from the frozen checkpoint catalog."
                )
            candidate_head = (
                stop_policy.replay_head_name
                if run.training_mode is mdstats.TrainingMode.MULTIHEAD_REPLAY
                else stop_policy.target_head_name
            )
            eval_policy = mdstats.CheckpointEvaluationPolicy(
                target_head_name=stop_policy.target_head_name,
                replay_head_name=candidate_head,
                focus_atomic_numbers=tuple(
                    int(v) for v in _cfg(cfg, "profile", "mobile_atomic_numbers", (3, 11, 19))
                ),
                device=str(_cfg(cfg, "evaluation", "device", _cfg(cfg, "training", "device", "cuda"))),
                default_dtype=model_dtype,
                batch_size=int(_cfg(cfg, "evaluation", "batch_size", 8)),
                cache_monitor_datasets=bool(_cfg(cfg, "evaluation", "cache_monitor_datasets", True)),
                cache_replay_baseline=bool(_cfg(cfg, "evaluation", "cache_replay_baseline", True)),
                evaluate_foundation_on_target=False,
                acceleration_policy=acceleration,
                **_evaluation_foundation_binding(cfg, paths),
                critical_precision_policy=critical_precision,
            )
            record_key = f"mlcv_select1_full_evaluation:{run.run_id}:{checkpoint.sha256}"
            evaluation = store.get_record_optional(record_key, mdstats.CheckpointEvaluationRecord)
            reusable = bool(
                evaluation is not None
                and evaluation.run_plan_digest == run.content_digest
                and evaluation.checkpoint_sha256 == checkpoint.sha256
                and evaluation.evaluation_policy_digest == eval_policy.policy_digest
                and evaluation.target_monitor_artifact_digest == target_full_artifact.content_digest
                and evaluation.target_monitor_sha256 == target_full_artifact.sha256
                and evaluation.replay_monitor_artifact_digest == replay_full_artifact.content_digest
                and evaluation.replay_monitor_sha256 == replay_full_artifact.sha256
                and evaluation.target_candidate_metrics is not None
                and evaluation.replay_candidate_metrics is not None
                and evaluation.replay_foundation_metrics is not None
            )
            if not reusable:
                if evaluation is not None:
                    store.delete_record(record_key)
                source, capsule = _checkpoint_source_for_evaluation(
                    paths, store, run.run_id, checkpoint, execution.checkpoint_catalog
                )
                job_root = (root / job.relative_directory).resolve()
                config_path = (root / job.config_relative_path).resolve()
                checkpoint_model_cache = paths.runs / run.run_id / "checkpoint-model-cache"
                training_replay_artifact = bundle.replay_plan.monitor_artifact
                training_replay_path = (
                    None
                    if training_replay_artifact is None
                    else _resolve_data8_runtime_member(bundle, root, training_replay_artifact.path)
                )
                prepared = mdstats.prepare_mace_checkpoint_evaluation(
                    run,
                    checkpoint,
                    candidate_model_path=source,
                    evaluation_state_capsule=capsule,
                    target_monitor_path=target_full_path,
                    target_monitor_artifact=target_full_artifact,
                    policy=eval_policy,
                    replay_monitor_path=replay_full_path,
                    replay_monitor_artifact=replay_full_artifact,
                    training_replay_monitor_artifact=(
                        training_replay_artifact
                        if run.replay_monitor_artifact_digest is not None
                        else None
                    ),
                    training_replay_monitor_path=(
                        training_replay_path
                        if run.replay_monitor_artifact_digest is not None
                        else None
                    ),
                    replay_baseline_model_path=baseline_model,
                    prediction_cache_directory=prediction_cache_directory,
                    graph_cache_directory=graph_cache_directory,
                    allow_target_monitor_override=True,
                    allow_replay_without_training_lineage=(
                        run.replay_monitor_artifact_digest is None
                    ),
                )
                calculator_model = None
                try:
                    if prepared.requires_candidate_inference:
                        calculator_model = mdstats.materialize_mace_checkpoint_model(
                            checkpoint,
                            source,
                            mace_config_path=config_path,
                            job_working_directory=job_root,
                            cache_directory=checkpoint_model_cache,
                            wrapper_path=local_wrappers["mdstats-mace-train"],
                            allow_checkpoint_dtype_template_cast=False,
                            evaluation_state_capsule=capsule,
                        )
                    predictions = mdstats.run_prepared_mace_checkpoint_inference(
                        prepared, calculator_model_path=calculator_model
                    )
                    evaluation = mdstats.finalize_prepared_mace_checkpoint_evaluation(
                        prepared, predictions
                    )
                finally:
                    if (
                        calculator_model is not None
                        and Path(calculator_model).resolve() != Path(source).resolve()
                    ):
                        mdstats.remove_materialized_mace_checkpoint_model(calculator_model)
                store.put_record(record_key, evaluation)
                _ok(
                    f"{run.run_id} epoch {checkpoint.epoch}: full target="
                    f"{evaluation.target_candidate_metrics.force_component_rmse_ev_per_angstrom*1000:.2f} meV/A; "
                    f"R_full={evaluation.replay_candidate_metrics.force_component_rmse_ev_per_angstrom*1000:.2f} meV/A"
                )
            else:
                _ok(f"{run.run_id} epoch {checkpoint.epoch}: reused authenticated SELECT1 full evaluation")
            evaluations.append(evaluation)

        selection = mdstats.select_mlcv_run_representative(
            run,
            ranking,
            tuple(evaluations),
            selection_policy,
            metric_policy,
            target_full_role=target_role,
            target_full_artifact_digest=target_full_artifact.content_digest,
            target_full_sha256=target_full_artifact.sha256,
            replay_full_artifact_digest=replay_full_artifact.content_digest,
            replay_full_sha256=replay_full_artifact.sha256,
        )
        record_key = f"mlcv_run_selection:{run.run_id}"
        existing = store.get_record_optional(record_key, mdstats.MlcvRunSelectionRecord)
        if existing is not None and existing.content_digest != selection.content_digest:
            raise CampaignCliError(
                f"{run.run_id}: existing immutable MLCV-SELECT1 record disagrees with current evidence."
            )
        store.put_record(record_key, selection)
        selections.append(selection)
        if selection.outcome == "representative_selected":
            representative = selection.representative_candidate
            assert representative is not None
            _ok(
                f"{run.run_id}: representative epoch {representative.checkpoint_epoch}; "
                f"full score={representative.full_score_ev_per_angstrom*1000:.2f} meV/A "
                f"(target={representative.target_force_rmse_ev_per_angstrom*1000:.2f}, "
                f"replay={representative.replay_force_rmse_ev_per_angstrom*1000:.2f})"
            )
        else:
            _warn(f"{run.run_id}: no retained checkpoint survives full SELECT1 gates")

    aggregate = {
        "schema": "mdstats.mlcv-select1-summary.v1",
        "campaign_plan_digest": campaign.content_digest,
        "full_evaluation": bool(full_evaluation),
        "run_selection_count": len(selections),
        "representative_count": sum(v.outcome == "representative_selected" for v in selections),
        "no_representative_count": sum(v.outcome == "no_representative" for v in selections),
        "run_selections": [v.to_dict() for v in selections],
        "production_freeze_created": False,
        "next_gate": "MLCV-AGG1",
        "model_inference_dtype": model_dtype,
        "scientific_analysis_dtype": "float64",
    }
    aggregate["content_digest"] = digest({k: v for k, v in aggregate.items() if k != "content_digest"})
    output_name = "mlcv-select1.json" if full_evaluation else "interim-mlcv-select1.json"
    _atomic_json(paths.results / output_name, aggregate)
    if full_evaluation:
        return _command_evaluate_mlcv_agg1(
            cfg=cfg,
            paths=paths,
            store=store,
            campaign=campaign,
            jobs=jobs,
            execution_records=execution_records,
            selections=tuple(selections),
            model_dtype=model_dtype,
        )
    _mark_stage(
        store,
        paths,
        "evaluate",
        StageState.WAITING,
        f"interim MLCV-SELECT1 froze {aggregate['representative_count']}/{len(selections)} run representative(s); AGG1 waits for full campaign completion",
    )
    return 0


def _command_evaluate_adaptive_topk(
    args: argparse.Namespace,
    *,
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    campaign: Any,
    jobs: Mapping[str, tuple[Any, Any, Path]],
    execution_records: Mapping[str, Any],
    runs_to_evaluate: Sequence[Any],
    full_evaluation: bool,
    model_dtype: str,
    precision_profile: Mapping[str, Any],
) -> int:
    """ADAPT-EVAL1: zero-partial-round top-K full evaluation of run champions."""
    import mdstats

    if not runs_to_evaluate:
        raise CampaignCliError("ADAPT-EVAL1 has no completed runs to evaluate.")
    metric_policy = _checkpoint_metric_policy(cfg)
    champion_records: dict[str, Any] = {}
    stop_policies: list[Any] = []
    for run in runs_to_evaluate:
        execution = execution_records[run.content_digest]
        bundle, job, _root = jobs[run.mace_job_artifact_digest]
        run_root = paths.runs / run.run_id
        state = _load_adaptive_stop_state(run_root, job, require_terminal=True)
        champion = _reconcile_lightweight_run_champion(
            run, job, run_root, state, execution.checkpoint_catalog
        )
        if champion is not None:
            champion_records[run.content_digest] = champion
        if job.protocol.adaptive_stop_policy is not None:
            stop_policies.append(job.protocol.adaptive_stop_policy)
    if not stop_policies:
        raise CampaignCliError(
            "ADAPT-EVAL1 requires ADAPT-STOP1/RANK1 evidence; use a historical "
            "checkpoint_strategy for pre-adaptive campaigns."
        )
    reference_stop = stop_policies[0]
    geometry = (
        float(reference_stop.maximum_target_force_rmse_ev_per_angstrom),
        float(reference_stop.target_score_weight),
        float(reference_stop.replay_score_weight),
    )
    for policy in stop_policies[1:]:
        observed = (
            float(policy.maximum_target_force_rmse_ev_per_angstrom),
            float(policy.target_score_weight),
            float(policy.replay_score_weight),
        )
        if observed != geometry:
            raise CampaignCliError(
                "ADAPT-EVAL1 cannot compare run champions with different target/replay "
                "score geometry."
            )
    full_policy = _adaptive_full_evaluation_policy(cfg, reference_stop, metric_policy)
    queue = mdstats.build_campaign_finalist_queue(campaign, champion_records, full_policy)
    if not queue.candidates:
        raise CampaignCliError(
            "No completed run has a lightweight-admissible champion; full evaluation has nothing to purchase."
        )
    queue_key = "campaign_finalist_queue" if full_evaluation else "interim_campaign_finalist_queue"
    existing_queue = store.get_record_optional(queue_key, mdstats.CampaignFinalistQueueRecord)
    if existing_queue is not None and existing_queue.content_digest != queue.content_digest:
        if full_evaluation:
            raise CampaignCliError(
                "Existing campaign finalist queue disagrees with current immutable RANK1 evidence."
            )
        store.delete_record(queue_key)
    store.put_record(queue_key, queue)

    # Every adaptive DATA8 bundle must expose the same full outer-monitor target domain.
    full_target_artifacts = []
    for run in runs_to_evaluate:
        bundle, _job, root = jobs[run.mace_job_artifact_digest]
        artifact = getattr(bundle, "full_target_evaluation_artifact", None)
        if artifact is None:
            raise CampaignCliError(
                f"{run.run_id}: DATA8 bundle predates ADAPT-EVAL1 full-target materialization. "
                "Re-run prepare for a new adaptive campaign or use a historical evaluator for old evidence."
            )
        full_target_artifacts.append((artifact, root))
    full_target_artifact, full_target_root = full_target_artifacts[0]
    for artifact, _root in full_target_artifacts[1:]:
        if (
            artifact.content_digest != full_target_artifact.content_digest
            or artifact.sha256 != full_target_artifact.sha256
            or artifact.frame_uids != full_target_artifact.frame_uids
        ):
            raise CampaignCliError(
                "ADAPT-EVAL1 requires one identical common full target domain across all finalists."
            )
    full_target_path = _resolve_data8_runtime_member(
        jobs[runs_to_evaluate[0].mace_job_artifact_digest][0],
        full_target_root,
        full_target_artifact.relative_path,
    )
    if not full_target_path.is_file() or _sha256(full_target_path) != full_target_artifact.sha256:
        raise CampaignCliError("Common full target evaluation artifact is missing or stale.")

    true_replay = _resolve_true_label_replay_inputs(cfg, paths, require_train=False)
    if true_replay is None:
        raise CampaignCliError(
            "ADAPT-EVAL1 requires independent true replay labels; new campaigns derive them from [paths].replay_set and legacy campaigns use [paths].replay_true_labels."
        )
    full_replay_artifact = true_replay.monitor_artifact
    full_replay_path = Path(true_replay.monitor_path)
    if not full_replay_path.is_file() or _sha256(full_replay_path) != full_replay_artifact.sha256:
        raise CampaignCliError("Common full true-replay artifact is missing or stale.")

    baseline_model = _path_cfg(cfg, paths, "foundation_model")
    assert baseline_model is not None
    prediction_cache_directory = paths.internal / "evaluation-predictions"
    graph_cache_directory = paths.internal / "evaluation-graphs"
    local_wrappers = _ensure_local_wrappers(paths)
    acceleration = _acceleration_policy(cfg)
    critical_precision = _critical_precision_policy(cfg)
    evaluated: list[Any] = []
    completed_batches = 0

    # Purchase only one deterministic batch at a time. Prediction artifacts are
    # persistent, so interruption between candidates or batches is restart-safe.
    max_batch = max(item.batch_index for item in queue.candidates)
    for batch_index in range(1, max_batch + 1):
        batch = tuple(item for item in queue.candidates if item.batch_index == batch_index)
        if not batch:
            continue
        completed_batches = batch_index
        _print_header(
            f"ADAPT-EVAL1 full finalist batch {batch_index} ({len(batch)} candidate(s))"
        )
        for finalist in batch:
            run = next(v for v in campaign.runs if v.content_digest == finalist.run_plan_digest)
            execution = execution_records[run.content_digest]
            bundle, job, root = jobs[run.mace_job_artifact_digest]
            catalog = _evaluation_checkpoint_catalog(store, run.run_id, execution)
            checkpoint = next(
                (
                    value
                    for value in catalog.checkpoints
                    if value.sha256 == finalist.checkpoint_sha256
                    and value.epoch == finalist.checkpoint_epoch
                ),
                None,
            )
            if checkpoint is None:
                raise CampaignCliError(
                    f"{run.run_id}: RANK1 champion checkpoint is absent from the frozen catalog."
                )
            candidate_head = (
                job.protocol.adaptive_stop_policy.replay_head_name
                if run.training_mode is mdstats.TrainingMode.MULTIHEAD_REPLAY
                else job.protocol.adaptive_stop_policy.target_head_name
            )
            eval_policy = mdstats.CheckpointEvaluationPolicy(
                target_head_name=job.protocol.adaptive_stop_policy.target_head_name,
                replay_head_name=candidate_head,
                focus_atomic_numbers=tuple(
                    int(v) for v in _cfg(cfg, "profile", "mobile_atomic_numbers", (3, 11, 19))
                ),
                device=str(_cfg(cfg, "evaluation", "device", _cfg(cfg, "training", "device", "cuda"))),
                default_dtype=model_dtype,
                batch_size=int(_cfg(cfg, "evaluation", "batch_size", 8)),
                cache_monitor_datasets=bool(_cfg(cfg, "evaluation", "cache_monitor_datasets", True)),
                cache_replay_baseline=bool(_cfg(cfg, "evaluation", "cache_replay_baseline", True)),
                evaluate_foundation_on_target=False,
                acceleration_policy=acceleration,
                **_evaluation_foundation_binding(cfg, paths),
                critical_precision_policy=critical_precision,
            )
            record_key = f"adaptive_full_evaluation:{run.run_id}:{checkpoint.sha256}"
            evaluation = store.get_record_optional(record_key, mdstats.CheckpointEvaluationRecord)
            reusable = bool(
                evaluation is not None
                and evaluation.run_plan_digest == run.content_digest
                and evaluation.checkpoint_sha256 == checkpoint.sha256
                and evaluation.evaluation_policy_digest == eval_policy.policy_digest
                and evaluation.target_monitor_artifact_digest == full_target_artifact.content_digest
                and evaluation.target_monitor_sha256 == full_target_artifact.sha256
                and evaluation.replay_monitor_artifact_digest == full_replay_artifact.content_digest
                and evaluation.replay_monitor_sha256 == full_replay_artifact.sha256
                and evaluation.target_candidate_metrics is not None
                and evaluation.replay_candidate_metrics is not None
                and evaluation.replay_foundation_metrics is not None
            )
            if not reusable:
                if evaluation is not None:
                    store.delete_record(record_key)
                source, capsule = _checkpoint_source_for_evaluation(
                    paths, store, run.run_id, checkpoint, execution.checkpoint_catalog
                )
                job_root = (root / job.relative_directory).resolve()
                config_path = (root / job.config_relative_path).resolve()
                checkpoint_model_cache = paths.runs / run.run_id / "checkpoint-model-cache"
                # For replay-trained runs preserve the old pseudo-monitor lineage
                # solely so foundation pseudolabel reuse remains possible; the
                # authoritative evaluation labels are always the full TRUE_DFT set.
                training_replay_artifact = bundle.replay_plan.monitor_artifact
                training_replay_path = (
                    None
                    if training_replay_artifact is None
                    else _resolve_data8_runtime_member(bundle, root, training_replay_artifact.path)
                )
                prepared = mdstats.prepare_mace_checkpoint_evaluation(
                    run,
                    checkpoint,
                    candidate_model_path=source,
                    evaluation_state_capsule=capsule,
                    target_monitor_path=full_target_path,
                    target_monitor_artifact=full_target_artifact,
                    policy=eval_policy,
                    replay_monitor_path=full_replay_path,
                    replay_monitor_artifact=full_replay_artifact,
                    training_replay_monitor_artifact=(
                        training_replay_artifact
                        if run.replay_monitor_artifact_digest is not None
                        else None
                    ),
                    training_replay_monitor_path=(
                        training_replay_path
                        if run.replay_monitor_artifact_digest is not None
                        else None
                    ),
                    replay_baseline_model_path=baseline_model,
                    prediction_cache_directory=prediction_cache_directory,
                    graph_cache_directory=graph_cache_directory,
                    allow_target_monitor_override=True,
                    allow_replay_without_training_lineage=(
                        run.replay_monitor_artifact_digest is None
                    ),
                )
                calculator_model = None
                try:
                    if prepared.requires_candidate_inference:
                        calculator_model = mdstats.materialize_mace_checkpoint_model(
                            checkpoint,
                            source,
                            mace_config_path=config_path,
                            job_working_directory=job_root,
                            cache_directory=checkpoint_model_cache,
                            wrapper_path=local_wrappers["mdstats-mace-train"],
                            allow_checkpoint_dtype_template_cast=False,
                            evaluation_state_capsule=capsule,
                        )
                    predictions = mdstats.run_prepared_mace_checkpoint_inference(
                        prepared, calculator_model_path=calculator_model
                    )
                    evaluation = mdstats.finalize_prepared_mace_checkpoint_evaluation(
                        prepared, predictions
                    )
                finally:
                    # Materialized caches remain persistent only when they are the
                    # exact checkpoint source; temporary reconstructions are safe
                    # to remove because predictions are now authenticated/cacheable.
                    if calculator_model is not None and Path(calculator_model).resolve() != Path(source).resolve():
                        mdstats.remove_materialized_mace_checkpoint_model(calculator_model)
                store.put_record(record_key, evaluation)
                _ok(
                    f"{run.run_id} epoch {checkpoint.epoch}: full target="
                    f"{evaluation.target_candidate_metrics.force_component_rmse_ev_per_angstrom*1000:.2f} meV/A; "
                    f"true replay={evaluation.replay_candidate_metrics.force_component_rmse_ev_per_angstrom*1000:.2f} meV/A"
                )
            else:
                _ok(f"{run.run_id} epoch {checkpoint.epoch}: reused authenticated full evaluation")
            candidate_record = mdstats.assess_full_evaluation_candidate(
                finalist, evaluation, full_policy, metric_policy
            )
            store.put_record(
                f"adaptive_full_candidate:{run.run_id}:{checkpoint.sha256}",
                candidate_record,
            )
            evaluated.append(candidate_record)
        # Rescue is authorized only if all purchased candidates remain rejected.
        if any(item.admissible for item in evaluated):
            break

    outcome = (
        "admissible_candidates_available"
        if any(item.admissible for item in evaluated)
        else "no_admissible_candidate"
    )
    result = mdstats.AdaptiveFullEvaluationRecord(
        campaign_plan_digest=campaign.content_digest,
        policy_digest=full_policy.policy_digest,
        finalist_queue_digest=queue.content_digest,
        full_target_artifact_digest=full_target_artifact.content_digest,
        full_replay_artifact_digest=full_replay_artifact.content_digest,
        evaluated_candidates=tuple(evaluated),
        completed_batch_count=completed_batches,
        outcome=outcome,
    )
    result_key = "adaptive_full_evaluation" if full_evaluation else "interim_adaptive_full_evaluation"
    existing_result = store.get_record_optional(result_key, mdstats.AdaptiveFullEvaluationRecord)
    if existing_result is not None and existing_result.content_digest != result.content_digest:
        # Completed predictions are reusable, but the aggregate evidence must be
        # regenerated exactly from the current immutable queue/policy.
        store.delete_record(result_key)
    store.put_record(result_key, result)
    summary = result.to_dict()
    summary["finalist_queue"] = queue.to_dict()
    summary["model_inference_dtype"] = model_dtype
    summary["scientific_analysis_dtype"] = "float64"
    summary["production_freeze_created"] = False
    output_name = (
        "adaptive-full-evaluation.json"
        if full_evaluation
        else "interim-adaptive-full-evaluation.json"
    )
    _atomic_json(paths.results / output_name, summary)
    if outcome == "no_admissible_candidate":
        _mark_stage(
            store, paths, "evaluate", StageState.WAITING,
            "ADAPT-EVAL1 exhausted the run-champion queue without an admissible full-evaluation candidate",
        )
        raise CampaignCliError(
            "ADAPT-EVAL1 completed all authorized full evaluations, but no candidate "
            "satisfies the full target/replay and retained safety gates."
        )
    best = result.admissible_candidates[0]
    _ok(
        f"ADAPT-EVAL1 best fully admissible candidate so far: {best.run_id} epoch "
        f"{best.checkpoint_epoch}; score={best.full_score_ev_per_angstrom*1000:.2f} meV/A"
    )
    if full_evaluation:
        _mark_stage(
            store, paths, "evaluate", StageState.COMPLETE,
            f"ADAPT-EVAL1 completed {len(evaluated)} full evaluation(s) through batch {completed_batches}; ready for ADAPT-VERIFY1",
        )
    else:
        _mark_stage(
            store, paths, "evaluate", StageState.WAITING,
            f"interim ADAPT-EVAL1 completed {len(evaluated)} full evaluation(s); campaign training incomplete",
        )
    return 0



def _train2_policy_set_digest(protocol: Any) -> str:
    """Digest the four orthogonal TRAIN2 authorities without run/size identity."""

    policies = (
        protocol.training_budget_policy,
        protocol.learning_rate_schedule_policy,
        protocol.checkpoint_admissibility_policy,
        protocol.checkpoint_selection_policy,
    )
    if any(value is None for value in policies):
        raise CampaignCliError("EVAL2 requires the complete TRAIN2 policy set.")
    return digest({
        "schema": "mdstats.train2-policy-set-authority.v1",
        "training_budget_policy_digest": protocol.training_budget_policy.policy_digest,
        "learning_rate_schedule_policy_digest": protocol.learning_rate_schedule_policy.policy_digest,
        "checkpoint_admissibility_policy_digest": protocol.checkpoint_admissibility_policy.policy_digest,
        "checkpoint_selection_policy_digest": protocol.checkpoint_selection_policy.policy_digest,
    })


def _eval2_label_domain_id(bundle: Any, role_freeze: Any) -> str:
    catalog = getattr(bundle, "mlcv_role_catalog", None)
    if catalog is not None and str(getattr(catalog, "label_domain_id", "")).strip():
        return str(catalog.label_domain_id)
    # Compatibility fallback: CV evaluation artifacts partition the entire
    # TARGET-DATA2A development domain exactly once.
    observed = {uid for artifact in bundle.fold_evaluation_artifacts for uid in artifact.frame_uids}
    matches = [
        domain.label_domain_id
        for domain in role_freeze.domains
        if observed and observed == set(domain.size_development_frame_uids)
    ]
    if len(matches) != 1:
        raise CampaignCliError("EVAL2 cannot resolve this DATA8 bundle to one TARGET-DATA2A label domain.")
    return matches[0]


def _eval2_target_role_for_run(
    *,
    store: CampaignStore,
    convergence: Any,
    role_freeze: Any,
    ladder: Any,
    bundle: Any,
    run: Any,
    coarse: bool = False,
    coarse_maximum_configurations: int = 256,
) -> Any:
    import mdstats

    label_domain_id = _eval2_label_domain_id(bundle, role_freeze)
    if run.kind is mdstats.MaceJobKind.CROSS_VALIDATION_FOLD:
        role = mdstats.build_eval2_cv_target_role(
            role_freeze,
            label_domain_id=label_domain_id,
            fold_index=int(run.fold_index),
        )
    else:
        if convergence.outcome in {"awaiting_stage_b0_coarse_training", "awaiting_stage_b1_short_training", "awaiting_stage_c_full_training"}:
            maximum_training_size = max(int(v) for v in convergence.stage_a_survivor_sizes)
        elif convergence.selected_target_size is not None:
            maximum_training_size = int(convergence.selected_target_size)
        else:
            raise CampaignCliError(
                "EVAL2 final-development checkpoint ranking has no leakage-safe target-role boundary."
            )
        if coarse:
            role = mdstats.build_eval2_coarse_size_study_target_role(
                role_freeze,
                ladder,
                label_domain_id=label_domain_id,
                maximum_training_size=maximum_training_size,
                maximum_configurations=int(coarse_maximum_configurations),
            )
        else:
            role = mdstats.build_eval2_size_study_target_role(
                role_freeze,
                ladder,
                label_domain_id=label_domain_id,
                maximum_training_size=maximum_training_size,
            )
    key = f"eval2_target_role:{role.content_digest}"
    existing = store.get_record_optional(key, mdstats.Eval2TargetRole)
    if existing is not None and existing.content_digest != role.content_digest:
        store.delete_record(key)
    store.put_record(key, role)
    return role


def _eval2_resolve_existing_cv_artifact(bundle: Any, job: Any, root: Path, role: Any) -> tuple[Any, Path] | None:
    """Resolve the full CV checkpoint-monitor artifact matching a frozen EVAL2 role."""

    expected = tuple(role.evaluation_frame_uids)
    candidates = [
        artifact
        for artifact in bundle.target_artifacts
        if artifact.role in {"target_checkpoint_full", "target_checkpoint_selection", "target_checkpoint_monitor"}
        and tuple(artifact.frame_uids) == expected
    ]
    if not candidates:
        return None
    # Artifacts are job-local. Prefer one whose path exists under this job root.
    job_root = (Path(root) / job.relative_directory).resolve()
    for artifact in candidates:
        path = (job_root / artifact.relative_path).resolve()
        if path.is_file() and _sha256(path) == artifact.sha256:
            return artifact, path
    return None


def _eval2_materialize_development_target_artifact(
    *,
    paths: CampaignPaths,
    store: CampaignStore,
    bundle: Any,
    root: Path,
    role: Any,
) -> tuple[Any, Path]:
    """Materialize a leakage-safe development-only target role from CV artifacts."""

    import mdstats
    try:
        from ase.io import read, write
    except Exception as exc:  # pragma: no cover - ASE is a package dependency
        raise CampaignCliError(f"EVAL2 target-role materialization requires ASE: {exc}") from exc

    role_root = (paths.internal / "eval2-target-roles" / role.content_digest).resolve()
    target_path = role_root / "target.xyz"
    sidecar_path = role_root / "target.role.json"
    role_root.mkdir(parents=True, exist_ok=True)
    artifact_key = f"eval2_target_artifact:{role.content_digest}"
    cached = store.get_record_optional(artifact_key, mdstats.MaceExtxyzArtifact)
    if cached is not None:
        if (
            cached.frame_uids == tuple(role.evaluation_frame_uids)
            and target_path.is_file()
            and _sha256(target_path) == cached.sha256
            and sidecar_path.is_file()
            and _sha256(sidecar_path) == cached.sidecar_sha256
        ):
            return cached, target_path
        store.delete_record(artifact_key)

    artifact_by_digest = {artifact.content_digest: artifact for artifact in bundle.fold_evaluation_artifacts}
    frame_atoms: dict[str, Any] = {}
    source_artifact_digests: list[str] = []
    for fold_job in bundle.jobs:
        digest_id = fold_job.fold_evaluation_artifact_digest
        if digest_id is None:
            continue
        artifact = artifact_by_digest.get(digest_id)
        if artifact is None:
            raise CampaignCliError("EVAL2 DATA8 fold-evaluation artifact lineage is incomplete.")
        source_path = (Path(root) / fold_job.relative_directory / artifact.relative_path).resolve()
        if not source_path.is_file() or _sha256(source_path) != artifact.sha256:
            raise CampaignCliError("EVAL2 DATA8 fold-evaluation bytes changed after preparation.")
        atoms_values = read(source_path, index=":", format="extxyz")
        if not isinstance(atoms_values, list):
            atoms_values = [atoms_values]
        if len(atoms_values) != artifact.configuration_count:
            raise CampaignCliError("EVAL2 fold-evaluation configuration count changed.")
        for frame_uid, atoms in zip(artifact.frame_uids, atoms_values):
            if frame_uid in frame_atoms:
                raise CampaignCliError("EVAL2 CV evaluation artifacts overlap in frame membership.")
            frame_atoms[frame_uid] = atoms
        source_artifact_digests.append(artifact.content_digest)

    missing = [uid for uid in role.evaluation_frame_uids if uid not in frame_atoms]
    if missing:
        raise CampaignCliError(
            f"EVAL2 leakage-safe development role is not reconstructable from DATA8 CV evidence; missing {len(missing)} frame(s)."
        )
    selected_atoms = [frame_atoms[uid] for uid in role.evaluation_frame_uids]
    write(target_path, selected_atoms, format="extxyz")
    sidecar_payload = {
        "schema": "mdstats.eval2-target-role-materialization.v1",
        "target_role": role.to_dict(),
        "source_artifact_digests": sorted(source_artifact_digests),
    }
    sidecar_path.write_text(json.dumps(sidecar_payload, sort_keys=True, separators=(",", ":")) + "\n", encoding="utf-8")
    atomic_numbers = tuple(sorted({int(z) for atoms in selected_atoms for z in atoms.numbers}))
    artifact = mdstats.MaceExtxyzArtifact(
        role="eval2_size_development_complement",
        relative_path=target_path.name,
        sha256=_sha256(target_path),
        configuration_count=len(selected_atoms),
        frame_uids=tuple(role.evaluation_frame_uids),
        atomic_numbers=atomic_numbers,
        policy_digest=digest({
            "schema": "mdstats.eval2-target-role-materialization-policy.v1",
            "target_role_digest": role.content_digest,
            "source_artifact_digests": sorted(source_artifact_digests),
        }),
        sidecar_relative_path=sidecar_path.name,
        sidecar_sha256=_sha256(sidecar_path),
        sidecar_digest=role.content_digest,
    )
    store.put_record(artifact_key, artifact)
    return artifact, target_path


def _eval2_target_artifact_for_run(
    *,
    paths: CampaignPaths,
    store: CampaignStore,
    bundle: Any,
    job: Any,
    root: Path,
    role: Any,
) -> tuple[Any, Path]:
    if role.role_kind == "cv_checkpoint_monitor":
        resolved = _eval2_resolve_existing_cv_artifact(bundle, job, root, role)
        if resolved is None:
            raise CampaignCliError(
                f"EVAL2 CV role for {job.job_id} does not match a frozen full checkpoint-monitor artifact."
            )
        return resolved
    return _eval2_materialize_development_target_artifact(
        paths=paths, store=store, bundle=bundle, root=root, role=role
    )


def _eval2_evaluation_policy(cfg: Mapping[str, Any], paths: CampaignPaths, job: Any, *, model_dtype: str) -> Any:
    import mdstats

    control = job.protocol.checkpoint_control_policy
    return mdstats.CheckpointEvaluationPolicy(
        target_head_name=control.target_head_name,
        replay_head_name=control.replay_head_name,
        focus_atomic_numbers=tuple(int(v) for v in _cfg(cfg, "profile", "mobile_atomic_numbers", (3, 11, 19))),
        device=str(_cfg(cfg, "evaluation", "device", _cfg(cfg, "training", "device", "cuda"))),
        default_dtype=model_dtype,
        batch_size=int(_cfg(cfg, "evaluation", "batch_size", 8)),
        cache_monitor_datasets=bool(_cfg(cfg, "evaluation", "cache_monitor_datasets", True)),
        cache_replay_baseline=bool(_cfg(cfg, "evaluation", "cache_replay_baseline", True)),
        evaluate_foundation_on_target=False,
        acceleration_policy=_acceleration_policy(cfg),
        **_evaluation_foundation_binding(cfg, paths),
        critical_precision_policy=_critical_precision_policy(cfg),
    )


def _eval2_full_checkpoint(
    *,
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    run: Any,
    job: Any,
    bundle: Any,
    root: Path,
    execution: Any,
    checkpoint: Any,
    point: Any,
    target_role: Any,
    target_artifact: Any,
    target_path: Path,
    true_replay_resolution: Any | None,
    baseline_model: Path | None,
    model_dtype: str,
    local_wrappers: Mapping[str, Path],
    shortlist_reasons: Sequence[str] = (),
    full_evaluation_rank: int = 0,
    include_replay: bool = True,
) -> Any:
    """Run/reuse one full EVAL2 candidate and reduce detailed target evidence."""

    import mdstats

    admissibility = job.protocol.checkpoint_admissibility_policy
    if admissibility is None:
        raise CampaignCliError("EVAL2 checkpoint is missing TRAIN2 admissibility authority.")
    evaluation_policy = _eval2_evaluation_policy(cfg, paths, job, model_dtype=model_dtype)
    training_replay_artifact = bundle.replay_plan.monitor_artifact
    training_replay_path = None
    replay_artifact = None
    replay_path = None
    replay_requested = bool(admissibility.replay_enabled and include_replay)
    if replay_requested:
        if true_replay_resolution is None:
            raise CampaignCliError("EVAL2 replay-enabled TRAIN2 requires an authenticated TRUE_DFT replay monitor.")
        if training_replay_artifact is None:
            raise CampaignCliError("EVAL2 replay-enabled run lacks DATA8 replay lineage.")
        replay_artifact = true_replay_resolution.monitor_artifact
        replay_path = Path(true_replay_resolution.monitor_path).resolve()
        training_replay_path = _resolve_data8_runtime_member(bundle, root, training_replay_artifact.path)
        if (
            replay_artifact.configuration_count != training_replay_artifact.configuration_count
            or replay_artifact.geometry_identities != training_replay_artifact.geometry_identities
        ):
            raise CampaignCliError("EVAL2 TRUE_DFT replay geometry/order differs from the frozen training replay monitor.")
        if baseline_model is None:
            raise CampaignCliError("EVAL2 replay retention requires the foundation model bytes.")

    replay_mode_key = "full" if replay_requested else "target-only"
    eval_key = f"eval2_evaluation:{replay_mode_key}:{run.run_id}:{target_role.content_digest}:{checkpoint.sha256}"
    metric_key = f"eval2_target_metric:{replay_mode_key}:{run.run_id}:{target_role.content_digest}:{checkpoint.sha256}"
    cached_eval = store.get_record_optional(eval_key, mdstats.CheckpointEvaluationRecord)
    cached_metric = store.get_record_optional(metric_key, mdstats.Eval2TargetMetricRecord)
    reusable = bool(
        cached_eval is not None
        and cached_metric is not None
        and cached_eval.run_plan_digest == run.content_digest
        and cached_eval.checkpoint_sha256 == checkpoint.sha256
        and cached_eval.evaluation_policy_digest == evaluation_policy.policy_digest
        and cached_eval.target_monitor_artifact_digest == target_artifact.content_digest
        and cached_eval.target_monitor_sha256 == target_artifact.sha256
        and cached_metric.target_role_digest == target_role.content_digest
        and cached_eval.target_candidate_prediction_digest == cached_metric.prediction_digest
        and cached_eval.replay_monitor_artifact_digest == (None if replay_artifact is None else replay_artifact.content_digest)
        and cached_eval.replay_monitor_sha256 == (None if replay_artifact is None else replay_artifact.sha256)
    )
    if not reusable:
        if cached_eval is not None:
            store.delete_record(eval_key)
        if cached_metric is not None:
            store.delete_record(metric_key)
        source, capsule = _checkpoint_source_for_evaluation(
            paths, store, run.run_id, checkpoint, execution.checkpoint_catalog
        )
        job_root = (Path(root) / job.relative_directory).resolve()
        config_path = (Path(root) / job.config_relative_path).resolve()
        checkpoint_model_cache = paths.runs / run.run_id / "checkpoint-model-cache"
        prepared = mdstats.prepare_mace_checkpoint_evaluation(
            run,
            checkpoint,
            candidate_model_path=source,
            evaluation_state_capsule=capsule,
            target_monitor_path=target_path,
            target_monitor_artifact=target_artifact,
            policy=evaluation_policy,
            replay_monitor_path=replay_path,
            replay_monitor_artifact=replay_artifact,
            training_replay_monitor_artifact=training_replay_artifact if replay_requested else None,
            training_replay_monitor_path=training_replay_path,
            replay_baseline_model_path=baseline_model if replay_requested else None,
            prediction_cache_directory=paths.internal / "evaluation-predictions",
            graph_cache_directory=paths.internal / "evaluation-graphs",
            allow_target_monitor_override=(target_artifact.content_digest != run.target_monitor_artifact_digest),
            allow_replay_without_training_lineage=False,
        )
        calculator_model = None
        try:
            if prepared.requires_candidate_inference:
                calculator_model = mdstats.materialize_mace_checkpoint_model(
                    checkpoint,
                    source,
                    mace_config_path=config_path,
                    job_working_directory=job_root,
                    cache_directory=checkpoint_model_cache,
                    wrapper_path=local_wrappers["mdstats-mace-train"],
                    allow_checkpoint_dtype_template_cast=False,
                    evaluation_state_capsule=capsule,
                )
            predictions = mdstats.run_prepared_mace_checkpoint_inference(
                prepared, calculator_model_path=calculator_model
            )
            cached_eval = mdstats.finalize_prepared_mace_checkpoint_evaluation(prepared, predictions)
            if replay_artifact is not None:
                cached_eval = mdstats.bind_checkpoint_evaluation_replay_provenance(
                    cached_eval,
                    replay_artifact.label_mode,
                    training_replay_monitor_artifact_digest=run.replay_monitor_artifact_digest,
                )
            prediction_digest = cached_eval.target_candidate_prediction_digest
            if prediction_digest is None:
                raise CampaignCliError("EVAL2 target prediction identity was not persisted.")
            cached_metric = mdstats.eval2_target_metrics_from_prediction_view(
                prepared.target_view,
                predictions.target_candidate_predictions,
                block_ids=target_role.correlation_block_ids,
                target_role_digest=target_role.content_digest,
                prediction_digest=prediction_digest,
            )
        finally:
            if calculator_model is not None and Path(calculator_model).resolve() != Path(source).resolve():
                mdstats.remove_materialized_mace_checkpoint_model(calculator_model)
        store.put_record(eval_key, cached_eval)
        store.put_record(metric_key, cached_metric)

    assert cached_eval is not None and cached_metric is not None
    replay_candidate = None if cached_eval.replay_candidate_metrics is None else cached_eval.replay_candidate_metrics.force_component_rmse_ev_per_angstrom
    replay_foundation = None if cached_eval.replay_foundation_metrics is None else cached_eval.replay_foundation_metrics.force_component_rmse_ev_per_angstrom
    result = mdstats.assess_eval2_checkpoint(
        point,
        evaluation_record_digest=cached_eval.content_digest,
        target_metrics=cached_metric,
        admissibility_policy=admissibility,
        replay_candidate_force_rmse_ev_per_angstrom=replay_candidate,
        replay_foundation_force_rmse_ev_per_angstrom=replay_foundation,
        replay_label_mode=None if replay_artifact is None else replay_artifact.label_mode.value,
        shortlist_reasons=shortlist_reasons,
        full_evaluation_rank=full_evaluation_rank,
    )
    store.put_record(
        f"eval2_checkpoint:{run.run_id}:{target_role.content_digest}:{checkpoint.sha256}", result
    )
    return result


def _eval2_run_record_for_completed_train2_run(
    *,
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    run: Any,
    job: Any,
    bundle: Any,
    root: Path,
    execution: Any,
    convergence: Any,
    role_freeze: Any,
    ladder: Any,
    true_replay_resolution: Any | None,
    baseline_model: Path | None,
    model_dtype: str,
    local_wrappers: Mapping[str, Path],
) -> Any:
    import mdstats

    target_role = _eval2_target_role_for_run(
        store=store, convergence=convergence, role_freeze=role_freeze, ladder=ladder,
        bundle=bundle, run=run,
    )
    target_artifact, target_path = _eval2_target_artifact_for_run(
        paths=paths, store=store, bundle=bundle, job=job, root=root, role=target_role,
    )
    catalog = _evaluation_checkpoint_catalog(store, run.run_id, execution)
    points = mdstats.read_train2_trajectory_points(
        catalog.root_directory,
        checkpoint_catalog=catalog,
        target_head_name=job.protocol.checkpoint_control_policy.target_head_name,
    )
    selection = job.protocol.checkpoint_selection_policy
    admissibility = job.protocol.checkpoint_admissibility_policy
    if selection is None or admissibility is None:
        raise CampaignCliError("EVAL2 run lacks TRAIN2 selection/admissibility authority.")
    rescue_cap = int(_cfg(cfg, "evaluation", "eval2_candidate_rescue_cap", 5))
    if rescue_cap < 0:
        raise CampaignCliError("[evaluation].eval2_candidate_rescue_cap must be nonnegative.")
    plan = mdstats.Eval2EvaluationPlan(
        run_plan_digest=run.content_digest,
        training_protocol_digest=job.protocol.content_digest,
        selection_policy_digest=selection.policy_digest,
        admissibility_policy_digest=admissibility.policy_digest,
        target_role_digest=target_role.content_digest,
        replay_role_digest=(None if true_replay_resolution is None else true_replay_resolution.monitor_artifact.content_digest),
        candidate_rescue_cap=rescue_cap,
        bootstrap_seed_material_digest=digest({
            "schema": "mdstats.eval2-bootstrap-plan-seed.v1",
            "run_plan_digest": run.content_digest,
            "training_protocol_digest": job.protocol.content_digest,
            "target_role_digest": target_role.content_digest,
            "selection_policy_digest": selection.policy_digest,
            "trajectory": [point.checkpoint_sha256 for point in points],
        }),
    )
    record_key = f"eval2_run:{run.run_id}"
    prior = store.get_record_optional(record_key, mdstats.Eval2RunRecord)
    if prior is not None and prior.evaluation_plan.content_digest != plan.content_digest:
        store.delete_record(record_key)
        prior = None
    by_sha = {checkpoint.sha256: checkpoint for checkpoint in catalog.checkpoints}
    evaluated = [] if prior is None else list(prior.evaluated_checkpoints)
    rescue_count = 0 if prior is None else int(prior.rescue_evaluated_count)
    reasons = {item.checkpoint_sha256: values for item, values in mdstats.build_eval2_shortlist(points, selection)}
    while True:
        current = mdstats.build_eval2_run_record(
            evaluation_plan=plan,
            trajectory_points=points,
            evaluated_checkpoints=tuple(evaluated),
            selection_policy=selection,
            rescue_evaluated_count=rescue_count,
        )
        store.put_record(record_key, current)
        if current.outcome != "awaiting_more_evaluations":
            return current
        batch = mdstats.next_eval2_checkpoint_batch(
            None if not evaluated else current,
            trajectory_points=points,
            policy=selection,
            rescue_cap=rescue_cap,
        )
        if not batch:
            return current
        initial_ids = {item.checkpoint_sha256 for item, _ in mdstats.build_eval2_shortlist(points, selection)}
        for point in batch:
            checkpoint = by_sha.get(point.checkpoint_sha256)
            if checkpoint is None:
                raise CampaignCliError("EVAL2 trajectory point disappeared from the frozen checkpoint catalog.")
            is_rescue = point.checkpoint_sha256 not in initial_ids
            if is_rescue:
                rescue_count += 1
            result = _eval2_full_checkpoint(
                cfg=cfg, paths=paths, store=store, run=run, job=job, bundle=bundle, root=root,
                execution=execution, checkpoint=checkpoint, point=point,
                target_role=target_role, target_artifact=target_artifact, target_path=target_path,
                true_replay_resolution=true_replay_resolution, baseline_model=baseline_model,
                model_dtype=model_dtype, local_wrappers=local_wrappers,
                shortlist_reasons=reasons.get(point.checkpoint_sha256, ("target_rank_rescue",)),
                full_evaluation_rank=len(evaluated) + 1,
            )
            evaluated.append(result)



def _eval2_stage_b0_evidence(
    *,
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    campaign: Any,
    jobs: Mapping[str, tuple[Any, Any, Path]],
    execution_records: Mapping[str, Any],
    convergence: Any,
    role_freeze: Any,
    ladder: Any,
    baseline_model: Path | None,
    model_dtype: str,
    local_wrappers: Mapping[str, Path],
) -> tuple[Any, ...]:
    """Evaluate the exact epoch-3 endpoint on one small common target-only role."""

    import mdstats

    evidence: list[Any] = []
    expected_sizes = set(int(v) for v in convergence.stage_a_survivor_sizes)
    screening_seed = int(convergence.policy.screening_optimizer_seed)
    runs = [
        run for run in campaign.runs
        if run.kind is mdstats.MaceJobKind.FINAL_DEVELOPMENT
        and run.seed == screening_seed and run.selection_size in expected_sizes
    ]
    if {run.selection_size for run in runs} != expected_sizes:
        raise CampaignCliError("EVAL2 Stage B0 cannot resolve one final-development screening run for every coverage-qualified rung.")
    for run in sorted(runs, key=lambda value: value.selection_size):
        execution = execution_records.get(run.content_digest)
        if execution is None:
            raise CampaignCliError(f"EVAL2 Stage B0 run {run.run_id} is not durably complete at epoch 3.")
        bundle, job, root = jobs[run.mace_job_artifact_digest]
        runtime = store.get_record_optional(f"train2_runtime:{run.run_id}", mdstats.Train2RuntimeSummary)
        if runtime is None:
            runtime = mdstats.load_train2_runtime_summary(paths.runs / run.run_id / "checkpoints")
        if runtime.completed_epochs != convergence.policy.coarse_training_epochs or runtime.planned_epochs != convergence.policy.final_training_epochs:
            raise CampaignCliError(f"EVAL2 Stage B0 run {run.run_id} is not the exact 3-of-30 boundary.")
        warmup_end = float(job.protocol.learning_rate_schedule_policy.warmup_end_fraction)
        if runtime.normalized_progress <= warmup_end + 1.0e-12:
            raise CampaignCliError(
                f"EVAL2 Stage B0 run {run.run_id} is not past LR warm-up: "
                f"progress={runtime.normalized_progress:.6g}, warmup_end={warmup_end:.6g}."
            )
        target_role = _eval2_target_role_for_run(
            store=store, convergence=convergence, role_freeze=role_freeze, ladder=ladder,
            bundle=bundle, run=run, coarse=True,
            coarse_maximum_configurations=int(convergence.policy.coarse_target_monitor_configurations),
        )
        target_artifact, target_path = _eval2_target_artifact_for_run(
            paths=paths, store=store, bundle=bundle, job=job, root=root, role=target_role,
        )
        catalog = _evaluation_checkpoint_catalog(store, run.run_id, execution)
        points = mdstats.read_train2_trajectory_points(
            catalog.root_directory, checkpoint_catalog=catalog,
            target_head_name=job.protocol.checkpoint_control_policy.target_head_name,
        )
        endpoint_epoch = int(convergence.policy.coarse_training_epochs) - 1
        matches = [point for point in points if point.epoch == endpoint_epoch]
        if len(matches) != 1:
            raise CampaignCliError(f"EVAL2 Stage B0 run {run.run_id} lacks its exact epoch-3 checkpoint.")
        point = matches[0]
        checkpoint = next(value for value in catalog.checkpoints if value.sha256 == point.checkpoint_sha256)
        record = _eval2_full_checkpoint(
            cfg=cfg, paths=paths, store=store, run=run, job=job, bundle=bundle, root=root,
            execution=execution, checkpoint=checkpoint, point=point,
            target_role=target_role, target_artifact=target_artifact, target_path=target_path,
            true_replay_resolution=None, baseline_model=baseline_model,
            model_dtype=model_dtype, local_wrappers=local_wrappers,
            shortlist_reasons=("target_size_stage_b0_exact_endpoint",), full_evaluation_rank=1,
            include_replay=False,
        )
        target_threshold = float(job.protocol.checkpoint_admissibility_policy.maximum_target_force_rmse_ev_per_angstrom)
        target_pass = record.target_metrics.force_component_rmse_ev_per_angstrom <= target_threshold
        wall_time = sum(float(attempt.elapsed_seconds) for attempt in execution.attempts)
        evidence.append(mdstats.TargetSizeTrainingEvidence(
            stage="coarse", target_size=run.selection_size, optimizer_seed=run.seed,
            completed_epochs=runtime.completed_epochs, planned_epochs=runtime.planned_epochs,
            optimizer_update_count=runtime.completed_updates, structures_presented=runtime.structures_presented,
            normalized_schedule_progress=runtime.normalized_progress,
            instantaneous_learning_rate=runtime.instantaneous_learning_rate, wall_time_seconds=wall_time,
            target_force_score_mev_per_a=record.target_metrics.force_component_rmse_ev_per_angstrom * 1000.0,
            numerical_valid=True, target_hard_gates_passed=target_pass,
            foundation_identity_digest=job.protocol.foundation_checkpoint.canonical_content_digest,
            evaluation_role_digest=target_role.content_digest,
            training_policy_digest=_train2_policy_set_digest(job.protocol), training_run_digest=run.content_digest,
            checkpoint_digest=point.checkpoint_sha256,
            schedule_digest=job.protocol.learning_rate_schedule_policy.policy_digest,
            optimizer_state_digest=runtime.optimizer_state_digest, rng_state_digest=runtime.rng_state_digest,
            target_evaluation_digest=record.target_metrics.content_digest,
        ))
    return tuple(evidence)


def _eval2_stage_b_evidence(
    *,
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    campaign: Any,
    jobs: Mapping[str, tuple[Any, Any, Path]],
    execution_records: Mapping[str, Any],
    convergence: Any,
    role_freeze: Any,
    ladder: Any,
    true_replay_resolution: Any | None,
    baseline_model: Path | None,
    model_dtype: str,
    local_wrappers: Mapping[str, Path],
) -> tuple[Any, ...]:
    """Evaluate exact 10-of-30 endpoints; replay is diagnostic only."""

    import mdstats

    evidence: list[Any] = []
    expected_sizes = set(int(v) for v in convergence.stage_b_survivor_sizes)
    screening_seed = int(convergence.policy.screening_optimizer_seed)
    runs = [
        run for run in campaign.runs
        if run.kind is mdstats.MaceJobKind.FINAL_DEVELOPMENT
        and run.seed == screening_seed and run.selection_size in expected_sizes
    ]
    if {run.selection_size for run in runs} != expected_sizes:
        raise CampaignCliError("EVAL2 Stage B cannot resolve one final-development screening run for every epoch-3 survivor.")
    coarse_by_size = {item.target_size: item for item in convergence.coarse_training_evidence}
    for run in sorted(runs, key=lambda value: value.selection_size):
        execution = execution_records.get(run.content_digest)
        if execution is None:
            raise CampaignCliError(f"EVAL2 Stage B run {run.run_id} is not durably complete at epoch 10.")
        bundle, job, root = jobs[run.mace_job_artifact_digest]
        runtime = store.get_record_optional(f"train2_runtime:{run.run_id}", mdstats.Train2RuntimeSummary)
        if runtime is None:
            runtime = mdstats.load_train2_runtime_summary(paths.runs / run.run_id / "checkpoints")
        if runtime.completed_epochs != convergence.policy.short_training_epochs or runtime.planned_epochs != convergence.policy.final_training_epochs:
            raise CampaignCliError(f"EVAL2 Stage B run {run.run_id} is not the exact 10-of-30 boundary.")
        target_role = _eval2_target_role_for_run(
            store=store, convergence=convergence, role_freeze=role_freeze, ladder=ladder,
            bundle=bundle, run=run,
        )
        target_artifact, target_path = _eval2_target_artifact_for_run(
            paths=paths, store=store, bundle=bundle, job=job, root=root, role=target_role,
        )
        catalog = _evaluation_checkpoint_catalog(store, run.run_id, execution)
        points = mdstats.read_train2_trajectory_points(
            catalog.root_directory, checkpoint_catalog=catalog,
            target_head_name=job.protocol.checkpoint_control_policy.target_head_name,
        )
        endpoint_epoch = int(convergence.policy.short_training_epochs) - 1
        matches = [point for point in points if point.epoch == endpoint_epoch]
        if len(matches) != 1:
            raise CampaignCliError(f"EVAL2 Stage B run {run.run_id} lacks its exact epoch-10 checkpoint.")
        point = matches[0]
        checkpoint = next(value for value in catalog.checkpoints if value.sha256 == point.checkpoint_sha256)
        # Full evaluation is purchased here, but replay is intentionally stripped
        # of Stage-B admissibility authority when the size evidence is reduced.
        record = _eval2_full_checkpoint(
            cfg=cfg, paths=paths, store=store, run=run, job=job, bundle=bundle, root=root,
            execution=execution, checkpoint=checkpoint, point=point,
            target_role=target_role, target_artifact=target_artifact, target_path=target_path,
            true_replay_resolution=true_replay_resolution, baseline_model=baseline_model,
            model_dtype=model_dtype, local_wrappers=local_wrappers,
            shortlist_reasons=("target_size_stage_b_exact_endpoint",), full_evaluation_rank=1,
        )
        target_threshold = float(job.protocol.checkpoint_admissibility_policy.maximum_target_force_rmse_ev_per_angstrom)
        target_pass = record.target_metrics.force_component_rmse_ev_per_angstrom <= target_threshold
        wall_time = sum(float(attempt.elapsed_seconds) for attempt in execution.attempts)
        parent = coarse_by_size.get(run.selection_size)
        if parent is None:
            raise CampaignCliError(f"EVAL2 Stage B run n={run.selection_size} lost its epoch-3 continuation parent.")
        evidence.append(mdstats.TargetSizeTrainingEvidence(
            stage="short",
            target_size=run.selection_size,
            optimizer_seed=run.seed,
            completed_epochs=runtime.completed_epochs,
            planned_epochs=runtime.planned_epochs,
            optimizer_update_count=runtime.completed_updates,
            structures_presented=runtime.structures_presented,
            normalized_schedule_progress=runtime.normalized_progress,
            instantaneous_learning_rate=runtime.instantaneous_learning_rate,
            wall_time_seconds=wall_time,
            target_force_score_mev_per_a=record.target_metrics.force_component_rmse_ev_per_angstrom * 1000.0,
            numerical_valid=True,
            target_hard_gates_passed=target_pass,
            foundation_identity_digest=job.protocol.foundation_checkpoint.canonical_content_digest,
            evaluation_role_digest=target_role.content_digest,
            training_policy_digest=_train2_policy_set_digest(job.protocol),
            training_run_digest=run.content_digest,
            checkpoint_digest=point.checkpoint_sha256,
            schedule_digest=job.protocol.learning_rate_schedule_policy.policy_digest,
            optimizer_state_digest=runtime.optimizer_state_digest,
            rng_state_digest=runtime.rng_state_digest,
            target_evaluation_digest=record.target_metrics.content_digest,
            replay_diagnostic_force_rmse_mev_per_a=(
                None if record.replay_candidate_force_rmse_ev_per_angstrom is None
                else record.replay_candidate_force_rmse_ev_per_angstrom * 1000.0
            ),
            replay_evaluation_digest=(
                None if record.replay_candidate_force_rmse_ev_per_angstrom is None
                else record.evaluation_record_digest
            ),
            parent_checkpoint_digest=parent.checkpoint_digest,
            parent_optimizer_state_digest=parent.optimizer_state_digest,
            parent_rng_state_digest=parent.rng_state_digest,
            failure_reasons=(() if target_pass else ("target_threshold_exceeded",)),
        ))
    return tuple(evidence)


def _command_evaluate_train2(
    args: argparse.Namespace,
    *,
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    campaign: Any,
    model_dtype: str,
) -> int:
    """Executable EVAL2 path for target-size and production TRAIN2 campaigns."""

    import mdstats

    entries = _current_data8_entries(store)
    jobs = _job_lookup(entries)
    convergence = _load_verified_target_size_convergence_authority(store)
    role_freeze = store.get_record("target_data_role_freeze", mdstats.TargetDataRoleFreeze)
    ladder = _load_verified_target_data_ladder_authority(store)
    execution_records = _available_successful_executions(cfg, paths, store, campaign, jobs)
    true_replay_resolution = _resolve_true_label_replay_inputs(cfg, paths, require_train=False)
    baseline_model = _path_cfg(cfg, paths, "foundation_model")
    local_wrappers = _ensure_local_wrappers(paths)

    _mark_stage(store, paths, "evaluate", StageState.RUNNING, "running EVAL2 target-first checkpoint evaluation")
    _print_header("EVAL2 target-first checkpoint evaluation")
    _print_precision_profile(cfg)

    if convergence.outcome == "awaiting_stage_b0_coarse_training":
        evidence = _eval2_stage_b0_evidence(
            cfg=cfg, paths=paths, store=store, campaign=campaign, jobs=jobs,
            execution_records=execution_records, convergence=convergence,
            role_freeze=role_freeze, ladder=ladder, baseline_model=baseline_model,
            model_dtype=model_dtype, local_wrappers=local_wrappers,
        )
        updated = mdstats.with_stage_b0_evidence(convergence, evidence)
        store.put_record("target_size_convergence", updated)
        for item in evidence:
            _ok(f"TARGET-DATA2D Stage B0 n={item.target_size}: target={item.target_force_score_mev_per_a:.2f} meV/A")
        if updated.outcome == "awaiting_stage_b1_short_training":
            _ok("Stage B0 retained epoch-3 survivors: " + ", ".join(f"n={v}" for v in updated.stage_b_survivor_sizes))
            _mark_stage(store, paths, "evaluate", StageState.COMPLETE, "EVAL2 Stage B0 complete; epoch-3 survivors frozen")
            print("\nEVAL2 Stage B0 complete. Next: `train` to continue the survivors to epoch 10.")
            return 0
        _mark_stage(store, paths, "evaluate", StageState.FAILED, updated.decision_reason)
        return 1

    if convergence.outcome == "awaiting_stage_b1_short_training":
        evidence = _eval2_stage_b_evidence(
            cfg=cfg, paths=paths, store=store, campaign=campaign, jobs=jobs,
            execution_records=execution_records, convergence=convergence,
            role_freeze=role_freeze, ladder=ladder,
            true_replay_resolution=true_replay_resolution, baseline_model=baseline_model,
            model_dtype=model_dtype, local_wrappers=local_wrappers,
        )
        updated = mdstats.with_stage_b_evidence(convergence, evidence)
        store.put_record("target_size_convergence", updated)
        for item in evidence:
            _ok(
                f"TARGET-DATA2D Stage B1 n={item.target_size}: target={item.target_force_score_mev_per_a:.2f} meV/A"
                + ("" if item.replay_diagnostic_force_rmse_mev_per_a is None else f"; replay diagnostic={item.replay_diagnostic_force_rmse_mev_per_a:.2f} meV/A")
            )
        if updated.outcome == "awaiting_stage_c_full_training":
            _ok("Stage B1 retained finalists: " + ", ".join(f"n={v}" for v in updated.stage_b_finalist_sizes))
            _mark_stage(store, paths, "evaluate", StageState.COMPLETE, "EVAL2 Stage B1 complete; two target-size finalists frozen")
            print("\nEVAL2 Stage B1 complete. Next: `train` to continue the two finalists to epoch 30.")
            return 0
        _mark_stage(store, paths, "evaluate", StageState.FAILED, updated.decision_reason)
        return 1

    if convergence.outcome == "awaiting_stage_c_full_training":
        expected_sizes = set(int(v) for v in convergence.stage_b_finalist_sizes)
        screening_seed = int(convergence.policy.screening_optimizer_seed)
        runs = [
            run for run in campaign.runs
            if run.kind is mdstats.MaceJobKind.FINAL_DEVELOPMENT
            and run.seed == screening_seed and run.selection_size in expected_sizes
        ]
        if {run.selection_size for run in runs} != expected_sizes:
            raise CampaignCliError("EVAL2 Stage C cannot resolve both completed finalist runs.")
        records = []
        for run in sorted(runs, key=lambda value: value.selection_size):
            execution = execution_records.get(run.content_digest)
            if execution is None:
                raise CampaignCliError(f"EVAL2 Stage C run {run.run_id} has not completed the 30-epoch budget.")
            bundle, job, root = jobs[run.mace_job_artifact_digest]
            runtime = store.get_record_optional(f"train2_runtime:{run.run_id}", mdstats.Train2RuntimeSummary)
            if runtime is None:
                runtime = mdstats.load_train2_runtime_summary(paths.runs / run.run_id / "checkpoints")
            if runtime.completed_epochs != convergence.policy.final_training_epochs or not runtime.complete_budget:
                raise CampaignCliError(f"EVAL2 Stage C run {run.run_id} is not a complete 30-epoch TRAIN2 trajectory.")
            record = _eval2_run_record_for_completed_train2_run(
                cfg=cfg, paths=paths, store=store, run=run, job=job, bundle=bundle, root=root,
                execution=execution, convergence=convergence, role_freeze=role_freeze, ladder=ladder,
                true_replay_resolution=true_replay_resolution, baseline_model=baseline_model,
                model_dtype=model_dtype, local_wrappers=local_wrappers,
            )
            records.append(record)
            if record.outcome != "selected":
                _mark_stage(store, paths, "evaluate", StageState.FAILED, f"{run.run_id}: EVAL2 found no admissible checkpoint")
                return 1
            selected = record.selected_checkpoint
            assert selected is not None
            _ok(
                f"{run.run_id}: EVAL2 selected epoch {record.selected_checkpoint_epoch}; "
                f"target={selected.target_metrics.force_component_rmse_ev_per_angstrom*1000:.2f} meV/A; "
                f"replay degradation={(selected.replay_degradation_ev_per_angstrom or 0.0)*1000:.2f} meV/A"
            )
        store.put_record("eval2_target_size_stage_c", {
            "schema": "mdstats.eval2-target-size-stage-c.v1",
            "target_size_convergence_digest": convergence.content_digest,
            "run_record_digests": [record.content_digest for record in records],
        })
        _mark_stage(store, paths, "evaluate", StageState.COMPLETE, "EVAL2 Stage C static evidence complete; physical qualification pending")
        print("\nEVAL2 Stage C static evaluation complete. Next: `verify` for deployment/PES/relaxation/dynamics qualification.")
        return 0

    if convergence.outcome == "selected":
        selected_size = int(convergence.selected_target_size)
        runs = [run for run in campaign.runs if run.selection_size == selected_size]
        missing = [run.run_id for run in runs if run.content_digest not in execution_records]
        if missing:
            raise CampaignCliError(
                "EVAL2 production evaluation requires the selected-size production runs to complete: " + ", ".join(missing[:4])
            )
        for run in runs:
            bundle, job, root = jobs[run.mace_job_artifact_digest]
            record = _eval2_run_record_for_completed_train2_run(
                cfg=cfg, paths=paths, store=store, run=run, job=job, bundle=bundle, root=root,
                execution=execution_records[run.content_digest], convergence=convergence,
                role_freeze=role_freeze, ladder=ladder,
                true_replay_resolution=true_replay_resolution, baseline_model=baseline_model,
                model_dtype=model_dtype, local_wrappers=local_wrappers,
            )
            if record.outcome != "selected":
                _warn(f"{run.run_id}: EVAL2 has no admissible checkpoint after bounded rescue")
            else:
                selected = record.selected_checkpoint
                assert selected is not None
                _ok(
                    f"{run.run_id}: selected epoch {record.selected_checkpoint_epoch}, "
                    f"target={selected.target_metrics.force_component_rmse_ev_per_angstrom*1000:.2f} meV/A"
                )
        _mark_stage(store, paths, "evaluate", StageState.COMPLETE, "EVAL2 production static checkpoint selection complete")
        print("\nEVAL2 production evaluation complete. Next: `verify`.")
        return 0

    raise CampaignCliError(
        "EVAL2 cannot run because TARGET-DATA2D is neither awaiting Stage B/C nor holding a selected production size: "
        f"{convergence.outcome}."
    )


@mace_runtime_warning_handled("campaign checkpoint evaluation")
def command_evaluate(args: argparse.Namespace) -> int:
    import mdstats

    cfg, paths = _load_config(args.config)
    precision_contract = _binary_model_precision_contract(cfg)
    model_dtype = str(precision_contract["model_dtype"])
    store = CampaignStore(paths.state_db)
    stored_campaign_digest = store.record_digest("training_campaign")
    campaign = store.get_record("training_campaign", mdstats.TrainingCampaignPlan)
    if _campaign_training_policy_family(campaign) == "train2":
        return _command_evaluate_train2(
            args, cfg=cfg, paths=paths, store=store, campaign=campaign, model_dtype=model_dtype
        )
    if (
        stored_campaign_digest is not None
        and stored_campaign_digest != campaign.content_digest
    ):
        # Older mdstats releases serialized the campaign with an older nested
        # policy schema.  The legacy bytes have already passed their original
        # parent digest plus every nested policy/run digest.  Persist the
        # canonical current-schema form once so subsequent evaluate/verify
        # invocations do not repeat the migration.  Scientific run identities,
        # checkpoints, and execution records are unchanged.
        store.put_record("training_campaign", campaign)
        store.event(
            "warning",
            "evaluate",
            "migrated a digest-verified legacy training-campaign plan to the current schema",
        )
        _warn(
            "migrated a digest-verified legacy training-campaign plan to the "
            "current schema; completed runs and checkpoint bytes were preserved"
        )
    data8_entries = _current_data8_entries(store)
    bundles = [entry.bundle for entry in data8_entries]
    jobs = _job_lookup(data8_entries)
    selections: dict[str, Any] = {}
    selected_metrics: dict[str, Any] = {}
    selected_evaluations: dict[str, Any] = {}
    train_state, train_message = _effective_stage(store, paths, "train")
    filters_active = any(
        value is not None
        for value in (getattr(args, "training_mode", None), getattr(args, "seed", None), getattr(args, "selection_size", None))
    )
    allow_partial = bool(
        _cfg(cfg, "evaluation", "allow_partial_campaign", True)
    ) and not bool(getattr(args, "require_complete", False))
    execution_records = _available_successful_executions(
        cfg, paths, store, campaign, jobs
    )
    if train_state is not StageState.COMPLETE and not allow_partial:
        raise CampaignCliError(
            f"Stage `train` is not complete ({train_message}) and partial evaluation is disabled."
        )
    availabilities = _variant_availability(
        campaign,
        execution_records,
        training_mode=getattr(args, "training_mode", None),
        seed=getattr(args, "seed", None),
        selection_size=getattr(args, "selection_size", None),
    )
    if not availabilities:
        raise CampaignCliError(
            "No completed training models match the requested evaluation scope. "
            "Resume `train`, or change the method/seed/selection-size filters."
        )
    full_evaluation = bool(
        train_state is StageState.COMPLETE
        and not filters_active
        and len(execution_records) == len(campaign.runs)
    )
    requested_checkpoint_strategy = str(
        _cfg(cfg, "evaluation", "checkpoint_strategy", "bounded")
    ).strip().lower()
    mlcv_authority = _reconcile_mlcv_lifecycle_authority(
        campaign, bundles, store, requested_checkpoint_strategy=requested_checkpoint_strategy
    )
    _enforce_evaluation_migration_boundary(campaign, requested_checkpoint_strategy, mlcv_authority)
    if mlcv_authority is None and requested_checkpoint_strategy == "adaptive_topk" and _reuse_frozen_adaptive_evaluation(paths, store):
        return 0
    if full_evaluation:
        runs_to_evaluate = tuple(campaign.runs)
        stage_message = (
            "running MLCV SELECT1/AGG1/FINAL1 conventional-CV evaluation"
            if mlcv_authority is not None
            else (
                "running ADAPT-EVAL1 top-K authoritative full evaluation"
                if requested_checkpoint_strategy == "adaptive_topk"
                else (
                "running nested multi-fidelity checkpoint evaluation and freezing protocol"
                if requested_checkpoint_strategy == "multi_fidelity"
                    else "shortlisting checkpoints, evaluating candidates, and freezing protocol"
                )
            )
        )
    else:
        included = {
            run.content_digest
            for availability in availabilities
            for run in availability.completed_runs
        }
        runs_to_evaluate = tuple(
            run for run in campaign.runs if run.content_digest in included
        )
        stage_prefix = (
            "MLCV " if mlcv_authority is not None
            else ("ADAPT-EVAL1 " if requested_checkpoint_strategy == "adaptive_topk" else "")
        )
        stage_message = (
            f"interim {stage_prefix}evaluation "
            f"of {len(runs_to_evaluate)}/{len(campaign.runs)} completed runs"
        )
    _mark_stage(store, paths, "evaluate", StageState.RUNNING, stage_message)
    _print_header(
        "Checkpoint evaluation"
        if full_evaluation
        else "Interim completed-model evaluation"
    )
    precision_profile = _print_precision_profile(cfg)

    if mlcv_authority is not None:
        if not all(
            getattr(jobs[run.mace_job_artifact_digest][0], "mlcv_monitor_catalog", None) is not None
            for run in runs_to_evaluate
        ):
            raise CampaignCliError("MLCV lifecycle authority exists but a run lacks MON1 catalog evidence.")
        return _command_evaluate_mlcv_select1(
            args, cfg=cfg, paths=paths, store=store, campaign=campaign, jobs=jobs,
            execution_records=execution_records, runs_to_evaluate=runs_to_evaluate,
            full_evaluation=full_evaluation, model_dtype=model_dtype, precision_profile=precision_profile,
        )
    if requested_checkpoint_strategy == "adaptive_topk":
        return _command_evaluate_adaptive_topk(
            args, cfg=cfg, paths=paths, store=store, campaign=campaign, jobs=jobs,
            execution_records=execution_records, runs_to_evaluate=runs_to_evaluate,
            full_evaluation=full_evaluation, model_dtype=model_dtype, precision_profile=precision_profile,
        )

    true_replay_resolution = _resolve_true_label_replay_inputs(
        cfg, paths, require_train=False
    )
    if true_replay_resolution is not None:
        _ok(
            "replay evaluation labels: independent true DFT monitor "
            f"({true_replay_resolution.monitor_artifact.configuration_count} configurations)"
        )

    deployment_dtype = model_dtype
    evaluation_policy = mdstats.CheckpointEvaluationPolicy(
        focus_atomic_numbers=tuple(
            int(v) for v in _cfg(cfg, "profile", "mobile_atomic_numbers", (3, 11, 19))
        ),
        device=str(_cfg(cfg, "evaluation", "device", _cfg(cfg, "training", "device", "cuda"))),
        default_dtype=model_dtype,
        batch_size=int(_cfg(cfg, "evaluation", "batch_size", 8)),
        cache_monitor_datasets=bool(
            _cfg(cfg, "evaluation", "cache_monitor_datasets", True)
        ),
        cache_replay_baseline=bool(
            _cfg(cfg, "evaluation", "cache_replay_baseline", True)
        ),
        evaluate_foundation_on_target=bool(
            _cfg(
                cfg,
                "evaluation",
                "evaluate_foundation_on_target",
                true_replay_resolution is not None,
            )
        ),
        acceleration_policy=_acceleration_policy(cfg),
        **_evaluation_foundation_binding(cfg, paths),
        critical_precision_policy=_critical_precision_policy(cfg),
    )
    metric_policy = _checkpoint_metric_policy(cfg)

    def has_required_model_dataset_matrix(record: Any) -> bool:
        if not (
            true_replay_resolution is not None
            or evaluation_policy.evaluate_foundation_on_target
        ):
            # Preserve v1/v3 pseudo-label-only cache reuse for legacy TOMLs.
            return True
        if record.target_candidate_metrics is None:
            return False
        if (
            evaluation_policy.evaluate_foundation_on_target
            and record.target_foundation_metrics is None
        ):
            return False
        if record.replay_configuration_count > 0 and (
            record.replay_candidate_metrics is None
            or record.replay_foundation_metrics is None
        ):
            return False
        return True

    baseline_model = _path_cfg(cfg, paths, "foundation_model")
    baseline_sha256 = None if baseline_model is None else _sha256(baseline_model)
    prediction_cache_directory = paths.internal / "evaluation-predictions"
    graph_cache_directory = paths.internal / "evaluation-graphs"
    foundation_prediction_manifest = None
    foundation_prediction_root = None
    model_sweep_root = paths.internal / "model-sweep"
    if baseline_sha256 is not None and model_sweep_root.is_dir():
        try:
            foundation_sweep = mdstats.load_data6_model_sweep_artifacts(
                model_sweep_root, verify_sidecars=False
            )
            if (
                foundation_sweep.complete
                and foundation_sweep.prediction_manifest is not None
                and foundation_sweep.prediction_manifest.checkpoint_identity.checkpoint_sha256
                == baseline_sha256
            ):
                foundation_prediction_manifest = foundation_sweep.prediction_manifest
                foundation_prediction_root = foundation_sweep.root_directory
                _ok(
                    "evaluation prediction reuse: authenticated DATA6 foundation predictions are available"
                )
        except Exception as exc:
            _warn(
                "DATA6 foundation-prediction reuse is unavailable; evaluation will use the "
                f"persistent prediction cache or fresh inference ({exc})"
            )
    local_wrappers = _ensure_local_wrappers(paths)
    checkpoint_strategy = str(
        _cfg(cfg, "evaluation", "checkpoint_strategy", "bounded")
    ).strip().lower()
    if checkpoint_strategy not in {"bounded", "exhaustive", "multi_fidelity"}:
        raise CampaignCliError(
            "[evaluation].checkpoint_strategy must be one of bounded, exhaustive, or multi_fidelity for historical evaluation paths."
        )
    maximum_checkpoint_evaluations = int(
        _cfg(cfg, "evaluation", "max_checkpoints_per_run", 4)
    )
    if maximum_checkpoint_evaluations < 0:
        raise CampaignCliError(
            "[evaluation].max_checkpoints_per_run must be nonnegative; 0 means evaluate all checkpoints."
        )
    if checkpoint_strategy == "exhaustive":
        maximum_checkpoint_evaluations = 0
    shortlists: dict[str, _CheckpointShortlist] = {}
    total_checkpoints = 0
    total_original_checkpoints = 0
    unavailable_refresh_checkpoints = 0
    refresh_limited_runs = 0
    for run in runs_to_evaluate:
        execution = execution_records[run.content_digest]
        original_catalog = _evaluation_checkpoint_catalog(
            store, run.run_id, execution
        )
        if checkpoint_strategy == "multi_fidelity":
            bundle, job, root = jobs[run.mace_job_artifact_digest]
            shortlist = _multi_fidelity_screen_run(
                cfg=cfg,
                paths=paths,
                store=store,
                run=run,
                original_catalog=original_catalog,
                bundle=bundle,
                job=job,
                root=root,
                execution=execution,
                evaluation_policy=evaluation_policy,
                metric_policy=metric_policy,
                true_replay_resolution=true_replay_resolution,
                baseline_model=baseline_model,
                prediction_cache_directory=prediction_cache_directory,
                graph_cache_directory=graph_cache_directory,
                foundation_prediction_manifest=foundation_prediction_manifest,
                foundation_prediction_root=foundation_prediction_root,
                local_wrappers=local_wrappers,
            )
        else:
            shortlist = _checkpoint_shortlist(
                run,
                original_catalog,
                paths.runs / run.run_id / "results",
                maximum_candidates=maximum_checkpoint_evaluations,
                target_head_name=evaluation_policy.target_head_name,
                replay_head_name=evaluation_policy.replay_head_name,
            )
            if true_replay_resolution is not None:
                shortlist, unavailable = _available_checkpoint_refresh_shortlist(
                    run, shortlist, original_catalog, store
                )
                if unavailable:
                    unavailable_refresh_checkpoints += unavailable
                    refresh_limited_runs += 1
                    _warn(
                        f"{run.run_id}: {unavailable} previously evaluated checkpoint(s) were "
                        "already pruned; refreshing the independent true-label metrics on "
                        f"{len(shortlist.catalog.checkpoints)} retained checkpoint(s)."
                    )
        shortlists[run.content_digest] = shortlist
        total_checkpoints += len(shortlist.catalog.checkpoints)
        total_original_checkpoints += shortlist.original_count
        store.put_record(f"checkpoint_shortlist:{run.run_id}", shortlist.to_dict())
        if checkpoint_strategy == "multi_fidelity":
            _write_multi_fidelity_epoch_report(
                paths=paths,
                store=store,
                run=run,
                original_catalog=original_catalog,
                policy=_multi_fidelity_policy(cfg),
                evaluation_policy=evaluation_policy,
                metric_policy=metric_policy,
            )
    checkpoint_progress = _ProgressReporter("EVAL", total_checkpoints)
    if checkpoint_strategy == "multi_fidelity":
        _ok(
            f"multi-fidelity checkpoint evaluation: all {total_original_checkpoints} saved epochs "
            f"entered round 1; {total_checkpoints} full-fidelity finalists remain for authoritative selection"
        )
    elif total_checkpoints < total_original_checkpoints:
        _ok(
            f"bounded checkpoint evaluation: {total_checkpoints}/{total_original_checkpoints} "
            "epochs shortlisted from training-time validation history"
        )
    checkpoint_index = 0
    reused_count = 0
    stale_evaluation_count = 0

    # Build one campaign-wide task queue so retained single-checkpoint runs can
    # execute concurrently after a stale true-label evaluation is invalidated.
    # This also permits checkpoints from different runs to share the same
    # adaptive GPU/CPU admission controller.
    pending_evaluation_tasks: list[_StagedEvaluationTask] = []
    evaluation_contexts: list[dict[str, Any]] = []
    def publish_evaluated_model(
        context: dict[str, Any], selection: Any
    ) -> Any:
        """Synchronously publish one selected run from durable evaluation state.

        The adaptive scheduler refills newly empty inference slots before invoking
        checkpoint-success callbacks, so doing publication here does not leave the
        GPU queue idle.  Keeping publication synchronous is intentional: once a
        run is fully evaluated, the parent ``models/`` artifact and its SQLite
        receipt are committed before evaluation proceeds with nonessential parent
        bookkeeping.  This also makes restart recovery deterministic.
        """

        run = context["run"]
        output = paths.models / f"{run.run_id}-target.model"
        record_key = f"evaluated_model:{run.run_id}"
        try:
            existing = store.get_record_optional(
                record_key, mdstats.VerificationModelRecord
            )
            if existing is not None and (
                existing.run_plan_digest == run.content_digest
                and existing.checkpoint_selection_record_digest
                == selection.content_digest
                and Path(existing.exported_model_path).resolve() == output.resolve()
                and output.is_file()
                and _sha256(output) == existing.exported_model_sha256
            ):
                context["export_record"] = existing
                shutil.rmtree(context["checkpoint_model_cache"], ignore_errors=True)
                _ok(f"{run.run_id}: evaluated target model already available at {output}")
                return existing
        except Exception:
            pass
        store.delete_record(record_key)

        evaluation_catalog = context["evaluation_catalog"]
        checkpoint = next(
            value
            for value in evaluation_catalog.checkpoints
            if value.sha256 == selection.selected_checkpoint_sha256
        )
        source = (
            Path(evaluation_catalog.root_directory) / checkpoint.relative_path
        ).resolve()
        print(
            f"[MODEL EXPORT] {run.run_id}: selected epoch "
            f"{selection.selected_checkpoint_epoch}; checking training-model/cache/direct restore paths",
            flush=True,
        )
        materialize_started = time.monotonic()
        model_source = mdstats.materialize_mace_checkpoint_model(
            checkpoint,
            source,
            mace_config_path=context["config_path"],
            job_working_directory=context["job_root"],
            cache_directory=context["checkpoint_model_cache"],
            wrapper_path=local_wrappers["mdstats-mace-train"],
            allow_checkpoint_dtype_template_cast=False,
        )
        reuse_note = (
            "completed training model"
            if model_source.parent.name == "models" and model_source.parent.parent == context["checkpoint_model_cache"].parent
            else "checkpoint-model cache"
        )
        materialize_elapsed = time.monotonic() - materialize_started
        print(
            f"[MODEL EXPORT] {run.run_id}: deployable source ready via {reuse_note} "
            f"in {materialize_elapsed:.2f}s; extracting target head",
            flush=True,
        )
        export_started = time.monotonic()
        member = mdstats.export_target_head_verification_model(
            run,
            selection,
            source,
            output,
            source_model_path=model_source,
            policy=mdstats.CommitteeExportPolicy(
                target_head_name=evaluation_policy.target_head_name,
                minimum_members=1,
            ),
            wrapper_path=local_wrappers["mdstats-mace-select-head"],
            deployment_dtype=deployment_dtype,
        )
        # Commit the durable publication receipt immediately.  A restart with a
        # complete evaluation set but no receipt/file will rerun this exact path.
        store.put_record(record_key, member)
        context["export_record"] = member
        shutil.rmtree(context["checkpoint_model_cache"], ignore_errors=True)
        export_elapsed = time.monotonic() - export_started
        print(
            f"[MODEL EXPORT] {run.run_id}: atomic target-head export and receipt committed "
            f"in {export_elapsed:.2f}s",
            flush=True,
        )
        print(
            f"[EVALUATED MODEL] {run.run_id}: {output} "
            f"(epoch {selection.selected_checkpoint_epoch})",
            flush=True,
        )
        return member

    def finalize_evaluated_run(context: dict[str, Any]) -> None:
        """Select and publish one run as soon as all of its evaluations exist."""

        if context.get("selection_finalized", False):
            return
        run = context["run"]
        shortlist = context["shortlist"]
        evaluation_catalog = context["evaluation_catalog"]
        evaluations_by_sha = context["evaluations_by_sha"]
        if any(
            checkpoint.sha256 not in evaluations_by_sha
            for checkpoint in evaluation_catalog.checkpoints
        ):
            return
        metric_records = [
            evaluations_by_sha[checkpoint.sha256].metric_record
            for checkpoint in evaluation_catalog.checkpoints
        ]
        evaluation_records = [
            evaluations_by_sha[checkpoint.sha256]
            for checkpoint in evaluation_catalog.checkpoints
        ]
        selection, selection_failure = _checkpoint_selection_or_failure(
            run, shortlist, evaluation_catalog, metric_records, metric_policy
        )
        if selection_failure is not None:
            failure_key = f"selection_failure:{run.run_id}"
            store.put_record(failure_key, selection_failure)
            store.delete_record(f"selection:{run.run_id}")
            store.delete_record(f"evaluated_model:{run.run_id}")
            stale_output = paths.models / f"{run.run_id}-target.model"
            stale_output.unlink(missing_ok=True)
            shutil.rmtree(context["checkpoint_model_cache"], ignore_errors=True)
            _warn(_format_checkpoint_selection_failure(selection_failure))
            if selection_failure["bounded_shortlist"]:
                if checkpoint_strategy == "multi_fidelity":
                    _warn(
                        f"{run.run_id}: multi-fidelity screening does not prove that every saved epoch "
                        "is inadmissible; only the declared full-fidelity finalists were authorized for "
                        "scientific selection. Use checkpoint_strategy=exhaustive for a brute-force rescue."
                    )
                else:
                    _warn(
                        f"{run.run_id}: bounded evaluation does not prove that every saved epoch is inadmissible; "
                        "this run is excluded from the current verification set. Set "
                        "[evaluation].max_checkpoints_per_run = 0 only when exhaustive rescue is worth the cost."
                    )
            if checkpoint_strategy == "multi_fidelity":
                _write_multi_fidelity_epoch_report(
                    paths=paths,
                    store=store,
                    run=run,
                    original_catalog=context["original_catalog"],
                    policy=_multi_fidelity_policy(cfg),
                    evaluation_policy=evaluation_policy,
                    metric_policy=metric_policy,
                    selection_failure=selection_failure,
                )
            context["selection_finalized"] = True
            return

        assert selection is not None
        store.delete_record(f"selection_failure:{run.run_id}")
        store.put_record(f"selection:{run.run_id}", selection)
        selections[run.content_digest] = selection
        metric = next(
            value
            for value in metric_records
            if value.checkpoint_sha256 == selection.selected_checkpoint_sha256
        )
        selected_metrics[run.content_digest] = metric
        selected_evaluations[run.content_digest] = next(
            value
            for value in evaluation_records
            if value.checkpoint_sha256 == selection.selected_checkpoint_sha256
        )
        replay_note = ""
        if (
            metric.replay_label_mode is mdstats.ReplayLabelMode.FOUNDATION_PSEUDOLABEL
            and metric.replay_candidate_metric is not None
        ):
            replay_note = (
                f"; pseudolabel disagreement={metric.replay_candidate_metric * 1000:.1f} meV/A "
                "(diagnostic)"
            )
        _ok(
            f"{run.run_id}: selected epoch {selection.selected_checkpoint_epoch}, "
            f"DFT force RMSE {metric.force_component_rmse_ev_per_angstrom * 1000:.1f} meV/A"
            f"{replay_note}"
        )
        # Publication is part of run finalization, not a deferred campaign-end
        # action.  If it fails, leave ``selection`` durable and the reconstruction
        # cache intact; rerunning ``evaluate`` will retry publication immediately.
        publish_evaluated_model(context, selection)
        if checkpoint_strategy == "multi_fidelity":
            _write_multi_fidelity_epoch_report(
                paths=paths,
                store=store,
                run=run,
                original_catalog=context["original_catalog"],
                policy=_multi_fidelity_policy(cfg),
                evaluation_policy=evaluation_policy,
                metric_policy=metric_policy,
                selection=selection,
            )
        # STOR2 can compact this run immediately because its selected checkpoint
        # is now known and already published.  The selected raw checkpoint remains
        # restart-capable; every nonselected epoch is replaced only after an exact
        # evaluation-state capsule has been committed and independently reloaded.
        stor2_report = _compact_evaluated_checkpoints(
            cfg, paths, store, campaign, run_ids={run.run_id}
        )
        if stor2_report.actions or stor2_report.skipped:
            _print_cleanup_report(stor2_report)
        context["selection_finalized"] = True

    for run in runs_to_evaluate:
        execution = execution_records[run.content_digest]
        bundle, job, root = jobs[run.mace_job_artifact_digest]
        job_root = (root / job.relative_directory).resolve()
        config_path = (root / job.config_relative_path).resolve()
        checkpoint_model_cache = paths.runs / run.run_id / "checkpoint-model-cache"
        target_artifacts, training_replay_artifact = _artifact_lookup(bundle)
        target_artifact = target_artifacts[run.target_monitor_artifact_digest]
        target_path = root / job.relative_directory / target_artifact.relative_path
        # A DATA8 bundle may contain replay data even when this particular run is
        # a target-only/naive campaign.  Preserve the legacy evaluation identity
        # for those runs: replay provenance and the foundation model only belong
        # in the record when the run actually uses replay, or when an explicit
        # foundation-on-target comparison is requested.
        active_training_replay_artifact = None
        evaluation_replay_artifact = None
        training_replay_path = None
        replay_path = None
        if run.replay_monitor_artifact_digest is not None:
            if training_replay_artifact is None:
                raise CampaignCliError(
                    f"{run.run_id}: replay run is missing its frozen DATA8 replay monitor artifact."
                )
            active_training_replay_artifact = training_replay_artifact
            evaluation_replay_artifact = training_replay_artifact
            training_replay_path = _resolve_data8_runtime_member(
                bundle, root, training_replay_artifact.path
            )
            replay_path = training_replay_path
        if active_training_replay_artifact is not None and true_replay_resolution is not None:
            candidate_true_artifact = true_replay_resolution.monitor_artifact
            if (
                candidate_true_artifact.configuration_count
                != active_training_replay_artifact.configuration_count
                or candidate_true_artifact.geometry_identities
                != active_training_replay_artifact.geometry_identities
            ):
                raise CampaignCliError(
                    f"{run.run_id}: configured true-label replay monitor does not match "
                    "the frozen DATA8 replay geometry/order."
                )
            evaluation_replay_artifact = candidate_true_artifact
            replay_path = Path(true_replay_resolution.monitor_path)
        if (
            active_training_replay_artifact is not None
            and active_training_replay_artifact.label_mode is mdstats.ReplayLabelMode.FOUNDATION_PSEUDOLABEL
            and evaluation_replay_artifact is active_training_replay_artifact
        ):
            _warn(
                f"{run.run_id}: no independent true replay labels are configured; "
                "candidate-vs-foundation replay disagreement remains diagnostic only."
            )
        requires_foundation_baseline = bool(
            evaluation_policy.evaluate_foundation_on_target
            or run.replay_monitor_artifact_digest is not None
        )
        expected_baseline_sha256 = (
            baseline_sha256 if requires_foundation_baseline else None
        )
        baseline_model_for_evaluation = (
            baseline_model if requires_foundation_baseline else None
        )
        metric_records = []
        evaluation_records = []
        shortlist = shortlists[run.content_digest]
        evaluation_catalog = shortlist.catalog
        evaluated_sha256s = {item.sha256 for item in evaluation_catalog.checkpoints}
        if true_replay_resolution is not None:
            original_catalog = _evaluation_checkpoint_catalog(
                store, run.run_id, execution
            )
            for archived_checkpoint in original_catalog.checkpoints:
                if archived_checkpoint.sha256 in evaluated_sha256s:
                    continue
                archived_key = (
                    f"evaluation:{run.run_id}:{archived_checkpoint.sha256}"
                )
                try:
                    archived = store.get_record_optional(
                        archived_key, mdstats.CheckpointEvaluationRecord
                    )
                    if archived is None:
                        continue
                    stale = bool(
                        archived.evaluation_policy_digest
                        != evaluation_policy.policy_digest
                        or archived.replay_monitor_artifact_digest
                        != (
                            None
                            if evaluation_replay_artifact is None
                            else evaluation_replay_artifact.content_digest
                        )
                        or archived.replay_monitor_sha256
                        != (
                            None
                            if evaluation_replay_artifact is None
                            else evaluation_replay_artifact.sha256
                        )
                        or archived.replay_baseline_model_sha256
                        != expected_baseline_sha256
                        or not has_required_model_dataset_matrix(archived)
                    )
                except Exception:
                    stale = True
                if stale:
                    store.delete_record(archived_key)
                    stale_evaluation_count += 1
                    store.event(
                        "warning",
                        "evaluate",
                        f"removed stale archived checkpoint evaluation "
                        f"{run.run_id} epoch {archived_checkpoint.epoch}",
                    )
        print(
            f"[EVAL RUN] {run.run_id}: {len(evaluation_catalog.checkpoints)}/"
            f"{shortlist.original_count} checkpoints; epochs="
            f"{','.join(str(value) for value in shortlist.selected_epochs)}",
            flush=True,
        )
        evaluations_by_sha: dict[str, Any] = {}
        context: dict[str, Any] = {
            "run": run,
            "shortlist": shortlist,
            "original_catalog": _evaluation_checkpoint_catalog(store, run.run_id, execution),
            "evaluation_catalog": evaluation_catalog,
            "evaluations_by_sha": evaluations_by_sha,
            "job_root": job_root,
            "config_path": config_path,
            "checkpoint_model_cache": checkpoint_model_cache,
            "selection_finalized": False,
        }
        evaluation_contexts.append(context)
        for checkpoint in evaluation_catalog.checkpoints:
            checkpoint_index += 1
            display_index = checkpoint_index
            model_path, capsule_record = _checkpoint_source_for_evaluation(
                paths, store, run.run_id, checkpoint, execution.checkpoint_catalog
            )
            key = f"evaluation:{run.run_id}:{checkpoint.sha256}"
            evaluation = None
            try:
                candidate = store.get_record_optional(
                    key, mdstats.CheckpointEvaluationRecord
                )
                if candidate is not None:
                    reusable = bool(
                        candidate.run_plan_digest == run.content_digest
                        and candidate.checkpoint_sha256 == checkpoint.sha256
                        and candidate.evaluation_policy_digest == evaluation_policy.policy_digest
                        and candidate.target_monitor_artifact_digest == target_artifact.content_digest
                        and candidate.target_monitor_sha256 == target_artifact.sha256
                        and candidate.replay_monitor_artifact_digest
                        == (None if evaluation_replay_artifact is None else evaluation_replay_artifact.content_digest)
                        and candidate.replay_monitor_sha256
                        == (None if evaluation_replay_artifact is None else evaluation_replay_artifact.sha256)
                        and candidate.candidate_model_sha256 == checkpoint.sha256
                        and candidate.replay_baseline_model_sha256 == expected_baseline_sha256
                        and has_required_model_dataset_matrix(candidate)
                        and target_path.is_file()
                        and _sha256(target_path) == target_artifact.sha256
                        and (
                            evaluation_replay_artifact is None
                            or (
                                replay_path is not None
                                and replay_path.is_file()
                                and _sha256(replay_path) == evaluation_replay_artifact.sha256
                            )
                        )
                    )
                    if reusable:
                        evaluation = mdstats.bind_checkpoint_evaluation_replay_provenance(
                            candidate,
                            None
                            if evaluation_replay_artifact is None
                            else evaluation_replay_artifact.label_mode,
                            training_replay_monitor_artifact_digest=run.replay_monitor_artifact_digest,
                        )
                        if evaluation.content_digest != candidate.content_digest:
                            store.put_record(key, evaluation)
                        reused_count += 1
                    else:
                        store.delete_record(key)
                        stale_evaluation_count += 1
                        store.event(
                            "warning",
                            "evaluate",
                            f"invalidated stale checkpoint evaluation {run.run_id} epoch {checkpoint.epoch}",
                        )
            except Exception:
                store.delete_record(key)
                stale_evaluation_count += 1
                evaluation = None
            was_cached = evaluation is not None
            label = f"{run.run_id}:epoch{checkpoint.epoch}"
            if was_cached:
                checkpoint_progress.item_start(
                    display_index,
                    label,
                    "verified cached result",
                )
                checkpoint_progress.item_done(
                    display_index,
                    label,
                    f"cached; force={evaluation.metric_record.force_component_rmse_ev_per_angstrom * 1000:.1f} meV/A",
                )
                evaluations_by_sha[checkpoint.sha256] = evaluation
                continue

            candidate_prediction_cache_ready = mdstats.checkpoint_prediction_cache_complete(
                prediction_cache_directory,
                checkpoint_sha256=checkpoint.sha256,
                target_geometry_identities=target_artifact.frame_uids,
                policy=evaluation_policy,
                replay_geometry_identities=(
                    None
                    if evaluation_replay_artifact is None
                    else evaluation_replay_artifact.geometry_identities
                ),
            )
            if model_path.is_file():
                expected_source_sha = (
                    checkpoint.sha256 if capsule_record is None else capsule_record.capsule_sha256
                )
                if _sha256(model_path) != expected_source_sha:
                    raise CampaignCliError(
                        f"Checkpoint/capsule bytes no longer match the frozen inventory: "
                        f"{run.run_id} epoch {checkpoint.epoch}. Refusing to hide changed "
                        "model state behind cached predictions."
                    )
            elif not candidate_prediction_cache_ready:
                raise CampaignCliError(
                    f"Checkpoint bytes required for a new inference are unavailable: "
                    f"{run.run_id} epoch {checkpoint.epoch}. No complete label-independent "
                    "prediction cache exists for the active target/replay geometry."
                )

            task_result_key = f"{run.content_digest}:{checkpoint.sha256}"

            def prepare_checkpoint(
                *,
                active_run: Any = run,
                active_checkpoint: Any = checkpoint,
                active_model_path: Path = model_path,
                active_capsule_record: Any = capsule_record,
                active_target_path: Path = target_path,
                active_target_artifact: Any = target_artifact,
                active_replay_path: Path | None = replay_path,
                active_evaluation_replay_artifact: Any = evaluation_replay_artifact,
                active_training_replay_artifact_bound: Any = active_training_replay_artifact,
                active_training_replay_path: Path | None = training_replay_path,
                active_baseline_model: Path | None = baseline_model_for_evaluation,
            ) -> Any:
                return mdstats.prepare_mace_checkpoint_evaluation(
                    active_run,
                    active_checkpoint,
                    candidate_model_path=active_model_path,
                    calculator_model_path=None,
                    evaluation_state_capsule=active_capsule_record,
                    target_monitor_path=active_target_path,
                    target_monitor_artifact=active_target_artifact,
                    policy=evaluation_policy,
                    replay_monitor_path=active_replay_path,
                    replay_monitor_artifact=active_evaluation_replay_artifact,
                    training_replay_monitor_artifact=active_training_replay_artifact_bound,
                    training_replay_monitor_path=active_training_replay_path,
                    replay_baseline_model_path=active_baseline_model,
                    prediction_cache_directory=prediction_cache_directory,
                    graph_cache_directory=graph_cache_directory,
                    foundation_prediction_manifest=foundation_prediction_manifest,
                    foundation_prediction_root=foundation_prediction_root,
                )

            def infer_checkpoint(
                prepared: Any,
                *,
                active_checkpoint: Any = checkpoint,
                active_model_path: Path = model_path,
                active_capsule_record: Any = capsule_record,
                active_config_path: Path = config_path,
                active_job_root: Path = job_root,
                active_checkpoint_model_cache: Path = checkpoint_model_cache,
            ) -> Any:
                calculator_model = None
                if prepared.requires_candidate_inference:
                    # Model reconstruction/conversion is accelerator-admitted in
                    # OPT-EVAL4.  In particular, CuEq/OEq FX conversion can use
                    # CUDA and must not occur in an unmetered CPU preparation
                    # worker.
                    calculator_model = mdstats.materialize_mace_checkpoint_model(
                        active_checkpoint,
                        active_model_path,
                        mace_config_path=active_config_path,
                        job_working_directory=active_job_root,
                        cache_directory=active_checkpoint_model_cache,
                        wrapper_path=local_wrappers["mdstats-mace-train"],
                        allow_checkpoint_dtype_template_cast=False,
                        evaluation_state_capsule=active_capsule_record,
                    )
                return mdstats.run_prepared_mace_checkpoint_inference(
                    prepared,
                    calculator_model_path=calculator_model,
                )

            def finalize_checkpoint(prepared: Any, prediction_bundle: Any) -> Any:
                result = mdstats.finalize_prepared_mace_checkpoint_evaluation(
                    prepared, prediction_bundle
                )
                # Keep reconstructable checkpoint-model caches until this run is
                # selected. Immediate per-run export can then reuse the exact
                # model bytes instead of reconstructing the selected checkpoint a
                # second time. Non-selected caches are removed after export.
                return mdstats.bind_checkpoint_evaluation_replay_provenance(
                    result,
                    None
                    if prepared.replay_monitor_artifact is None
                    else prepared.replay_monitor_artifact.label_mode,
                    training_replay_monitor_artifact_digest=prepared.run_plan.replay_monitor_artifact_digest,
                )

            def commit_checkpoint_evaluation(
                result: Any,
                *,
                active_context: dict[str, Any] = context,
                checkpoint_sha256: str = checkpoint.sha256,
                record_key: str = key,
            ) -> None:
                store.put_record(record_key, result)
                active_context["evaluations_by_sha"][checkpoint_sha256] = result
                finalize_evaluated_run(active_context)

            pending_evaluation_tasks.append(
                _StagedEvaluationTask(
                    display_index=display_index,
                    key=task_result_key,
                    label=label,
                    start_detail="target/replay evaluation pipeline",
                    prepare=prepare_checkpoint,
                    requires_inference=lambda prepared: bool(prepared.requires_model_inference),
                    infer=infer_checkpoint,
                    finalize=finalize_checkpoint,
                    done_detail=lambda result, wall: (
                        f"force={result.metric_record.force_component_rmse_ev_per_angstrom * 1000:.1f} meV/A; "
                        f"elapsed={format_progress_time(wall)}"
                    ),
                    on_success=commit_checkpoint_evaluation,
                )
            )

        # Cached-only runs can be selected and exported before any new worker
        # starts. Runs with pending checkpoints finalize from their last success
        # callback while unrelated campaign evaluations continue.
        finalize_evaluated_run(context)

    _run_staged_evaluation_tasks(
        pending_evaluation_tasks,
        cfg=cfg,
        device=evaluation_policy.device,
        progress=checkpoint_progress,
    )

    # Cached-only contexts finalize before the worker queue starts; pending
    # contexts normally finalize from the last successful checkpoint callback.
    # This final pass is an idempotent durable reconciliation path.  In
    # particular, restarting ``evaluate`` after all checkpoint records exist but
    # before a parent-level model was published will publish it here immediately.
    for context in evaluation_contexts:
        finalize_evaluated_run(context)

    qualified_availabilities = _variant_availability(
        campaign,
        selections.keys(),
        training_mode=getattr(args, "training_mode", None),
        seed=getattr(args, "seed", None),
        selection_size=getattr(args, "selection_size", None),
    )
    rejected_run_count = len(runs_to_evaluate) - len(selections)
    if rejected_run_count:
        _warn(
            f"{rejected_run_count}/{len(runs_to_evaluate)} completed runs have no checkpoint "
            "that satisfies all frozen mandatory constraints in the evaluated candidate set; "
            "they are excluded from model export and verification."
        )
    if not qualified_availabilities:
        summary = {
            "schema": "mdstats.mlff-inadmissible-evaluation.v1",
            "campaign_plan_digest": campaign.content_digest,
            "completed_run_count": len(runs_to_evaluate),
            "qualified_run_count": 0,
            "rejected_run_count": rejected_run_count,
            "checkpoint_evaluations": total_checkpoints,
            "checkpoint_evaluations_available": total_original_checkpoints,
            "checkpoint_evaluations_reused": reused_count,
            "stale_checkpoint_evaluations_invalidated": stale_evaluation_count,
            "true_label_refresh_limited_runs": refresh_limited_runs,
            "true_label_refresh_unavailable_checkpoints": unavailable_refresh_checkpoints,
            "production_freeze_created": False,
            "precision": precision_profile,
        }
        store.put_record("interim_evaluation", summary)
        _atomic_json(paths.results / "interim-completed-model-evaluation.json", summary)
        _mark_stage(
            store, paths, "evaluate", StageState.WAITING,
            "completed checkpoint evaluation, but no admissible trained model is available",
        )
        raise CampaignCliError(
            "Checkpoint evaluation completed, but no completed run has an admissible "
            "checkpoint under the frozen acceptance policy. Inspect "
            "results/interim-completed-model-evaluation.json and the "
            "selection_failure:<run-id> records; do not weaken thresholds without a scientific review."
        )
    availabilities = qualified_availabilities
    if full_evaluation and len(selections) != len(campaign.runs):
        full_evaluation = False
        _warn(
            "The configured campaign finished training, but at least one run has no admissible "
            "checkpoint. Production protocol freeze is withheld; continuing with interim "
            "verification of the strongest admissible completed variant."
        )

    if not full_evaluation:
        (
            selected_availability,
            primary_metric_name,
            evidence_runs,
            primary_values,
            mean_primary,
            worst_primary,
        ) = _select_available_variant(availabilities, selections)
        warnings = list(_partial_evidence_warnings(selected_availability))
        if rejected_run_count:
            warnings.append(
                f"{rejected_run_count} completed run(s) were excluded because no evaluated checkpoint satisfied all mandatory constraints."
            )
        warnings = tuple(warnings)
        _print_header("Available-model verification export")
        for message in warnings:
            _warn(message)
        interim_root = paths.models / "interim"
        if interim_root.exists():
            shutil.rmtree(interim_root)
        interim_dir = interim_root / (
            f"{selected_availability.training_mode.value}-"
            f"n{selected_availability.selection_size}-seed{selected_availability.seed}"
        )
        members = []
        export_progress = _ProgressReporter(
            "EXPORT", len(selected_availability.completed_runs)
        )
        wrapper = _ensure_local_wrappers(paths)["mdstats-mace-select-head"]
        for export_index, run in enumerate(
            selected_availability.completed_runs, start=1
        ):
            export_progress.item_start(
                export_index, run.run_id, "interim target-head extraction"
            )
            selection = selections[run.content_digest]
            execution = execution_records[run.content_digest]
            catalog = _evaluation_checkpoint_catalog(
                store, run.run_id, execution
            )
            checkpoint = next(
                value
                for value in catalog.checkpoints
                if value.sha256 == selection.selected_checkpoint_sha256
            )
            source = Path(catalog.root_directory) / checkpoint.relative_path
            bundle, job, root = jobs[run.mace_job_artifact_digest]
            job_root = (root / job.relative_directory).resolve()
            config_path = (root / job.config_relative_path).resolve()
            model_source = mdstats.materialize_mace_checkpoint_model(
                checkpoint,
                source,
                mace_config_path=config_path,
                job_working_directory=job_root,
                cache_directory=paths.runs / run.run_id / "checkpoint-model-cache",
                wrapper_path=local_wrappers["mdstats-mace-train"],
                allow_checkpoint_dtype_template_cast=False,
            )
            output = interim_dir / f"{run.run_id}-target.model"
            try:
                member = mdstats.export_target_head_verification_model(
                    run,
                    selection,
                    source,
                    output,
                    source_model_path=model_source,
                    wrapper_path=wrapper,
                    deployment_dtype=deployment_dtype,
                )
            finally:
                if model_source.resolve() != source.resolve():
                    mdstats.remove_materialized_mace_checkpoint_model(model_source)
            members.append(member)
            store.put_record(f"interim_member:{run.run_id}", member)
            export_progress.item_done(
                export_index, run.run_id, output.name
            )
        scope_executions = {
            run.content_digest: execution_records[run.content_digest]
            for run in runs_to_evaluate
        }
        verification_set = mdstats.AvailableModelVerificationSet(
            campaign_plan_digest=campaign.content_digest,
            available_execution_digest=_available_execution_digest(
                scope_executions
            ),
            selected_protocol_family_digest=selected_availability.protocol_family_digest,
            selected_protocol_variant_digest=selected_availability.protocol_variant_digest,
            training_mode=selected_availability.training_mode,
            selection_size=selected_availability.selection_size,
            seed=selected_availability.seed,
            evidence_level=selected_availability.evidence_level,
            expected_cross_validation_folds=selected_availability.expected_fold_count,
            completed_cross_validation_folds=selected_availability.completed_fold_indices,
            final_development_completed=selected_availability.final_completed,
            completed_run_plan_digests=tuple(
                run.content_digest for run in selected_availability.completed_runs
            ),
            missing_run_plan_digests=tuple(
                run.content_digest for run in selected_availability.missing_runs
            ),
            evidence_run_plan_digests=tuple(
                run.content_digest for run in evidence_runs
            ),
            primary_metric_name=primary_metric_name,
            primary_metric_values=primary_values,
            mean_primary_metric=mean_primary,
            worst_primary_metric=worst_primary,
            members=tuple(members),
            warnings=warnings,
            created_at_utc=_utc_now(),
        )
        store.put_record("available_model_verification_set", verification_set)
        interim_summary = {
            "schema": "mdstats.mlff-interim-evaluation.v1",
            "campaign_plan_digest": campaign.content_digest,
            "available_execution_digest": verification_set.available_execution_digest,
            "training_filter": {
                "training_mode": getattr(args, "training_mode", None),
                "seed": getattr(args, "seed", None),
                "selection_size": getattr(args, "selection_size", None),
            },
            "completed_run_count": len(runs_to_evaluate),
            "qualified_run_count": len(selections),
            "rejected_run_count": rejected_run_count,
            "configured_run_count": len(campaign.runs),
            "selected_verification_set": verification_set.to_dict(),
            "selected_checkpoint_evaluations": {
                run.run_id: selected_evaluations[run.content_digest].to_dict()
                for run in selected_availability.completed_runs
                if run.content_digest in selected_evaluations
            },
            "checkpoint_evaluations": total_checkpoints,
            "checkpoint_evaluations_available": total_original_checkpoints,
            "checkpoint_evaluations_reused": reused_count,
            "stale_checkpoint_evaluations_invalidated": stale_evaluation_count,
            "true_label_refresh_limited_runs": refresh_limited_runs,
            "true_label_refresh_unavailable_checkpoints": unavailable_refresh_checkpoints,
            "checkpoint_shortlisting_enabled": total_checkpoints < total_original_checkpoints,
            "production_freeze_created": False,
        }
        store.put_record("interim_evaluation", interim_summary)
        _atomic_json(
            paths.results / "interim-completed-model-evaluation.json",
            interim_summary,
        )
        _update_benchmark(paths, "evaluate_interim", interim_summary)
        _mark_stage(
            store,
            paths,
            "evaluate",
            StageState.WAITING,
            (
                f"interim {verification_set.evidence_level.value} evidence for "
                f"{verification_set.training_mode.value} seed {verification_set.seed}; "
                f"{len(selections)} admissible of {len(runs_to_evaluate)} completed runs; "
                f"{len(runs_to_evaluate)}/{len(campaign.runs)} campaign runs complete"
            ),
        )
        print(
            f"\nInterim evidence: {verification_set.evidence_level.value}; "
            f"models exported: {len(verification_set.members)}",
            flush=True,
        )
        print(
            "Next: `verify` may test these completed models now; resume `train` "
            "later for the full configured campaign.",
            flush=True,
        )
        return 0

    for key in (
        "interim_evaluation",
        "available_model_verification_set",
        "interim_verification",
    ):
        store.delete_record(key)
    interim_root = paths.models / "interim"
    if interim_root.exists():
        shutil.rmtree(interim_root)

    _print_header("Protocol aggregation and committee export")
    variants = [
        mdstats.aggregate_protocol_variant(
            campaign, selections, selected_metrics, protocol_variant_digest=value
        )
        for value in sorted({v.protocol_variant_digest for v in campaign.runs})
    ]
    variants_by_family: dict[str, list[object]] = {}
    for variant in variants:
        variants_by_family.setdefault(variant.protocol_family_digest, []).append(variant)
    families = [
        mdstats.aggregate_protocol_family(variants_by_family[family])
        for family in sorted(variants_by_family)
    ]
    comparison = mdstats.compare_protocol_families(families)
    selected_family = next(
        v for v in families if v.content_digest == comparison.selected_family_aggregate_digest
    )
    store.put_records(
        {
            "protocol_comparison": comparison,
            "selected_family": selected_family,
        }
    )

    members = []
    final_selections = []
    selected_final_runs = [
        run for run in campaign.runs
        if run.protocol_family_digest == comparison.selected_protocol_family_digest
        and run.kind is mdstats.MaceJobKind.FINAL_DEVELOPMENT
    ]
    export_progress = _ProgressReporter("EXPORT", len(selected_final_runs))
    for export_index, run in enumerate(selected_final_runs, start=1):
        export_progress.item_start(export_index, run.run_id, "target-head extraction")
        selection = selections[run.content_digest]
        final_selections.append(selection)
        execution = store.get_record(
            f"execution:{run.run_id}", mdstats.TrainingRunExecutionRecord
        )
        export_catalog = _evaluation_checkpoint_catalog(
            store, run.run_id, execution
        )
        checkpoint = next(
            v for v in export_catalog.checkpoints
            if v.sha256 == selection.selected_checkpoint_sha256
        )
        source = Path(execution.checkpoint_catalog.root_directory) / checkpoint.relative_path
        bundle, job, root = jobs[run.mace_job_artifact_digest]
        job_root = (root / job.relative_directory).resolve()
        config_path = (root / job.config_relative_path).resolve()
        model_source = mdstats.materialize_mace_checkpoint_model(
            checkpoint,
            source,
            mace_config_path=config_path,
            job_working_directory=job_root,
            cache_directory=paths.runs / run.run_id / "checkpoint-model-cache",
            wrapper_path=local_wrappers["mdstats-mace-train"],
            allow_checkpoint_dtype_template_cast=False,
        )
        output = paths.models / f"{run.run_id}-target.model"
        try:
            member = mdstats.export_target_head_member(
                run,
                selection,
                source,
                output,
                source_model_path=model_source,
                wrapper_path=local_wrappers["mdstats-mace-select-head"],
                deployment_dtype=deployment_dtype,
            )
        finally:
            if model_source.resolve() != source.resolve():
                mdstats.remove_materialized_mace_checkpoint_model(model_source)
        members.append(member)
        store.put_record(f"committee_member:{run.run_id}", member)
        export_progress.item_done(export_index, run.run_id, output.name)
    committee = mdstats.build_committee_identity(
        campaign,
        comparison,
        members,
        policy=mdstats.CommitteeExportPolicy(
            minimum_members=len(selected_final_runs)
        ),
    )
    qualification = store.get_record(
        "production_qualification", mdstats.ProductionCorpusQualificationRecord
    )
    freeze = mdstats.freeze_training_protocol(
        qualification, campaign, comparison, selected_family, committee, final_selections
    )
    store.put_records(
        {
            "committee": committee,
            "protocol_freeze": freeze,
        }
    )
    summary = {
        "selected_training_mode": comparison.selected_training_mode.value,
        "precision": precision_profile,
        "selected_protocol_family_digest": comparison.selected_protocol_family_digest,
        "committee_members": [v.exported_model_path for v in committee.members],
        "protocol_freeze_digest": freeze.content_digest,
        "families": [v.to_dict() for v in families],
        "selected_checkpoint_evaluations": {
            run.run_id: selected_evaluations[run.content_digest].to_dict()
            for run in campaign.runs
            if run.content_digest in selected_evaluations
        },
        "checkpoint_evaluations": total_checkpoints,
        "checkpoint_evaluations_available": total_original_checkpoints,
        "checkpoint_evaluations_reused": reused_count,
        "stale_checkpoint_evaluations_invalidated": stale_evaluation_count,
        "true_label_refresh_limited_runs": refresh_limited_runs,
        "true_label_refresh_unavailable_checkpoints": unavailable_refresh_checkpoints,
        "checkpoint_shortlisting_enabled": total_checkpoints < total_original_checkpoints,
    }
    _atomic_json(paths.results / "fine-tuning-result.json", summary)
    _update_benchmark(paths, "evaluate", summary)
    _mark_stage(
        store, paths, "evaluate", StageState.COMPLETE,
        f"selected {comparison.selected_training_mode.value} and froze {len(members)}-member committee",
    )
    checkpoint_cleanup = _compact_evaluated_checkpoints(
        cfg, paths, store, campaign
    )
    _print_cleanup_report(checkpoint_cleanup)
    general_cleanup = _campaign_cleanup(
        cfg, paths, store, phase="evaluate-end", include_preparation_caches=True
    )
    _print_cleanup_report(general_cleanup)
    print(f"\nSelected protocol: {comparison.selected_training_mode.value}", flush=True)
    print(f"Committee models: {paths.models}", flush=True)
    print(
        f"Reused checkpoint evaluations: {reused_count}/{total_checkpoints}; "
        f"stale invalidated: {stale_evaluation_count}; "
        f"full-monitor candidates: {total_checkpoints}/{total_original_checkpoints}",
        flush=True,
    )
    print("Next: `verify`.", flush=True)
    return 0


_VERIFICATION_WORKER_LOCAL = threading.local()


def _minimum_distance(atoms: Any) -> float:
    """Return the exact nearest distinct-atom distance without an N x N matrix.

    The search uses ASE's periodic neighbor-list implementation with an
    adaptive radius.  As soon as at least one distinct pair is found, the
    minimum returned distance is globally exact: every omitted pair lies at or
    beyond the active search radius.  The final radius is bounded by the
    Cartesian bounding-box diagonal of wrapped positions, which always contains
    the direct displacement of every distinct pair and therefore guarantees a
    result for ``len(atoms) >= 2``.

    This keeps the common condensed-phase path near linear in atom count and
    removes verification's former dense periodic distance matrix.
    """
    import numpy as np
    from ase.neighborlist import neighbor_list

    n_atoms = len(atoms)
    if n_atoms < 2:
        raise ValueError("Minimum pair distance requires at least two atoms.")
    positions = np.asarray(atoms.get_positions(wrap=True), dtype=float)
    if positions.shape != (n_atoms, 3) or np.any(~np.isfinite(positions)):
        raise ValueError("Verification positions must be finite with shape (n_atoms, 3).")

    extent = np.ptp(positions, axis=0)
    guaranteed_radius = float(np.linalg.norm(extent))
    scale = max(1.0, guaranteed_radius, float(np.max(np.abs(positions), initial=0.0)))
    epsilon = max(1.0e-10, np.finfo(float).eps * scale * 256.0)
    guaranteed_radius = max(guaranteed_radius + epsilon, epsilon)

    # Most condensed-matter verification cells have a nearest pair below 2 A.
    # Starting there keeps the cell-list stencil local even for very large
    # replicated cells.  Sparse/pathological cells expand geometrically until
    # the guaranteed direct-displacement radius is reached.
    cutoff = min(2.0, guaranteed_radius)
    while True:
        first, second, distances = neighbor_list(
            "ijd", atoms, cutoff, self_interaction=False
        )
        first = np.asarray(first, dtype=np.int64)
        second = np.asarray(second, dtype=np.int64)
        distances = np.asarray(distances, dtype=float)
        distinct = first != second
        if np.any(distinct):
            accepted = distances[distinct]
            if np.any(~np.isfinite(accepted)):
                raise ValueError("Neighbor-list distance search produced non-finite values.")
            return float(np.min(accepted))
        if cutoff >= guaranteed_radius:
            # The direct Cartesian separation of every pair is <= the wrapped
            # bounding-box diagonal. Reaching this branch for n>=2 therefore
            # indicates a neighbor-list/runtime inconsistency rather than a
            # legitimate no-pair configuration.
            raise RuntimeError(
                "Periodic neighbor-list search did not return a distinct atom pair "
                "within the guaranteed direct-displacement radius."
            )
        cutoff = min(guaranteed_radius, max(cutoff * 2.0, cutoff + epsilon))


def _verification_calculator_cache_key(
    model_path: Path,
    *,
    device: str,
    dtype: str,
    acceleration_policy: Any,
    acceleration_realization_digest: str | None = None,
    resolved_acceleration_kernel_mode: str | None = None,
    critical_precision_policy: Any | None = None,
) -> tuple[str, ...]:
    return (
        str(model_path.resolve()),
        str(device),
        str(dtype),
        str(getattr(acceleration_policy, "policy_digest", repr(acceleration_policy))),
        str(acceleration_realization_digest or "legacy-unresolved-realization"),
        str(resolved_acceleration_kernel_mode or "legacy-policy-mode"),
        str(
            getattr(critical_precision_policy, "policy_digest", "legacy-critical-fp64")
            if critical_precision_policy is not None
            else "legacy-critical-fp64"
        ),
    )


def _worker_cached_nve_calculator(
    model_path: Path,
    *,
    device: str,
    dtype: str,
    acceleration_policy: Any,
    acceleration_realization_digest: str | None = None,
    resolved_acceleration_kernel_mode: str | None = None,
    critical_precision_policy: Any | None = None,
) -> tuple[Any, bool]:
    """Return one private calculator cached on the current verification worker.

    Only one calculator is retained per worker thread.  This bounds resident
    model state by the scheduler's worker count while reusing model
    deserialization/device transfer across adjacent structure/temperature cases.
    No mutable ASE/MACE calculator is shared between threads.
    """
    key = _verification_calculator_cache_key(
        model_path,
        device=device,
        dtype=dtype,
        acceleration_policy=acceleration_policy,
        acceleration_realization_digest=acceleration_realization_digest,
        resolved_acceleration_kernel_mode=resolved_acceleration_kernel_mode,
        critical_precision_policy=critical_precision_policy,
    )
    cached = getattr(_VERIFICATION_WORKER_LOCAL, "nve_calculator", None)
    if cached is not None and cached[0] == key:
        return cached[1], True
    calculator_kwargs: dict[str, Any] = {
        "device": device,
        "dtype": dtype,
        "acceleration_policy": acceleration_policy,
    }
    if resolved_acceleration_kernel_mode is not None:
        calculator_kwargs["resolved_acceleration_kernel_mode"] = resolved_acceleration_kernel_mode
    if critical_precision_policy is not None:
        calculator_kwargs["critical_precision_policy"] = critical_precision_policy
    calculator = _nve_calculator(model_path, **calculator_kwargs)
    _VERIFICATION_WORKER_LOCAL.nve_calculator = (key, calculator)
    return calculator, False


def _load_verification_structure_templates(
    structures: Sequence[Path],
) -> dict[str, Any]:
    """Parse immutable verification structures once in the parent thread."""
    from ase.io import read

    templates: dict[str, Any] = {}
    for structure in structures:
        atoms = read(structure)
        atoms.calc = None
        templates[str(structure)] = atoms
    return templates


@mace_runtime_warning_handled("bounded MACE NVE calculator construction")
def _nve_calculator(
    model_path: Path,
    *,
    device: str,
    dtype: str,
    acceleration_policy: Any,
    resolved_acceleration_kernel_mode: str | None = None,
    critical_precision_policy: Any | None = None,
) -> Any:
    import mdstats
    from mace.calculators import MACECalculator

    active_critical_precision = (
        mdstats.MaceCriticalPrecisionPolicy()
        if critical_precision_policy is None
        else critical_precision_policy
    )
    mdstats.activate_mace_critical_precision_policy(active_critical_precision)
    calculator_kwargs = (
        acceleration_policy.calculator_kwargs()
        if resolved_acceleration_kernel_mode is None
        else mdstats.MaceAccelerationKernelMode(resolved_acceleration_kernel_mode).calculator_kwargs()
    )
    return MACECalculator(
        model_paths=str(model_path),
        device=device,
        default_dtype=dtype,
        **calculator_kwargs,
    )


@mace_runtime_warning_handled("bounded MACE NVE verification")
def _nve_verify(
    model_path: Path,
    structure: Path,
    *,
    device: str,
    dtype: str,
    acceleration_policy: Any,
    acceleration_realization_digest: str | None = None,
    resolved_acceleration_kernel_mode: str | None = None,
    temperature: float,
    timestep_fs: float,
    steps: int,
    velocity_seed: int,
    critical_precision_policy: Any | None = None,
    sample_interval_steps: int = 10,
    calculator: Any | None = None,
    structure_atoms: Any | None = None,
    reuse_worker_calculator: bool = False,
) -> dict[str, Any]:
    import numpy as np
    from ase import units
    from ase.io import read
    from ase.md.velocitydistribution import MaxwellBoltzmannDistribution, Stationary, ZeroRotation
    from ase.md.verlet import VelocityVerlet
    report_inference_worker_phase("loading verification structure")
    atoms = read(structure) if structure_atoms is None else structure_atoms.copy()
    atoms.calc = None
    active_calculator = calculator
    calculator_reused = calculator is not None
    if active_calculator is None:
        # Model deserialization/device transfer dominates many short bounded-NVE
        # cases, so begin mixed-stage telemetry here rather than at the later
        # first force evaluation.
        mark_inference_workload_started("loading verification MACE model")
        if reuse_worker_calculator:
            active_calculator, calculator_reused = _worker_cached_nve_calculator(
                model_path,
                device=device,
                dtype=dtype,
                acceleration_policy=acceleration_policy,
                acceleration_realization_digest=acceleration_realization_digest,
                resolved_acceleration_kernel_mode=resolved_acceleration_kernel_mode,
                critical_precision_policy=critical_precision_policy,
            )
        else:
            active_calculator = _nve_calculator(
                model_path,
                device=device,
                dtype=dtype,
                acceleration_policy=acceleration_policy,
                resolved_acceleration_kernel_mode=resolved_acceleration_kernel_mode,
                critical_precision_policy=critical_precision_policy,
            )
            calculator_reused = False
    atoms.calc = active_calculator
    if calculator is not None or calculator_reused:
        mark_inference_workload_started("initializing verification dynamics")
    report_inference_worker_phase("initializing verification dynamics")
    rng = np.random.default_rng(int(velocity_seed))
    MaxwellBoltzmannDistribution(
        atoms, temperature_K=temperature, force_temp=True, rng=rng
    )
    Stationary(atoms)
    ZeroRotation(atoms)
    dynamics = VelocityVerlet(atoms, timestep=timestep_fs * units.fs)
    interval = max(1, int(sample_interval_steps))
    sample_steps = list(range(0, steps + 1, interval))
    if not sample_steps or sample_steps[-1] != steps:
        sample_steps.append(steps)
    times, energies, min_distances, max_forces = [], [], [], []
    current_step = 0
    report_inference_worker_phase("running bounded NVE trajectory")
    for sample_step in sample_steps:
        if sample_step > current_step:
            dynamics.run(sample_step - current_step)
            current_step = sample_step
        times.append(sample_step * timestep_fs / 1000.0)
        energies.append(float(atoms.get_total_energy()) / len(atoms))
        min_distances.append(_minimum_distance(atoms))
        max_forces.append(float(np.max(np.linalg.norm(atoms.get_forces(), axis=1))))
    report_inference_worker_phase("analyzing NVE stability metrics")
    slope = float(np.polyfit(np.asarray(times), np.asarray(energies), 1)[0]) if len(times) > 1 else 0.0
    return {
        "model": str(model_path),
        "structure": str(structure),
        "temperature_kelvin": temperature,
        "timestep_fs": timestep_fs,
        "steps": steps,
        "velocity_seed": int(velocity_seed),
        "sample_interval_steps": interval,
        "sample_count": len(sample_steps),
        "acceleration_backend": acceleration_policy.backend.value,
        "calculator_reused": bool(calculator_reused),
        "structure_template_reused": bool(structure_atoms is not None),
        "minimum_distance_backend": "periodic_neighbor_list_adaptive_v1",
        "energy_drift_ev_per_atom_per_ps": slope,
        "absolute_energy_drift_ev_per_atom_per_ps": abs(slope),
        "minimum_pair_distance_angstrom": min(min_distances),
        "maximum_force_ev_per_angstrom": max(max_forces),
        "finite": bool(np.isfinite(energies).all() and np.isfinite(max_forces).all()),
    }



def _adaptive_verification_policy(
    cfg: Mapping[str, Any], *, model_dtype: str
) -> Any:
    """Freeze ADAPT-VERIFY1 fallback and precision semantics."""
    import mdstats

    return mdstats.AdaptiveVerificationPolicy(
        fallback_to_next_admissible_candidate=bool(
            _cfg(
                cfg,
                "verification",
                "fallback_to_next_full_evaluation_candidate",
                True,
            )
        ),
        model_inference_dtype=str(model_dtype),
        scientific_analysis_dtype="float64",
    )


def _atomic_copy_file(source: Path, destination: Path) -> None:
    """Publish one verified immutable model by same-directory atomic replace."""
    destination.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary_name = tempfile.mkstemp(
        prefix=f".{destination.name}.", suffix=".tmp", dir=destination.parent
    )
    os.close(fd)
    temporary = Path(temporary_name)
    try:
        shutil.copy2(source, temporary)
        with temporary.open("rb") as handle:
            os.fsync(handle.fileno())
        os.replace(temporary, destination)
    finally:
        temporary.unlink(missing_ok=True)


def _adaptive_verification_case_results(
    store: CampaignStore,
    case_digests: Sequence[str],
) -> list[dict[str, Any]]:
    results: list[dict[str, Any]] = []
    for case_digest in case_digests:
        payload = store.get_payload_optional(f"verification_case:{case_digest}")
        if payload is None or payload.get("case_digest") != case_digest:
            raise CampaignCliError(
                "ADAPT-VERIFY1 verification-case evidence disappeared after the "
                "candidate decision was frozen."
            )
        results.append(dict(payload["result"]))
    return results


def _command_verify_adaptive_topk(
    args: argparse.Namespace,
    *,
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    model_dtype: str,
) -> int:
    """ADAPT-VERIFY1: verify ordered EVAL1 candidates and publish first passer."""
    import mdstats
    from .campaign_execution import _export_target_head_model_with_dtype

    evaluation = store.get_record_optional(
        "adaptive_full_evaluation", mdstats.AdaptiveFullEvaluationRecord
    )
    if evaluation is None:
        raise CampaignCliError(
            "ADAPT-VERIFY1 requires a completed authoritative ADAPT-EVAL1 record."
        )
    if evaluation.outcome != "admissible_candidates_available":
        raise CampaignCliError(
            "ADAPT-VERIFY1 cannot run because ADAPT-EVAL1 has no fully admissible candidate."
        )
    campaign = store.get_record("training_campaign", mdstats.TrainingCampaignPlan)
    if evaluation.campaign_plan_digest != campaign.content_digest:
        raise CampaignCliError("ADAPT-VERIFY1 campaign/full-evaluation lineage mismatch.")
    policy = _adaptive_verification_policy(cfg, model_dtype=model_dtype)
    candidates = mdstats.ordered_admissible_candidates(
        evaluation,
        fallback_to_next_admissible_candidate=policy.fallback_to_next_admissible_candidate,
    )

    existing = store.get_record_optional(
        "adaptive_verification", mdstats.AdaptiveVerificationRecord
    )
    if existing is not None:
        if (
            existing.campaign_plan_digest != campaign.content_digest
            or existing.adaptive_full_evaluation_digest != evaluation.content_digest
            or existing.verification_policy_digest != policy.policy_digest
        ):
            raise CampaignCliError(
                "Existing ADAPT-VERIFY1 evidence belongs to a different full-evaluation "
                "or verification policy. Refusing to reinterpret frozen verification evidence."
            )
        if existing.outcome == "no_candidate_passed":
            _mark_stage(
                store,
                paths,
                "verify",
                StageState.FAILED,
                "all authorized fully admissible ADAPT-EVAL1 candidates failed bounded verification",
            )
            return 1
        deployment = store.get_record_optional(
            "adaptive_deployment_model", mdstats.AdaptiveDeploymentModelRecord
        )
        freeze = store.get_record_optional(
            "adaptive_protocol_freeze", mdstats.AdaptiveProtocolFreezeRecord
        )
        if deployment is None or freeze is None:
            raise CampaignCliError(
                "ADAPT-VERIFY1 selected a candidate but deployment/freeze evidence is incomplete."
            )
        published = Path(deployment.exported_model_path)
        if not published.is_file() or _sha256(published) != deployment.exported_model_sha256:
            raise CampaignCliError(
                "Published adaptive deployment model is missing or changed after verification."
            )
        if freeze.adaptive_verification_digest != existing.content_digest:
            raise CampaignCliError("Adaptive protocol freeze/verification digest mismatch.")
        _reconcile_adaptive_migration(paths, store)
        _mark_stage(
            store,
            paths,
            "verify",
            StageState.COMPLETE,
            f"ADAPT-VERIFY1 already selected {deployment.run_id} epoch {deployment.checkpoint_epoch}",
        )
        _ok(
            f"reused verified deployment model: {published.name} "
            f"({deployment.model_inference_dtype} model inference; FP64 scientific arithmetic)"
        )
        return 0

    # Adaptive production never allows historical committee/freeze evidence to
    # choose a winner. A stale legacy committee in a new adaptive campaign is a
    # lineage conflict, not an alternative fallback source.
    if store.has_record("committee"):
        raise CampaignCliError(
            "ADAPT-VERIFY1 found legacy committee evidence in an adaptive_topk campaign. "
            "Refusing to let historical committee ranking determine the adaptive winner."
        )

    structures = list(args.structure or _cfg(cfg, "verification", "structures", ()))
    if not structures:
        raise CampaignCliError(
            "No verification structures were provided. Add [verification].structures or pass --structure."
        )
    resolved_structures = [_resolve_path(v, paths.config_dir) for v in structures]
    for structure in resolved_structures:
        if not structure.is_file():
            raise CampaignCliError(f"Verification structure not found: {structure}")
    temperatures = tuple(
        float(v)
        for v in _cfg(cfg, "verification", "temperatures_kelvin", (300.0, 700.0, 800.0))
    )
    if not temperatures:
        raise CampaignCliError("[verification].temperatures_kelvin must not be empty.")
    steps = int(
        args.steps
        if args.steps is not None
        else _cfg(cfg, "verification", "steps", 2000)
    )
    timestep = float(_cfg(cfg, "verification", "timestep_fs", 0.5))
    velocity_seed = int(_cfg(cfg, "verification", "velocity_seed", 314159))
    sample_interval_steps = int(_cfg(cfg, "verification", "sample_interval_steps", 10))
    drift_limit = float(
        _cfg(cfg, "verification", "maximum_energy_drift_ev_per_atom_per_ps", 0.026)
    )
    min_distance_limit = float(
        _cfg(cfg, "verification", "minimum_pair_distance_angstrom", 0.8)
    )
    max_force_limit = float(
        _cfg(cfg, "verification", "maximum_force_ev_per_angstrom", 100.0)
    )
    if steps <= 0 or timestep <= 0 or sample_interval_steps <= 0 or velocity_seed < 0:
        raise CampaignCliError("ADAPT-VERIFY1 verification integration settings are invalid.")

    device = str(
        _cfg(cfg, "verification", "device", _cfg(cfg, "training", "device", "cuda"))
    )
    acceleration = _acceleration_policy(cfg)
    critical_precision = _critical_precision_policy(cfg)
    precision_profile = _print_precision_profile(cfg)
    local_wrappers = _ensure_local_wrappers(paths)
    data8_entries = _current_data8_entries(store)
    jobs = _job_lookup(data8_entries)
    executions = _available_successful_executions(cfg, paths, store, campaign, jobs)
    runs = {run.content_digest: run for run in campaign.runs}
    first_run = runs.get(candidates[0].run_plan_digest)
    if first_run is None:
        raise CampaignCliError("ADAPT-VERIFY1 first candidate run is absent from campaign plan.")
    _first_bundle, first_job, _first_root = jobs[first_run.mace_job_artifact_digest]
    if first_job.protocol.adaptive_stop_policy is None:
        raise CampaignCliError("ADAPT-VERIFY1 cannot reconstruct the EVAL1 score policy.")
    full_policy = _adaptive_full_evaluation_policy(
        cfg, first_job.protocol.adaptive_stop_policy, _checkpoint_metric_policy(cfg)
    )
    if full_policy.policy_digest != evaluation.policy_digest:
        raise CampaignCliError(
            "ADAPT-VERIFY1 reconstructed full-evaluation policy differs from frozen EVAL1 evidence."
        )
    structure_sha256_by_path = {str(path): _sha256(path) for path in resolved_structures}
    structure_templates = _load_verification_structure_templates(resolved_structures)
    doctor_versions = (
        store.get_payload("doctor").get("versions", {})
        if store.has_record("doctor")
        else {}
    )
    verification_runtime_digest = digest(
        {
            "schema": "mdstats.mlff-adaptive-verification-runtime.v1",
            "mdstats_version": "0.20.132a0",
            "configured_mace_version": str(_cfg(cfg, "runtime", "mace_version", "0.3.16")),
            "doctor_versions": doctor_versions,
        }
    )
    qualification = store.get_record(
        "production_qualification", mdstats.ProductionCorpusQualificationRecord
    )
    candidate_root = paths.internal / "verification-candidates"
    candidate_root.mkdir(parents=True, exist_ok=True)
    attempts: list[Any] = []
    selected_candidate = None
    selected_candidate_model = None
    selected_target_head = None

    _mark_stage(
        store,
        paths,
        "verify",
        StageState.RUNNING,
        f"ADAPT-VERIFY1 testing {len(candidates)} fully admissible EVAL1 candidate(s) in score order",
    )
    _print_header("ADAPT-VERIFY1 ordered deployment verification")

    for candidate_index, candidate in enumerate(candidates, start=1):
        run = runs.get(candidate.run_plan_digest)
        if run is None:
            raise CampaignCliError("ADAPT-VERIFY1 candidate run is absent from campaign plan.")
        execution = executions.get(run.content_digest)
        if execution is None:
            raise CampaignCliError(f"{run.run_id}: successful execution evidence is unavailable.")
        bundle, job, root = jobs[run.mace_job_artifact_digest]
        stop_policy = job.protocol.adaptive_stop_policy
        if stop_policy is None:
            raise CampaignCliError(f"{run.run_id}: adaptive stop/target-head identity is missing.")
        target_head_name = str(stop_policy.target_head_name)
        catalog = _evaluation_checkpoint_catalog(store, run.run_id, execution)
        checkpoint = next(
            (
                item
                for item in catalog.checkpoints
                if item.sha256 == candidate.checkpoint_sha256
                and item.epoch == candidate.checkpoint_epoch
            ),
            None,
        )
        if checkpoint is None:
            raise CampaignCliError(
                f"{run.run_id}: selected EVAL1 checkpoint is absent from the frozen catalog."
            )
        full_eval_record = store.get_record_optional(
            f"adaptive_full_evaluation:{run.run_id}:{checkpoint.sha256}",
            mdstats.CheckpointEvaluationRecord,
        )
        if (
            full_eval_record is None
            or full_eval_record.content_digest != candidate.evaluation_record_digest
        ):
            raise CampaignCliError(
                f"{run.run_id}: authoritative full-evaluation metric evidence is missing or changed."
            )

        attempt_key = f"adaptive_verification_candidate:{run.run_id}:{checkpoint.sha256}"
        attempt = store.get_record_optional(
            attempt_key, mdstats.AdaptiveVerificationCandidateRecord
        )
        candidate_dir = candidate_root / f"rank-{candidate.finalist_rank:03d}-{checkpoint.sha256[:12]}"
        temporary_model = candidate_dir / "target.model"
        candidate_model_sha256 = None
        if attempt is not None:
            expected_identity = (
                attempt.adaptive_full_evaluation_digest == evaluation.content_digest
                and attempt.verification_policy_digest == policy.policy_digest
                and attempt.full_evaluation_candidate_digest == candidate.content_digest
                and attempt.run_plan_digest == run.content_digest
                and attempt.checkpoint_sha256 == checkpoint.sha256
                and attempt.checkpoint_epoch == checkpoint.epoch
                and attempt.model_inference_dtype == model_dtype
                and attempt.scientific_analysis_dtype == "float64"
            )
            if not expected_identity:
                raise CampaignCliError(
                    f"{run.run_id}: existing ADAPT-VERIFY1 candidate evidence disagrees with current immutable lineage."
                )
            attempts.append(attempt)
            _ok(
                f"candidate {candidate_index}/{len(candidates)} rank {candidate.finalist_rank}: "
                f"reused {'PASS' if attempt.passed else 'FAIL'} verification evidence"
            )
            if attempt.passed:
                # Reconstruct the exact passing target-head artifact if the parent
                # died after verification but before publication.
                candidate_model_sha256 = attempt.candidate_model_sha256
                if not temporary_model.is_file() or _sha256(temporary_model) != candidate_model_sha256:
                    temporary_model.parent.mkdir(parents=True, exist_ok=True)
                    source, capsule = _checkpoint_source_for_evaluation(
                        paths, store, run.run_id, checkpoint, execution.checkpoint_catalog
                    )
                    job_root = (root / job.relative_directory).resolve()
                    config_path = (root / job.config_relative_path).resolve()
                    model_source = mdstats.materialize_mace_checkpoint_model(
                        checkpoint,
                        source,
                        mace_config_path=config_path,
                        job_working_directory=job_root,
                        cache_directory=paths.runs / run.run_id / "checkpoint-model-cache",
                        wrapper_path=local_wrappers["mdstats-mace-train"],
                        allow_checkpoint_dtype_template_cast=False,
                        evaluation_state_capsule=capsule,
                    )
                    try:
                        _export_target_head_model_with_dtype(
                            model_source,
                            temporary_model,
                            target_head_name=target_head_name,
                            target_device="cpu",
                            wrapper_path=local_wrappers["mdstats-mace-select-head"],
                            required_wrapper="mdstats-mace-select-head",
                            failure_prefix="ADAPT-VERIFY1 target-head materialization",
                            deployment_dtype=model_dtype,
                        )
                    finally:
                        if Path(model_source).resolve() != Path(source).resolve():
                            mdstats.remove_materialized_mace_checkpoint_model(model_source)
                    if _sha256(temporary_model) != candidate_model_sha256:
                        raise CampaignCliError(
                            f"{run.run_id}: regenerated passing candidate model bytes disagree with frozen verification evidence."
                        )
                selected_candidate = candidate
                selected_candidate_model = temporary_model
                selected_target_head = target_head_name
                break
            if not policy.fallback_to_next_admissible_candidate:
                break
            continue

        source, capsule = _checkpoint_source_for_evaluation(
            paths, store, run.run_id, checkpoint, execution.checkpoint_catalog
        )
        if not source.is_file():
            raise CampaignCliError(
                f"{run.run_id}: source checkpoint/capsule is unavailable for verification."
            )
        candidate_dir.mkdir(parents=True, exist_ok=True)
        job_root = (root / job.relative_directory).resolve()
        config_path = (root / job.config_relative_path).resolve()
        model_source = mdstats.materialize_mace_checkpoint_model(
            checkpoint,
            source,
            mace_config_path=config_path,
            job_working_directory=job_root,
            cache_directory=paths.runs / run.run_id / "checkpoint-model-cache",
            wrapper_path=local_wrappers["mdstats-mace-train"],
            allow_checkpoint_dtype_template_cast=False,
            evaluation_state_capsule=capsule,
        )
        try:
            _export_target_head_model_with_dtype(
                model_source,
                temporary_model,
                target_head_name=target_head_name,
                target_device="cpu",
                wrapper_path=local_wrappers["mdstats-mace-select-head"],
                required_wrapper="mdstats-mace-select-head",
                failure_prefix="ADAPT-VERIFY1 target-head materialization",
                deployment_dtype=model_dtype,
            )
        finally:
            if Path(model_source).resolve() != Path(source).resolve():
                mdstats.remove_materialized_mace_checkpoint_model(model_source)
        candidate_model_sha256 = _sha256(temporary_model)

        cases: list[dict[str, Any]] = []
        pending: list[_AdaptiveInferenceTask] = []
        progress = _ProgressReporter(
            f"VERIFY candidate rank {candidate.finalist_rank}",
            len(resolved_structures) * len(temperatures),
        )
        case_index = 0
        for structure in resolved_structures:
            for temperature in temperatures:
                case_index += 1
                identity = {
                    "schema": "mdstats.mlff-adaptive-verification-case-identity.v1",
                    "adaptive_full_evaluation_digest": evaluation.content_digest,
                    "full_evaluation_candidate_digest": candidate.content_digest,
                    "checkpoint_sha256": checkpoint.sha256,
                    "candidate_model_sha256": candidate_model_sha256,
                    "structure_sha256": structure_sha256_by_path[str(structure)],
                    "temperature_kelvin": temperature,
                    "timestep_fs": timestep,
                    "steps": steps,
                    "sample_interval_steps": sample_interval_steps,
                    "velocity_seed": velocity_seed,
                    "device": device,
                    "model_inference_dtype": model_dtype,
                    "scientific_analysis_dtype": "float64",
                    "acceleration_policy_digest": acceleration.policy_digest,
                    **_evaluation_acceleration_binding(cfg, paths),
                    "critical_precision_policy_digest": critical_precision.policy_digest,
                    "runtime_digest": verification_runtime_digest,
                }
                case_digest = _verification_case_digest(identity)
                cache_key = f"verification_case:{case_digest}"
                cached = store.get_payload_optional(cache_key)
                if cached is not None and cached.get("case_digest") == case_digest:
                    cases.append({"case_digest": case_digest, "result": dict(cached["result"])})
                    progress.item_start(case_index, f"{structure.name}:{temperature:g}K", "cached")
                    progress.item_done(case_index, f"{structure.name}:{temperature:g}K", "reused")
                    continue

                def execute_case(
                    *,
                    active_structure: Path = structure,
                    active_structure_atoms: Any = structure_templates[str(structure)],
                    active_temperature: float = temperature,
                    active_model: Path = temporary_model,
                ) -> dict[str, Any]:
                    return _nve_verify(
                        active_model,
                        active_structure,
                        device=device,
                        dtype=model_dtype,
                        acceleration_policy=acceleration,
                        **_evaluation_acceleration_binding(cfg, paths),
                        critical_precision_policy=critical_precision,
                        temperature=active_temperature,
                        timestep_fs=timestep,
                        steps=steps,
                        velocity_seed=velocity_seed,
                        sample_interval_steps=sample_interval_steps,
                        calculator=None,
                        structure_atoms=active_structure_atoms,
                        reuse_worker_calculator=True,
                    )

                pending.append(
                    _AdaptiveInferenceTask(
                        display_index=case_index,
                        key=case_digest,
                        label=f"{structure.name}:{temperature:g}K",
                        start_detail=f"rank {candidate.finalist_rank} full NVE",
                        execute=execute_case,
                        done_detail=lambda value, wall: (
                            f"drift={value['absolute_energy_drift_ev_per_atom_per_ps']*1000:.2f} meV/atom/ps, "
                            f"r_min={value['minimum_pair_distance_angstrom']:.2f} A, "
                            f"elapsed={format_progress_time(wall)}"
                        ),
                        on_success=lambda value, active_cache_key=cache_key,
                        active_case_digest=case_digest, active_identity=identity: store.put_record(
                            active_cache_key,
                            {
                                "schema": "mdstats.mlff-verification-case-cache.v1",
                                "case_digest": active_case_digest,
                                "identity": active_identity,
                                "result": value,
                                "created_at_utc": _utc_now(),
                            },
                        ),
                    )
                )
        completed = _run_adaptive_inference_tasks(
            pending,
            cfg=cfg,
            phase="verification",
            device=device,
            progress=progress,
        )
        for task in pending:
            cases.append({"case_digest": task.key, "result": dict(completed[task.key])})
        cases.sort(key=lambda item: item["case_digest"])
        reasons = mdstats.verification_rejection_reasons(
            [item["result"] for item in cases],
            maximum_energy_drift_ev_per_atom_per_ps=drift_limit,
            minimum_pair_distance_angstrom=min_distance_limit,
            maximum_force_ev_per_angstrom=max_force_limit,
        )
        attempt = mdstats.AdaptiveVerificationCandidateRecord(
            adaptive_full_evaluation_digest=evaluation.content_digest,
            verification_policy_digest=policy.policy_digest,
            full_evaluation_candidate_digest=candidate.content_digest,
            finalist_rank=candidate.finalist_rank,
            finalist_batch_index=candidate.finalist_batch_index,
            run_plan_digest=run.content_digest,
            run_id=run.run_id,
            checkpoint_sha256=checkpoint.sha256,
            checkpoint_epoch=checkpoint.epoch,
            full_score_ev_per_angstrom=candidate.full_score_ev_per_angstrom,
            target_force_rmse_ev_per_angstrom=candidate.target_force_rmse_ev_per_angstrom,
            replay_force_rmse_ev_per_angstrom=candidate.replay_force_rmse_ev_per_angstrom,
            candidate_model_sha256=candidate_model_sha256,
            model_inference_dtype=model_dtype,
            scientific_analysis_dtype="float64",
            verification_case_digests=tuple(item["case_digest"] for item in cases),
            passed=not reasons,
            rejection_reasons=reasons,
        )
        store.put_record(attempt_key, attempt)
        attempts.append(attempt)
        if attempt.passed:
            _ok(
                f"candidate rank {candidate.finalist_rank} PASS: {run.run_id} epoch {checkpoint.epoch}; "
                f"full score={candidate.full_score_ev_per_angstrom*1000:.2f} meV/A"
            )
            selected_candidate = candidate
            selected_candidate_model = temporary_model
            selected_target_head = target_head_name
            break
        _fail(
            f"candidate rank {candidate.finalist_rank} FAIL: {run.run_id} epoch {checkpoint.epoch}; "
            + ", ".join(reasons)
        )
        temporary_model.unlink(missing_ok=True)
        if not policy.fallback_to_next_admissible_candidate:
            break

    if selected_candidate is None or selected_candidate_model is None or selected_target_head is None:
        record = mdstats.AdaptiveVerificationRecord(
            campaign_plan_digest=campaign.content_digest,
            adaptive_full_evaluation_digest=evaluation.content_digest,
            verification_policy_digest=policy.policy_digest,
            attempts=tuple(attempts),
            outcome="no_candidate_passed",
            selected_attempt_digest=None,
        )
        store.put_record("adaptive_verification", record)
        payload = {
            **record.to_dict(),
            "precision": precision_profile,
            "model_inference_dtype": model_dtype,
            "scientific_analysis_dtype": "float64",
            "full_evaluation_policy": full_policy.to_dict(),
            "verification_attempt_details": [
                {
                    "attempt": attempt.to_dict(),
                    "cases": _adaptive_verification_case_results(
                        store, attempt.verification_case_digests
                    ),
                }
                for attempt in attempts
            ],
            "thresholds": {
                "maximum_energy_drift_ev_per_atom_per_ps": drift_limit,
                "minimum_pair_distance_angstrom": min_distance_limit,
                "maximum_force_ev_per_angstrom": max_force_limit,
            },
            "published_model": None,
        }
        _atomic_json(paths.results / "production-verification.json", payload)
        _mark_stage(
            store,
            paths,
            "verify",
            StageState.FAILED,
            f"ADAPT-VERIFY1 exhausted {len(attempts)} authorized candidate(s) without a verification pass",
        )
        return 1

    selected_attempt = attempts[-1]
    record = mdstats.AdaptiveVerificationRecord(
        campaign_plan_digest=campaign.content_digest,
        adaptive_full_evaluation_digest=evaluation.content_digest,
        verification_policy_digest=policy.policy_digest,
        attempts=tuple(attempts),
        outcome="verified_candidate_selected",
        selected_attempt_digest=selected_attempt.content_digest,
    )
    selected_run = runs[selected_candidate.run_plan_digest]
    published = paths.models / (
        f"selected-{selected_run.run_id}-epoch-{selected_candidate.checkpoint_epoch}-target.model"
    )
    _atomic_copy_file(selected_candidate_model, published)
    published_sha = _sha256(published)
    if published_sha != selected_attempt.candidate_model_sha256:
        raise CampaignCliError("Published adaptive deployment model changed during atomic promotion.")
    # The verified bytes are now protected in models/. Internal candidate
    # materialization is reconstructable and must not look like a second
    # published model.
    selected_candidate_model.unlink(missing_ok=True)
    try:
        selected_candidate_model.parent.rmdir()
    except OSError:
        pass
    deployment = mdstats.AdaptiveDeploymentModelRecord(
        campaign_plan_digest=campaign.content_digest,
        adaptive_full_evaluation_digest=evaluation.content_digest,
        adaptive_verification_digest=record.content_digest,
        selected_full_evaluation_candidate_digest=selected_candidate.content_digest,
        selected_verification_attempt_digest=selected_attempt.content_digest,
        run_plan_digest=selected_run.content_digest,
        run_id=selected_run.run_id,
        checkpoint_sha256=selected_candidate.checkpoint_sha256,
        checkpoint_epoch=selected_candidate.checkpoint_epoch,
        target_head_name=selected_target_head,
        model_inference_dtype=model_dtype,
        scientific_analysis_dtype="float64",
        exported_model_path=str(published.resolve()),
        exported_model_sha256=published_sha,
        byte_size=published.stat().st_size,
    )
    freeze = mdstats.AdaptiveProtocolFreezeRecord(
        production_qualification_digest=qualification.content_digest,
        campaign_plan_digest=campaign.content_digest,
        adaptive_full_evaluation_digest=evaluation.content_digest,
        adaptive_verification_digest=record.content_digest,
        adaptive_deployment_model_digest=deployment.content_digest,
        selected_full_evaluation_candidate_digest=selected_candidate.content_digest,
        full_target_artifact_digest=evaluation.full_target_artifact_digest,
        full_replay_artifact_digest=evaluation.full_replay_artifact_digest,
        exported_model_sha256=published_sha,
        model_inference_dtype=model_dtype,
        scientific_analysis_dtype="float64",
        frozen_at_utc=_utc_now(),
    )
    authority = mdstats.protocol_freeze_authority_from_adaptive(freeze)
    store.put_records(
        {
            "adaptive_verification": record,
            "adaptive_deployment_model": deployment,
            "adaptive_protocol_freeze": freeze,
            # Generic lifecycle consumers bind to an explicit schema-neutral
            # authority adapter; the scientific adaptive freeze remains intact
            # under adaptive_protocol_freeze.
            "protocol_freeze": authority,
        }
    )
    migration = _reconcile_adaptive_migration(paths, store)

    full_eval_metric = store.get_record(
        f"adaptive_full_evaluation:{selected_run.run_id}:{selected_candidate.checkpoint_sha256}",
        mdstats.CheckpointEvaluationRecord,
    )
    target_metrics = full_eval_metric.target_candidate_metrics
    replay_metrics = full_eval_metric.replay_candidate_metrics
    payload = {
        **record.to_dict(),
        "selected_model": deployment.to_dict(),
        "adaptive_protocol_freeze": freeze.to_dict(),
        "adaptive_migration": None if migration is None else migration.to_dict(),
        "precision": precision_profile,
        "model_inference_dtype": model_dtype,
        "scientific_analysis_dtype": "float64",
        "acceleration_policy": acceleration.to_dict(),
        "fallback_count": max(0, len(attempts) - 1),
        "full_evaluation_policy": full_policy.to_dict(),
        "verification_attempt_details": [
            {
                "attempt": attempt.to_dict(),
                "cases": _adaptive_verification_case_results(
                    store, attempt.verification_case_digests
                ),
            }
            for attempt in attempts
        ],
        "full_evaluation": {
            "finalist_rank": selected_candidate.finalist_rank,
            "finalist_batch_index": selected_candidate.finalist_batch_index,
            "target_force_rmse_ev_per_angstrom": selected_candidate.target_force_rmse_ev_per_angstrom,
            "replay_force_rmse_ev_per_angstrom": selected_candidate.replay_force_rmse_ev_per_angstrom,
            "full_score_ev_per_angstrom": selected_candidate.full_score_ev_per_angstrom,
            "replay_foundation_force_rmse_ev_per_angstrom": selected_candidate.replay_foundation_force_rmse_ev_per_angstrom,
            "replay_absolute_degradation_ev_per_angstrom": selected_candidate.replay_absolute_degradation_ev_per_angstrom,
            "replay_fractional_degradation": selected_candidate.replay_fractional_degradation,
            "target_energy_mae_ev_per_atom": None if target_metrics is None else target_metrics.energy_mae_ev_per_atom,
            "target_stress_rmse_ev_per_angstrom3": None if target_metrics is None else target_metrics.stress_rmse_ev_per_angstrom3,
            "target_focus_force_rmse_ev_per_angstrom": None if target_metrics is None else list(target_metrics.focus_force_rmse_ev_per_angstrom),
            "target_worst_condition_force_rmse_ev_per_angstrom": None if target_metrics is None else target_metrics.worst_condition_force_rmse_ev_per_angstrom,
            "target_configuration_count": None if target_metrics is None else target_metrics.configuration_count,
            "replay_configuration_count": None if replay_metrics is None else replay_metrics.configuration_count,
            "full_target_artifact_digest": evaluation.full_target_artifact_digest,
            "full_replay_artifact_digest": evaluation.full_replay_artifact_digest,
        },
        "verification_thresholds": {
            "maximum_energy_drift_ev_per_atom_per_ps": drift_limit,
            "minimum_pair_distance_angstrom": min_distance_limit,
            "maximum_force_ev_per_angstrom": max_force_limit,
        },
        "committee_handling": "adaptive_single_verified_deployment; legacy committee ranking not used",
        "passed": True,
    }
    _atomic_json(paths.results / "production-verification.json", payload)
    store.put_record("production_verification", payload)
    _update_benchmark(
        paths,
        "verify",
        {
            "passed": True,
            "adaptive_verify1": True,
            "attempted_candidate_count": len(attempts),
            "fallback_count": max(0, len(attempts) - 1),
            "selected_finalist_rank": selected_candidate.finalist_rank,
            "model_inference_dtype": model_dtype,
            "scientific_analysis_dtype": "float64",
        },
    )
    _mark_stage(
        store,
        paths,
        "verify",
        StageState.COMPLETE,
        f"ADAPT-VERIFY1 selected finalist rank {selected_candidate.finalist_rank}: "
        f"{selected_run.run_id} epoch {selected_candidate.checkpoint_epoch}",
    )
    cleanup_report = _campaign_cleanup(
        cfg, paths, store, phase="verify-end", include_preparation_caches=True
    )
    _print_cleanup_report(cleanup_report)
    print(
        "\nADAPT-VERIFY1 deployment verification passed. "
        f"Published {published.name} after {len(attempts)} candidate attempt(s). "
        "This bounded stability gate is still not a substitute for matched scientific observable validation.",
        flush=True,
    )
    return 0


def _mlcv_verification_policy(
    cfg: Mapping[str, Any], *, model_dtype: str
) -> Any:
    """Freeze MLCV-VERIFY1 fallback, locked-E, and precision semantics."""
    import mdstats

    retained = _checkpoint_metric_policy(cfg)
    return mdstats.MlcvVerificationPolicy(
        fallback_to_next_qualified_final_seed=bool(
            _cfg(
                cfg,
                "verification",
                "fallback_to_next_qualified_final_seed",
                _cfg(
                    cfg,
                    "verification",
                    "fallback_to_next_full_evaluation_candidate",
                    True,
                ),
            )
        ),
        model_inference_dtype=str(model_dtype),
        scientific_analysis_dtype="float64",
        maximum_target_force_rmse_ev_per_angstrom=float(
            _cfg(cfg, "acceptance", "maximum_target_force_rmse_ev_per_angstrom", 0.030)
        ),
        maximum_energy_drift_ev_per_atom_per_ps=float(
            _cfg(cfg, "verification", "maximum_energy_drift_ev_per_atom_per_ps", 0.026)
        ),
        minimum_pair_distance_angstrom=float(
            _cfg(cfg, "verification", "minimum_pair_distance_angstrom", 0.8)
        ),
        maximum_force_ev_per_angstrom=float(
            _cfg(cfg, "verification", "maximum_force_ev_per_angstrom", 100.0)
        ),
        retained_checkpoint_metric_policy_digest=retained.policy_digest,
    )


def _mlcv_locked_test_artifact(
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    *,
    verification: Any,
) -> tuple[Any, Any, Path]:
    """Activate/materialize locked E only after physical candidate freeze."""
    import mdstats

    if verification.outcome != "physical_candidate_frozen":
        raise CampaignCliError("Locked E cannot activate before physical verification freezes one candidate.")
    entries = _current_data8_entries(store)
    sealed_by_digest: dict[str, Any] = {}
    bundle_by_sealed: dict[str, Any] = {}
    for entry in entries:
        for sealed in entry.bundle.sealed_outer_evaluations:
            if sealed.role != "locked_interpolation_test":
                continue
            sealed_by_digest[sealed.content_digest] = sealed
            bundle_by_sealed[sealed.content_digest] = entry.bundle
    if not sealed_by_digest:
        raise CampaignCliError("MLCV-VERIFY1 requires the DATA8 locked_interpolation_test E artifact.")
    identities = {
        (
            value.role,
            value.label_domain_id,
            value.frame_uids,
            value.frame_catalog_digest,
            value.data5_bundle_digest,
        )
        for value in sealed_by_digest.values()
    }
    if len(identities) != 1:
        raise CampaignCliError("DATA8 variants disagree on the sealed locked-E identity.")
    sealed = next(iter(sealed_by_digest.values()))
    bundle = bundle_by_sealed[sealed.content_digest]
    mdstats.require_mlcv_role(
        mdstats.MlcvDataRole.TARGET_LOCKED_TEST,
        mdstats.MlcvEvidenceOperation.LOCKED_TEST_EVALUATION,
        context="MLCV-VERIFY1 locked E activation",
    )
    sources, frames, _data4, data5 = _load_prepared(store, include_data4=False)
    if sealed.frame_catalog_digest != frames.content_digest or sealed.data5_bundle_digest != data5.content_digest:
        raise CampaignCliError("Locked-E DATA5/frame-catalog lineage differs from the sealed DATA8 authority.")
    frame_data = _load_or_rebuild_frame_data(cfg, paths, sources)
    root = paths.internal / "mlcv-verify1" / "locked-test-E"
    artifact = mdstats.write_mace_extxyz_artifact(
        root,
        dataset_id=str(bundle.dataset_id),
        role="locked_postfreeze_test_E",
        filename="locked-E.extxyz",
        frame_uids=sealed.frame_uids,
        frame_catalog=frames,
        frame_data_by_run=frame_data,
        data7_bundle=None,
        policy=mdstats.MaceExtxyzPolicy(),
    )
    target = (root / artifact.relative_path).resolve()
    if not target.is_file() or _sha256(target) != artifact.sha256:
        raise CampaignCliError("Locked-E materialization failed authentication.")
    return sealed, artifact, target


def _command_verify_mlcv(
    args: argparse.Namespace,
    *,
    cfg: Mapping[str, Any],
    paths: CampaignPaths,
    store: CampaignStore,
    campaign: Any,
    model_dtype: str,
) -> int:
    """MLCV-VERIFY1: physical fallback, one-shot locked E, then publication."""
    import mdstats

    final_selection = store.get_record("mlcv_final_selection", mdstats.MlcvFinalSelectionRecord)
    committee = store.get_record("mlcv_final_committee", mdstats.MlcvFinalCommitteeRecord)
    if final_selection.campaign_plan_digest != campaign.content_digest or committee.campaign_plan_digest != campaign.content_digest:
        raise CampaignCliError("MLCV-VERIFY1 FINAL1/campaign lineage mismatch.")
    if committee.final_selection_record_digest != final_selection.content_digest:
        raise CampaignCliError("MLCV-VERIFY1 committee does not belong to the frozen FINAL1 selection.")
    if final_selection.outcome != "production_candidate_selected":
        raise CampaignCliError("MLCV-VERIFY1 requires one FINAL1 production verification candidate.")

    policy = _mlcv_verification_policy(cfg, model_dtype=model_dtype)
    store.put_record("mlcv_verification_policy", policy)
    retained_metric_policy = _checkpoint_metric_policy(cfg)
    if (
        policy.retained_checkpoint_metric_policy_digest is not None
        and retained_metric_policy.policy_digest != policy.retained_checkpoint_metric_policy_digest
    ):
        raise CampaignCliError("MLCV-VERIFY1 retained metric policy changed after FINAL1.")

    existing_production = store.get_record_optional("mlcv_production_model", mdstats.MlcvProductionModelRecord)
    existing_locked = store.get_record_optional("mlcv_locked_test", mdstats.MlcvLockedTestRecord)
    existing_verification = store.get_record_optional("mlcv_verification", mdstats.MlcvVerificationRecord)
    if existing_production is not None:
        published = Path(existing_production.exported_model_path)
        if not published.is_file() or _sha256(published) != existing_production.exported_model_sha256:
            raise CampaignCliError("Published MLCV production model bytes changed after VERIFY1.")
        if existing_locked is None or not existing_locked.passed or existing_production.locked_test_record_digest != existing_locked.content_digest:
            raise CampaignCliError("MLCV production publication is missing its passing locked-E authority.")
        migration = _reconcile_mlcv_migration(paths, store, campaign)
        if migration is None:
            raise CampaignCliError("Completed MLCV production evidence could not be closed under MIGRATE1 authority.")
        _mark_stage(store, paths, "verify", StageState.COMPLETE, "MLCV-VERIFY1 production evidence reused; MIGRATE1 authority closed")
        _ok(f"MLCV-VERIFY1: reused verified production model {published.name}; MIGRATE1 authority is closed")
        return 0
    if existing_locked is not None and not existing_locked.passed:
        _mark_stage(store, paths, "verify", StageState.FAILED, "MLCV locked E previously failed; fallback/reselection forbidden")
        _warn("MLCV-VERIFY1: locked E already failed. The frozen model cannot be replaced using E; create/review a new protocol instead.")
        return 1

    _mark_stage(store, paths, "verify", StageState.RUNNING, "MLCV-VERIFY1 physical verification")
    _print_precision_profile(cfg)
    structures = list(args.structure or _cfg(cfg, "verification", "structures", ()))
    if not structures:
        raise CampaignCliError("No verification structures were provided. Add [verification].structures or pass --structure.")
    resolved_structures = tuple(_resolve_path(v, paths.config_dir) for v in structures)
    for structure in resolved_structures:
        if not structure.is_file():
            raise CampaignCliError(f"Verification structure not found: {structure}")
    temperatures = tuple(float(v) for v in _cfg(cfg, "verification", "temperatures_kelvin", (300.0, 700.0, 800.0)))
    if not temperatures:
        raise CampaignCliError("[verification].temperatures_kelvin must not be empty.")
    steps = int(args.steps if args.steps is not None else _cfg(cfg, "verification", "steps", 2000))
    timestep = float(_cfg(cfg, "verification", "timestep_fs", 0.5))
    velocity_seed = int(_cfg(cfg, "verification", "velocity_seed", 314159))
    sample_interval_steps = int(_cfg(cfg, "verification", "sample_interval_steps", 10))
    drift_limit = policy.maximum_energy_drift_ev_per_atom_per_ps
    min_distance_limit = policy.minimum_pair_distance_angstrom
    max_force_limit = policy.maximum_force_ev_per_angstrom
    if steps <= 0 or timestep <= 0.0 or sample_interval_steps <= 0 or velocity_seed < 0:
        raise CampaignCliError("MLCV-VERIFY1 verification integration settings are invalid.")
    device = str(_cfg(cfg, "verification", "device", _cfg(cfg, "training", "device", "cuda")))
    acceleration = _acceleration_policy(cfg)
    critical_precision = _critical_precision_policy(cfg)
    structure_templates = _load_verification_structure_templates(resolved_structures)
    structure_sha256 = {str(value): _sha256(value) for value in resolved_structures}

    candidate_order = mdstats.ordered_mlcv_physical_candidates(
        final_selection,
        fallback_enabled=policy.fallback_to_next_qualified_final_seed,
    )
    member_by_candidate = {value.final_candidate_digest: value for value in committee.members}
    attempts: list[Any] = []
    if existing_verification is not None:
        if existing_verification.verification_policy_digest != policy.policy_digest:
            raise CampaignCliError("Existing MLCV physical-verification policy differs from current campaign configuration.")
        if existing_verification.final_selection_record_digest != final_selection.content_digest or existing_verification.final_committee_record_digest != committee.content_digest:
            raise CampaignCliError("Existing MLCV physical-verification evidence belongs to different FINAL1 authority.")
        attempts = list(existing_verification.attempts)
    if existing_verification is None:
        for rank, candidate in enumerate(candidate_order, start=1):
            member = member_by_candidate.get(candidate.content_digest)
            if member is None:
                raise CampaignCliError("Qualified FINAL1 candidate is missing from the committee export.")
            model_path = Path(member.exported_model_path).resolve()
            if not model_path.is_file() or _sha256(model_path) != member.exported_model_sha256:
                raise CampaignCliError(f"FINAL1 committee model changed before verification: {model_path}")
            case_digests: list[str] = []
            case_results: list[dict[str, Any]] = []
            for structure in resolved_structures:
                for temperature in temperatures:
                    identity = {
                        "schema": "mdstats.mlcv-physical-verification-case-identity.v1",
                        "campaign_plan_digest": campaign.content_digest,
                        "final_selection_record_digest": final_selection.content_digest,
                        "final_candidate_digest": candidate.content_digest,
                        "committee_member_digest": member.content_digest,
                        "verification_policy_digest": policy.policy_digest,
                        "model_sha256": member.exported_model_sha256,
                        "structure_sha256": structure_sha256[str(structure)],
                        "temperature_kelvin": float(temperature),
                        "timestep_fs": timestep,
                        "steps": steps,
                        "sample_interval_steps": sample_interval_steps,
                        "velocity_seed": velocity_seed,
                        "device": device,
                        "model_inference_dtype": model_dtype,
                        "scientific_analysis_dtype": "float64",
                        "acceleration_policy_digest": acceleration.policy_digest,
                        "critical_precision_policy_digest": critical_precision.policy_digest,
                    }
                    case_digest = _verification_case_digest(identity)
                    cache_key = f"mlcv_verification_case:{case_digest}"
                    cached = store.get_payload_optional(cache_key)
                    if cached is not None and cached.get("case_digest") == case_digest:
                        result = dict(cached["result"])
                    else:
                        result = _nve_verify(
                            model_path,
                            structure,
                            device=device,
                            dtype=model_dtype,
                            acceleration_policy=acceleration,
                            **_evaluation_acceleration_binding(cfg, paths),
                            critical_precision_policy=critical_precision,
                            temperature=float(temperature),
                            timestep_fs=timestep,
                            steps=steps,
                            velocity_seed=velocity_seed,
                            sample_interval_steps=sample_interval_steps,
                            calculator=None,
                            structure_atoms=structure_templates[str(structure)],
                            reuse_worker_calculator=True,
                        )
                        store.put_record(
                            cache_key,
                            {
                                "schema": "mdstats.mlcv-physical-verification-case-cache.v1",
                                "case_digest": case_digest,
                                "identity": identity,
                                "result": result,
                                "created_at_utc": _utc_now(),
                            },
                        )
                    case_digests.append(case_digest)
                    case_results.append(result)
            reasons = mdstats.verification_rejection_reasons(
                case_results,
                maximum_energy_drift_ev_per_atom_per_ps=drift_limit,
                minimum_pair_distance_angstrom=min_distance_limit,
                maximum_force_ev_per_angstrom=max_force_limit,
            )
            attempt = mdstats.MlcvPhysicalVerificationAttemptRecord(
                final_candidate_digest=candidate.content_digest,
                committee_member_digest=member.content_digest,
                seed=candidate.seed,
                final_run_plan_digest=candidate.final_run_plan_digest,
                run_id=candidate.final_run_id,
                checkpoint_sha256=candidate.checkpoint_sha256,
                checkpoint_epoch=candidate.checkpoint_epoch,
                candidate_rank=rank,
                exported_model_sha256=member.exported_model_sha256,
                verification_policy_digest=policy.policy_digest,
                verification_case_digests=tuple(case_digests),
                passed=not reasons,
                rejection_reasons=tuple(reasons),
            )
            store.put_record(f"mlcv_physical_attempt:{rank}", attempt)
            attempts.append(attempt)
            _ok(f"MLCV-VERIFY1 seed {candidate.seed}: {'PASS' if attempt.passed else 'FAIL'} physical verification")
            if attempt.passed or not policy.fallback_to_next_qualified_final_seed:
                break
        verification = mdstats.build_mlcv_verification_record(campaign, final_selection, committee, policy, tuple(attempts))
        store.put_record("mlcv_verification", verification)
        existing_verification = verification
        _atomic_json(paths.results / "mlcv-verify1-physical.json", verification.to_dict())
    verification = existing_verification
    assert verification is not None
    if verification.outcome != "physical_candidate_frozen":
        _mark_stage(store, paths, "verify", StageState.FAILED, "MLCV-VERIFY1: no qualified final seed passed physical verification")
        _warn("MLCV-VERIFY1: all authorized qualified final seeds failed bounded physical verification; locked E was never activated.")
        return 1

    frozen = verification.frozen_attempt
    assert frozen is not None
    frozen_member = next((value for value in committee.members if value.content_digest == frozen.committee_member_digest), None)
    frozen_candidate = next((value for value in final_selection.qualified_candidates if value.content_digest == frozen.final_candidate_digest), None)
    if frozen_member is None or frozen_candidate is None:
        raise CampaignCliError("Frozen MLCV physical candidate disappeared from FINAL1 authority.")

    # Locked E is activated only after physical fallback has ended permanently.
    if existing_locked is None:
        sealed, locked_artifact, locked_path = _mlcv_locked_test_artifact(
            cfg, paths, store, verification=verification
        )
        run = next((value for value in campaign.runs if value.content_digest == frozen.final_run_plan_digest), None)
        if run is None:
            raise CampaignCliError("Frozen MLCV final run is absent from the campaign plan.")
        synthetic_checkpoint = mdstats.CheckpointFileRecord(
            run_plan_digest=run.content_digest,
            candidate_id=f"mlcv-verify1-locked-E-seed-{frozen.seed}",
            epoch=frozen.checkpoint_epoch,
            relative_path="mlcv-verify1/frozen-target-head.model",
            sha256=frozen_member.exported_model_sha256,
            size_bytes=frozen_member.byte_size,
        )
        eval_policy = mdstats.CheckpointEvaluationPolicy(
            target_head_name=frozen_member.target_head_name,
            replay_head_name="pt_head",
            replay_baseline_head_name=None,
            focus_atomic_numbers=tuple(int(v) for v in _cfg(cfg, "profile", "mobile_atomic_numbers", (3, 11, 19))),
            device=str(_cfg(cfg, "evaluation", "device", _cfg(cfg, "training", "device", "cuda"))),
            default_dtype=model_dtype,
            batch_size=int(_cfg(cfg, "evaluation", "batch_size", 8)),
            cache_monitor_datasets=bool(_cfg(cfg, "evaluation", "cache_monitor_datasets", True)),
            cache_replay_baseline=False,
            evaluate_foundation_on_target=False,
            acceleration_policy=acceleration,
            **_evaluation_acceleration_binding(cfg, paths),
            critical_precision_policy=critical_precision,
        )
        prediction_cache_directory = paths.internal / "mlcv-verify1" / "prediction-cache"
        graph_cache_directory = paths.internal / "mlcv-verify1" / "graph-cache"
        prepared = mdstats.prepare_mace_checkpoint_evaluation(
            run,
            synthetic_checkpoint,
            candidate_model_path=Path(frozen_member.exported_model_path),
            target_monitor_path=locked_path,
            target_monitor_artifact=locked_artifact,
            policy=eval_policy,
            prediction_cache_directory=prediction_cache_directory,
            graph_cache_directory=graph_cache_directory,
            allow_target_monitor_override=True,
        )
        predictions = mdstats.run_prepared_mace_checkpoint_inference(
            prepared,
            calculator_model_path=Path(frozen_member.exported_model_path),
        )
        locked_evaluation = mdstats.finalize_prepared_mace_checkpoint_evaluation(prepared, predictions)
        store.put_record("mlcv_locked_test_evaluation", locked_evaluation)
        locked = mdstats.build_mlcv_locked_test_record(
            campaign,
            final_selection,
            committee,
            verification,
            policy,
            locked_evaluation,
            retained_metric_policy,
            sealed_evaluation_artifact_digest=sealed.content_digest,
            locked_test_artifact_digest=locked_artifact.content_digest,
            locked_test_sha256=locked_artifact.sha256,
        )
        store.put_record("mlcv_locked_test", locked)
        existing_locked = locked
        _atomic_json(paths.results / "mlcv-verify1-locked-E.json", locked.to_dict())
    locked = existing_locked
    assert locked is not None
    if locked.verification_record_digest != verification.content_digest:
        raise CampaignCliError("Locked-E evidence belongs to different physical-verification authority.")
    if not locked.passed:
        _mark_stage(store, paths, "verify", StageState.FAILED, "MLCV locked E failed; model remains frozen and no fallback is permitted")
        _warn(
            "MLCV-VERIFY1: the physically frozen model failed locked E. "
            "No other seed/checkpoint will be tried on E; campaign requires scientific review/new protocol identity."
        )
        return 1

    # Only a physical passer that also passes one-shot locked E may be published.
    source_model = Path(frozen_member.exported_model_path).resolve()
    if not source_model.is_file() or _sha256(source_model) != frozen_member.exported_model_sha256:
        raise CampaignCliError("Frozen FINAL1 committee model bytes changed before production publication.")
    published = (paths.models / "production_best.model").resolve()
    _atomic_copy_file(source_model, published)
    published_sha = _sha256(published)
    production = mdstats.build_mlcv_production_model_record(
        campaign,
        final_selection,
        committee,
        verification,
        locked,
        policy,
        exported_model_path=str(published),
        exported_model_sha256=published_sha,
        byte_size=published.stat().st_size,
    )
    store.put_record("mlcv_production_model", production)
    migration = _reconcile_mlcv_migration(paths, store, campaign)
    if migration is None:
        raise CampaignCliError("MLCV-VERIFY1 publication completed but MIGRATE1 could not freeze lifecycle authority.")
    summary = {
        "schema": "mdstats.mlcv-verify1-summary.v1",
        "campaign_plan_digest": campaign.content_digest,
        "verification": verification.to_dict(),
        "locked_test": locked.to_dict(),
        "production_model": production.to_dict(),
        "qualified_committee": committee.to_dict(),
        "mlcv_migration": migration.to_dict(),
        "next_gate": "complete",
    }
    summary["content_digest"] = digest(summary)
    _atomic_json(paths.results / "mlcv-verify1.json", summary)
    _mark_stage(
        store,
        paths,
        "verify",
        StageState.COMPLETE,
        f"MLCV-VERIFY1 published seed {production.seed} after physical verification and one-shot locked E; MLCV-MIGRATE1 lifecycle authority closed",
    )
    _ok(
        f"MLCV-VERIFY1: published {published.name} from seed {production.seed}; "
        f"locked E target RMSE={locked.target_force_rmse_ev_per_angstrom*1000:.2f} meV/A"
    )
    return 0



