        include_strain_modes=bool(_cfg(cfg, "verification", "pes_include_strain_modes", True)),
        projected_force_atol_ev_per_angstrom=float(_cfg(cfg, "verification", "pes_projected_force_atol_ev_per_angstrom", 0.05)),
        projected_force_rtol=float(_cfg(cfg, "verification", "pes_projected_force_rtol", 0.25)),
